            async function consumeBarrierIfAny(targetP, targetI, sourceLabel) {
                const t = state.players[targetP]?.field[targetI];
                if (!t || !t.barrier) return false;
                // Barreira permanente (Aura Anti-Magia): bloqueia e permanece.
                if (!t.barrierPermanent) {
                    t.barrier = false;
                    t.barrierTurns = 0;
                }
                log(t.barrierPermanent
                    ? `${t.name}: Barreira permanente bloqueou ${sourceLabel}!`
                    : `${t.name}: Barreira bloqueou ${sourceLabel}!`);
                await animateBarrierBlock(targetP, targetI);
                updateUI();
                return true;
            }
            // Manual §6: Barreira dá imunidade a Vulnerável. A Barreira NÃO é
