            // ====================================================================
            // ORÇAMENTO DE EFEITOS (FX BUDGET) — performance mobile
            // --------------------------------------------------------------------
            // Detecta aparelhos de baixo/médio custo (pouca RAM, poucos cores,
            // tela pequena / pointer grosso) e respeita prefers-reduced-motion.
            // Em vez de remover os efeitos, ESCALA a quantidade de partículas/
            // nós DOM criados por frame — o que era o gargalo real de FPS no
            // combate (50+ elementos com box-shadow/blur/blend-mode criados de
            // uma vez). Calculado UMA vez e cacheado.
            // ====================================================================
            const FX = (() => {
                let mobile = false, lowEnd = false, reduced = false;
                try {
                    mobile = !(window.DfLayout?.isDesktopLayout?.())
                        && window.matchMedia("(max-width: 900px), (pointer: coarse)").matches;
                    reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
                    const mem = navigator.deviceMemory || 8;
                    const cores = navigator.hardwareConcurrency || 8;
                    lowEnd = mem <= 4 || cores <= 4;
                } catch (e) {}
                const hints = window.DfViewport?.getPerfHints?.();
                const coarse = !!(window.DfLayout?.isCoarsePointer?.() || hints?.coarse);
                const perfFactor = hints?.particleFactor ?? 1;
                const medium = !mobile && !lowEnd && !reduced && (navigator.hardwareConcurrency || 8) <= 6;
                let factor = perfFactor;
                if (reduced) factor = Math.min(factor, 0.22);
                else if (lowEnd) factor = Math.min(factor, 0.5);
                else if (coarse) factor = Math.min(factor, 0.78);
                const ultFactor = reduced ? 0.2 : Math.min(0.72, factor * 0.85);
                return {
                    mobile, lowEnd, reduced, medium, coarse, factor, ultFactor,
                    // liteVfx só por reduced-motion ou escolha Leve/Mínimo
                    // (applyToFx). Device low → particleFactor, não mata GPU.
                    liteVfx: !!reduced,
                    n(count) {
                        if (reduced && count > 6) return Math.max(2, Math.round(count * 0.18));
                        if (factor < 1) return Math.max(2, Math.round(count * factor));
                        return count;
                    },
                    nUlt(count) {
                        if (reduced) return Math.max(1, Math.round(count * 0.35));
                        if (factor < 1) return Math.max(1, Math.round(count * ultFactor));
                        return count;
                    },
                };
            })();
            if (window.DfVfxSettings) window.DfVfxSettings.applyToFx(FX);
            window.__dfFX = FX;
            window.__dfOnVfxQualityChange = () => {
                window.DfViewport?.measure?.();
                if (window.DfVfxSettings) window.DfVfxSettings.applyToFx(FX);
                try { window.DfVfxSettings?.refreshPreview?.(); } catch (e) { /* */ }
            };

