            async function forceEndTurn() {
                if (state.winner !== null) return;
                try { closePreviewZoom?.(); } catch (e) { /* */ }
                // Talento a meio (alvo/spotlight): cancela e devolve à mão — sem efeito.
                if (state.activeTalent) {
                    try { abortActiveTalent(); } catch (e) { /* */ }
                }
                if (aiBusy) {
                    console.warn("[DF] Timer: destravando turno da IA (aiBusy)");
                    aiBusy = false;
                    try { await window.DfPresentationBus?.flush?.(); } catch (e) { /* */ }
                    try { window.DfUltimateDirector?.purgeUltimateVfx?.(); } catch (e) { /* */ }
                    document.querySelectorAll(".phase-blocker, .maint-box").forEach((el) => el.remove());
                    gamePhase = "normal";
                    targetData = {};
                    enterProcessed = false;
                }
                const p = state.players[state.currentPlayer];
                log(`⏰ Tempo esgotado para ${p.name}!`);
                floatText("⏰ Tempo esgotado!", "warn center", 1800); if (gamePhase === "menu") closeOverlay(); if (
                    gamePhase === "detail") closeDetail(); if (gamePhase === "discard") closeDiscard();                 if (gamePhase === "target-ally" && targetData?.ability === "ritualSacrifice") {
                    cancelRitualSacrifice();
                } else if ([
                        "select-attacker", "select-defender", "target-champion", "target-ally", "ultimate-target",
                        "unfreeze-choice", "summon-placement"
                    ].includes(gamePhase)) {
                    if (gamePhase === "summon-placement" && pendingSummon) {
                        const ps = pendingSummon;
                        pendingSummon = null;
                        const loc = dfLocalPlayer();
                        if (!ps.freeAction) loc.actions += DfRules.championSummonCost(ps.placed) || ps.placed.currentPower || ps.placed.power || 0;
                        loc.hand.push(ps.placed);
                        log("Posicionamento cancelado — carta devolvida à mão.");
                    }
                    gamePhase = "normal";
                    targetData = {};
                }
                p.actions = 0;
                gamePhase = "normal";
                updateUI();
                const T = DfProtocol?.ACTION_TYPES || {};
                try {
                    await dfPlayerAction({ type: T.END_TURN || "END_TURN", playerId: state.currentPlayer });
                } catch (turnEndErr) {
                    console.warn("[DF] forceEndTurn falhou — tentando dispatch direto", turnEndErr);
                    try {
                        await dfDispatch({ type: T.END_TURN || "END_TURN", playerId: state.currentPlayer }, { fromHuman: false, broadcast: false });
                    } catch (e) { /* */ }
                }
                // Multiplayer: se a vez não avançou (ACK falhou), heal + timer (endTurn já tenta).
                if (window.__DF_ONLINE && state.winner === null && dfIsMyTurn()) {
                    try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                    if (dfIsMyTurn() && !timerForceEnding) {
                        try { startTimer(); } catch (e2) { /* */ }
                    }
                }
            }



            async function dfAwaitChampionDom(pIdx, fIdx, maxMs = 2400) {
                if (!window.__dfCombatActive) updateUI(true);
                const step = 40;
                let elapsed = 0;
                while (elapsed < maxMs) {
                    const el = getChampionDom(pIdx, fIdx);
                    if (el && el.isConnected && el.offsetParent !== null) return el;
                    await wait(step);
                    elapsed += step;
                }
                return getChampionDom(pIdx, fIdx);
            }

            async function dfAwaitTalentInPlay(ownerP, maxMs = 2000) {
                updateUI();
                const step = 40;
                let elapsed = 0;
                while (elapsed < maxMs) {
                    const el = window.__dfTalentSpotlightEl?.();
                    if (el && el.isConnected && el.offsetParent !== null) return el;
                    await wait(step);
                    elapsed += step;
                }
                return null;
            }



            function cancelRitualSacrifice() {
                if (gamePhase !== "target-ally" || targetData?.ability !== "ritualSacrifice") return false;
                if (typeof clearDropHighlight === "function") clearDropHighlight();
                const ritualOwner = targetData?.caster
                    ?? (typeof dfLocalSeat === "function" ? dfLocalSeat() : 0);
                gamePhase = "normal";
                targetData = {};
                state.activeTalent = null; // remove o holofote do RITUAL ao cancelar
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    try {
                        dfOnlineBroadcastVisual({ kind: "ritual_spotlight_clear", ownerP: ritualOwner });
                    } catch (e) { /* */ }
                }
                log("Ritual cancelado — a carta permanece na sua mão.");
                floatText("Ritual cancelado", "info center", 1400);
                updateUI();
                return true;
            }

            function makeSummonInsertSlot(insertIdx, fieldLen) {
                const slot = document.createElement("button");
                slot.type = "button";
                slot.className = "summon-insert-slot";
                slot.dataset.insert = String(insertIdx);
                const isLeft = insertIdx === 0;
                const isRight = insertIdx === fieldLen;
                slot.title = isLeft ? "Colocar à esquerda do primeiro Campeão"
                    : isRight ? "Colocar à direita do último Campeão"
                    : "Colocar entre Campeões";
                slot.textContent = isLeft ? "◂" : isRight ? "▶" : "▸";
                slot.setAttribute("aria-label", slot.title);
                slot.addEventListener("click", (ev) => {
                    ev.preventDefault();
                    ev.stopPropagation();
                    confirmSummonPlacement(insertIdx);
                });
                slot.addEventListener("pointerdown", (ev) => ev.stopPropagation());
                return slot;
            }

            async function confirmSummonPlacement(insertIdx) {
                if (gamePhase !== "summon-placement" || !pendingSummon) return;
                const idx = Math.max(0, Math.min(insertIdx | 0, state.players[dfHumanSeat()].field.length));
                await finishPendingSummon(idx);
            }

            async function finishPendingSummon(insertIdx) {
                const ps = pendingSummon;
                if (!ps) return false;
                pendingSummon = null;
                gamePhase = "normal";
                targetData = {};
                const { playerIdx, placed, summonSrc } = ps;
                const p = state.players[playerIdx];
                const fieldIdx = Math.max(0, Math.min(insertIdx | 0, p.field.length));
                ensureTurnReady();
                if (window._summonLock) {
                    if (dfIsSummonAnimLive?.()) return false;
                    window._summonLock = false;
                }
                window._summonLock = true;
                try {
                    if (summonSrc) placed._summoning = true;
                    p.field.splice(fieldIdx, 0, placed);
                    updateUI();
                    if (summonSrc) {
                        try {
                            await summonAnimation(playerIdx, fieldIdx, summonSrc);
                        } finally {
                            delete placed._summoning;
                            const liveDest = getChampionDom(playerIdx, fieldIdx)
                                || document.getElementById(`champ-${playerIdx}-${fieldIdx}`);
                            if (liveDest) {
                                liveDest.classList.remove("is-summoning", "df-summon-busy");
                                liveDest.style.visibility = "";
                                liveDest.style.opacity = "";
                                window.dfEndFieldSummonBusy?.(liveDest);
                                window.dfScheduleFieldRowLock?.(liveDest);
                            }
                        }
                    }
                    window._summonLock = false;
                    try {
                        window.sfx && window.sfx("champion_summon");
                        window.sfx && window.sfx("champion_summon", { gain: 0.45, delay: 0.085 });
                    } catch (e) {}
                    if (isDragonCard(placed)) {
                        await animateDragonEntry(playerIdx, fieldIdx);
                    } else {
                        void championLandImpact(playerIdx, fieldIdx);
                    }
                    log(`${p.name} invocou ${placed.name}.`);
                    refreshHandChampionForSummon(placed, playerIdx);
                    const wasCursed = !!p.maldicaoForgetNext;
                    if (wasCursed) {
                        placed.silenced = true;
                        placed.onEnter = null;
                        placed.onDestroy = null;
                        placed.talentEffect = null;
                        placed.silencedInHand = false;
                        p.maldicaoForgetNext = false;
                        (p.hand || []).forEach(card => { if (card) card.silencedInHand = false; });
                        // Sem box central: o ícone de silenciado na carta já informa.
                        log(`🔮 ${placed.name} foi invocado sob ESQUECIMENTO — sem habilidade!`);
                        try { window.sfx && window.sfx("maldicao"); } catch (e) {}
                        updateUI();
                    }
                    delete placed._necromanciaFresh;
                    await resolveOnEnter(playerIdx, fieldIdx, placed.uid);
                    applyConstantFieldEffects(playerIdx, fieldIdx);
                    if (["target-champion", "target-ally", "ultimate-target"].includes(gamePhase)) {
                        updateUI({ immediate: true });
                    } else {
                        updateUI();
                    }
                    window.dfScheduleFieldRowLock?.(getChampionDom(playerIdx, fieldIdx));
                    checkWin();
                    return true;
                } finally {
                    window._summonLock = false;
                }
            }



