            /** Tamanho vertical da carta em combate (tapped usa bbox trocada). */
            function dfCombatLayoutSize(el, rect) {
                if (!rect || rect.width < 4) return { w: 90, h: 126 };
                const tapped = !!el?.classList?.contains("tapped");
                let w = rect.width;
                let h = rect.height;
                if (tapped) {
                    w = Math.min(rect.width, rect.height);
                    h = Math.max(rect.width, rect.height);
                }
                if (window.DfLayout?.isCanvasFieldLayout?.() && window.DfLayout?.viewportRectToCanvas) {
                    const box = window.DfLayout.viewportRectToCanvas({
                        left: rect.left,
                        top: rect.top,
                        width: w,
                        height: h,
                    });
                    return {
                        w: Math.max(4, Math.abs(box.width)),
                        h: Math.max(4, Math.abs(box.height)),
                    };
                }
                return { w, h };
            }

            /** Largura em viewport para geometria de encontro (DOM + pré-Pixi). */
            function dfCombatViewportSize(el, rect) {
                if (!rect || rect.width < 4) return { w: 72, h: 101 };
                let w = rect.width;
                let h = rect.height;
                if (el?.classList?.contains("tapped")) {
                    w = Math.min(rect.width, rect.height);
                    h = Math.max(rect.width, rect.height);
                }
                return { w, h };
            }
