                // Desistir, Reiniciar, Sair do Jogo. (Passar a Vez foi
                // removido a pedido do usuário — fim de turno acontece
                // via botão dedicado / esgotar ações.)
                const actionOpts = [
                    { label: "RETOMAR" },
                    { label: "🏳️ Desistir" },
                ];
                // Multiplayer: sem Reiniciar (só vs-IA / offline).
                if (!window.__DF_ONLINE && !document.body.classList.contains("df-pvp-mode")) {
                    actionOpts.push({ label: "🔄 Reiniciar" });
                }
                actionOpts.push({ label: "Sair do Jogo" });
