            // Touch (mobile) long-press menu for hand cards.
            // Always 3 options: Invocar/Usar Talento, Ver mais (zoom), Voltar.
            function openHandTouchMenu(handIdx) { if (!dfIsMyTurn() || gamePhase !== "normal") return; const p =
                    dfLocalPlayer(); const c = p.hand[handIdx]; if (!c) return;
                const isTalent = c.category === "talent";
                const playLabel = isTalent ? "Usar Talento" : "Invocar Campeão";
                // RITUAL (Ômega/Tiamat): custo é sacrifício, não Ações. Só
                // pode ser jogada se houver um aliado de Poder = summonRitual
                // no campo. summonFromHand re-valida e bloqueia se necessário.
                const isRitual = !isTalent && !!c.summonRitual;
                const hasRitualSac = isRitual && p.field.some(f => f.currentPower === c.summonRitual);
                const canPlay = isTalent ? p.actions >= (c.currentPower || 0)
                    : isRitual ? hasRitualSac
                    : p.actions >= c.currentPower;
                gamePhase = "menu";
                // O jogador SEMPRE pode TENTAR jogar a carta (pedido do autor):
                // sem Ações suficientes, o fluxo de invocação/talento responde
                // com o aviso de "Sem Pontos de Ação" em vez de a opção ficar
                // morta no menu, sem explicação.
                menuData = { type: "hand-touch", handIdx, selected: 0,
                    options: [
                        { label: playLabel },
                        { label: "Ver mais" },
                        { label: "Voltar" }
                    ] };
                const warning = canPlay ? "" :
                    isRitual ? `<div class="menu-warning">Você precisa de um Campeão aliado de Poder ${c.summonRitual} no campo para sacrificar.</div>`
                    : `<div class="menu-warning">Você não tem pontos de ação suficientes</div>`;
                const catLabel = isTalent ? "Talento" : "Campeão";
                openOverlay(`<h3>${c.name} (${catLabel})</h3>${warning}`, menuData.options);
                document.activeElement?.blur?.(); }

            // Invoca uma carta talento: tira da mão e coloca em activeTalent
            // (overlay central visível a todos até o efeito ser resolvido).
            // Depois, durante target-champion, o jogador escolhe o alvo:
            //   - Desktop: setas para navegar + Enter para confirmar
            //   - Mobile/Desktop: dois cliques rápidos no campeão alvo
            // Resolvido o efeito, a carta talento vai pro descarte automaticamente.
            async function startTalentUse(handIdx) {
                // MP: NÃO chamar dfEnsureLocalPlayMode — leaveRoom = SURRENDER.
                if (!(window.__DF_ONLINE || document.body.classList.contains("df-pvp-mode"))) {
                    try { dfEnsureLocalPlayMode?.(); } catch (e) { /* */ }
                }
                const pid = state.currentPlayer;
                if (gamePhase !== "normal") return;
                // Limpa fantasma de arrasto da mão — evita talento "preso" perto da mão.
                try { cleanupOrphanGhosts?.(); } catch (e) { /* */ }
                document.querySelectorAll(".drag-ghost, .drag-ghost-hand, .talent-fly-discard").forEach((el) => {
                    try { el.remove(); } catch (err) { /* */ }
                });
                dfClosePreviewForTargeting();
                const c = state.players[pid].hand[handIdx];
                if (!c || c.category !== "talent") return;
                // CUSTO DE AÇÃO — talentos com Custo > 0 (ex.: EXPLOSÃO custo 1)
                // exigem o número correspondente de ações disponíveis. O resto
                // dos talentos é Custo 0; o check vira no-op. A dedução
                // acontece quando o talento é COMPROMETIDO (após escolher
                // alvo), em confirmTargetTalentCost(), pra que cancelar a
                // seleção não cobre.
                const talentCost = DfRules.talentPlayCost?.(c) ?? (c.currentPower || c.power || 0);
                if (talentCost > 0 && state.players[pid].actions < talentCost) {
                    flashInsufficientActions(talentCost, state.players[pid].actions, handIdx);
                    return;
                }
                if (c.talentEffect === "bloquearAtaque") {
                    flashRuleBanner("Bloquear Ataque é REATIVA.", "Só pode ser usada FORA do seu turno, quando um Campeão seu for atacado.");
                    return;
                }
                if (c.talentEffect === "protecaoDivina") {
                    flashRuleBanner("Proteção Divina é REATIVA.", "Dispara sozinha quando um Campeão seu sofrer redução de Poder.");
                    return;
                }
                if (c.talentEffect === "cancelarUltimate") {
                    flashRuleBanner("Cancelar Ultimate é REATIVA.", "Dispara sozinha quando o adversário usar uma Ultimate.");
                    return;
                }
                if (c.talentEffect === "doppelganger") {
                    const allies = gatherAllyTargets(pid, -1, ch => ch && ch.currentPower === 2);
                    if (!allies.length) {
                        log("Doppelganger: nenhum Campeão aliado de Poder 2 em campo.");
                        floatText("Sem aliados de Poder 2", "warn center", 1800);
                        return;
                    }
                    if (state.players[pid].field.length >= MAX_FIELD) {
                        notifyFieldFull(pid);
                        return;
                    }
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        if (talentCost > 0) state.players[pid].actions = Math.max(0, state.players[pid].actions - talentCost);
                    }
                    updateUI();
                    await awaitTalentSpotlight();
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    await resolveTalentDoppelganger(pid);
                    return;
                }
                if (c.talentEffect === "fortalecerTalento") {
                    const allies = gatherAllyTargets(pid, -1, allyTargetCanGainPower);
                    if (!allies.length) {
                        log("Fortalecer: nenhum Campeão aliado disponível.");
                        floatText("Sem aliados", "info center", 1400);
                        return;
                    }
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        // Auth já removeu a carta e debitou ações.
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        if (talentCost > 0) state.players[pid].actions = Math.max(0, state.players[pid].actions - talentCost);
                    }
                    gamePhase = "target-ally";
                    targetData = {
                        ability: "fortalecerTalento",
                        caster: pid,
                        allyTargets: allies,
                        targetIndex: 0,
                        handIdx,
                    };
                    log("Qual Campeão aliado você quer Fortalecer? Clique no aliado destacado em verde.");
                    dfInvalidateQuadrantFp(pid);
                    updateUI();
                    await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    return;
                }
                if (c.talentEffect === "barreira") {
                    const allies = gatherAllyTargets(pid, -1, () => true);
                    const needBarrier = allies.filter((t) => {
                        const ch = state.players[t.p]?.field[t.i];
                        return ch && !ch.barrier && !ch.barrierPermanent;
                    });
                    if (!needBarrier.length) {
                        log("Barreira: todos os aliados já têm Barreira.");
                        floatText("Sem alvos", "info center", 1400);
                        return;
                    }
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                    }
                    updateUI();
                    await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    await resolveTalentBarreira(pid);
                    return;
                }
                if (c.talentEffect === "aceleracao") {
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                    }
                    updateUI();
                    await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    await resolveTalentAceleracao(pid);
                    return;
                }
                if (c.talentEffect === "baforadaVenenosa") {
                    const targets = gatherEnemyTargets(pid, () => true);
                    if (!targets.length) {
                        log("Baforada Venenosa: nenhum Campeão adversário em campo.");
                        floatText("Sem alvos", "info center", 1400);
                        return;
                    }
                    if (talentCost > 0 && state.players[pid].actions < talentCost) {
                        flashInsufficientActions(talentCost, state.players[pid].actions, handIdx);
                        return;
                    }
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        if (talentCost > 0) state.players[pid].actions = Math.max(0, state.players[pid].actions - talentCost);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                    }
                    gamePhase = "target-champion";
                    targetData = { ability: "baforadaVenenosa", caster: pid, targets, targetIndex: 0, handIdx };
                    log("Clique no campeão adversário destacado em VERDE — Baforada Venenosa envenena o alvo.");
                    dfInvalidateQuadrantFp(pid);
                    updateUI();
                    await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    return;
                }
                if (c.talentEffect === "missemagicos") {
                    if (talentCost > 0 && state.players[pid].actions < talentCost) {
                        flashInsufficientActions(talentCost, state.players[pid].actions, handIdx);
                        return;
                    }
                    if (!gatherEnemyTargets(pid, () => true).length) {
                        log("Mísseis Mágicos: nenhum Campeão adversário em campo.");
                        floatText("Sem alvos", "info center", 1400);
                        return;
                    }
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                        if (!ack || ack.ok === false) {
                            dfOnlineActionFailToast?.("talent", ack?.error);
                            try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                            return;
                        }
                        if (!state.activeTalent) {
                            state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        }
                    } else {
                        state.players[pid].hand.splice(handIdx, 1);
                        state.activeTalent = { ownerP: pid, card: c, spentActions: talentCost > 0 ? talentCost : 0 };
                        if (talentCost > 0) state.players[pid].actions = Math.max(0, state.players[pid].actions - talentCost);
                    }
                    updateUI();
                    await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                    if (!state.activeTalent || state.currentPlayer !== pid) return;
                    await resolveTalentMisseisMagicos(pid);
                    return;
                }
                let targets, prompt;
                if (c.talentEffect === "bolaDeFogoTalento") {
                    targets = gatherEnemyTargets(pid, () => true);
                    prompt = "Clique no campeão adversário destacado em VERMELHO — Bola de Fogo tira 1 de Poder dele.";
                    if (!targets.length) { log("Não há campeões adversários."); floatText("Sem alvos", "info center", 1400); return; }
                } else if (c.talentEffect === "explosao") {
                    targets = gatherEnemyTargets(pid, () => true);
                    prompt = "Em qual campeão você deseja utilizar a Explosão? — Clique no Campeão adversário destacado em VERMELHO.";
                    if (!targets.length) { log("Não há campeões adversários."); floatText("Sem alvos", "info center", 1400); return; }
                } else if (c.talentEffect === "zeroAbsoluto") {
                    targets = gatherEnemyTargets(pid, () => true);
                    prompt = "Qual campeão você deseja Congelar? — Clique no Campeão adversário destacado em AZUL.";
                    if (!targets.length) { log("Não há campeões adversários."); floatText("Sem alvos", "info center", 1400); return; }
                } else if (c.talentEffect === "medoTalento") {
                    targets = gatherAllFieldTargets().filter(t => {
                        const ch = state.players[t.p].field[t.i];
                        return ch && ch.currentPower <= 2;
                    });
                    prompt = "Clique no campeão destacado em vermelho — Amedrontar só afeta Campeões com Poder ≤ 2.";
                    if (!targets.length) {
                        log("Amedrontar: nenhum Campeão com Poder ≤ 2 em campo.");
                        floatText("Sem alvos com Poder ≤ 2", "warn center", 1800);
                        return;
                    }
                } else { return; }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    const ack = await dfOnlinePublishTalentStart(handIdx, { card: c });
                    if (!ack || ack.ok === false) {
                        dfOnlineActionFailToast?.("talent", ack?.error);
                        try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                        return;
                    }
                    if (!state.activeTalent) {
                        state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                    }
                } else {
                    state.players[pid].hand.splice(handIdx, 1);
                    state.activeTalent = { ownerP: pid, card: c, spentActions: 0 };
                }
                gamePhase = "target-champion";
                targetData = { ability: c.talentEffect, caster: pid, targets, targetIndex: 0, handIdx };
                log(prompt);
                dfClosePreviewForTargeting();
                dfInvalidateAllQuadrantFp();
                targets.forEach(({ p }) => dfInvalidateQuadrantFp(p));
                document.body.setAttribute("data-targeting", "target-champion");
                updateUI({ immediate: true });
                await awaitTalentSpotlight(DF_TALENT_SPOTLIGHT_MS);
                if (!state.activeTalent || state.currentPlayer !== pid) return;
                // O holofote do talento roda 1,5s com vários updateUI/restore no
                // meio — reafirma as bordas dos alvos ao devolver o controle.
                if (gamePhase === "target-champion") {
                    document.body.setAttribute("data-targeting", "target-champion");
                    try { window.dfSyncTargetingHighlights?.(); } catch (e) { /* */ }
                    try { window.DfTargetLevitate?.sync?.(); } catch (e) { /* */ }
                }
            }

            function gatherAllFieldTargets() { const arr = []; for (let p = 0; p < state.playersCount; p++) state.players[
                    p].field.forEach((c, i) => arr.push({ p, i })); return arr; }

            function openCardDetail(card) { const tc = getCardTypeClass(card);
                // Render ONLY the card art (PNG) with the current-power overlay.
                // The art hook applies .has-art, hides .nm, and positions .pow
                // as the corner badge — current power reflects fortalecer/dano/etc.
                $("detail-panel").innerHTML =
                    `<div class="hcard ${tc}" style="margin:0 auto;width:280px;height:392px;border-radius:14px;position:relative"><div class="pow">${card.currentPower}</div><div class="nm">${card.name}</div>${gemOverlayHtml(card)}</div>`;
                window.applyCardArtTree?.($("detail-panel"));
                $("detail-overlay").classList.add("active");
                gamePhase = "detail"; }

            function closeDetail() { $("detail-overlay").classList.remove("active"); if (state.currentPlayer === 0)
                    gamePhase = "normal"; }

            function openDiscard() {
                const discard = state.players[0]?.discard || [];
                const list = discard.map((c, i) =>
                    `<div style="padding:5px;border:1px solid #3b2945;border-radius:6px;margin-bottom:4px;text-align:left;font-size:0.85rem"><b>${i + 1}.</b> ${c.name} <span style="color:#e9c672">(${c.currentPower})</span> - <span style="color:#bda8d8">${c.abilityName || "-"}</span></div>`
                    ).join("");
                $("discard-panel").innerHTML =
                    `<h3>Descarte (${discard.length})</h3>${list || '<div style="color:#aaa">Vazio</div>'}`;
                $("discard-overlay").classList.add("active");
                gamePhase = "discard"; }

            function closeDiscard() { $("discard-overlay").classList.remove("active"); if (state.currentPlayer === 0)
                    gamePhase = "normal"; }

            function chooseMenuOption() { if (!menuData) return; const sel = menuData.options[menuData.selected]; if (sel
                    .disabled) return; if (menuData.type === "actions") { const label = sel.label;
                if (label === "RETOMAR" || label === "Voltar") { closeOverlay();
                gamePhase = "normal";
                updateUI(); return; }                 if (label === "🏳️ Desistir") { closeOverlay();
                gamePhase = "normal";
                if (window.__DF_ONLINE) {
                    void dfOnlineSurrenderAndShowDefeat();
                } else {
                    surrenderGame();
                }
                return; } if (label === "🔄 Reiniciar") { closeOverlay();
                gamePhase = "normal";
                if (window.__DF_ONLINE) return;
                restartCurrentGame(); return; } if (label === "Sair do Jogo") { backToMenu(); return; }
                } else if (menuData.type === "hand-touch") {
                    const label = sel.label; const idx = menuData.handIdx; const card = state.players[0].hand[idx];
                    if (label === "Ver mais") { closeOverlay(); gamePhase = "normal"; if (card) openCardZoom(card); return; }
                    if (label === "Voltar") { closeOverlay(); gamePhase = "normal"; updateUI(); return; }
                    if (label === "Invocar Campeão") {
                        closeOverlay(); gamePhase = "normal";
                        const T = DfProtocol?.ACTION_TYPES || {};
                        void dfPlayerAction({ type: T.SUMMON || "SUMMON", handIdx: idx });
                        return;
                    }
                    if (label === "Usar Talento") { closeOverlay(); gamePhase = "normal"; startTalentUse(idx); return; }
                } else if (menuData.type === "target-player") {
                    // Dispatch por habilidade — Pesadelo (Void/Succubus),
                    // Roubar (Tagarela/Raziel) e Desacelerar (Maga do Tempo
                    // / Soldado Futurista) reusam o mesmo seletor de jogador.
                    const picked = menuData.targets[menuData.selected];
                    if (targetData?.ability === "roubar") confirmRoubarTarget(picked);
                    else if (targetData?.ability === "desacelerar") confirmDesacelerarTarget(picked);
                    else confirmPesadeloTarget(picked);
                } else if (menuData.type === "unfreeze") { closeOverlay(); if (
                    menuData.confirmed) { state.players[0].actions -= 1;
                    state.players[0].field[menuData.fieldIdx].frozen = false;
                    state.players[0].field[menuData.fieldIdx].frozenTurns = 0;
                    log("Descongelado!");
                    floatText("🔥 Descongelado!", "info center", 1500); } else log("Não descongelou.");
                gamePhase = "normal";
                updateUI(); } }









            // Animação compartilhada (Sinistrela ult + talento AMEDRONTAR):
            // a carta-alvo no campo é clonada e voa em arco até a mão do
            // dono, rotacionando e diminuindo, pra que o jogador afetado
            // VEJA que sua carta está retornando. Roda ANTES do splice.
            // VERSÃO ROBUSTA (pedido do usuário): aura forte + floatText
            // "↩ VOLTOU À MÃO" + trilha de brilho + pulso no quadrante
            // destino, pra ninguém perder o que aconteceu.
            function dfScareFlyStartRect(targetP, targetI, fieldEl) {
                if (fieldEl) return fieldEl.getBoundingClientRect();
                const qIdx = dfQuadrantForPlayer(targetP);
                const fieldArea = document.querySelector(`#quadrant-${qIdx} .quadrant-field`);
                if (!fieldArea) return { left: innerWidth / 2 - 45, top: innerHeight / 2 - 63, width: 90, height: 126 };
                const fr = fieldArea.getBoundingClientRect();
                const cards = [...fieldArea.querySelectorAll(".ccard")];
                const ref = cards[targetI] || cards[cards.length - 1];
                if (ref) return ref.getBoundingClientRect();
                const slotW = Math.min(100, Math.max(72, fr.width / 5));
                const slotH = Math.min(140, fr.height - 8);
                const slots = Math.max(1, targetI + 1);
                const startX = fr.left + (fr.width - slots * slotW) / 2 + targetI * slotW;
                return { left: startX, top: fr.top + 6, width: slotW, height: slotH };
            }

            function dfHandCardCssSize() {
                const cs = getComputedStyle(document.documentElement);
                const w = parseFloat(cs.getPropertyValue("--df-hand-card-w")) || (FX.mobile ? 68 : 74);
                const h = parseFloat(cs.getPropertyValue("--df-hand-card-h")) || Math.round(w / DF_CARD_ASPECT);
                return { w, h };
            }

            function dfHandLandingCenter(targetP, insertIdx) {
                const qIdx = dfQuadrantForPlayer(targetP);
                const handEl = document.querySelector(`#quadrant-${qIdx} .quadrant-hand`);
                if (!handEl) return null;
                const cssSz = dfHandCardCssSize();
                const wraps = handEl.querySelectorAll(":scope > .hand-wrap");
                const idx = Math.max(0, Math.min(insertIdx ?? wraps.length, wraps.length));
                if (wraps[idx]) {
                    const r = wraps[idx].getBoundingClientRect();
                    const hc = wraps[idx].querySelector(".hcard, .ai-back");
                    return {
                        x: r.left + r.width / 2,
                        y: r.top + r.height / 2,
                        w: cssSz.w || hc?.offsetWidth || r.width,
                        h: cssSz.h || hc?.offsetHeight || r.height,
                    };
                }
                const hr = handEl.getBoundingClientRect();
                const ref = wraps[wraps.length - 1];
                const hw = cssSz.w || ref?.querySelector(".hcard, .ai-back")?.offsetWidth || 64;
                const hh = cssSz.h || ref?.querySelector(".hcard, .ai-back")?.offsetHeight || 90;
                const refR = ref?.getBoundingClientRect();
                return {
                    x: refR ? refR.right + hw * 0.22 : hr.left + hr.width * 0.55,
                    y: refR ? refR.top + refR.height / 2 : hr.top + hr.height * 0.45,
                    w: hw,
                    h: hh,
                };
            }

            async function dfFlushHandLayout(tries = 3) {
                for (let i = 0; i < tries; i++) {
                    await new Promise((r) => requestAnimationFrame(r));
                }
            }

            function dfScareCardSnapFromState(card) {
                if (!card) return null;
                return {
                    name: card.name,
                    category: card.category || "champion",
                    power: card.power ?? 0,
                    currentPower: card.currentPower ?? card.power ?? 0,
                    basePower: card.basePower ?? card.power ?? 0,
                    tapped: !!card.tapped,
                };
            }

            /** Wrapper + carta vertical — mesmo padrão do .battle-fly de combate. */
            function dfBuildScareFlyCard(fieldEl, cardSnap, fr) {
                const layout = dfCombatLayoutSize(fieldEl, fr);
                const flyW = layout.w * 1.2;
                const flyH = layout.h * 1.2;
                const fromCx = fr.left + fr.width / 2;
                const fromCy = fr.top + fr.height / 2;
                const champName = cardSnap?.name || fieldEl?.querySelector(".nm")?.textContent?.trim() || "";

                const wrap = document.createElement("div");
                wrap.className = "df-scare-fly-wrap";
                wrap.style.width = Math.round(flyW) + "px";
                wrap.style.height = Math.round(flyH) + "px";

                let card;
                if (fieldEl) {
                    card = fieldEl.cloneNode(true);
                    card.classList.remove(
                        "df-field-static", "valid-target", "target", "vt-red", "vt-green",
                        "fear-card-shudder", "tapped", "combat-animating", "combat-src-hidden",
                        "field-drag-src", "field-dragging", "impact", "land-impact",
                        "drag-attack-target", "buff-aura", "counting-bounce", "counting-bounce-tapped",
                        "hl", "attacker", "defender-combat", "attacker-combat",
                    );
                } else if (cardSnap) {
                    card = document.createElement("div");
                    card.className = "ccard type-champion df-scare-fly-card";
                    card.innerHTML = buildFlyCardHtml(cardSnap);
                } else {
                    return null;
                }
                card.classList.add("df-scare-fly-card");
                card.removeAttribute("id");
                card.removeAttribute("data-player");
                card.removeAttribute("data-field");
                card.removeAttribute("style");
                card.style.cssText =
                    "width:100%;height:100%;margin:0;position:relative;visibility:visible;opacity:1;" +
                    "transform:none;transition:none;box-sizing:border-box;";

                const img = fieldEl?.querySelector(":scope > img.card-art-bg");
                const artSnap = {
                    cardName: champName,
                    currentPower: cardSnap?.currentPower ?? 0,
                    basePower: cardSnap?.basePower ?? cardSnap?.power ?? 0,
                    artSrc: img?.currentSrc || img?.src || "",
                    cardArtCss: fieldEl?.style?.getPropertyValue("--card-art")
                        || (fieldEl ? getComputedStyle(fieldEl).getPropertyValue("--card-art") : "") || "",
                };
                if (champName && window.dfAttachCardArt) {
                    window.dfAttachCardArt(card, champName);
                }
                window.applyCardArtTree?.(card);
                dfEnsureBattleFlyArt(card, artSnap);
                dfSyncBattleFlyPower(card, artSnap);
                if (window.DfCardFace?.isComposed?.(champName)) {
                    try {
                        window.DfCardFace.mount(card, cardSnap || { name: champName }, {
                            power: artSnap.currentPower,
                        });
                    } catch (eMount) { /* */ }
                    card.classList.remove("df-card-face--loading", "art-loading");
                    card.classList.add("has-composed-face", "has-art", "art-ready");
                    const face = card.querySelector(":scope > .df-card-face");
                    if (face) face.style.opacity = "1";
                }
                card.querySelectorAll("img.card-art-bg").forEach((im) => {
                    im.style.cssText =
                        "position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none;display:block;opacity:1;";
                });
                wrap.appendChild(card);
                return { flyer: wrap, fromCx, fromCy, flyW, flyH, champName };
            }

            function dfSpawnScareFlyEmojis(cx, cy) {
                const icons = ["😱", "👻", "💨", "🌙"];
                icons.forEach((icon, i) => {
                    const el = document.createElement("div");
                    el.className = "df-scare-ult-emoji";
                    el.textContent = icon;
                    el.style.animationDelay = (i * 90) + "ms";
                    dfVfxSetPoint(el, cx, cy);
                    setTimeout(() => el.remove(), 1100);
                });
            }

            async function playScareUltimateBeat(targetP, targetI) {
                await playMedoFearBurst(targetP, targetI);
                const tr = dfChampionAnchorRect(targetP, targetI);
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                dfSpawnScareFlyEmojis(cx, cy);
                dfSpawnScareFlyEmojis(cx + 18, cy - 12);
                await wait(FX.mobile ? 280 : 360);
            }

            /** Pulso leve no talento AMEDRONTAR — sem banner, anéis ou traços. */
            async function playMedoFearBurst(targetP, targetI) {
                const tel = getChampionDom(targetP, targetI);
                if (tel) {
                    tel.classList.add("fear-card-shudder");
                    try { window.sfx && window.sfx("scare"); } catch (e) {}
                    await wait(FX.mobile ? 420 : 520);
                    tel.classList.remove("fear-card-shudder");
                } else {
                    await wait(200);
                }
            }

            async function animateChampionFlyToHand(targetP, targetI, cardSnap, handInsertIdx, flyOpts = {}) {
                document.querySelectorAll(".df-scare-fly-wrap").forEach((el) => el.remove());
                const fieldEl = getChampionDom(targetP, targetI);
                const champ = cardSnap || state.players[targetP]?.field[targetI];
                if (!fieldEl && !champ) return;

                const fr = dfScareFlyStartRect(targetP, targetI, fieldEl);
                const dest = dfHandLandingCenter(targetP, handInsertIdx);
                const fromCx = fr.left + fr.width / 2;
                const fromCy = fr.top + fr.height / 2;
                const toX = dest?.x ?? fromCx;
                const toY = dest?.y ?? (fromCy + 120);

                // Mantém o slot oculto até applyScareReturnToHand (evita duplicata).
                window.__dfScareReturnActive = { p: targetP, i: targetI, until: Date.now() + 4500 };
                const hideScareSrc = (el) => {
                    if (!el) return;
                    el.classList.add("scare-src-hidden", "combat-src-hidden");
                    el.style.setProperty("visibility", "hidden", "important");
                    el.style.setProperty("opacity", "0", "important");
                    el.style.setProperty("pointer-events", "none", "important");
                };
                hideScareSrc(fieldEl);
                let scareHidePulse = null;
                try {
                    scareHidePulse = setInterval(() => {
                        if (!window.__dfScareReturnActive) return;
                        hideScareSrc(getChampionDom(targetP, targetI));
                    }, 80);

                    const wantsGpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                        && typeof window.DfPixiVfx?.playScareReturnScene === "function";
                    if (wantsGpu) {
                        if (flyOpts.ultimate) dfSpawnScareFlyEmojis(fromCx, fromCy);
                        const cardName = champ?.name || fieldEl?.querySelector(".nm")?.textContent?.trim() || "";
                        const pow = champ?.currentPower ?? champ?.power ?? champ?.basePower;
                        const artFromDom = fieldEl?.querySelector(":scope > img.card-art-bg")?.currentSrc
                            || fieldEl?.querySelector(":scope > img.card-art-bg")?.src
                            || fieldEl?.querySelector(".df-card-face__art")?.currentSrc
                            || fieldEl?.querySelector(".df-card-face__art")?.src
                            || "";
                        let artUrl = null;
                        try {
                            if (cardName && window.DfCardFace?.isComposed?.(cardName) && window.DfCardFace.warmFace) {
                                await Promise.race([
                                    window.DfCardFace.warmFace(
                                        champ || { name: cardName, currentPower: pow, power: pow },
                                        { power: pow },
                                    ),
                                    new Promise((r) => setTimeout(() => r(""), 900)),
                                ]);
                                artUrl = window.DfCardFace.getFaceDataUrl?.(cardName, pow) || null;
                            }
                            if (!artUrl) {
                                artUrl = window.DfPixiVfx?.resolveCardArtUrl?.(cardName, {
                                    ...(champ && typeof champ === "object" ? champ : {}),
                                    name: cardName,
                                    cardName,
                                    currentPower: pow,
                                    artSrc: artFromDom,
                                }) ?? (window.dfCardSrc ? window.dfCardSrc(cardName) : null);
                            }
                            if (!artUrl && artFromDom) artUrl = artFromDom;
                        } catch (eArt) { /* */ }
                        const ok = await window.DfPixiVfx.playScareReturnScene({
                            fromX: fromCx, fromY: fromCy, toX, toY,
                            cardW: fr.width * 1.2, cardH: fr.height * 1.2,
                            cardSrc: artUrl,
                            cardName,
                            currentPower: pow,
                            power: pow,
                            ultimate: !!flyOpts.ultimate,
                        });
                        if (ok) {
                            const qIdx = dfQuadrantForPlayer(targetP);
                            const handEl = document.querySelector(`#quadrant-${qIdx} .quadrant-hand`);
                            const wraps = handEl?.querySelectorAll(":scope > .hand-wrap");
                            const landIdx = Math.max(0, Math.min(handInsertIdx ?? (wraps?.length || 0), (wraps?.length || 1) - 1));
                            const landWrap = wraps?.[landIdx] || wraps?.[wraps.length - 1];
                            if (landWrap) {
                                landWrap.classList.add("df-scare-hand-land");
                                setTimeout(() => landWrap.classList.remove("df-scare-hand-land"), 620);
                            }
                            await wait(80);
                            return;
                        }
                    }

                    const built = dfBuildScareFlyCard(fieldEl, champ, fr);
                    if (!built) return;
                    const wrap = built.flyer;
                    const flyFromCx = built.fromCx;
                    const flyFromCy = built.fromCy;
                    const destScale = dest
                        ? Math.min(dest.w / built.flyW, dest.h / built.flyH)
                        : 0.94;
                    const fromP = dfVfxMap(flyFromCx, flyFromCy);
                    const toP = dfVfxMap(toX, toY);
                    wrap.style.cssText +=
                        `position:${dfVfxPos()};left:0;top:0;z-index:` + dfAllocAnimZ() + ";pointer-events:none;will-change:transform;";
                    wrap.style.transform =
                        `translate3d(${fromP.x}px, ${fromP.y}px, 0) translate(-50%, -50%) scale(1)`;
                    wrap.style.opacity = "1";
                    wrap.style.visibility = "visible";
                    dfVfxMount(wrap);
                    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                    if (flyOpts.ultimate) dfSpawnScareFlyEmojis(flyFromCx, flyFromCy);

                    const dx = toP.x - fromP.x;
                    const dy = toP.y - fromP.y;

                    const FLY_MS = FX.mobile ? 820 : 1050;
                    const peakLift = -Math.min(64, Math.max(32, Math.hypot(dx, dy) * 0.16));
                    const endScale = Math.max(0.96, Math.min(1.02, destScale || 1));
                    const t0 = performance.now();
                    await new Promise((resolve) => {
                        function tick(now) {
                            const t = Math.min(1, (now - t0) / FLY_MS);
                            const ease = t < 0.5
                                ? 4 * t * t * t
                                : 1 - Math.pow(-2 * t + 2, 3) / 2;
                            const arcY = peakLift * Math.sin(Math.PI * t);
                            const x = dx * ease;
                            const y = dy * ease + arcY;
                            const rot = -9 * Math.sin(Math.PI * t) * (1 - t * 0.2);
                            const scale = 1 + (endScale - 1) * ease;
                            wrap.style.transform =
                                `translate3d(${fromP.x + x}px, ${fromP.y + y}px, 0) ` +
                                `translate(-50%, -50%) scale(${scale}) rotate(${rot}deg)`;
                            wrap.style.opacity = String(1 - t * 0.03);
                            if (t < 1) requestAnimationFrame(tick);
                            else resolve();
                        }
                        requestAnimationFrame(tick);
                    });
                    wrap.remove();

                    const qIdx = dfQuadrantForPlayer(targetP);
                    const handEl = document.querySelector(`#quadrant-${qIdx} .quadrant-hand`);
                    const wraps = handEl?.querySelectorAll(":scope > .hand-wrap");
                    const landIdx = Math.max(0, Math.min(handInsertIdx ?? (wraps?.length || 0), (wraps?.length || 1) - 1));
                    const landWrap = wraps?.[landIdx] || wraps?.[wraps.length - 1];
                    if (landWrap) {
                        landWrap.classList.add("df-scare-hand-land");
                        setTimeout(() => landWrap.classList.remove("df-scare-hand-land"), 620);
                    }
                    await wait(100);
                } finally {
                    if (scareHidePulse) clearInterval(scareHidePulse);
                    // Não limpa o hide aqui — applyScareReturnToHand remove o campeão do field.
                }
            }

            // "Tell" visual reativo: o atacante brilha/treme brevemente
            // ANTES do prompt de Bloquear/Proteção Divina abrir, deixando
            // claro que a ação adversária está começando (e fica em pausa
            // visual enquanto o defensor decide). Beat curto (~520ms) pra
            // não atrasar demais o fluxo.
            async function animateReactiveTell(attOwner, attacker, defOwner, defender, kind) {
                const attIdx = attacker ? findFieldIdx(attOwner, attacker) : -1;
                const defIdx = defender ? findFieldIdx(defOwner, defender) : -1;
                const attEl = attIdx >= 0 ? getChampionDom(attOwner, attIdx) : null;
                const defEl = defIdx >= 0 ? getChampionDom(defOwner, defIdx) : null;
                const color = kind === "block" ? "#ff5050" : "#ffd76b";
                if (attEl) {
                    attEl.style.transition = "filter 220ms ease, transform 220ms ease";
                    attEl.style.filter = `drop-shadow(0 0 14px ${color}) drop-shadow(0 0 28px ${color})`;
                    attEl.style.transform = "scale(1.06)";
                }
                if (defEl) {
                    defEl.style.transition = "filter 220ms ease, transform 220ms ease";
                    defEl.style.filter = `drop-shadow(0 0 12px ${color})`;
                    defEl.style.transform = "scale(0.97)";
                }
                await wait(500);
                if (attEl) {
                    attEl.style.filter = "";
                    attEl.style.transform = "";
                }
                if (defEl) {
                    defEl.style.filter = "";
                    defEl.style.transform = "";
                }
                window.dfStabilizeFieldCards?.(attEl);
                window.dfStabilizeFieldCards?.(defEl);
                // Pequena pausa pra o usuário registrar o "tell" antes do prompt.
                await wait(60);
            }

            /** Destaca a carta AMEDRONTAR no campo do adversário antes do efeito. */
            async function dfHighlightMedoTalent(ownerP, ms = 1200) {
                const el = window.__dfTalentSpotlightEl?.();
                if (!el) { await wait(Math.min(ms, 350)); return; }
                el.classList.add("df-medo-spotlight");
                await wait(ms);
                el.classList.remove("df-medo-spotlight");
            }

            /** Amedrontar / ult Sinistrela — carta volta à mão do dono com Poder base. */
            function buildScareReturnHandCard(target) {
                const ret = cloneCard(target);
                const base = target.basePower ?? target.power ?? target.currentPower ?? 0;
                ret.currentPower = base;
                ret.basePower = base;
                ret.power = base;
                ret.tapped = false;
                ret.frozen = false; ret.frozenTurns = 0;
                ret.freeAttack = false;
                ret.shielded = false; ret.shieldedTurns = 0; ret.shieldedPermanent = false;
                ret.silenced = false; ret.pulled = false; ret.pulledFromOwner = -1; ret.pulledTurns = 0;
                ret.poisoned = false; ret.poisonTurns = 0; ret.poisonedByP = -1;
                ret.vulnerable = false;
                ret.corruptedNoHonor = false;
                ret.barrier = false; ret.barrierTurns = 0; ret.barrierPermanent = false;
                ret.fireAura = false; ret.fireAuraTurns = 0;
                ret.fury = false; ret.furyTurns = 0; ret.furyStacks = 0; ret.furyBonusActive = false;
                ret.wallBuff = false; ret.foreverGrowth = false;
                ret.burning = false; ret.burningTurns = 0; ret.burningByP = undefined;
                ret.guerraBuff = false; ret.guerraBuffTurns = 0;
                // Mão→campo de novo: Instantânea deve reativar (Troca Injusta
                // no campo continua com onEnterConsumed — não passa por aqui).
                ret.onEnterConsumed = false;
                const tokDef = dragonTokenDef(ret.name);
                if (tokDef) {
                    ret.currentPower = base;
                    ret.isToken = !!target.isToken;
                }
                return ret;
            }

            /** Transição atômica: remove do campo e empilha na mão do dono. */
            function applyScareReturnToHand(targetP, targetI, cardSnap) {
                const owner = state.players[targetP];
                if (!owner) return null;
                const live = owner.field[targetI];
                const source = live || cardSnap;
                if (!source) return null;
                if (live) owner.field.splice(targetI, 1);
                const handCard = buildScareReturnHandCard(source);
                owner.hand.push(handCard);
                try { dfInvalidateQuadrantFp?.(targetP); } catch (e) { /* */ }
                window.__dfScareReturnActive = null;
                return handCard;
            }

            async function playScareReturnVisual(targetP, targetI, cardSnap, talentOwnerP, visualOpts = {}) {
                const isUltimate = !!visualOpts.ultimate;
                let applyingRemote = false;
                try { applyingRemote = !!dfOnlineApplyingRemote; } catch (e) { applyingRemote = false; }
                // MP: uma única animação de volta à mão (local + peer / double commit).
                if (window.__DF_ONLINE) {
                    try {
                        const sk = `scare:${targetP}|${targetI}|${cardSnap?.uid || cardSnap?.name || ""}`;
                        const now = Date.now();
                        if (window.__dfScareReturnKey === sk && (now - (window.__dfScareReturnAt | 0)) < 2200) {
                            return;
                        }
                        window.__dfScareReturnKey = sk;
                        window.__dfScareReturnAt = now;
                    } catch (eDedup) { /* */ }
                }
                // Sempre esconde o slot do campo antes do fly (vs-IA + MP):
                // evita duplicata (carta no campo + clone voando).
                const hideFieldFirst = true;
                {
                    window.__dfScareReturnActive = {
                        p: targetP, i: targetI, until: Date.now() + 4500,
                    };
                    const preEl = getChampionDom(targetP, targetI);
                    if (preEl) {
                        preEl.classList.add("scare-src-hidden", "combat-src-hidden");
                        preEl.style.setProperty("visibility", "hidden", "important");
                        preEl.style.setProperty("opacity", "0", "important");
                        preEl.style.setProperty("pointer-events", "none", "important");
                    }
                }
                if (!isUltimate && talentOwnerP != null) {
                    await dfAwaitTalentInPlay(talentOwnerP);
                    await dfHighlightMedoTalent(talentOwnerP, 360);
                }
                const live = state.players[targetP]?.field[targetI];
                const snap = cardSnap || (live ? dfScareCardSnapFromState(live) : null);
                if (!snap && !getChampionDom(targetP, targetI)) return;
                if (isUltimate) {
                    await playScareUltimateBeat(targetP, targetI);
                } else if (!hideFieldFirst) {
                    await playMedoFearBurst(targetP, targetI);
                } else {
                    try { window.sfx && window.sfx("scare"); } catch (e) { /* */ }
                    await wait(FX.mobile ? 180 : 240);
                }
                const handIdx = visualOpts.handInsertIdx != null
                    ? (visualOpts.handInsertIdx | 0)
                    : (state.players[targetP]?.hand?.length ?? 0);
                await animateChampionFlyToHand(targetP, targetI, snap, handIdx, visualOpts);
            }
            window.animateChampionFlyToHand = animateChampionFlyToHand;
            window.playScareReturnVisual = playScareReturnVisual;

            // SINISTRELA / AMEDRONTAR (ult) — mesmo efeito do talento Medo,
            // mas embutido na ult (sem activeTalent). Reusa a animação
            // aterrorizante do resolveTalentMedo.
            async function resolveScareReturn(casterP, targetP, targetI, skipVisual = false) {
                const target = state.players[targetP].field[targetI];
                if (!target) return;
                const targetSnap = cloneCard(target);
                if (!skipVisual) await playScareReturnVisual(targetP, targetI, targetSnap, casterP);
                applyScareReturnToHand(targetP, targetI, targetSnap);
                await new Promise((r) => requestAnimationFrame(r));
                updateUI({ immediate: true });
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    try {
                        await dfOnlineBroadcastVisualAwait({
                            kind: "scare_return",
                            targetP,
                            targetI,
                            cardSnap: targetSnap,
                            cardName: targetSnap?.name,
                            currentPower: targetSnap?.currentPower,
                            power: targetSnap?.power,
                        });
                    } catch (eScareVis) {
                        dfOnlineBroadcastVisual({
                            kind: "scare_return",
                            targetP,
                            targetI,
                            cardSnap: targetSnap,
                        });
                    }
                    dfOnlineBroadcastState();
                }
            }

            // PRINCESA SLIME — Travessura: escolhe o adversário com quem trocar.
            // Prioridade: Poder 2 > Poder 3+ > Poder 1. Aleatório dentro da banda.
            // A troca é sempre entre 2 jogadores (caster e um adversário).
            function pickTrickerySwapTarget(casterIdx) {
                const pow2 = [], pow3plus = [], pow1 = [];
                for (let ep = 0; ep < state.playersCount; ep++) {
                    if (ep === casterIdx) continue;
                    state.players[ep].field.forEach((c, i) => {
                        const pw = c.currentPower;
                        if (pw === 2) pow2.push({ p: ep, i });
                        else if (pw >= 3) pow3plus.push({ p: ep, i });
                        else if (pw === 1) pow1.push({ p: ep, i });
                    });
                }
                const pool = pow2.length ? pow2 : (pow3plus.length ? pow3plus : pow1);
                if (!pool.length) return null;
                return pool[Math.floor(Math.random() * pool.length)];
            }

            // Executa a troca de lugares: aliado (allyI no campo do caster) vai
            // pro slot do adversário, e o campeão adversário vem pro slot do
            // aliado. Limpa efeitos temporários que pertencem ao dono original
            // (freeAttack, escudo) — tapped/frozen/poder permanecem.
            function performTrickerySwap(casterIdx, allyI, enemyP, enemyI) {
                const a = state.players[casterIdx].field[allyI];
                const e = state.players[enemyP].field[enemyI];
                if (!a || !e) return;
                // Limpa efeitos que só fazem sentido pro dono original.
                for (const ch of [a, e]) {
                    ch.freeAttack = false;
                    if (!ch.shieldedPermanent) {
                        ch.shielded = false;
                        ch.shieldedTurns = 0;
                    }
                    // Guerra/Sobrepujar temporário pertence ao caster original.
                    ch.guerraBuff = false;
                    ch.guerraBuffTurns = 0;
                }
                state.players[casterIdx].field[allyI] = e;
                state.players[enemyP].field[enemyI] = a;
            }

            // ========= ULTIMATES CINEMATOGRÁFICAS — afetam a tela inteira =========
            //
            // Todas as Ultimates compartilham uma intro dramática:
            //   1. Vinheta de cor invade a tela inteira (tema da magia)
            //   2. Banner gigante com o nome da Ultimate + nome do herói
            //   3. Tremida na tela
            //   4. Efeito específico (meteoro / nevasca / vórtice / etc.)



            // ===== BOLA DE FOGO — meteoro descendo dos céus =====


            /** @deprecated mantido como alias — só Rei Bomba usa targetEnemy. */




            // ===== FORTALECER — chevron ▲ + aura verde emanando do campeão =====








            function prepTrickerySwapEl(el, r) {
                const mr = dfVfxMapRect(r);
                el.classList.add("trickery-swap-active");
                el.style.position = dfVfxPos();
                el.style.left = mr.left + "px";
                el.style.top = mr.top + "px";
                el.style.width = mr.width + "px";
                el.style.height = mr.height + "px";
                el.style.margin = "0";
                el.style.zIndex = "9700";
                el.style.pointerEvents = "none";
                el.style.transformOrigin = "center center";
                el.style.willChange = "transform, left, top";
            }
            function clearTrickerySwapEl(el) {
                el.classList.remove("trickery-swap-active");
                ["position", "left", "top", "width", "height", "margin", "zIndex",
                    "pointerEvents", "transform", "transformOrigin", "willChange", "filter"]
                    .forEach((p) => el.style.removeProperty(p));
            }
            async function playTrickerySwapVisual(allyP, allyI, enemyP, enemyI) {
                const allyEl = getChampionDom(allyP, allyI);
                const enemyEl = getChampionDom(enemyP, enemyI);
                if (!allyEl || !enemyEl) return;
                const ar = allyEl.getBoundingClientRect();
                const er = enemyEl.getBoundingClientRect();
                const arM = dfVfxMapRect(ar);
                const erM = dfVfxMapRect(er);
                const acx = ar.left + ar.width / 2;
                const acy = ar.top + ar.height / 2;
                const ecx = er.left + er.width / 2;
                const ecy = er.top + er.height / 2;
                prepTrickerySwapEl(allyEl, ar);
                prepTrickerySwapEl(enemyEl, er);
                const bg = document.createElement("div");
                bg.className = "trickery-swap-bg";
                dfVfxMount(bg);
                const mkPortal = (x, y, green) => {
                    const p = document.createElement("div");
                    p.className = "trickery-swap-portal" + (green ? " portal-green" : "");
                    dfVfxSetPoint(p, x, y);
                    dfVfxMount(p);
                    setTimeout(() => p.remove(), 920);
                    return p;
                };
                mkPortal(acx, acy, false);
                mkPortal(ecx, ecy, true);
                requestAnimationFrame(() => bg.classList.add("active"));
                try { document.getElementById("game")?.classList.add("df-trickery-tremor"); } catch (e) {}
                const DUR = FX.mobile ? 920 : 1080;
                const arcHeight = FX.mobile ? 110 : 140;
                const midT = Math.round(DUR * 0.48);
                const flashTimer = setTimeout(() => {
                    const flash = document.createElement("div");
                    flash.className = "trickery-swap-flash";
                    dfVfxMount(flash);
                    setTimeout(() => flash.remove(), 520);
                }, midT);
                const t0 = performance.now();
                await new Promise((resolve) => {
                    function step(now) {
                        const t = Math.min(1, (now - t0) / DUR);
                        const ease = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
                        const arc = Math.sin(Math.PI * ease) * arcHeight;
                        const scale = 1 + 0.1 * Math.sin(Math.PI * ease);
                        allyEl.style.left = (arM.left + (erM.left - arM.left) * ease) + "px";
                        allyEl.style.top = (arM.top + (erM.top - arM.top) * ease - arc) + "px";
                        allyEl.style.transform = `rotate(${ease * 16}deg) scale(${scale})`;
                        allyEl.style.filter =
                            "drop-shadow(0 0 14px rgba(200,100,255,0.9)) drop-shadow(0 0 28px rgba(200,100,255,0.55))";
                        enemyEl.style.left = (erM.left + (arM.left - erM.left) * ease) + "px";
                        enemyEl.style.top = (erM.top + (arM.top - erM.top) * ease - arc) + "px";
                        enemyEl.style.transform = `rotate(${-ease * 16}deg) scale(${scale})`;
                        enemyEl.style.filter =
                            "drop-shadow(0 0 14px rgba(90,255,170,0.9)) drop-shadow(0 0 28px rgba(90,255,170,0.55))";
                        if (t < 1) requestAnimationFrame(step);
                        else resolve();
                    }
                    requestAnimationFrame(step);
                });
                for (let i = 0; i < 14; i++) {
                    const sp = document.createElement("div");
                    sp.className = "trickery-swap-spark";
                    const t = i / 14;
                    sp.style.setProperty("--hue", i % 2 ? "285" : "145");
                    sp.style.animationDelay = (i * 35) + "ms";
                    dfVfxSetPoint(
                        sp,
                        acx + (ecx - acx) * t + (Math.random() - 0.5) * 28,
                        acy + (ecy - acy) * t + (Math.random() - 0.5) * 22,
                    );
                    setTimeout(() => sp.remove(), 980 + i * 35);
                }
                clearTimeout(flashTimer);
                try { document.getElementById("game")?.classList.remove("df-trickery-tremor"); } catch (e) {}
                clearTrickerySwapEl(allyEl);
                clearTrickerySwapEl(enemyEl);
                bg.classList.remove("active");
                setTimeout(() => bg.remove(), 320);
            }
            window.__dfPlayTrickerySwapVisual = playTrickerySwapVisual;







