            /**
             * Congelado 2× (Rajada / Zero Absoluto): cristal estilhaça e o campeão é destruído.
             * Diferente do freeze normal — impacto de destruição por gelo.
             */
            async function playFreezeShatterDestroyVisual(targetP, targetI, ctx = {}) {
                await ensureVfxReady();
                try { window.sfx && window.sfx("zero_absoluto"); } catch (e) { /* */ }
                const el = getChampionDom(targetP, targetI)
                    || (ctx?.preDomSnaps && window.dfFindPreDomSnap?.(ctx.preDomSnaps, targetP, targetI));
                let rect = el?.getBoundingClientRect?.();
                if (!(rect && rect.width > 2)) {
                    const vr = championVisualRect(targetP, targetI);
                    rect = { left: vr.left, top: vr.top, width: vr.width || 90, height: vr.height || 126 };
                }
                const cx = rect.left + rect.width / 2;
                const cy = rect.top + rect.height / 2;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playIceShatterDestroyScene === "function";
                if (gpu) {
                    try {
                        const ok = await window.DfPixiVfx.playIceShatterDestroyScene({
                            cx, cy, cinematic: true,
                            w: rect.width, h: rect.height,
                        });
                        if (ok) {
                            if (ctx?.preField) {
                                await playStandardDestroyVisual(targetP, targetI, ctx);
                            } else if (el) {
                                await triggerChampionShatter(el);
                            }
                            return;
                        }
                    } catch (e) { /* DOM abaixo */ }
                }
                // Fallback DOM: gelo → estilhaço → shatter do campeão
                const wash = document.createElement("div");
                const cp = dfVfxMap(cx, cy);
                const pos = dfVfxPos();
                wash.style.cssText = "position:" + pos + ";inset:0;background:radial-gradient(circle at " + cp.x + "px " + cp.y + "px, rgba(180,230,255,0.55), rgba(40,120,200,0.22) 35%, transparent 62%);pointer-events:none;z-index:9997;opacity:0;transition:opacity .15s";
                wash.dataset.dfVfxMapped = "1";
                dfVfxMount(wash);
                requestAnimationFrame(() => { wash.style.opacity = "1"; });
                const crystal = document.createElement("div");
                crystal.style.cssText = "transform:translate(-50%,-50%) scale(0.3) rotate(-12deg);background:linear-gradient(145deg,rgba(230,250,255,0.98),rgba(100,180,240,0.88) 55%,rgba(40,110,190,0.92));clip-path:polygon(18% 0,82% 6%,100% 28%,92% 78%,70% 100%,28% 100%,4% 72%,0 28%);border:3px solid rgba(220,245,255,0.95);box-shadow:0 0 50px 14px rgba(140,210,255,0.9),inset 0 0 28px rgba(255,255,255,0.55);pointer-events:none;z-index:9999;opacity:0.95;transition:transform .4s cubic-bezier(.2,.9,.3,1)";
                dfVfxPlaceBox(crystal, cx - rect.width * 0.65, cy - rect.height * 0.65, rect.width * 1.3, rect.height * 1.3);
                await wait(380);
                crystal.style.transition = "transform .22s ease-in, opacity .22s ease-in";
                crystal.style.transform = "translate(-50%,-50%) scale(1.55) rotate(18deg)";
                crystal.style.opacity = "0";
                for (let i = 0; i < 22; i++) {
                    const shard = document.createElement("div");
                    shard.textContent = ["❄️", "❅", "✦"][i % 3];
                    shard.style.cssText = "font-size:" + (0.85 + Math.random() * 1.2) + "rem;color:#dff6ff;text-shadow:0 0 10px #9ad8ff;pointer-events:none;z-index:10000;opacity:1;transition:transform .85s ease-out, opacity .85s ease-out";
                    dfVfxSetPoint(shard, cx, cy);
                    const ang = Math.random() * Math.PI * 2;
                    const dist = 80 + Math.random() * 140;
                    requestAnimationFrame(() => {
                        shard.style.transform = "translate(" + (Math.cos(ang) * dist) + "px," + (Math.sin(ang) * dist - 20) + "px) rotate(" + ((Math.random() - 0.5) * 400) + "deg)";
                        shard.style.opacity = "0";
                    });
                    setTimeout(() => shard.remove(), 900);
                }
                DfAnim.spawnParticles(cx, cy, FX.n(14));
                const q = document.getElementById(`quadrant-${dfQuadrantForPlayer(targetP)}`);
                if (q) {
                    q.classList.add("ground-tremor");
                    setTimeout(() => q.classList.remove("ground-tremor"), 700);
                }
                await wait(320);
                crystal.remove();
                wash.style.opacity = "0";
                setTimeout(() => wash.remove(), 220);
                if (ctx?.preField) {
                    await playStandardDestroyVisual(targetP, targetI, ctx);
                } else if (el) {
                    await triggerChampionShatter(el);
                    await wait(420);
                } else {
                    await wait(280);
                }
            }

            // FORTALECER — projétil verde origem→alvo + burst stylized (DfSpriteVfx).
            async function animateStrongArm(targetP, targetI, opts = {}) {
                if (!dfMatchAlive()) return;
                try { window.sfx && window.sfx("buff_power"); } catch (e) {}
                const targetUid = state.players[targetP]?.field?.[targetI]?.uid ?? null;
                const resolveEl = () => getChampionDom(targetP, targetI)
                    || (targetUid ? document.querySelector(`.ccard[data-uid="${targetUid}"]`) : null);
                let el = resolveEl();
                if (!el || !(el.getBoundingClientRect?.().width > 2)) {
                    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                    el = resolveEl();
                }
                if (!el || !(el.getBoundingClientRect?.().width > 2)) {
                    try { updateUI({ immediate: true }); } catch (e) { /* */ }
                    await new Promise((r) => requestAnimationFrame(r));
                    el = resolveEl();
                }
                let anchorRect = el?.getBoundingClientRect?.();
                if (!(anchorRect && anchorRect.width > 2)) {
                    anchorRect = dfChampionAnchorRect(targetP, targetI);
                }
                const targetAnchor = anchorRect && anchorRect.width > 2
                    ? {
                        x: anchorRect.left + anchorRect.width / 2,
                        y: anchorRect.top + anchorRect.height * 0.46,
                    }
                    : null;
                await ensureVfxReady();
                if (!opts.forceDomFallback && !opts.fromTalent) {
                    try {
                        // MP: orçamento curto — waitFull 10s na habilidade com mira
                        // congelava a página ("Página sem resposta"). Mas 900ms era
                        // curto demais: o Pixi frio nunca ficava pronto e a animação
                        // simplesmente não aparecia no online. Com o pré-aquecimento
                        // em dfPrewarmVfxEngine este await resolve na hora, e o teto
                        // maior só serve de rede de segurança.
                        const cinMs = window.__DF_ONLINE ? 3000 : 10000;
                        await window.DfVfxEngine?.ensureCinematicReady?.({
                            waitFull: true,
                            maxMs: cinMs,
                        });
                    } catch (e) { /* */ }
                }
                let pixiOk = false;
                if (window.DfSpriteVfx?.playFortify && !opts.forceDomFallback) {
                    try {
                        const ok = await DfSpriteVfx.playFortify({
                            targetP,
                            targetI,
                            targetUid,
                            targetAnchor,
                            casterP: opts.casterP ?? targetP,
                            casterField: opts.casterField ?? -1,
                            fromTalent: !!opts.fromTalent,
                            premium: !opts.fromTalent,
                        });
                        pixiOk = ok !== false;
                        // Campeão/ultimate: Pixi basta. Talento: sempre splash DOM de reforço.
                        if (pixiOk && !opts.fromTalent) return;
                    } catch (e) {
                        console.warn("[DF] playFortify falhou", e);
                        pixiOk = false;
                    }
                } else if (window.DfSpriteVfx?.playFortify) {
                    try {
                        await DfSpriteVfx.playFortify({
                            targetP,
                            targetI,
                            targetUid,
                            targetAnchor,
                            casterP: opts.casterP ?? targetP,
                            casterField: opts.casterField ?? -1,
                            fromTalent: !!opts.fromTalent,
                            premium: !opts.fromTalent,
                        });
                    } catch (e) { /* */ }
                }
                el = resolveEl() || el;
                if (el) {
                    const r = el.getBoundingClientRect();
                    const cx = r.left + r.width / 2;
                    const cy = r.top + r.height / 2;
                    const emoji = document.createElement("div");
                    emoji.className = "df-fortify-emoji-splash";
                    emoji.textContent = "💪";
                    emoji.style.cssText =
                        `position:fixed;left:${cx}px;top:${cy - 24}px;transform:translate(-50%,-50%);` +
                        `z-index:98600;pointer-events:none;font-size:2.4rem;` +
                        `filter:drop-shadow(0 0 12px rgba(80,255,140,0.9));`;
                    document.body.appendChild(emoji);
                    el.classList.add("df-fortify-flash");
                    setTimeout(() => {
                        try { emoji.remove(); } catch (e) { /* */ }
                        try { el.classList.remove("df-fortify-flash"); } catch (e) { /* */ }
                    }, 900);
                    await wait(720);
                    return;
                }
                if (pixiOk) return;
                await wait(400);
            }

