            // DOPPELGANGER — raio vermelho conecta o original à cópia recém-invocada.
            async function animateDoppelgangerClone(ownerP, srcIdx, newIdx) {
                const srcEl = getChampionDom(ownerP, srcIdx);
                const newEl = getChampionDom(ownerP, newIdx);
                if (!srcEl || !newEl) { await wait(800); return; }
                const rs = srcEl.getBoundingClientRect();
                const rn = newEl.getBoundingClientRect();
                const sx = rs.left + rs.width / 2, sy = rs.top + rs.height / 2;
                const nx = rn.left + rn.width / 2, ny = rn.top + rn.height / 2;
                newEl.style.opacity = "0";
                newEl.style.transform = "scale(0.35)";
                const bolt = document.createElement("div");
                bolt.className = "doppel-bolt";
                const ang = Math.atan2(ny - sy, nx - sx) * 180 / Math.PI;
                const len = Math.hypot(nx - sx, ny - sy);
                dfVfxSetPoint(bolt, sx, sy);
                bolt.style.width = len + "px";
                bolt.style.transform = `rotate(${ang}deg)`;
                const ring = document.createElement("div");
                ring.className = "doppel-clone-ring";
                dfVfxSetPoint(ring, nx, ny);
                try { window.sfx && window.sfx("explosao"); } catch (e) {}
                await wait(420);
                newEl.style.transition = "opacity 520ms ease, transform 620ms cubic-bezier(.2,1.2,.3,1)";
                newEl.style.opacity = "1";
                newEl.style.transform = "scale(1)";
                newEl.classList.add("doppel-clone-spawn");
                await wait(720);
                bolt.remove();
                ring.remove();
                srcEl.classList.remove("doppel-source");
                newEl.classList.remove("doppel-clone-spawn");
                newEl.style.transition = "";
                newEl.style.transform = "";
            }

