            // TROCA INJUSTA (Cavaleira Brinquedo) — dois campeões trocam de lugar em arco.
            async function animateTrocaInjusta(casterP, cavIdx, enemyP, enemyI, preRects) {
                try { window.sfx && window.sfx("potion"); } catch (e) {}
                let allyEl = getChampionDom(casterP, cavIdx);
                let enemyEl = getChampionDom(enemyP, enemyI);
                // Peer MP: após reconcile os índices ainda apontam aos slots; retry curto.
                if ((!allyEl || !enemyEl) && window.__DF_ONLINE) {
                    for (let n = 0; n < 8 && (!allyEl || !enemyEl); n++) {
                        await wait(40);
                        allyEl = getChampionDom(casterP, cavIdx);
                        enemyEl = getChampionDom(enemyP, enemyI);
                    }
                }
                let ax, ay, ex, ey, W, H;
                if (preRects?.ally && preRects?.enemy) {
                    ax = preRects.ally.x; ay = preRects.ally.y;
                    ex = preRects.enemy.x; ey = preRects.enemy.y;
                    W = Math.min(preRects.ally.w || 80, preRects.enemy.w || 80) * 0.85;
                    H = Math.min(preRects.ally.h || 110, preRects.enemy.h || 110) * 0.85;
                } else if (allyEl && enemyEl) {
                    const ra = allyEl.getBoundingClientRect();
                    const re = enemyEl.getBoundingClientRect();
                    ax = ra.left + ra.width / 2; ay = ra.top + ra.height / 2;
                    ex = re.left + re.width / 2; ey = re.top + re.height / 2;
                    W = Math.min(ra.width, re.width) * 0.85;
                    H = Math.min(ra.height, re.height) * 0.85;
                } else {
                    await wait(600);
                    return;
                }
                if (allyEl) {
                    try {
                        allyEl.classList.add("combat-src-hidden");
                        allyEl.style.visibility = "hidden";
                    } catch (eH) { /* */ }
                }
                if (enemyEl) {
                    try {
                        enemyEl.classList.add("combat-src-hidden");
                        enemyEl.style.visibility = "hidden";
                    } catch (eH2) { /* */ }
                }
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playTrocaInjustaScene === "function";
                if (gpu) {
                    const ran = await window.DfPixiVfx.playTrocaInjustaScene({
                        ax, ay, bx: ex, by: ey, cinematic: true,
                    });
                    if (allyEl) {
                        try {
                            allyEl.classList.remove("combat-src-hidden");
                            allyEl.style.visibility = "";
                        } catch (eS) { /* */ }
                    }
                    if (enemyEl) {
                        try {
                            enemyEl.classList.remove("combat-src-hidden");
                            enemyEl.style.visibility = "";
                        } catch (eS2) { /* */ }
                    }
                    if (ran) return;
                }
                const sky = document.createElement("div");
                sky.className = "troca-sky";
                dfVfxMount(sky);
                const g1 = document.createElement("div");
                g1.className = "troca-ghost";
                g1.textContent = "🪀";
                dfVfxPlaceBox(g1, ax - W / 2, ay - H / 2, W, H);
                const g2 = document.createElement("div");
                g2.className = "troca-ghost";
                g2.textContent = "♞";
                dfVfxPlaceBox(g2, ex - W / 2, ey - H / 2, W, H);
                const T0 = performance.now();
                const DUR = 1000;
                const arcHeight = 140;
                await new Promise(resolve => {
                    function step(now) {
                        const t = Math.min(1, (now - T0) / DUR);
                        const cx1 = ax + (ex - ax) * t;
                        const cy1 = ay + (ey - ay) * t - Math.sin(Math.PI * t) * arcHeight;
                        const cx2 = ex + (ax - ex) * t;
                        const cy2 = ey + (ay - ey) * t - Math.sin(Math.PI * t) * arcHeight;
                        dfVfxPlaceBox(g1, cx1 - W / 2, cy1 - H / 2, W, H);
                        g1.style.transform = `rotate(${t * 360}deg) scale(${0.8 + 0.3 * Math.sin(Math.PI * t)})`;
                        dfVfxPlaceBox(g2, cx2 - W / 2, cy2 - H / 2, W, H);
                        g2.style.transform = `rotate(${-t * 360}deg) scale(${0.8 + 0.3 * Math.sin(Math.PI * t)})`;
                        if (t < 1) requestAnimationFrame(step); else resolve();
                    }
                    requestAnimationFrame(step);
                });
                const poof = document.createElement("div");
                poof.className = "troca-poof";
                dfVfxPlaceBox(poof, (ax + ex) / 2 - 40, (ay + ey) / 2 - 40, 80, 80);
                g1.remove(); g2.remove();
                await wait(400);
                poof.remove();
                if (allyEl) {
                    try {
                        allyEl.classList.remove("combat-src-hidden");
                        allyEl.style.visibility = "";
                    } catch (eS3) { /* */ }
                }
                if (enemyEl) {
                    try {
                        enemyEl.classList.remove("combat-src-hidden");
                        enemyEl.style.visibility = "";
                    } catch (eS4) { /* */ }
                }
                sky.classList.add("fade-out");
                setTimeout(() => sky.remove(), 500);
            }

            // IMPACTO de entrada — campeão "salta" e cai com onda de choque,
            // tremida no quadrante e fagulhas. Usado em TODA invocação.
            async function championLandImpact(pIdx, fIdx) {
                const el = getChampionDom(pIdx, fIdx);
                if (!el) return;
                // GPU summon já fez impacto Pixi — só trava o slot, sem tremor/emoji.
                if (window.DfVfxEngine?.wantsGpuPresentation?.()) {
                    window.dfScheduleFieldRowLock?.(el);
                    return;
                }
                const rect = el.getBoundingClientRect();
                const cx = rect.left + rect.width / 2;
                const cy = rect.top + rect.height / 2;
                const shockRect = { left: cx - 120, top: cy, width: 240, height: 60 };

                const shock = document.createElement("div");
                shock.className = "land-shockwave";
                dfVfxPlaceRect(shock, shockRect);
                const shock2 = document.createElement("div");
                shock2.className = "land-shockwave shock2";
                dfVfxPlaceRect(shock2, shockRect);
                DfAnim.spawnBurst(FX.n(6), "land-dust", (p, i) => {
                    p.textContent = i % 2 === 0 ? "✨" : "💨";
                    const dustX = cx + (Math.random() - 0.5) * 160;
                    const dustY = cy + 30;
                    p.style.left = dustX + "px";
                    p.style.top = dustY + "px";
                    p.style.setProperty("--px", ((Math.random() - 0.5) * 160) + "px");
                    p.style.setProperty("--py", (Math.random() * -60 - 10) + "px");
                }, 900, () => {
                    const d = document.createElement("div");
                    d.className = "land-dust";
                    return d;
                });
                setTimeout(() => { shock.remove(); shock2.remove(); }, 900);

                const q = document.getElementById(`quadrant-${pIdx}`);
                if (q && !window.DfVfxEngine?.wantsGpuPresentation?.()) {
                    q.classList.add("ground-tremor");
                    setTimeout(() => q.classList.remove("ground-tremor"), 360);
                }

                if (!FX.mobile) {
                    window.dfScheduleFieldRowLock?.(el);
                    return;
                }

                el.classList.add("land-impact");
                await wait(280);
                el.classList.remove("land-impact");
                window.dfScheduleFieldRowLock?.(el);
            }

            // DESTRUIÇÃO — explosão fantasiosa: o campeão racha em estilhaços
            // brilhantes, halo dourado, flash e partículas voando. Recompensa
            // visual para quem destruiu, sem nada violento.


            // DEVORAR — presas fechando no alvo; destruição padrão no impacto (on-enter) ou após (targeting).
            async function animateDevour(targetP, targetI, ctx = {}) {
                await ensureVfxReady();
                const uid = ctx.preField?.[targetP]?.[targetI]?.uid;
                const snap = (uid && ctx.preDomSnaps?.get(uid))
                    || dfCaptureFieldCardSnap(targetP, targetI);
                const tr = snap
                    ? { left: snap.left, top: snap.top, width: snap.width, height: snap.height }
                    : championVisualRect(targetP, targetI);
                if (!tr || tr.width < 4) {
                    if (ctx.preField) await playStandardDestroyVisual(targetP, targetI, ctx);
                    return;
                }
                const cx = snap?.cx ?? (tr.left + tr.width / 2);
                const cy = snap?.cy ?? (tr.top + tr.height / 2);
                const destroyOnImpact = !!(ctx.preField || ctx.destroyOnImpact);
                let destroyPromise = null;
                let impactCalled = false;
                const runDestroy = () => {
                    if (impactCalled) return destroyPromise;
                    impactCalled = true;
                    if (typeof ctx.onImpactState === "function") {
                        try { ctx.onImpactState(); } catch (e) { /* */ }
                    }
                    destroyPromise = playStandardDestroyVisual(targetP, targetI, ctx);
                    return destroyPromise;
                };
                try { window.sfx?.("devour"); } catch (e) { /* */ }
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playDevourScene === "function";
                if (gpu) {
                    let ok = false;
                    try {
                        ok = await Promise.race([
                            window.DfPixiVfx.playDevourScene({
                                cx, cy, local: true, cinematic: true,
                                onImpact: destroyOnImpact ? () => { runDestroy(); } : undefined,
                            }),
                            wait(FX.mobile ? 2200 : 2800).then(() => false),
                        ]);
                    } catch (e) { ok = false; }
                    if (ok) {
                        if (destroyOnImpact && !impactCalled) runDestroy();
                        if (destroyPromise) await destroyPromise;
                        return;
                    }
                }
                const el = getChampionDom(targetP, targetI);
                if (el?.isConnected) {
                    el.style.transition = "filter .18s ease-out, transform .18s ease-out";
                    el.style.filter = "drop-shadow(0 0 20px rgba(255,48,72,0.95))";
                    el.style.transform = "scale(0.9)";
                    await wait(320);
                    el.style.filter = "";
                    el.style.transform = "";
                }
                if (destroyOnImpact) await runDestroy();
            }

            async function animateAxe(targetP, targetI) { try { window.sfx && window.sfx("bomb"); } catch (e) {}
                const el = getChampionDom(targetP, targetI); if (!el) return;
                const rect = el.getBoundingClientRect(); const axe = document.createElement("div");
                axe.className = "axe-anim";
                axe.textContent = "🪓";
                dfVfxPlaceBox(
                    axe,
                    rect.left + rect.width / 2 - 22,
                    rect.top - 16,
                    44, 44,
                );
                await wait(1200);
                axe.remove(); }

            // Feedback FORTE quando o jogador tenta jogar uma carta sem ter
            // pontos de ação suficientes. Sacode os pontos do cabeçalho do
            // jogador (com pulso vermelho), sacode a carta da mão que ele
            // tentou jogar, mostra um banner grande no centro da tela e dá
            // um log explicativo. A intenção é ENSINAR o jogador que ele
            // precisa olhar os pontos de ação antes de jogar.
            function flashInsufficientActions(needed, have, handIdx) {
                const qIdx = dfQuadrantForPlayer(dfHumanSeat());
                const q = document.getElementById(`quadrant-${qIdx}`);
                const dotsEl = q?.querySelector(".action-dots");
                if (dotsEl) {
                    dotsEl.classList.remove("shake");
                    void dotsEl.offsetWidth;
                    dotsEl.classList.add("shake");
                    setTimeout(() => dotsEl.classList.remove("shake"), 600);
                    dotsEl.querySelectorAll(".dot").forEach(d => {
                        d.classList.remove("insufficient");
                        void d.offsetWidth;
                        d.classList.add("insufficient");
                        setTimeout(() => d.classList.remove("insufficient"), 1900);
                    });
                }
                // Sacode a carta da mão correspondente
                if (typeof handIdx === "number") {
                    const handDiv = q?.querySelector(".quadrant-hand");
                    const wraps = handDiv?.querySelectorAll(".hand-wrap");
                    const w = wraps?.[handIdx];
                    if (w) {
                        w.classList.remove("insufficient-shake");
                        void w.offsetWidth;
                        w.classList.add("insufficient-shake");
                        setTimeout(() => w.classList.remove("insufficient-shake"), 550);
                    }
                }
                // Banner grande no centro da tela
                document.querySelectorAll(".insufficient-banner").forEach(el => el.remove());
                const banner = document.createElement("div");
                banner.className = "insufficient-banner";
                banner.innerHTML =
                    `<div class="ib-title">⚡ Sem Pontos de Ação</div>` +
                    `<div class="ib-sub">Precisa de <b>${needed}</b> • Você tem <b>${have}</b></div>`;
                dfVfxMount(banner);
                setTimeout(() => banner.remove(), 1700);
                log(`⚡ Precisa de ${needed} pontos de ação (você tem ${have}).`);
                try { window.__dfSyncActionsPedestalForce?.(); } catch (e) { /* */ }
            }

            // Banner grande e contundente, reutilizado pelas regras do
            // Resistente (Come Pedra / Guardião da Chave). Mesmo estilo do
            // banner de "ações insuficientes" pra manter linguagem visual.
            // =========================================================
            // REATIVA: Bloquear Ataque
            // =========================================================
            // "Bloquear Ataque" é a ÚNICA carta que pode ser usada fora do
            // turno do dono. Chamada do topo de resolveCombat. Se o dono do
            // defensor tem a carta na mão:
            //   - Humano: overlay com a carta em evidência + Sim/Não +
            //     barra de 4s. Sem resposta = ataque prossegue.
            //   - IA: aiShouldReactiveBlock decide (bloqueia ataques que
            //     matariam um campeão valioso).
            // Se bloqueado, a carta vai pro descarte AGORA e resolveCombat
            // retorna. O atacante já gastou a ação antes dessa chamada
            // (humano: confirmEnter/finishDrag; IA: aiTakeTurn), então
            // ele perde a ação "à toa" conforme regra do usuário.
            async function offerReactiveBlock(attOwner, defOwner, attacker, defender, opts = {}) {
                if (attOwner === defOwner) return false;
                const defP = state.players[defOwner];
                if (!defP) return false;
                // Prompt remoto do peer: permitir mesmo com applyingRemote no envelope.
                if (dfOnlineApplyingRemote && !opts.allowRemotePrompt) return false;
                const handIdx = defP.hand.findIndex(c => c && c.talentEffect === "bloquearAtaque");
                if (handIdx < 0) return false;

                // "Tell" pré-prompt: o atacante brilha vermelho e cresce,
                // o defensor encolhe — pedido do usuário: ação do adversário
                // aparece "incompleta" antes da resposta defensiva.
                await animateReactiveTell(attOwner, attacker, defOwner, defender, "block");

                if (defP.isAI) {
                    if (!aiShouldReactiveBlock(attacker, defender)) return false;
                    const card = defP.hand.splice(handIdx, 1)[0];
                    // Descarte IMEDIATO conforme regra do usuário ("é descartada
                    // na hora"). A exibição via activeTalent é só visual: a
                    // carta já está no descarte enquanto fica em evidência.
                    pushDiscard(defOwner, card);
                    state.activeTalent = { ownerP: defOwner, card };
                    log(`${defP.name} usou Bloquear Ataque — ataque cancelado!`);
                    flashRuleBanner("🛡️ Ataque Bloqueado!", `${defP.name} usou Bloquear Ataque.`);
                    updateUI();
                    // Beat 1: animação "ATAQUE BLOQUEADO" SOBRE o defensor,
                    // pra ficar explícito que o ataque foi anulado antes
                    // da carta sair de cena.
                    await animateBlockedAttack(defOwner, defender);
                    // Beat 2: carta visível em evidência (leitura). Reduzido
                    // de 1500 → 600 porque a animação acima já segura ~850.
                    await wait(600);
                    // Beat 3: carta voa pro descarte (leitura "foi descartada")
                    await flyActiveTalentToDiscard(defOwner);
                    state.activeTalent = null;
                    updateUI();
                    return true;
                }
                return await showHumanBlockPrompt(defOwner, handIdx, attOwner, attacker, defender);
            }

            /** Arte de carta para overlays de reação (composed / portrait / WebP). */
            function dfReactivePromptArtUrl(cardName) {
                const name = String(cardName || "");
                if (!name) return "";
                try {
                    if (window.DfCardFace?.isComposed?.(name)) {
                        const du = window.DfCardFace.getFaceDataUrl?.(name);
                        if (du) return du;
                    }
                } catch (e) { /* */ }
                try {
                    const primary = window.dfPrimaryCardArtSrc?.(name);
                    if (primary) return primary;
                } catch (e) { /* */ }
                try {
                    const urls = window.dfResolveCardArtUrls?.(name);
                    if (urls && urls[0]) return urls[0];
                } catch (e) { /* */ }
                const file = name.replace(/ /g, "_");
                const rel = `cards/portraits/${file}.png`;
                return typeof window.dfAssetUrl === "function" ? window.dfAssetUrl(rel) : `cards/portraits/${file}.webp`;
            }

            function showHumanBlockPrompt(defOwner, handIdx, attOwner, attacker, defender) {
                return new Promise((resolve) => {
                    if (window.__DF_ONLINE && !dfIsLocalPlayer(defOwner)) {
                        resolve(false);
                        return;
                    }
                    const overlay = $("block-overlay");
                    if (!overlay) { resolve(false); return; }
                    const prevPhase = gamePhase;
                    gamePhase = "reactive-block";
                    const attName = attacker?.name || "Atacante";
                    const defName = defender?.name || "Defensor";
                    const attPow = attacker?.currentPower ?? attacker?.power ?? "?";
                    const defPow = defender?.currentPower ?? defender?.power ?? "?";
                    // Painel responsivo: cabe em telas pequenas sem cortar.
                    // `min(440px, 92vw)` impede transbordo no celular e
                    // `max-height:92vh + overflow:auto` garante rolagem
                    // se a tela for muito baixa. Carta interna usa clamp
                    // pra encolher proporcionalmente.
                    // Botões reativos: sobrescrevem o `min-width:280px` do
                    // `.menu-btn` (que faria os 2 botões SIM/NÃO somarem
                    // 560px+ e estourar o painel mobile). Aqui cada botão
                    // ocupa 1fr do grid de 2 colunas e cabe sempre dentro.
                    const blockArt = dfReactivePromptArtUrl("BLOQUEAR ATAQUE");
                    overlay.innerHTML =
                        '<div class="panel" style="width:min(440px,92vw);max-width:92vw;max-height:92vh;overflow-x:hidden;overflow-y:auto;text-align:center;padding:14px;box-sizing:border-box">' +
                            '<div style="font-size:0.95rem;color:#ffd76b;margin-bottom:6px">⚡ Reação: BLOQUEAR ATAQUE</div>' +
                            '<img src="' + blockArt + '" alt="Bloquear Ataque" class="reactive-card-img" draggable="false">' +
                            '<div style="font-size:0.88rem;color:#e9d8ff;margin-bottom:6px;line-height:1.35">' +
                                '<b style="color:#ff8585">' + attName + '</b> (Poder ' + attPow + ') está atacando ' +
                                '<b style="color:#8fffae">' + defName + '</b> (Poder ' + defPow + ').' +
                            '</div>' +
                            '<div style="font-size:1rem;color:#fff;margin:8px 0 6px"><b>Deseja Bloquear esse ataque?</b></div>' +
                            '<div style="height:6px;background:#241830;border-radius:3px;overflow:hidden;margin:6px 0 10px">' +
                                '<div id="block-progress-bar" style="height:100%;width:100%;background:linear-gradient(90deg,#ffd76b,#ff8585);transition:width 100ms linear"></div>' +
                            '</div>' +
                            '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;box-sizing:border-box">' +
                                '<button id="block-yes" class="menu-btn" style="background:#2a6a3a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">SIM</button>' +
                                '<button id="block-no" class="menu-btn" style="background:#6a2a2a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">NÃO</button>' +
                            '</div>' +
                        '</div>';
                    overlay.classList.add("active");
                    window.applyCardArtTree?.(overlay);
                    window.dfRewriteDomAssets?.(overlay);

                    const DURATION = 5000;
                    const startT = performance.now();
                    let done = false;
                    const bar = overlay.querySelector("#block-progress-bar");
                    const tick = () => {
                        if (done) return;
                        const elapsed = performance.now() - startT;
                        const pct = Math.max(0, 1 - elapsed / DURATION);
                        if (bar) bar.style.width = (pct * 100).toFixed(1) + "%";
                        if (elapsed >= DURATION) { finish(false); return; }
                        requestAnimationFrame(tick);
                    };
                    // `finish` é async pra rodar as MESMAS animações
                    // reativas que o caminho da IA usa (impacto sobre o
                    // defensor + carta voando pro descarte). Os listeners
                    // chamam `finish(true/false)` sem aguardar — o Promise
                    // externo só resolve quando a sequência inteira acaba,
                    // o que mantém resolveCombat/ultimates pausados até lá.
                    const finish = async (blocked) => {
                        if (done) return;
                        done = true;
                        overlay.classList.remove("active");
                        overlay.innerHTML = "";
                        gamePhase = prevPhase;
                        if (blocked) {
                            const defP = state.players[defOwner];
                            const stillThere = defP.hand[handIdx]?.talentEffect === "bloquearAtaque"
                                ? handIdx
                                : defP.hand.findIndex(c => c && c.talentEffect === "bloquearAtaque");
                            if (stillThere >= 0) {
                                const card = defP.hand.splice(stillThere, 1)[0];
                                pushDiscard(defOwner, card);
                                state.activeTalent = { ownerP: defOwner, card };
                            }
                            log("🛡️ Você bloqueou o ataque!");
                            flashRuleBanner("🛡️ Ataque Bloqueado!", "O atacante perdeu a ação que gastou.");
                            updateUI();
                            // MP: resolve antes das animas — ANSWER precisa sair antes do timeout do atacante.
                            if (window.__DF_ONLINE) {
                                resolve(true);
                                void (async () => {
                                    try {
                                        await animateBlockedAttack(defOwner, defender);
                                        await flyActiveTalentToDiscard(defOwner);
                                    } catch (e) { /* */ }
                                    state.activeTalent = null;
                                    updateUI();
                                })();
                                return;
                            }
                            await animateBlockedAttack(defOwner, defender);
                            await flyActiveTalentToDiscard(defOwner);
                            state.activeTalent = null;
                            updateUI();
                        } else {
                            log("Você não bloqueou o ataque.");
                            updateUI();
                        }
                        resolve(blocked);
                    };
                    overlay.querySelector("#block-yes")?.addEventListener("click", () => finish(true));
                    overlay.querySelector("#block-no")?.addEventListener("click", () => finish(false));
                    requestAnimationFrame(tick);
                });
            }



            // =============================================================
            // PROTEÇÃO DIVINA (reativa) — dispara automaticamente quando um
            // Campeão do defensor sofreria redução de Poder (Bola de Fogo,
            // Assassinar, Bomba Explosiva, qualquer Ultimate "targetEnemy",
            // etc.). Funciona em paralelo com Bloquear Ataque: aquela cobre
            // ATAQUES (combate); esta cobre REDUÇÕES de Poder. Quando "Sim",
            // a redução é cancelada e a carta vai pro descarte na hora.
            // =============================================================
            async function offerReactiveProtection(attOwner, defOwner, defender, sourceLabel, isUltimate, opts = {}) {
                if (attOwner === defOwner) return false;
                // REGRA NOVA (a pedido do usuário): Proteção Divina NÃO
                // bloqueia mais redução de Poder vinda de qualquer Ultimate
                // (Fogo e Gelo do Jekiro, Bola de Fogo da Estrelar como
                // Ultimate, etc.). Continua valendo pra efeitos NÃO-Ultimate
                // (carta Bola de Fogo, Assassinar, Bomba Explosiva, etc.).
                if (isUltimate) return false;
                const defP = state.players[defOwner];
                if (!defP) return false;
                // Prompt remoto do peer: permitir mesmo com applyingRemote no envelope.
                if (dfOnlineApplyingRemote && !opts.allowRemotePrompt) return false;

                // MP: fog-of-war — só o holder vê a mão; caster consulta o peer.
                if (window.__DF_ONLINE) {
                    await animateReactiveTell(attOwner, null, defOwner, defender, "protect");
                    if (dfIsLocalPlayer(defOwner)) {
                        const handIdx = defP.hand.findIndex(c => c && c.talentEffect === "protecaoDivina");
                        if (handIdx < 0) return false;
                        return await showHumanProtecaoDivinaPrompt(defOwner, handIdx, defender, sourceLabel);
                    }
                    if (!dfIsLocalPlayer(attOwner)) return false;
                    return await dfOnlineResolveReactiveProtect(
                        attOwner, defOwner, defender, sourceLabel, isUltimate,
                    );
                }

                const handIdx = defP.hand.findIndex(c => c && c.talentEffect === "protecaoDivina");
                if (handIdx < 0) return false;

                // "Tell" pré-prompt: o defensor brilha dourado, sinalizando
                // a redução iminente — pedido do usuário: efeito adversário
                // aparece "incompleto" antes da resposta defensiva.
                await animateReactiveTell(attOwner, null, defOwner, defender, "protect");

                if (defOwner !== 0) {
                    if (!aiShouldReactiveProtect(defender)) return false;
                    const card = defP.hand.splice(handIdx, 1)[0];
                    pushDiscard(defOwner, card);
                    state.activeTalent = { ownerP: defOwner, card };
                    log(`${defP.name} usou Proteção Divina — redução cancelada!`);
                    flashRuleBanner("✨ Proteção Divina!", `${defP.name} protegeu ${defender.name || "seu Campeão"}.`);
                    updateUI();
                    // Mesmo padrão da Bloquear: visual de "PROTEGIDO!"
                    // SOBRE o defensor antes da carta voar pro descarte.
                    await animateDivineProtection(defOwner, defender);
                    // Carta em evidência (encurtado de 1500 → 600 porque
                    // a animação acima já segura ~850ms).
                    await wait(600);
                    await flyActiveTalentToDiscard(defOwner);
                    state.activeTalent = null;
                    updateUI();
                    return true;
                }
                return await showHumanProtecaoDivinaPrompt(0, handIdx, defender, sourceLabel);
            }

            function showHumanProtecaoDivinaPrompt(defOwner, handIdx, defender, sourceLabel) {
                return new Promise((resolve) => {
                    if (window.__DF_ONLINE && !dfIsLocalPlayer(defOwner)) {
                        resolve(false);
                        return;
                    }
                    const overlay = $("block-overlay");
                    if (!overlay) { resolve(false); return; }
                    const prevPhase = gamePhase;
                    gamePhase = "reactive-block";
                    const defName = defender?.name || "seu Campeão";
                    const defPow = defender?.currentPower ?? defender?.power ?? "?";
                    const src = sourceLabel || "Redução de Poder";
                    const protArt = dfReactivePromptArtUrl("PROTEÇÃO DIVINA");
                    overlay.innerHTML =
                        '<div class="panel" style="width:min(440px,92vw);max-width:92vw;max-height:92vh;overflow-x:hidden;overflow-y:auto;text-align:center;padding:14px;box-sizing:border-box">' +
                            '<div style="font-size:0.95rem;color:#ffd76b;margin-bottom:6px">⚡ Reação: PROTEÇÃO DIVINA</div>' +
                            '<img src="' + protArt + '" alt="Proteção Divina" class="reactive-card-img" draggable="false">' +
                            '<div style="font-size:0.88rem;color:#e9d8ff;margin-bottom:6px;line-height:1.35">' +
                                '<b style="color:#ff8585">' + src + '</b> está reduzindo o Poder de ' +
                                '<b style="color:#8fffae">' + defName + '</b> (Poder ' + defPow + ').' +
                            '</div>' +
                            '<div style="font-size:1rem;color:#fff;margin:8px 0 6px"><b>Deseja evitar a redução de Poder?</b></div>' +
                            '<div style="height:6px;background:#241830;border-radius:3px;overflow:hidden;margin:6px 0 10px">' +
                                '<div id="prot-progress-bar" style="height:100%;width:100%;background:linear-gradient(90deg,#ffd76b,#ff8585);transition:width 100ms linear"></div>' +
                            '</div>' +
                            '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;box-sizing:border-box">' +
                                '<button id="prot-yes" class="menu-btn" style="background:#2a6a3a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">SIM</button>' +
                                '<button id="prot-no" class="menu-btn" style="background:#6a2a2a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">NÃO</button>' +
                            '</div>' +
                        '</div>';
                    overlay.classList.add("active");
                    window.applyCardArtTree?.(overlay);
                    window.dfRewriteDomAssets?.(overlay);

                    const DURATION = 5000;
                    const startT = performance.now();
                    let done = false;
                    const bar = overlay.querySelector("#prot-progress-bar");
                    const tick = () => {
                        if (done) return;
                        const elapsed = performance.now() - startT;
                        const pct = Math.max(0, 1 - elapsed / DURATION);
                        if (bar) bar.style.width = (pct * 100).toFixed(1) + "%";
                        if (elapsed >= DURATION) { finish(false); return; }
                        requestAnimationFrame(tick);
                    };
                    // `finish` é async pra rodar a animação de PROTEGIDO!
                    // sobre o defensor e o voo da carta pro descarte —
                    // mesma sequência do caminho da IA. O Promise externo
                    // só resolve quando tudo acaba (mantém o efeito que
                    // disparou a Proteção pausado até lá).
                    const finish = async (didProtect) => {
                        if (done) return;
                        done = true;
                        overlay.classList.remove("active");
                        overlay.innerHTML = "";
                        gamePhase = prevPhase;
                        if (didProtect) {
                            const defP = state.players[defOwner];
                            const stillThere = defP?.hand?.[handIdx]?.talentEffect === "protecaoDivina"
                                ? handIdx
                                : (defP?.hand?.findIndex(c => c && c.talentEffect === "protecaoDivina") ?? -1);
                            if (stillThere >= 0) {
                                const card = defP.hand.splice(stillThere, 1)[0];
                                pushDiscard(defOwner, card);
                                state.activeTalent = { ownerP: defOwner, card };
                            }
                            log("✨ Proteção Divina ativada — redução cancelada!");
                            flashRuleBanner("✨ Proteção Divina!", "A redução de Poder foi cancelada.");
                            updateUI();
                            if (window.__DF_ONLINE) {
                                resolve(true);
                                void (async () => {
                                    try {
                                        await animateDivineProtection(defOwner, defender);
                                        await flyActiveTalentToDiscard(defOwner);
                                    } catch (e) { /* */ }
                                    state.activeTalent = null;
                                    updateUI();
                                })();
                                return;
                            }
                            await animateDivineProtection(defOwner, defender);
                            await flyActiveTalentToDiscard(defOwner);
                            state.activeTalent = null;
                            updateUI();
                        } else {
                            log("Você não usou Proteção Divina.");
                            updateUI();
                        }
                        resolve(didProtect);
                    };
                    overlay.querySelector("#prot-yes")?.addEventListener("click", () => finish(true));
                    overlay.querySelector("#prot-no")?.addEventListener("click", () => finish(false));
                    requestAnimationFrame(tick);
                });
            }



            // Localiza o índice de campo de um campeão a partir do dono
            // e da referência do objeto. Usado pelas animações reativas
            // (Bloquear / Proteção Divina) pra achar o DOM do defensor
            // sem precisar propagar `defIdx` por toda a cadeia de chamadas
            // (resolveCombat, ultimates, Bola de Fogo, Assassinar, etc).
            function findFieldIdx(ownerP, champ) {
                const f = state.players[ownerP]?.field;
                if (!f) return -1;
                return f.findIndex(c => c === champ);
            }

            // "ATAQUE BLOQUEADO" — disparada DEPOIS que a carta
            // Bloquear Ataque é confirmada e ANTES dela voar pro descarte.
            // Escudo 🛡️ pula sobre o defensor, 2 anéis de deflexão saem
            // dele em eco e a palavra BLOQUEADO! sobe. Bloqueia ~850ms.
            // Tudo transform/opacity (GPU) pra não causar jank.
            async function animateBlockedAttack(defOwner, defender) {
                try { window.sfx && window.sfx("block"); } catch (e) {}
                await DfAnim.preAnimBanner({
                    category: "reaction",
                    title: "Bloquear Ataque",
                    subtitle: "Reação",
                    theme: { color: "#3ee07a", ring: "#aaffcc", emoji: "🛡️" },
                    duration: 560,
                });
                const fIdx = findFieldIdx(defOwner, defender);
                const el = fIdx >= 0 ? getChampionDom(defOwner, fIdx) : null;
                if (!el) { await wait(700); return; }
                const r = el.getBoundingClientRect();
                const cx = r.left + r.width / 2;
                const cy = r.top  + r.height / 2;

                const shield = document.createElement("div");
                shield.className = "block-shield-pop";
                shield.textContent = "🛡️";
                dfVfxSetPoint(shield, cx, cy);
                setTimeout(() => shield.remove(), 950);

                for (let i = 0; i < 2; i++) {
                    setTimeout(() => {
                        const ring = document.createElement("div");
                        ring.className = "block-deflect-ring";
                        dfVfxSetPoint(ring, cx, cy);
                        setTimeout(() => ring.remove(), 780);
                    }, i * 140);
                }

                const label = document.createElement("div");
                label.className = "block-label";
                label.textContent = "BLOQUEADO!";
                dfVfxSetPoint(label, cx, cy - r.height * 0.45);
                setTimeout(() => label.remove(), 1050);

                await wait(850);
            }

            // "PROTEÇÃO DIVINA" — análoga à animateBlockedAttack, mas
            // celestial: aura dourada pulsa em volta do defensor, ✨
            // central pula, 8 faíscas radiais saem dele e PROTEGIDO!
            // flutua. Mesma duração pro ritmo das duas reativas casar.
            async function animateDivineProtection(defOwner, defender) {
                try { window.sfx && window.sfx("divine"); } catch (e) {}
                await DfAnim.preAnimBanner({
                    category: "reaction",
                    title: "Proteção Divina",
                    subtitle: "Reação",
                    theme: { color: "#ffd84a", ring: "#fff3a8", emoji: "✨" },
                    duration: 560,
                });
                const fIdx = findFieldIdx(defOwner, defender);
                const el = fIdx >= 0 ? getChampionDom(defOwner, fIdx) : null;
                if (!el) { await wait(700); return; }
                const r = el.getBoundingClientRect();
                const cx = r.left + r.width / 2;
                const cy = r.top  + r.height / 2;

                const aura = document.createElement("div");
                aura.className = "divine-aura";
                aura.style.left = cx + "px";
                aura.style.top  = cy + "px";
                dfVfxMount(aura);
                setTimeout(() => aura.remove(), 1000);

                const emoji = document.createElement("div");
                emoji.className = "divine-emoji";
                emoji.textContent = "✨";
                emoji.style.left = cx + "px";
                emoji.style.top  = cy + "px";
                dfVfxMount(emoji);
                setTimeout(() => emoji.remove(), 950);

                for (let i = 0; i < 8; i++) {
                    const s = document.createElement("div");
                    s.className = "divine-spark";
                    s.textContent = i % 2 ? "✦" : "✨";
                    s.style.left = cx + "px";
                    s.style.top  = cy + "px";
                    const ang = (Math.PI * 2 * i) / 8;
                    const dist = 80 + Math.random() * 25;
                    s.style.setProperty("--px", (Math.cos(ang) * dist) + "px");
                    s.style.setProperty("--py", (Math.sin(ang) * dist) + "px");
                    s.style.animationDelay = (i * 25) + "ms";
                    dfVfxMount(s);
                    setTimeout(() => s.remove(), 950);
                }

                const label = document.createElement("div");
                label.className = "protect-label";
                label.textContent = "PROTEGIDO!";
                label.style.left = cx + "px";
                label.style.top  = (cy - r.height * 0.45) + "px";
                dfVfxMount(label);
                setTimeout(() => label.remove(), 1050);

                await wait(850);
            }

            async function awaitTalentSpotlight(ms = DF_TALENT_SPOTLIGHT_MS) {
                try { cleanupOrphanGhosts?.(); } catch (e) { /* */ }
                updateUI({ immediate: true });
                const ownerP = state.activeTalent?.ownerP;
                if (ownerP == null) {
                    await wait(ms);
                    return;
                }
                const el = window.__dfTalentSpotlightEl?.();
                if (el) {
                    el.classList.add("talent-spotlight-active");
                    void el.offsetWidth;
                }
                await wait(ms);
                el?.classList.remove("talent-spotlight-active");
                try { cleanupOrphanGhosts?.(); } catch (e) { /* */ }
                updateUI({ immediate: true });
            }

            // Descarta a carta talento ativa: anima voo pro descarte (opcional),
            // move pro monte de descarte e limpa state.activeTalent IMEDIATAMENTE.


            // Devolve talento pendente à mão (cancelamento de alvo / fim de turno).
            function abortActiveTalent() {
                if (!state.activeTalent) return;
                const { ownerP, card, noDiscard, spentActions } = state.activeTalent;
                // Holofote de RITUAL (Ômega/Tiamate): a carta NUNCA saiu da mão,
                // então só limpamos o holofote — devolver à mão duplicaria a carta.
                if (noDiscard) {
                    state.activeTalent = null;
                    try { if (typeof cancelRitualSacrifice === "function") cancelRitualSacrifice(); } catch (e) { /* */ }
                    try {
                        const layer = document.getElementById("talent-spotlight-layer");
                        layer?.replaceChildren?.();
                        layer?.classList?.remove("talent-spotlight-above-hud", "talent-spotlight-touch-hud");
                    } catch (e2) { /* */ }
                    updateUI();
                    return;
                }
                const spent = Math.max(0, Number(spentActions) | 0);
                if (spent > 0 && state.players[ownerP]) {
                    state.players[ownerP].actions = (state.players[ownerP].actions ?? 0) + spent;
                }
                if (card) state.players[ownerP]?.hand?.push(card);
                state.activeTalent = null;
                gamePhase = "normal";
                targetData = {};
                try { dfDismissTargetingPhase?.(); } catch (e) { /* */ }
                try {
                    const layer = document.getElementById("talent-spotlight-layer");
                    layer?.replaceChildren?.();
                    layer?.classList?.remove("talent-spotlight-above-hud", "talent-spotlight-touch-hud");
                } catch (e2) { /* */ }
                updateUI();
            }

            // Quando a IA usa uma carta REATIVA (Bloquear Ataque /
            // Proteção Divina), a gente deixa a carta brilhando no
            // campo dela por um tempinho via state.activeTalent (efeito
            // talent-in-play). Esta função é chamada IMEDIATAMENTE antes
            // de limpar o state.activeTalent — clona o elemento da carta,
            // o posiciona fixo na mesma coordenada, e anima ele voando
            // até o ícone do descarte no topo. Dá a leitura visual
            // explícita "a carta foi USADA → DESCARTADA" pedida pelo
            // usuário. Se algum elemento não for encontrado, é noop.
            async function flyActiveTalentToDiscard(ownerP) {
                try {
                    const cardEl = window.__dfTalentSpotlightEl?.();
                    const discardEl = getDiscardPileEl(ownerP);
                    if (!cardEl || !discardEl) { await wait(50); return; }
                    const sr = cardEl.getBoundingClientRect();
                    const dr = discardEl.getBoundingClientRect();
                    const clone = cardEl.cloneNode(true);
                    clone.classList.add("talent-fly-discard");
                    clone.style.left = sr.left + "px";
                    clone.style.top  = sr.top  + "px";
                    clone.style.width  = sr.width + "px";
                    clone.style.height = sr.height + "px";
                    clone.style.margin = "0";
                    clone.style.transform = "translate(0,0) scale(1) rotate(0deg)";
                    clone.style.opacity = "1";
                    dfVfxMount(clone);
                    const dx = (dr.left + dr.width / 2) - (sr.left + sr.width / 2);
                    const dy = (dr.top  + dr.height / 2) - (sr.top  + sr.height / 2);
                    // Esconde o original durante o voo pra não duplicar visualmente
                    cardEl.style.visibility = "hidden";
                    requestAnimationFrame(() => {
                        clone.style.transform =
                            `translate(${dx}px, ${dy}px) scale(0.18) rotate(-280deg)`;
                        clone.style.opacity = "0.1";
                    });
                    await wait(720);
                    clone.remove();
                } catch (e) { /* noop — animação cosmética */ }
            }

            // Thor (Trovoada): carta específica da mão → descarte do adversário.
            // Esconde o slot na hora pra não duplicar; clone usa verso.png e
            // voa em arco até o ícone de descarte (sem encolher/sumir no meio).
            async function animateThunderDiscardFromHand(oppP, handIdx) {
                try {
                    const q = document.getElementById(`quadrant-${dfQuadrantForPlayer(oppP)}`);
                    if (!q) { await wait(50); return; }
                    const hand = q.querySelector(".quadrant-hand");
                    if (!hand) { await wait(50); return; }
                    const wraps = hand.querySelectorAll(".hand-wrap");
                    const wrap = wraps[handIdx] || wraps[wraps.length - 1];
                    const src = wrap?.querySelector(".ai-back, .hcard") || wrap || hand;
                    const discardEl = getDiscardPileEl(oppP);
                    if (!discardEl) { await wait(50); return; }
                    const sr = src.getBoundingClientRect();
                    const dr = discardEl.getBoundingClientRect();
                    if (!sr.width || !sr.height) { await wait(50); return; }
                    if (wrap) {
                        wrap.style.visibility = "hidden";
                        wrap.style.pointerEvents = "none";
                    }
                    const cardW = Math.max(52, sr.width);
                    const cardH = Math.round(cardW * 7 / 5);
                    const x0 = sr.left + sr.width / 2;
                    const y0 = sr.top + sr.height / 2;
                    const x1 = dr.left + dr.width / 2;
                    const y1 = dr.top + dr.height / 2;
                    const fly = document.createElement("div");
                    fly.className = "thor-discard-fly";
                    fly.style.width = cardW + "px";
                    fly.style.height = cardH + "px";
                    fly.style.left = x0 + "px";
                    fly.style.top = y0 + "px";
                    fly.style.transform = "translate(-50%, -50%) scale(1) rotate(0deg)";
                    fly.style.opacity = "1";
                    dfVfxMount(fly);
                    const dx = x1 - x0;
                    const dy = y1 - y0;
                    const arc = Math.min(90, Math.abs(dy) * 0.28 + Math.abs(dx) * 0.12 + 36);
                    const duration = 1080;
                    const t0 = performance.now();
                    await new Promise((resolve) => {
                        const tick = (now) => {
                            const raw = Math.min(1, (now - t0) / duration);
                            const e = 1 - Math.pow(1 - raw, 2.15);
                            const cx = x0 + dx * e;
                            const cy = y0 + dy * e - Math.sin(Math.PI * e) * arc;
                            const sc = 1 - e * 0.56;
                            const rot = -16 * Math.sin(Math.PI * e);
                            fly.style.left = cx + "px";
                            fly.style.top = cy + "px";
                            fly.style.transform =
                                `translate(-50%, -50%) scale(${sc}) rotate(${rot}deg)`;
                            fly.style.opacity = raw < 0.9 ? "1" : String(Math.max(0, 1 - (raw - 0.9) / 0.1));
                            if (raw < 1) requestAnimationFrame(tick);
                            else resolve();
                        };
                        requestAnimationFrame(tick);
                    });
                    const origSh = discardEl.style.boxShadow;
                    const origTr = discardEl.style.transform;
                    discardEl.style.transition = "box-shadow 220ms ease, transform 220ms ease";
                    discardEl.style.boxShadow =
                        "0 0 0 3px rgba(180, 220, 255, 0.92), 0 0 26px rgba(100, 180, 255, 0.78)";
                    discardEl.style.transform = "scale(1.1)";
                    setTimeout(() => {
                        discardEl.style.boxShadow = origSh || "";
                        discardEl.style.transform = origTr || "";
                        discardEl.style.transition = "";
                    }, 300);
                    fly.remove();
                } catch (e) { /* noop — animação cosmética */ }
            }

            function flashRuleBanner(title, sub) {
                document.querySelectorAll(".insufficient-banner").forEach(el => el.remove());
                const banner = document.createElement("div");
                banner.className = "insufficient-banner";
                banner.innerHTML =
                    `<div class="ib-title">${title}</div>` +
                    (sub ? `<div class="ib-sub">${sub}</div>` : "");
                dfVfxMount(banner);
                setTimeout(() => banner.remove(), 1900);
                log(`⛔ ${title}`);
            }

            // Detecta se uma carta é "dragão" pra disparar a animação épica
            // de chegada. Cobre Filhote, Feragross e qualquer
            // futura carta com "DRAGÃO/DRAGÕES" no nome.
            function isDragonCard(c) {
                if (!c || !c.name) return false;
                const n = c.name.toUpperCase();
                // WYVERN (ex-"TREINADORA DE DRAGÕES") e FERAGROSS (ex-"DRAGÃO
                // DE DUAS CABEÇAS") são dragões pra todos os efeitos —
                // mantemos a mesma animação épica de entrada.
                if (n === "WYVERN" || n === "FERAGROSS") return true;
                return n.includes("DRAGÃO") || n.includes("DRAGÕES");
            }

            // Entrada APOCALÍPTICA de dragão: tela treme, fundo flasha em
            // laranja/vermelho, dragão gigante aparece em cima da carta,
            // ondas de choque ardentes expandem e brasas voam pra todo lado.
            // Chamada NO LUGAR do impacto comum quando a carta é dragão.
            async function animateDragonEntry(pIdx, fIdx) {
                try { window.sfx && window.sfx("dragon_roar"); } catch (e) {}
                const el = getChampionDom(pIdx, fIdx);
                if (!el) return;
                const rect = el.getBoundingClientRect();
                const cx = rect.left + rect.width / 2;
                const cy = rect.top + rect.height / 2;

                // Flash na tela inteira (camada laranja/vermelha)
                const flash = document.createElement("div");
                flash.className = "dragon-screen-flash";
                dfVfxMount(flash);
                setTimeout(() => flash.remove(), 1100);

                // ANTES: tremor era aplicado no <#game> root, o que forçava
                // recomposição da tela inteira a cada frame da animação
                // (causa nº 1 do travamento em celular). Agora a tremida
                // fica isolada ao QUADRANTE do jogador — pintura local,
                // sem reflow do resto da UI. Sensação de impacto preservada.
                const q = document.getElementById(`quadrant-${pIdx}`);
                if (q) {
                    q.classList.remove("ground-tremor");
                    void q.offsetWidth;
                    q.classList.add("ground-tremor");
                    setTimeout(() => q.classList.remove("ground-tremor"), 500);
                }

                // (Dragão emoji 🐉 removido — o impacto vem do flash + ondas
                // de choque + brasas; o emoji ficava poluindo a tela.)

                // 2 ondas de choque (era 3 — uma a menos significa um shadow
                // gigantesco a menos pintando ao mesmo tempo).
                for (let i = 0; i < 2; i++) {
                    setTimeout(() => {
                        const shock = document.createElement("div");
                        shock.className = "dragon-fire-shock";
                        shock.style.left = cx + "px";
                        shock.style.top  = cy + "px";
                        dfVfxMount(shock);
                        setTimeout(() => shock.remove(), 950);
                    }, i * 180);
                }

                // Brasas: reduzidas de 22 → 12. Cada brasa custa 1 shadow
                // grande por frame, então cortar quase metade dá um ganho
                // enorme de FPS sem perder a sensação de "explosão".
                const embers = ["🔥","✨","💥","🔥","⚡","🔥"];
                for (let i = 0; i < 12; i++) {
                    const e = document.createElement("div");
                    e.className = "dragon-ember";
                    e.textContent = embers[i % embers.length];
                    e.style.left = cx + "px";
                    e.style.top  = cy + "px";
                    const ang = (Math.PI * 2 * i) / 12 + (Math.random() - 0.5) * 0.3;
                    const dist = 140 + Math.random() * 160;
                    e.style.setProperty("--px", (Math.cos(ang) * dist) + "px");
                    e.style.setProperty("--py", (Math.sin(ang) * dist - 40) + "px");
                    e.style.setProperty("--rot", (Math.random() * 720 - 360) + "deg");
                    e.style.animationDelay = (i * 30) + "ms";
                    dfVfxMount(e);
                    setTimeout(() => e.remove(), 1300);
                }

                // Card também "aterrisa" com o impacto comum (efeito clássico)
                el.classList.add("land-impact");
                setTimeout(() => el.classList.remove("land-impact"), 650);

                await wait(900);
            }

            async function summonFromHand(playerIdx, handIdx, fromHuman = false, freeAction = false, dropPoint = null, ritualOpts = null) {
                // RE-ENTRANCY GUARD (anti carta duplicada no mobile):
                // double-tap, pointerup+click duplo ou clique no menu
                // antes do await terminar entrava DUAS vezes aqui e
                // empurrava a MESMA carta da mão pro field duas vezes.
                // Tranca global liberada no finally bem no fim da função.
                ensureTurnReady();
                if (window.__DF_ONLINE) {
                    try {
                        window.__dfTurnEndingPending = false;
                        window.__dfTurnEndingStuckAt = 0;
                        if (!window.__dfOnlineMatchBoot && !window.__dfMatchBoot) {
                            window.__dfMatchOpeningSeat = null;
                            window.__dfOnlineBootLockInput = false;
                        }
                        if (!dfIsCombatPresentationLive()) {
                            try { dfCombatForceCleanup(); } catch (eCf) { /* */ }
                        }
                        try { dfOnlineApplyingRemote = false; } catch (eAr) { /* */ }
                        ensureTurnReady();
                    } catch (eMpSum) { /* */ }
                }
                if (pendingSummon || gamePhase === "summon-placement") {
                    if (fromHuman && dfIsLocalPlayer(playerIdx)) {
                        floatText("Aguarde o posicionamento da invocação.", "warn center", 1600);
                    }
                    return false;
                }
                if (window.__dfCombatActive) {
                    dfEnsurePresentationUnblocked("invocar-combat");
                    ensureTurnReady();
                    if (window.__dfCombatActive) {
                        if (fromHuman && dfIsLocalPlayer(playerIdx)) {
                            floatText("Aguarde o combate terminar.", "warn center", 1400);
                        }
                        return false;
                    }
                }
                if (window._summonLock) {
                    ensureTurnReady();
                    if (window._summonLock) {
                        if (fromHuman && dfIsLocalPlayer(playerIdx)) {
                            floatText("Aguarde a invocação em andamento.", "warn center", 1400);
                        }
                        return false;
                    }
                }
                window._summonLock = true;
                let ritualMeta = ritualOpts && typeof ritualOpts === "object" ? { ...ritualOpts } : null;
                dfEnsurePresentationUnblocked("invocar");
                try {
                const p = state.players[playerIdx];
                let card = p.hand[handIdx]; if (!card || card.category === "talent") return false;

                const summonCtx = DfRules.summonContextForPlayer(state, playerIdx);
                const noEnemies = DfRules.totalEnemyFieldCount(state, playerIdx) === 0;
                const legality = p.isAI
                    ? DfRules.canSummon(state, playerIdx, handIdx, {
                        freeAction,
                        ...summonCtx,
                        strictFumacaToxica: false,
                        avoidEnemyOnEnterWaste: noEnemies,
                        allowWastedOnEnter: false,
                    })
                    : DfRules.canSummon(state, playerIdx, handIdx, {
                        freeAction,
                        allowWastedOnEnter: true,
                        avoidEnemyOnEnterWaste: false,
                        strictFumacaToxica: false,
                    });
                if (!legality.ok) {
                    if (fromHuman && dfIsLocalPlayer(playerIdx)) {
                        if (legality.code === "INSUFFICIENT_ACTIONS") {
                            flashInsufficientActions(card.currentPower, p.actions, handIdx);
                        } else if (legality.code === "FIELD_FULL") {
                            notifyFieldFull(playerIdx);
                        } else if (legality.code === "NO_RITUAL_SACRIFICE") {
                            flashRuleBanner(
                                `${card.name} requer sacrificar um Campeão aliado de Poder ${card.summonRitual}.`,
                                `Você não tem nenhum aliado de Poder <b>${card.summonRitual}</b> no campo.`);
                        } else if (legality.code === "ON_ENTER_BLOCKED" || legality.code === "WASTED_ON_ENTER") {
                            flashRuleBanner(
                                `${card.name} não pode ser invocado agora.`,
                                legality.reason || "A habilidade ao entrar não teria efeito neste momento.");
                        } else if (legality.code === "NOT_YOUR_TURN") {
                            floatText("Aguarde sua vez.", "warn center", 1400);
                        } else if (legality.code === "BAD_PHASE" || gamePhase !== "normal") {
                            if (gamePhase === "target-champion" || gamePhase === "ultimate-target") {
                                floatText("Selecione o alvo destacado antes de invocar outra carta.", "warn center", 2200);
                            } else if (gamePhase === "summon-placement") {
                                floatText("Aguarde o posicionamento da invocação.", "warn center", 1600);
                            } else {
                                floatText("Aguarde o fim da manutenção ou feche menus abertos.", "warn center", 1800);
                            }
                        }
                    }
                    return false;
                }

                // RITUAL (Ômega, Tiamat): custo alternativo. Em vez de gastar
                // Ações, sacrifica um aliado de Poder = summonRitual e invoca
                // como Ação Livre. Se não houver aliado válido, a carta não
                // pode ser jogada. Fluxo:
                //   • HUMANO: entra na fase "target-ally" com ability
                //     "ritualSacrifice"; o clique no aliado em
                //     confirmEnter → destroy + nova chamada de summonFromHand
                //     com freeAction=true.
                //   • IA: escolhe sacrifício automaticamente, destrói, e
                //     cai direto na rota freeAction abaixo.
                if (card.summonRitual && !freeAction) {
                    const reqPow = card.summonRitual;
                    if (!p.isAI) {
                        gamePhase = "target-ally";
                        targetData = {
                            ability: "ritualSacrifice",
                            ritualHandIdx: handIdx,
                            ritualCardName: card.name,
                            caster: playerIdx,
                            allyTargets: DfRules.listRitualSacrificeIndices(state, playerIdx, reqPow)
                                .map((i) => ({ p: playerIdx, i })),
                            targetIndex: 0,
                        };
                        window._ritualDragAt = Date.now();
                        // Pedido do autor: a carta do RITUAL (Ômega/Tiamate) fica em
                        // evidência ao lado de "Sua vez" (mesmo holofote do talento),
                        // com a tag "RITUAL", até o jogador escolher o sacrifício.
                        // `noDiscard` deixa explícito que ela NÃO voa pro descarte
                        // (será invocada ao campo). Limpamos em confirm/cancel.
                        state.activeTalent = { ownerP: playerIdx, card, tag: "RITUAL", noDiscard: true };
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            try {
                                dfOnlineBroadcastVisual({
                                    kind: "ritual_spotlight",
                                    ownerP: playerIdx,
                                    cardName: card.name,
                                    summonRitual: card.summonRitual,
                                    power: card.power,
                                    card: {
                                        name: card.name,
                                        category: card.category || "champion",
                                        summonRitual: card.summonRitual,
                                        power: card.power,
                                        currentPower: card.power,
                                        img: card.img,
                                        composedFace: card.composedFace,
                                    },
                                });
                            } catch (e) { /* */ }
                        }
                        log(`RITUAL — escolha o aliado de Poder ${reqPow} destacado em ROXO para sacrificar e invocar ${card.name}.`);
                        floatText(`RITUAL — clique no aliado P${reqPow} (borda roxa)`, "info center", 2400);
                        updateUI();
                        return "ritual_pending";
                    }
                    // IA: pega o sacrifício menos valioso
                    const sacIdx = aiPickRitualSacrifice(playerIdx, reqPow);
                    if (sacIdx === null) return false;
                    const sacCard = p.field[sacIdx];
                    const sacName = sacCard.name;
                    const sacUid = sacCard.uid || undefined;
                    destroyChampion(playerIdx, sacIdx, null, "ritualSacrifice", { ignoreNoHonor: true });
                    if (window.__dfPendingDestroyVisual) {
                        await window.__dfPendingDestroyVisual;
                        window.__dfPendingDestroyVisual = null;
                    }
                    log(`${p.name} sacrificou ${sacName} para o Ritual de ${card.name}.`);
                    freeAction = true;
                    ritualMeta = { sacrificeIdx: sacIdx, sacrificeUid: sacUid };
                }
                if (!freeAction && p.actions < card.currentPower) {
                    // Feedback INCISIVO: o jogador insistiu, vamos lembrar
                    // ele bem claro que faltam ações.
                    if (fromHuman && dfIsLocalPlayer(playerIdx)) {
                        flashInsufficientActions(card.currentPower, p.actions, handIdx);
                    }
                    return false;
                }
                // Limite duro de 8 Campeões em campo. Bloqueia ANTES de gastar
                // ações ou remover a carta da mão. Aviso central só pro humano.
                if (p.field.length >= MAX_FIELD) {
                    notifyFieldFull(playerIdx);
                    return false;
                }
                // Limpa qualquer ghost de drag ou fly de invocação anterior
                // que tenha ficado pendurado no body — assim nunca aparece
                // uma "cópia fantasma" da carta junto da invocação real.
                document.querySelectorAll(".drag-ghost, .summon-fly").forEach(el => el.remove());
                window._activeGhost = null;
                window.dfPrefetchCardArt?.(card.name);

                // Índice real na mão (nome/uid) — evita invocar o campeão errado
                // quando a mão do cliente e a do servidor divergiram por sync.
                {
                    const hand = p.hand;
                    const wantUid = card.uid != null ? String(card.uid) : "";
                    const wantName = card.name;
                    let liveIdx = handIdx;
                    if (wantUid) {
                        const byUid = hand.findIndex((c) => c && String(c.uid || "") === wantUid);
                        if (byUid >= 0) liveIdx = byUid;
                    } else if (wantName && (!hand[liveIdx] || hand[liveIdx].name !== wantName)) {
                        const byName = hand.findIndex((c) => c && c.name === wantName);
                        if (byName >= 0) liveIdx = byName;
                    }
                    handIdx = liveIdx;
                    const liveCard = hand[handIdx];
                    if (!liveCard || liveCard.category === "talent") return false;
                    card = liveCard;
                }

                let summonSrc = dfCaptureSummonHandSrc(playerIdx, handIdx, card);
                if (!freeAction) p.actions -= (DfRules.championSummonCost(card) || card.currentPower || 0);
                p.hand.splice(handIdx, 1);
                const placed = { ...card, tapped: false, basePower: card.power,
                    currentPower: card.currentPower ?? card.power ?? 0,
                    frozen: false, frozenTurns: 0, freeAttack: false, shielded: false, shieldedTurns: 0,
                    silenced: false, pulled: false, pulledFromOwner: -1, pulledTurns: 0 };
                // Offline/IA: marcar _summoning já no insert — updateUI não pinta
                // a carta semi-visível antes do voo (1º campeão da IA).
                // MP: não marcar antes do ACK (slot vazio durante rede).
                const onlineSummon = window.__DF_ONLINE && !dfOnlineApplyingRemote;
                // Esconde no campo desde o insert — nunca flash antes do fly.
                placed._summoning = true;
                const summonUid = placed.uid != null ? String(placed.uid) : `${placed.name}:${Date.now()}`;
                window.__dfLocalSummonUid = summonUid;
                if (summonSrc) {
                    summonSrc.uid = summonUid;
                    summonSrc.cardName = placed.name;
                    summonSrc.currentPower = placed.currentPower;
                }

                let insertIdx = dfDefaultSummonInsertIdx(p.field.length);
                if (dropPoint && typeof dropPoint.insertIdx === "number") {
                    insertIdx = Math.max(0, Math.min(dropPoint.insertIdx | 0, p.field.length));
                } else if (dfIsLocalPlayer(playerIdx) && fromHuman && dropPoint &&
                    typeof dropPoint.x === "number" && typeof dropPoint.y === "number" &&
                    p.field.length > 0) {
                    insertIdx = fieldInsertIndexAt(dropPoint.x, dropPoint.y);
                }
                p.field.splice(insertIdx, 0, placed);
                let fieldIdx = insertIdx;
                let summonAck = null;
                if (onlineSummon) {
                    window.__dfSummonInFlight = true;
                    try {
                        // Congela a mão visual: só a carta invocada some (via animação).
                        // Slot do campo já em _summoning (invisível) até o fly terminar.
                        updateUI({ immediate: true });
                        await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                        const ack = await dfOnlineSendActionAwait({
                            type: "SUMMON",
                            playerId: playerIdx,
                            handIdx,
                            insertIdx,
                            cardName: card.name,
                            uid: card.uid || undefined,
                            freeAction: !!freeAction,
                            sacrificeIdx: ritualMeta?.sacrificeIdx != null
                                ? (ritualMeta.sacrificeIdx | 0)
                                : undefined,
                            sacrificeUid: ritualMeta?.sacrificeUid || undefined,
                            anim: {
                                kind: "summon",
                                cardName: card.name,
                                insertIdx,
                                uid: card.uid || undefined,
                            },
                        });
                        summonAck = ack;
                        if (!ack || ack.ok === false) {
                            floatText("Invocação rejeitada pelo servidor.", "warn center", 2200);
                            if (ack?.authoritativeState?.players?.length) {
                                dfOnlineReconcileSnapshot(
                                    { state: ack.authoritativeState, full: true },
                                    { skipPhase: true },
                                );
                            } else {
                                await dfOnlineRollbackToServer();
                            }
                            delete placed._summoning;
                            window.__dfSummonInFlight = false;
                            window.__dfLocalSummonUid = null;
                            updateUI({ immediate: true });
                            return false;
                        }
                        // Raio Duplo: snaps ANTES do reconcile (auth já remove P1=0).
                        try {
                            window.__dfRaioDuploPreHits = typeof window.dfOnlineCaptureRaioDuploPreHits === "function"
                                ? window.dfOnlineCaptureRaioDuploPreHits(ack.events || [])
                                : null;
                        } catch (eRaio) { window.__dfRaioDuploPreHits = null; }
                        if (ack.authoritativeState?.players?.length) {
                            const want = card.name;
                            try {
                                window.dfOnlineMarkDragonTokensFromEvents?.(
                                    ack.authoritativeState,
                                    ack.events || [],
                                );
                            } catch (eTok) { /* */ }
                            dfOnlineReconcileSnapshot(
                                { state: ack.authoritativeState, full: true },
                                { skipPhase: true },
                            );
                            const liveField = state.players[playerIdx]?.field || [];
                            let authIdx = liveField.findIndex((c) =>
                                c && (c.uid === summonUid || c.name === want));
                            if (authIdx < 0) authIdx = Math.min(insertIdx, Math.max(0, liveField.length - 1));
                            fieldIdx = authIdx;
                            // Rearmar hide após reconcile (auth limpa _summoning).
                            const liveCard = liveField[fieldIdx];
                            if (liveCard) liveCard._summoning = true;
                            updateUI({ immediate: true });
                        }
                    } catch (e) {
                        console.warn("[DF online] SUMMON", e);
                        window.__dfSummonInFlight = false;
                        window.__dfLocalSummonUid = null;
                        await dfOnlineRollbackToServer();
                        return false;
                    }
                } else {
                    updateUI({ immediate: true });
                    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                }
                if (summonSrc) {
                    try {
                        await Promise.race([
                            summonAnimation(playerIdx, fieldIdx, summonSrc),
                            wait(4000).then(() => {
                                console.warn("[DF summon] anim watchdog — força revelar");
                                try {
                                    const live = state.players[playerIdx]?.field?.[fieldIdx];
                                    if (live) delete live._summoning;
                                } catch (e) { /* */ }
                                document.querySelectorAll(".summon-fly").forEach((el) => el.remove());
                                const liveDest = getChampionDom(playerIdx, fieldIdx)
                                    || document.getElementById(`champ-${playerIdx}-${fieldIdx}`);
                                if (liveDest) {
                                    liveDest.classList.remove("is-summoning", "df-summon-busy");
                                    liveDest.style.visibility = "";
                                    liveDest.style.opacity = "";
                                    window.dfEndFieldSummonBusy?.(liveDest);
                                }
                                try { window.DfPixiVfx?.forceClearStage?.(); } catch (e2) { /* */ }
                            }),
                        ]);
                    } finally {
                        delete placed._summoning;
                        try {
                            const live = state.players[playerIdx]?.field?.[fieldIdx];
                            if (live) delete live._summoning;
                        } catch (e) { /* */ }
                        const liveDest = getChampionDom(playerIdx, fieldIdx)
                            || document.getElementById(`champ-${playerIdx}-${fieldIdx}`);
                        if (liveDest) {
                            liveDest.classList.remove("is-summoning", "df-summon-busy");
                            liveDest.style.visibility = "";
                            liveDest.style.opacity = "";
                            window.dfEndFieldSummonBusy?.(liveDest);
                            window.dfScheduleFieldRowLock?.(liveDest);
                        }
                        if (onlineSummon) {
                            window.__dfSummonInFlight = false;
                            window.__dfLocalSummonUid = null;
                            updateUI({ immediate: true });
                        } else {
                            window.__dfLocalSummonUid = null;
                        }
                    }
                } else {
                    // Sempre limpar _summoning (nunca deixar carta invisível).
                    delete placed._summoning;
                    try {
                        const live = state.players[playerIdx]?.field?.[fieldIdx];
                        if (live) delete live._summoning;
                    } catch (e) { /* */ }
                    const liveDest = getChampionDom(playerIdx, fieldIdx)
                        || document.getElementById(`champ-${playerIdx}-${fieldIdx}`);
                    if (liveDest) {
                        liveDest.classList.remove("is-summoning", "df-summon-busy");
                        liveDest.style.visibility = "";
                        liveDest.style.opacity = "";
                        window.dfEndFieldSummonBusy?.(liveDest);
                    }
                    if (onlineSummon) {
                        window.__dfSummonInFlight = false;
                        window.__dfLocalSummonUid = null;
                        updateUI({ immediate: true });
                    } else {
                        window.__dfLocalSummonUid = null;
                    }
                }
                window._summonLock = false;
                try {
                    window.sfx && window.sfx("champion_summon");
                    window.sfx && window.sfx("champion_summon", { gain: 0.45, delay: 0.085 });
                } catch (e) {}
                // Peer faz land no replay do SUMMON — não mandar land_impact solto.
                if (isDragonCard(placed)) {
                    await animateDragonEntry(playerIdx, fieldIdx);
                } else {
                    await championLandImpact(playerIdx, fieldIdx);
                }
                log(`${p.name} invocou ${placed.name}.`);
                refreshHandChampionForSummon(placed, playerIdx);
                updateUI({ immediate: true });
                await wait(48);
                const wasCursed = !!p.maldicaoForgetNext;
                if (wasCursed) {
                    placed.silenced = true;
                    placed.onEnter = null;
                    placed.onDestroy = null;
                    placed.talentEffect = null;
                    placed.silencedInHand = false;
                    p.maldicaoForgetNext = false;
                    (p.hand || []).forEach(c => { if (c) c.silencedInHand = false; });
                    // Sem box central: o ícone de silenciado na carta já informa.
                    log(`🔮 ${placed.name} foi invocado sob ESQUECIMENTO — sem habilidade!`);
                    try { window.sfx && window.sfx("maldicao"); } catch (e) {}
                    updateUI();
                }
                delete placed._necromanciaFresh;
                try {
                    // MP: servidor já resolveu onEnter auto no SUMMON — não re-disparar
                    // com uid pós-Troca (Lilith não pode usar Bola de Fogo de novo).
                    const evTypes = new Set(
                        (onlineSummon && summonAck
                            ? (summonAck.events || []).map((e) => e?.type).filter(Boolean)
                            : []),
                    );
                    const serverAutoOnEnter = evTypes.has("TROCA_INJUSTA")
                        || evTypes.has("RAIO_DUPLO")
                        || evTypes.has("DRAGON_TOKEN_SUMMON")
                        || evTypes.has("ROUBAR")
                        || evTypes.has("PESADELO")
                        || evTypes.has("DESACELERAR")
                        || evTypes.has("MALDICAO_SETE_MARES")
                        || evTypes.has("FUMACA_TOXICA")
                        || evTypes.has("GRITO_DE_GUERRA")
                        || evTypes.has("DEFENSOR")
                        || evTypes.has("RAPIDEZ");
                    if (!(onlineSummon && serverAutoOnEnter)) {
                        await resolveOnEnter(playerIdx, fieldIdx, placed.uid);
                    }
                } catch (onEnterErr) {
                    console.warn("[DF onEnter]", onEnterErr);
                }
                // MP: on-enter auto já resolvido no servidor — replay VFX do envelope
                // (Roubar, Maldição, Desacelerar, Fumaça…) sem reaplicar regras.
                if (onlineSummon && summonAck && typeof dfOnlineReplayPresentationEnvelope === "function") {
                    try {
                        await dfOnlineReplayPresentationEnvelope(summonAck, {
                            skipKinds: new Set(["summon", "land_impact"]),
                            authApplied: true,
                            budgetMs: 4200,
                        });
                    } catch (e) { /* */ }
                    try { window.__dfRaioDuploPreHits = null; } catch (e2) { /* */ }
                }
                dfRestoreFieldPresentation();
                applyConstantFieldEffects(playerIdx, fieldIdx);
                if (onlineSummon) {
                    const summoned = state.players[playerIdx]?.field?.[fieldIdx];
                    if (summoned?.freeAttack) {
                        try {
                            await dfOnlineCommitStatus(playerIdx, fieldIdx, {
                                kind: "status_sync",
                                broadcast: true,
                            });
                        } catch (e) { /* */ }
                    }
                }
                if (["target-champion", "target-ally", "ultimate-target"].includes(gamePhase)) {
                    updateUI({ immediate: true });
                } else {
                    updateUI();
                }
                window.dfScheduleFieldRowLock?.(getChampionDom(playerIdx, fieldIdx));
                checkWin();
                if (onlineSummon) dfOnlineBroadcastState();
                return true;
                } finally {
                    window._summonLock = false;
                }
            }



            // INVOCAR DRAGÃO — cinematográfica e GPU-friendly.
            //
            // Antes: um único 🐉 voava com `transition: left/top` (anima
            // propriedades de layout → reflow a cada frame) e só.
            // Pouco impressionante e ainda travava em celular.
            //
            // Agora: a DRAGOA-MÃE sobrevoa a tela, deixa um rastro de
            // faíscas, SOLTA UM OVO BRILHANTE em cima do campo, o ovo cai,
            // explode em chamas, e dali nasce o Filhote.
            // Todas as etapas usam SÓ transform/opacity (compositor da
            // GPU), sem mix-blend-mode em tela cheia, sem tremor no root,
            // sem filtros empilhados — zero queda de FPS.
            // ===== INVOCAR DRAGÃO — animação REESCRITA =====
            // O usuário disse que a anterior (mãe voando, ovo caindo,
            // emojis brotando) estava POLUÍDA e não divertida. Agora é
            // limpa, focada e épica: um portal arcano vermelho abre no
            // ponto de invocação, um pilar de luz dourado-rubro brota,
            // uma onda de choque expande e o Filhote MATERIALIZA num
            // flash dourado. Sem emojis voando, sem ovos, sem dragoa
            // sobrevoando — pura magia ritual.
            async function animateDragonSummon(targetP, targetFieldIdx) {
                // O slot entra oculto (_summoning / is-summoning) para o emerge
                // aparecer. Revelar NÃO pode depender do caminho felizardo: se
                // saíssemos antes (DOM ainda não montado no MP) ou por exceção,
                // a classe `is-summoning` ficava presa no elemento e
                // `patchFieldCardDom` mantinha o Dragão Azul invisível para
                // sempre — era o bug do adversário não ver o dragão.
                const reveal = () => {
                    const el = getChampionDom(targetP, targetFieldIdx);
                    if (!el) return;
                    el.classList.remove("is-summoning", "df-dragon-emerge");
                    el.style.removeProperty("visibility");
                    el.style.removeProperty("opacity");
                };
                let dest = getChampionDom(targetP, targetFieldIdx);
                if (!dest && window.__DF_ONLINE) {
                    // No MP o paint do slot pode demorar mais que 320ms.
                    for (let n = 0; n < 20 && !dest; n++) {
                        await wait(40);
                        dest = getChampionDom(targetP, targetFieldIdx);
                    }
                }
                if (!dest) {
                    reveal();
                    return;
                }
                try {
                    dest.classList.remove("is-summoning");
                    dest.style.removeProperty("visibility");
                    dest.style.removeProperty("opacity");
                    dest.classList.add("df-dragon-emerge");
                    try { window.sfx && window.sfx("dragon_roar"); } catch (e) {}
                    await wait(920);
                } finally {
                    reveal();
                }
            }

            // RAPIDEZ — feedback CHAMATIVO: relâmpago grande sobre o
            // campeão, raios convergindo pra ele, texto "+1 AÇÃO" voando da
            // carta até os pontos de ação do cabeçalho, e os pontos pulsam
            // em amarelo brilhante. Mostra claramente que o jogador ganhou
            // uma ação a mais.
            async function animateWings(casterIdx) {
                const q = $(`quadrant-${casterIdx}`);
                if (!q) return;
                // Encontra o campeão que acabou de entrar (último do campo)
                const pl = state.players[casterIdx];
                const fIdx = pl.field.length - 1;
                const champEl = getChampionDom(casterIdx, fIdx);
                const champRect = champEl
                    ? champEl.getBoundingClientRect()
                    : q.getBoundingClientRect();
                const cx = champRect.left + champRect.width / 2;
                const cy = champRect.top + champRect.height / 2;

                // Raios convergindo no campeão (vindos das 4 diagonais)
                const directions = [
                    { dx: -120, dy: -90, icon: "⚡" },
                    { dx:  120, dy: -90, icon: "⚡" },
                    { dx: -120, dy:  90, icon: "⚡" },
                    { dx:  120, dy:  90, icon: "⚡" },
                    { dx:    0, dy: -130, icon: "✨" },
                    { dx:    0, dy:  130, icon: "✨" },
                ];
                directions.forEach((d, i) => {
                    const bolt = document.createElement("div");
                    bolt.className = "rapidez-bolt";
                    bolt.textContent = d.icon;
                    bolt.style.left = cx + "px";
                    bolt.style.top  = cy + "px";
                    bolt.style.setProperty("--sx", d.dx + "px");
                    bolt.style.setProperty("--sy", d.dy + "px");
                    bolt.style.animationDelay = (i * 30) + "ms";
                    dfVfxMount(bolt);
                    setTimeout(() => bolt.remove(), 1000);
                });

                // Relâmpago grande no centro do campeão
                const burst = document.createElement("div");
                burst.className = "rapidez-burst";
                burst.textContent = "⚡";
                burst.style.left = cx + "px";
                burst.style.top  = cy + "px";
                dfVfxMount(burst);
                setTimeout(() => burst.remove(), 1150);

                // Localiza os pontos de ação no cabeçalho para o texto voar até lá
                const dotsEl = q.querySelector(".action-dots");
                const dotsRect = dotsEl ? dotsEl.getBoundingClientRect() : null;
                // Pulso amarelo nos pontos de ação do cabeçalho, sincronizado
                // com o texto chegando lá (~900ms depois de aparecer).
                setTimeout(() => {
                    if (!dotsEl) return;
                    dotsEl.querySelectorAll(".dot").forEach(d => {
                        d.classList.remove("rapidez-pulse");
                        void d.offsetWidth;
                        d.classList.add("rapidez-pulse");
                        setTimeout(() => d.classList.remove("rapidez-pulse"), 1500);
                    });
                }, 850);

                await wait(1200);
            }

            // ACELERAÇÃO (Talento) — bota em dash com rastro de fogo + ação extra.
            async function animateAceleracao(ownerP) {
                try { window.sfx && window.sfx("buff_power"); } catch (e) {}
                const q = $(`quadrant-${ownerP}`);
                const qRect = q ? q.getBoundingClientRect()
                    : { left: 200, top: 400, width: 300, height: 200 };
                const sx = qRect.left + qRect.width * 0.2;
                const sy = qRect.top + qRect.height * 0.6;
                const mx = qRect.left + qRect.width * 0.55;
                const my = qRect.top + qRect.height * 0.45;
                const ex = qRect.left + qRect.width * 0.85;
                const ey = qRect.top + qRect.height * 0.35;
                await ensureVfxReady();
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playAceleracaoScene === "function";
                if (gpu) {
                    const ran = await window.DfPixiVfx.playAceleracaoScene({
                        fromX: sx, fromY: sy, midX: mx, midY: my, toX: ex, toY: ey, cinematic: true,
                    });
                    if (ran) {
                        const dotsEl = q?.querySelector(".action-dots");
                        setTimeout(() => {
                            if (!dotsEl) return;
                            dotsEl.querySelectorAll(".dot").forEach(d => {
                                d.classList.remove("rapidez-pulse");
                                void d.offsetWidth;
                                d.classList.add("rapidez-pulse");
                                setTimeout(() => d.classList.remove("rapidez-pulse"), 1500);
                            });
                        }, 720);
                        try { window.DfPixiVfx?.sweepOrphanScenes?.(); } catch (e) { /* */ }
                        await wait(950);
                        return;
                    }
                }
                const sky = document.createElement("div");
                sky.className = "acel-sky";
                dfVfxMount(sky);
                const boot = document.createElement("div");
                boot.className = "acel-boot";
                boot.textContent = "👢";
                boot.style.left = sx + "px";
                boot.style.top = sy + "px";
                boot.style.setProperty("--sx", "0px");
                boot.style.setProperty("--sy", "0px");
                boot.style.setProperty("--mx", (mx - sx) + "px");
                boot.style.setProperty("--my", (my - sy) + "px");
                boot.style.setProperty("--ex", (ex - sx) + "px");
                boot.style.setProperty("--ey", (ey - sy) + "px");
                dfVfxMount(boot);
                [0, 1, 2].forEach(i => {
                    const streak = document.createElement("div");
                    streak.className = "acel-streak";
                    streak.style.left = (sx + 20) + "px";
                    streak.style.top = (sy - 10 + i * 8) + "px";
                    streak.style.width = (80 + i * 40) + "px";
                    streak.style.setProperty("--rot", (-15 + i * 12) + "deg");
                    streak.style.animationDelay = (i * 80) + "ms";
                    dfVfxMount(streak);
                    setTimeout(() => streak.remove(), 950);
                });
                const dotsEl = q?.querySelector(".action-dots");
                setTimeout(() => {
                    if (!dotsEl) return;
                    dotsEl.querySelectorAll(".dot").forEach(d => {
                        d.classList.remove("rapidez-pulse");
                        void d.offsetWidth;
                        d.classList.add("rapidez-pulse");
                        setTimeout(() => d.classList.remove("rapidez-pulse"), 1500);
                    });
                }, 850);
                await wait(1200);
                boot.remove();
                sky.classList.add("fade-out");
                setTimeout(() => sky.remove(), 450);
            }

            // BAFORADA VENENOSA — gosma PNG do jogador ao alvo (proj 1→2 voo, 3→4 impacto).
            async function animateBaforadaBreathLegacy(srcX, srcY, tx, ty, el) {
                const dx = tx - srcX;
                const dy = ty - srcY;
                const dist = Math.hypot(dx, dy) || 1;
                const rot = Math.atan2(dy, dx) * 180 / Math.PI;
                const breath = document.createElement("div");
                breath.className = "baf-breath";
                breath.style.left = srcX + "px";
                breath.style.top = srcY + "px";
                breath.style.width = dist + "px";
                breath.style.setProperty("--rot", rot + "deg");
                dfVfxMount(breath);
                setTimeout(() => breath.remove(), 1100);
                await wait(520);
                const cloud = document.createElement("div");
                cloud.className = "ult-poison-cloud";
                cloud.style.left = tx + "px";
                cloud.style.top = ty + "px";
                dfVfxMount(cloud);
                setTimeout(() => cloud.remove(), 1650);
                if (el) {
                    el.classList.add("poison-flash");
                    setTimeout(() => el.classList.remove("poison-flash"), 1300);
                }
            }

            async function animateBaforadaVenenosa(casterP, targets) {
                await ensureVfxReady();
                // Talento: boot curto — não esperar 10s de cinematic.
                try {
                    await window.DfVfxEngine?.ensureCinematicReady?.({ waitFull: true, maxMs: 2500 });
                } catch (e) { /* */ }
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playDragonBreathScene === "function";
                const resolveTargetEl = (p, i, uid) => getChampionDom(p, i)
                    || (uid != null ? document.querySelector(`.ccard[data-uid="${uid}"]`) : null);
                const sorted = [...targets].sort((a, b) => {
                    const elA = resolveTargetEl(a.p, a.i, a.uid);
                    const elB = resolveTargetEl(b.p, b.i, b.uid);
                    const ra = elA?.getBoundingClientRect?.();
                    const rb = elB?.getBoundingClientRect?.();
                    const xa = ra ? ra.left + ra.width / 2 : a.p * 1000 + a.i;
                    const xb = rb ? rb.left + rb.width / 2 : b.p * 1000 + b.i;
                    return xa - xb;
                });
                for (let ti = 0; ti < sorted.length; ti++) {
                    if (ti > 0) await wait(350);
                    const { p, i } = sorted[ti];
                    const uid = state.players[p]?.field?.[i]?.uid ?? sorted[ti].uid ?? null;
                    let el = resolveTargetEl(p, i, uid);
                    if (!el || !(el.getBoundingClientRect?.().width > 2)) {
                        await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                        el = resolveTargetEl(p, i, uid);
                    }
                    if (!el || !(el.getBoundingClientRect?.().width > 2)) {
                        try { updateUI({ immediate: true }); } catch (e) { /* */ }
                        await new Promise((r) => requestAnimationFrame(r));
                        el = resolveTargetEl(p, i, uid);
                    }
                    if (!el) {
                        console.warn("[DF] baforada: DOM do alvo ausente", p, i);
                        continue;
                    }
                    const tr = el.getBoundingClientRect();
                    const tcx = tr.left + tr.width / 2;
                    const tcy = tr.top + tr.height / 2;
                    let ok = false;
                    if (gpu) {
                        try {
                            ok = await window.DfPixiVfx.playDragonBreathScene({
                                mode: "poison", cx: tcx, cy: tcy, cinematic: true, sweepFromLeft: true,
                            });
                        } catch (e) { ok = false; }
                    }
                    if (!ok && window.DfSpriteVfx) {
                        try {
                            const from = DfSpriteVfx._resolveOrigin?.(casterP, null, true)
                                || { x: tcx - 80, y: tcy - 40 };
                            ok = !!(await DfSpriteVfx.playPoisonSlimePng?.(from.x, from.y, tcx, tcy, {
                                targetP: p, targetI: i,
                            }));
                        } catch (e) { ok = false; }
                    }
                    if (!ok) {
                        const from = window.DfSpriteVfx?._resolveOrigin?.(casterP, null, true)
                            || { x: tcx - 80, y: tcy - 40 };
                        await animateBaforadaBreathLegacy(from.x, from.y, tcx, tcy, el);
                    }
                    el.classList.add("poison-flash");
                    setTimeout(() => el.classList.remove("poison-flash"), 1300);
                }
                await wait(300);
            }

            /** Morte por veneno na manutenção — burst + shatter antes do campo sumir. */
            async function playPoisonMaintenanceDeaths(victims, preDomSnaps) {
                const list = Array.isArray(victims) ? victims : [];
                if (!list.length) return;
                await ensureVfxReady();
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playPoisonExplosionBurstScene === "function";
                for (let vi = 0; vi < list.length; vi++) {
                    if (vi > 0) await wait(160);
                    const v = list[vi];
                    const snap = (v.uid != null && preDomSnaps?.get(v.uid))
                        || dfCaptureFieldCardSnap(v.p, v.i);
                    let cx = snap?.cx;
                    let cy = snap?.cy;
                    if (cx == null || cy == null) {
                        const el = getChampionDom(v.p, v.i);
                        const r = el?.getBoundingClientRect?.();
                        if (!r || r.width < 4) continue;
                        cx = r.left + r.width / 2;
                        cy = r.top + r.height / 2;
                    }
                    // O estouro de veneno JÁ é a animação de destruição. Rodar
                    // também a destruição genérica exibia duas explosões
                    // seguidas no mesmo campeão — o "aparece duas vezes" que o
                    // autor relatou. A destruição padrão fica só como reserva,
                    // quando o estouro não pôde rodar (sem GPU ou falhou).
                    let burstPlayed = false;
                    if (gpu) {
                        try {
                            await window.DfPixiVfx.playPoisonExplosionBurstScene(cx, cy, { cinematic: true });
                            burstPlayed = true;
                        } catch (e) { /* */ }
                    }
                    if (!burstPlayed) {
                        await playStandardDestroyVisual(v.p, v.i, {
                            uid: v.uid,
                            preDomSnaps,
                        });
                    }
                }
                await wait(120);
            }

            /** Explosão Venenosa — burst Pixi no campeão afetado (não baforada). */
            async function animateExplosaoVenenosaTargets(targets) {
                await ensureVfxReady();
                try {
                    await window.DfVfxEngine?.ensureCinematicReady?.({ waitFull: true, maxMs: 10000 });
                } catch (e) { /* */ }
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playPoisonExplosionBurstScene === "function";
                const list = Array.isArray(targets) ? targets : [];
                for (let ti = 0; ti < list.length; ti++) {
                    if (ti > 0) await wait(180);
                    const { p, i } = list[ti];
                    const el = getChampionDom(p, i);
                    if (!el) continue;
                    const r = el.getBoundingClientRect();
                    const cx = r.left + r.width / 2;
                    const cy = r.top + r.height / 2;
                    let ok = false;
                    if (gpu) {
                        ok = await window.DfPixiVfx.playPoisonExplosionBurstScene(cx, cy, {
                            cinematic: true,
                        });
                    }
                    el.classList.add("poison-flash");
                    setTimeout(() => el.classList.remove("poison-flash"), ok ? 900 : 1100);
                }
                await wait(200);
            }

            /** Mordida Venenosa — mordida + veneno Pixi; status só depois da cena. */
            async function animateMordidaVenenosa(targetP, targetI) {
                await ensureVfxReady();
                try {
                    await window.DfVfxEngine?.ensureCinematicReady?.({ waitFull: true, maxMs: 10000 });
                } catch (e) { /* */ }
                const el = getChampionDom(targetP, targetI);
                if (!el) return;
                const r = el.getBoundingClientRect();
                const cx = r.left + r.width / 2;
                const cy = r.top + r.height / 2;
                let ok = false;
                if (window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playPoisonBiteScene === "function") {
                    ok = await window.DfPixiVfx.playPoisonBiteScene(cx, cy, { cinematic: true });
                }
                if (!ok) {
                    el.classList.add("poison-flash");
                    setTimeout(() => el.classList.remove("poison-flash"), 1100);
                    await wait(400);
                    return;
                }
                el.classList.add("poison-flash");
                setTimeout(() => el.classList.remove("poison-flash"), 900);
                await wait(120);
            }

            // MISSEIS MÁGICOS — míssil voa até cada alvo + explosão + resultado.
            /** Atualiza Poder/joia no DOM sem remount (ex.: durante barragem Pixi). */
            function getChampionDomByUid(uid) {
                if (uid == null) return null;
                return document.querySelector(`.ccard[data-uid="${uid}"]`);
            }

            /** Resolve DOM do campeão por índice ou uid — evita cast silencioso após re-render. */
            function resolveChampionDom(pIdx, fIdx, uid) {
                let el = getChampionDom(pIdx, fIdx);
                if (el?.isConnected) return { el, fieldIdx: fIdx };
                if (uid != null) {
                    el = getChampionDomByUid(uid);
                    if (el?.isConnected) {
                        const live = state.players[pIdx]?.field?.findIndex((c) => c && c.uid === uid);
                        return { el, fieldIdx: live >= 0 ? live : fIdx };
                    }
                }
                return { el: null, fieldIdx: fIdx };
            }

            function syncChampionPowerDisplay(p, i, uid) {
                const c = uid != null
                    ? state.players[p]?.field?.find((x) => x && x.uid === uid)
                    : state.players[p]?.field[i];
                const el = (uid != null ? getChampionDomByUid(uid) : null) || getChampionDom(p, i);
                if (!c || !el || !el.isConnected) return;
                const pow = el.querySelector(".pow");
                if (pow) pow.textContent = String(c.currentPower);
                const showGem = typeof c.basePower === "number"
                    && c.currentPower !== c.basePower
                    && c.currentPower >= 1;
                let gem = el.querySelector(".gem-overlay");
                if (showGem) {
                    const n = Math.min(10, c.currentPower);
                    const src = typeof window.dfAssetUrl === "function"
                        ? window.dfAssetUrl(`gems/${n}.png`)
                        : `gems/${n}.png`;
                    if (!gem) {
                        gem = document.createElement("img");
                        gem.className = "gem-overlay gem-anim-debuff";
                        gem.alt = "";
                        el.appendChild(gem);
                    } else {
                        gem.classList.remove("gem-anim-buff", "gem-anim-fadeout");
                        gem.classList.add("gem-anim-debuff");
                    }
                    if (gem.getAttribute("src") !== src) gem.setAttribute("src", src);
                } else if (gem) {
                    gem.classList.remove("gem-anim-buff", "gem-anim-debuff");
                    gem.classList.add("gem-anim-fadeout");
                    setTimeout(() => { try { gem.remove(); } catch (e) { /* */ } }, 420);
                }
            }

            async function animateMissileStrike(fromX, fromY, targetP, targetI, resultLabel, resultClass, opts = {}) {
                let el = opts.uid != null ? getChampionDomByUid(opts.uid) : getChampionDom(targetP, targetI);
                // Preferir retângulo AO VIVO da arte/carta — mira no centro real do campeo.
                let tr = null;
                const art = el?.querySelector?.(":scope > img.card-art-bg, :scope > .card-art-bg, :scope img");
                const artR = art?.getBoundingClientRect?.();
                if (artR && artR.width >= 4) tr = artR;
                if (!tr || tr.width < 4) tr = el?.getBoundingClientRect?.();
                if (!tr || tr.width < 4) tr = championVisualRect(targetP, targetI);
                if ((!tr || tr.width < 4) && opts.tx != null && opts.ty != null && opts.tw > 4 && opts.th > 4) {
                    tr = {
                        left: opts.tx - opts.tw / 2,
                        top: opts.ty - opts.th / 2,
                        width: opts.tw,
                        height: opts.th,
                    };
                }
                if (!tr || tr.width < 4) return;
                const tx = tr.left + tr.width / 2;
                const ty = tr.top + tr.height / 2;
                const hit = opts.hit != null ? !!opts.hit : resultClass === "hit";
                const runImpact = async () => {
                    if (typeof opts.onImpact !== "function") return;
                    try { await opts.onImpact(); } catch (e) { /* */ }
                };
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playMagicMissileStrikeScene === "function";
                if (gpu) {
                    const ok = await window.DfPixiVfx.playMagicMissileStrikeScene({
                        fromX, fromY, cx: tx, cy: ty, hit,
                        label: resultLabel,
                        cinematic: true,
                        barrage: !!opts.barrage,
                        deferImpactLabel: !!opts.deferImpactLabel,
                        onImpact: () => runImpact(),
                    });
                    if (ok) {
                        el = (opts.uid != null ? getChampionDomByUid(opts.uid) : null) || el;
                        if (hit && el?.isConnected) {
                            el.style.transition = "filter .15s ease-out, transform .15s ease-out";
                            el.style.filter = "drop-shadow(0 0 14px rgba(255,80,40,1))";
                            el.style.transform = "translateY(-4px) scale(1.04)";
                            await wait(180);
                            if (el.isConnected) {
                                el.style.filter = "";
                                el.style.transform = "";
                            }
                        }
                        return;
                    }
                }
                const dx = tx - fromX;
                const dy = ty - fromY;
                const rot = Math.atan2(dy, dx) * 180 / Math.PI;
                const missile = document.createElement("div");
                missile.className = "mis-missile";
                missile.style.left = fromX + "px";
                missile.style.top = fromY + "px";
                missile.style.setProperty("--dx", dx + "px");
                missile.style.setProperty("--dy", dy + "px");
                missile.style.setProperty("--rot", rot + "deg");
                dfVfxMount(missile);
                await wait(780);
                missile.remove();
                await runImpact();
                const boom = document.createElement("div");
                boom.className = "mis-boom";
                boom.style.left = tx + "px";
                boom.style.top = ty + "px";
                dfVfxMount(boom);
                setTimeout(() => boom.remove(), 700);
                spawnParticles(tx, ty, FX.n(8));
                const res = document.createElement("div");
                res.className = "mis-result " + resultClass;
                res.textContent = resultLabel;
                res.style.left = tx + "px";
                res.style.top = ty + "px";
                dfVfxMount(res);
                setTimeout(() => res.remove(), 1150);
                el = (opts.uid != null ? getChampionDomByUid(opts.uid) : null) || el;
                if (resultClass === "hit" && el?.isConnected) {
                    el.style.transition = "filter .15s ease-out, transform .15s ease-out";
                    el.style.filter = "drop-shadow(0 0 14px rgba(255,80,40,1))";
                    el.style.transform = "translateY(-4px) scale(1.04)";
                    await wait(180);
                    if (el.isConnected) {
                        el.style.filter = "";
                        el.style.transform = "";
                    }
                }
            }

            function dfMissileOriginForPlayer(casterP) {
                const deckEl = getDeckPileEl(casterP);
                const deckRect = deckEl?.getBoundingClientRect?.();
                if (deckRect && deckRect.width > 4) {
                    return {
                        x: deckRect.left + deckRect.width / 2,
                        y: deckRect.top + deckRect.height / 2,
                    };
                }
                const q = $(`quadrant-${casterP}`);
                const qRect = q?.getBoundingClientRect?.()
                    || { left: 200, top: 400, width: 300, height: 200 };
                return { x: qRect.left + qRect.width / 2, y: qRect.top + qRect.height * 0.28 };
            }

            async function runMisseisMagicosTalent(ownerP) {
                const rawTargets = gatherEnemyTargets(ownerP, () => true);
                // Congela alvos (uid) ANTES de qualquer destroy — índices mudam no meio.
                const strikes = [];
                for (const { p, i } of rawTargets) {
                    const t = state.players[p]?.field[i];
                    if (!t || t.uid == null) continue;
                    const snap = dfCaptureFieldCardSnap(p, i);
                    const el = getChampionDom(p, i);
                    let tr = el?.getBoundingClientRect?.();
                    if (!tr || tr.width < 4) tr = championVisualRect(p, i);
                    if (!tr || tr.width < 4) continue;
                    strikes.push({
                        p,
                        uid: t.uid,
                        snap,
                        tx: tr.left + tr.width / 2,
                        ty: tr.top + tr.height / 2,
                        tw: tr.width,
                        th: tr.height,
                    });
                }
                if (!strikes.length) return { mutations: [], fieldPatches: [] };
                log(`${state.players[ownerP].name} lançou Mísseis Mágicos!`);
                const { x: fromX, y: fromY } = dfMissileOriginForPlayer(ownerP);
                const gpuBarrage = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.beginMagicMissilesBarrage === "function";
                let sky = null;
                let barrageOpen = false;
                // Destruições SÓ depois da barragem — await mid-loop travava
                // o 2º míssil e deixava estilhaço/💥 presos no Pixi.
                const pendingDeaths = [];
                /** @type {Array<Record<string, unknown>>} */
                const mutations = [];
                /** @type {Array<Record<string, unknown>>} */
                const fieldPatches = [];
                try {
                    if (gpuBarrage) {
                        barrageOpen = await window.DfPixiVfx.beginMagicMissilesBarrage();
                    }
                    if (!barrageOpen) {
                        sky = document.createElement("div");
                        sky.className = "mis-sky";
                        document.body.appendChild(sky);
                    }
                    for (const strike of strikes) {
                        const { p, uid } = strike;
                        const liveIdx = state.players[p]?.field.findIndex(
                            (c) => c && c.uid === uid,
                        );
                        if (liveIdx < 0) continue;
                        const target = state.players[p].field[liveIdx];
                        if (!target) continue;
                        // Ordem pedida pelo autor:
                        // 1) sorteio → erro mantém Barreira
                        // 2) acerto → anima míssil primeiro
                        // 3) Proteção Divina (se usada)
                        // 4) senão consome Barreira
                        // 5) senão −1 Poder
                        const rolledHit = Math.random() < 0.6;
                        let willHit = false;
                        let label = "FALHOU!";
                        let cls = "miss";
                        let pendingDefense = null;
                        if (rolledHit) {
                            willHit = true;
                            label = "−1 PODER";
                            cls = "hit";
                            pendingDefense = { p, uid, ownerP };
                        }
                        if (barrageOpen) {
                            try { window.DfPixiVfx?.ensureMagicMissilesBarrageScene?.(); } catch (e) { /* */ }
                        }
                        const liveEl = getChampionDomByUid(uid) || getChampionDom(p, liveIdx);
                        let liveTr = liveEl?.getBoundingClientRect?.();
                        if (!liveTr || liveTr.width < 4) liveTr = championVisualRect(p, liveIdx);
                        const aimTx = (liveTr && liveTr.width >= 4)
                            ? (liveTr.left + liveTr.width / 2)
                            : strike.tx;
                        const aimTy = (liveTr && liveTr.width >= 4)
                            ? (liveTr.top + liveTr.height / 2)
                            : strike.ty;
                        const aimTw = (liveTr && liveTr.width >= 4) ? liveTr.width : strike.tw;
                        const aimTh = (liveTr && liveTr.width >= 4) ? liveTr.height : strike.th;
                        await animateMissileStrike(fromX, fromY, p, liveIdx, label, cls, {
                            hit: willHit,
                            barrage: barrageOpen,
                            uid,
                            tx: aimTx,
                            ty: aimTy,
                            tw: aimTw,
                            th: aimTh,
                            deferImpactLabel: !!pendingDefense,
                            onImpact: async () => {
                                if (!pendingDefense) return;
                                const defIdx = state.players[p].field.findIndex(
                                    (c) => c && c.uid === uid,
                                );
                                if (defIdx < 0) return;
                                const live = state.players[p].field[defIdx];
                                if (!live) return;
                                if (await offerReactiveProtection(ownerP, p, live, "Mísseis Mágicos")) {
                                    label = "BLOQUEADO!";
                                    cls = "miss";
                                    willHit = false;
                                    try {
                                        window.DfPixiVfx?.spawnMagicMissileOutcomeLabel?.(
                                            aimTx, aimTy, label, false,
                                        );
                                    } catch (e) { /* */ }
                                    return;
                                }
                                if (await consumeBarrierIfAny(p, defIdx, "Mísseis Mágicos")) {
                                    label = "BLOQUEADO!";
                                    cls = "miss";
                                    willHit = false;
                                    try {
                                        window.DfPixiVfx?.spawnMagicMissileOutcomeLabel?.(
                                            aimTx, aimTy, label, false,
                                        );
                                    } catch (e) { /* */ }
                                    // Barreira consumida: sync status no MP via commit separado se necessário
                                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                        fieldPatches.push({
                                            targetP: p,
                                            targetI: defIdx,
                                            barrier: false,
                                            barrierTurns: 0,
                                        });
                                    }
                                    return;
                                }
                                reduceChampionPower(live, 1, p, defIdx);
                                syncChampionPowerDisplay(p, defIdx, uid);
                                const powAfter = live.currentPower ?? 0;
                                mutations.push({
                                    op: "reducePower",
                                    targetP: p,
                                    targetI: defIdx,
                                    amount: 1,
                                    destroyIfZero: true,
                                    awardVpTo: ownerP,
                                    reason: "missemagicos",
                                });
                                if (powAfter <= 0) {
                                    fieldPatches.push({ targetP: p, targetI: defIdx, removed: true });
                                    const deathSnap = strike.snap
                                        ? { ...strike.snap, uid, currentPower: 0 }
                                        : dfCaptureFieldCardSnap(p, defIdx);
                                    destroyChampion(p, defIdx, ownerP, "missemagicos", {
                                        skipOnlineSync: true,
                                        deferShatter: true,
                                    });
                                    if (deathSnap) pendingDeaths.push(deathSnap);
                                } else {
                                    fieldPatches.push({
                                        targetP: p,
                                        targetI: defIdx,
                                        currentPower: powAfter,
                                    });
                                }
                                checkWin();
                            },
                        });
                        if (!barrageOpen) {
                            updateUI({ immediate: true });
                            await wait(180);
                        }
                    }
                } finally {
                    if (barrageOpen && window.DfPixiVfx?.endMagicMissilesBarrage) {
                        try { await window.DfPixiVfx.endMagicMissilesBarrage(); } catch (e) { /* */ }
                    }
                    if (sky) {
                        sky.classList.add("fade-out");
                        setTimeout(() => { try { sky.remove(); } catch (e) { /* */ } }, 450);
                    }
                }
                // Estilhaços depois que a barragem Pixi já terminou (palco limpo).
                for (const deathSnap of pendingDeaths) {
                    try {
                        await Promise.race([
                            playChampionDestroyVisual(deathSnap, null),
                            wait(1400),
                        ]);
                    } catch (e) { /* */ }
                }
                try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
                try { window.__dfResetQuadCache?.(); } catch (e) { /* */ }
                updateUI({ immediate: true });

                // MP: persiste dano no servidor (SYNC_STATE cosmético não grava poder).
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote && mutations.length) {
                    try {
                        if (dfOnlineNetReady()) {
                            const ack = await dfOnlineSendActionAwait({
                                type: "FIELD_COMMIT",
                                mutations,
                            }, { noSnap: true });
                            if (ack?.authoritativeState?.players?.length) {
                                dfOnlineReconcileSnapshot(
                                    { state: ack.authoritativeState, full: true },
                                    { skipPhase: true },
                                );
                                updateUI({ immediate: true });
                            }
                        }
                    } catch (e) {
                        console.warn("[DF online] missemagicos FIELD_COMMIT", e);
                    }
                }
                return { mutations, fieldPatches };
            }

            /** Peer MP: barragem cosmética (sem rolar dano / proteção — estado via fieldPatches/SYNC). */
            async function playMisseisMagicosPeerVisual(ownerP) {
                if (!window.__DF_ONLINE) return;
                const rawTargets = gatherEnemyTargets(ownerP, () => true);
                const strikes = [];
                for (const { p, i } of rawTargets) {
                    const t = state.players[p]?.field[i];
                    if (!t) continue;
                    const el = getChampionDom(p, i);
                    let tr = el?.getBoundingClientRect?.();
                    if (!tr || tr.width < 4) tr = championVisualRect(p, i);
                    if (!tr || tr.width < 4) continue;
                    strikes.push({
                        p,
                        i,
                        tx: tr.left + tr.width / 2,
                        ty: tr.top + tr.height / 2,
                        tw: tr.width,
                        th: tr.height,
                    });
                }
                if (!strikes.length) return;
                const { x: fromX, y: fromY } = dfMissileOriginForPlayer(ownerP);
                const gpuBarrage = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.beginMagicMissilesBarrage === "function";
                let sky = null;
                let barrageOpen = false;
                try {
                    if (gpuBarrage) {
                        barrageOpen = await window.DfPixiVfx.beginMagicMissilesBarrage();
                    }
                    if (!barrageOpen) {
                        sky = document.createElement("div");
                        sky.className = "mis-sky";
                        document.body.appendChild(sky);
                    }
                    for (const strike of strikes) {
                        if (barrageOpen) {
                            try { window.DfPixiVfx?.ensureMagicMissilesBarrageScene?.(); } catch (e) { /* */ }
                        }
                        await animateMissileStrike(fromX, fromY, strike.p, strike.i, "!", "hit", {
                            hit: true,
                            barrage: barrageOpen,
                            tx: strike.tx,
                            ty: strike.ty,
                            tw: strike.tw,
                            th: strike.th,
                            deferImpactLabel: true,
                        });
                        if (!barrageOpen) await wait(120);
                    }
                } finally {
                    if (barrageOpen && window.DfPixiVfx?.endMagicMissilesBarrage) {
                        try { await window.DfPixiVfx.endMagicMissilesBarrage(); } catch (e) { /* */ }
                    }
                    if (sky) {
                        sky.classList.add("fade-out");
                        setTimeout(() => { try { sky.remove(); } catch (e) { /* */ } }, 450);
                    }
                }
            }

            async function animateMisseisMagicos(casterP, strikeFn) {
                const { x: fromX, y: fromY } = dfMissileOriginForPlayer(casterP);
                await strikeFn(fromX, fromY);
            }

            /** Eventos já aplicados em state via DfEffectsResolve — só VFX/log. */
            async function playOnEnterEvents(events, casterIdx, fieldIdx, vfxCtx = {}) {
                for (const ev of events || []) {
                    switch (ev.type) {
                        case "RAPIDEZ":
                            log(`${state.players[casterIdx].name} ganhou +1 ação!`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({ kind: "wings", casterIdx: ev.casterIdx ?? casterIdx });
                            }
                            await animateWings(ev.casterIdx ?? casterIdx);
                            break;
                        case "PESADELO":
                            log(`💀 Pesadelo em ${state.players[ev.targetIdx].name}.`);
                            try { window.sfx && window.sfx("nightmare"); } catch (e) {}
                            // MP: broadcast ANTES do await local (peer em tempo real).
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({ kind: "pesadelo", casterIdx: ev.casterIdx, targetIdx: ev.targetIdx });
                            }
                            await playPesadeloSmokeVisual(ev.targetIdx, ev.casterIdx ?? casterIdx);
                            dfSyncPesadeloShrouds();
                            break;
                        case "DESACELERAR":
                            log(`${state.players[ev.targetIdx].name} será desacelerado no próximo turno.`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "desacelerar",
                                    casterIdx: ev.casterIdx ?? casterIdx,
                                    targetIdx: ev.targetIdx,
                                    casterFieldIdx: fieldIdx,
                                });
                            }
                            await animateDesacelerar(ev.casterIdx ?? casterIdx, fieldIdx, ev.targetIdx);
                            break;
                        case "ROUBAR": {
                            const cardLabel = typeof ev.card === "string"
                                ? ev.card
                                : (ev.card?.name || ev.cardSnap?.name || "?");
                            log(`🃏 Roubou ${cardLabel} de ${state.players[ev.targetIdx].name}.`);
                            try { window.sfx && window.sfx("roubar"); } catch (e) {}
                            const stealCard = ev.cardSnap || (typeof ev.card === "object" ? ev.card : {
                                name: cardLabel,
                                power: ev.cardPower,
                                currentPower: ev.cardPower,
                            });
                            // Snapshot origem ANTES do updateUI (carta some da mão).
                            const qVic = $(`quadrant-${dfQuadrantForPlayer(ev.targetIdx)}`);
                            const originEl = qVic?.querySelector(
                                ".hand-wrap .hcard, .ai-hand-wrap .ai-back, .ai-hand-wrap .hcard, .hcard, .ai-back",
                            );
                            const originRect = originEl?.getBoundingClientRect?.();
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "roubar",
                                    casterIdx: ev.casterIdx ?? casterIdx,
                                    targetIdx: ev.targetIdx,
                                    card: stealCard,
                                    cardSnap: stealCard,
                                    originRect: originRect && originRect.width
                                        ? {
                                            left: originRect.left,
                                            top: originRect.top,
                                            width: originRect.width,
                                            height: originRect.height,
                                        }
                                        : null,
                                });
                            }
                            updateUI({ immediate: true });
                            await dfFlushHandLayout();
                            await animateRoubar(
                                ev.casterIdx ?? casterIdx,
                                ev.targetIdx,
                                stealCard,
                                { originRect },
                            );
                            updateUI();
                            break;
                        }
                        case "MALDICAO_SETE_MARES":
                            // Garante Silêncio na mão mesmo se o onEnter veio só do servidor MP.
                            try {
                                const cIdx = ev.casterIdx ?? casterIdx;
                                for (let p = 0; p < state.playersCount; p++) {
                                    if (p === cIdx) continue;
                                    const opp = state.players[p];
                                    if (!opp) continue;
                                    opp.maldicaoForgetNext = true;
                                    (opp.hand || []).forEach((card) => {
                                        if (card?.category === "champion") card.silencedInHand = true;
                                    });
                                }
                            } catch (eM) { /* */ }
                            try { window.sfx && window.sfx("maldicao"); } catch (e) {}
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({ kind: "maldicao_sete_mares", casterIdx: ev.casterIdx });
                            }
                            await animateMaldicaoSeteMares(ev.casterIdx);
                            log(`🔮 ${state.players[casterIdx].field[fieldIdx]?.name || "Campeão"} lançou MALDIÇÃO DOS SETE MARES — todo Campeão na mão dos adversários ficou amaldiçoado!`);
                            updateUI();
                            break;
                        case "TROCA_INJUSTA": {
                            const enemyName = state.players[ev.enemyP]?.field?.[ev.enemyI]?.name || "inimigo";
                            // MP: envelope do SUMMON já leva troca_injusta ao peer — não PRESENT paralelo.
                            await animateTrocaInjusta(ev.casterIdx, ev.fieldIdx, ev.enemyP, ev.enemyI);
                            log(`${state.players[casterIdx].name} trocou de lugar com ${enemyName} (Troca Injusta)!`);
                            break;
                        }
                        case "FORTALECER":
                            log(`${state.players[ev.casterIdx].name} fortaleceu ${state.players[ev.targetP].field[ev.targetI].name}.`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const buffed = state.players[ev.targetP]?.field?.[ev.targetI];
                                const powerAfter = buffed?.currentPower ?? buffed?.power ?? 0;
                                dfOnlineBroadcastVisual({
                                    kind: "strong_arm",
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    powerAfter,
                                    casterP: ev.casterIdx,
                                    casterField: fieldIdx,
                                    fieldPatches: [{ targetP: ev.targetP, targetI: ev.targetI, currentPower: powerAfter }],
                                });
                                try {
                                    await dfOnlineCommitStatus(ev.targetP, ev.targetI, { broadcast: false });
                                } catch (e) { /* */ }
                            }
                            await animateStrongArm(ev.targetP, ev.targetI, {
                                casterP: ev.casterIdx,
                                casterField: fieldIdx,
                                forceDomFallback: true,
                            });
                            break;
                        case "DEVOUR":
                            log(`${state.players[casterIdx].name}: devorou um aliado (+Poder).`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                // Motor já removeu a presa: ev.fieldIdx = índice pós-remoção do Devorar.
                                // Peer ainda tem o campo pré-devorar → patch de poder no índice ORIGINAL.
                                const preyI = ev.devouredI;
                                const casterPostI = (ev.fieldIdx != null) ? (ev.fieldIdx | 0) : (
                                    (typeof preyI === "number" && preyI < fieldIdx)
                                        ? fieldIdx - 1
                                        : fieldIdx
                                );
                                const casterPreI = (typeof preyI === "number" && preyI < casterPostI)
                                    ? casterPostI + 1
                                    : casterPostI;
                                const casterLive = state.players[ev.casterIdx]?.field?.[casterPostI];
                                const powerAfter = casterLive?.currentPower
                                    ?? ev.powerAfter
                                    ?? casterLive?.power
                                    ?? 0;
                                const fieldPatches = [];
                                if (casterLive || powerAfter != null) {
                                    fieldPatches.push({
                                        targetP: ev.casterIdx,
                                        targetI: casterPreI,
                                        currentPower: powerAfter,
                                    });
                                }
                                if (preyI != null) {
                                    fieldPatches.push({
                                        targetP: ev.casterIdx,
                                        targetI: preyI,
                                        removed: true,
                                    });
                                }
                                dfOnlineBroadcastVisual({
                                    kind: "devour",
                                    targetP: ev.casterIdx,
                                    targetI: preyI,
                                    casterP: ev.casterIdx,
                                    casterFieldIdx: casterPreI,
                                    fieldPatches,
                                });
                            }
                            await animateDevour(ev.casterIdx, ev.devouredI, vfxCtx);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                try {
                                    const preyI = ev.devouredI;
                                    const casterPostI = (ev.fieldIdx != null) ? (ev.fieldIdx | 0) : (
                                        (typeof preyI === "number" && preyI < fieldIdx)
                                            ? fieldIdx - 1
                                            : fieldIdx
                                    );
                                    const casterLive = state.players[ev.casterIdx]?.field?.[casterPostI];
                                    const powerAfter = casterLive?.currentPower
                                        ?? ev.powerAfter
                                        ?? casterLive?.power
                                        ?? 0;
                                    // destroy primeiro (índice pré-remoção no servidor), depois poder no pós.
                                    const mutations = [];
                                    if (preyI != null) {
                                        mutations.push({
                                            op: "destroy",
                                            targetP: ev.casterIdx,
                                            targetI: preyI,
                                            reason: "devorar",
                                            noVpOnKill: true,
                                        });
                                    }
                                    mutations.push({
                                        op: "setStatus",
                                        targetP: ev.casterIdx,
                                        targetI: casterPostI,
                                        flags: { currentPower: powerAfter },
                                    });
                                    await dfOnlineCommitMutations(mutations, { reconcile: true });
                                } catch (e) {
                                    console.warn("[DF online] devour FIELD_COMMIT", e);
                                }
                                try {
                                    const postI = (ev.fieldIdx != null) ? (ev.fieldIdx | 0) : fieldIdx;
                                    const el = getChampionDom(ev.casterIdx, postI);
                                    if (el) {
                                        el.classList.remove("combat-animating", "combat-src-hidden");
                                        el.style.removeProperty("visibility");
                                        el.style.removeProperty("opacity");
                                        el.style.removeProperty("pointer-events");
                                    }
                                } catch (eRest) { /* */ }
                            }
                            break;
                        case "BARRIER_BLOCKED":
                            log(`${state.players[ev.targetP]?.field?.[ev.targetI]?.name || "Campeão"}: Barreira bloqueou!`);
                            await animateBarrierBlock(ev.targetP, ev.targetI);
                            updateUI();
                            break;
                        case "BOLA_DE_FOGO":
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const live = state.players[ev.targetP]?.field?.[ev.targetI];
                                const fieldPatches = live
                                    ? [{ targetP: ev.targetP, targetI: ev.targetI, currentPower: live.currentPower ?? 0 }]
                                    : [{ targetP: ev.targetP, targetI: ev.targetI, removed: true }];
                                dfOnlineBroadcastVisual({
                                    kind: "bola_de_fogo",
                                    casterP: ev.casterIdx,
                                    casterField: fieldIdx,
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    powerAfter: live ? (live.currentPower ?? 0) : 0,
                                    fieldPatches,
                                });
                            }
                            await playBolaDeFogoVisual(ev.casterIdx, fieldIdx, ev.targetP, ev.targetI, false);
                            break;
                        case "ASSASSINAR":
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "assassinar",
                                    casterP: ev.casterIdx,
                                    casterField: fieldIdx,
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    fieldPatches: [{ targetP: ev.targetP, targetI: ev.targetI, removed: true }],
                                });
                            }
                            await playAssassinarVisual(ev.casterIdx, fieldIdx, ev.targetP, ev.targetI, vfxCtx);
                            break;
                        case "IMITAR":
                            try { window.sfx && window.sfx("imitar"); } catch (e) {}
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const mim = state.players[ev.casterIdx]?.field?.[fieldIdx];
                                const idPatch = mim ? {
                                    targetP: ev.casterIdx,
                                    targetI: fieldIdx,
                                    mimico: true,
                                    mimicAbilityName: mim.mimicAbilityName || ev.abilityName || "Habilidade",
                                    mimicAbilityDesc: mim.mimicAbilityDesc || mim.abilityDesc || "",
                                    mimicSourceName: mim.mimicSourceName || ev.mimicName || "",
                                    mimicOnEnter: mim.mimicOnEnter ?? mim.onEnter ?? null,
                                    mimicOnDestroy: mim.mimicOnDestroy ?? mim.onDestroy ?? null,
                                    mimicConstantEffect: mim.mimicConstantEffect ?? mim.constantEffect ?? null,
                                    abilityType: mim.abilityType ?? null,
                                    abilityName: mim.abilityName ?? null,
                                    abilityDesc: mim.abilityDesc ?? null,
                                    onEnter: mim.onEnter ?? null,
                                    onDestroy: mim.onDestroy ?? null,
                                    talentEffect: mim.talentEffect ?? null,
                                    constantEffect: mim.constantEffect ?? null,
                                } : null;
                                dfOnlineBroadcastVisual({
                                    kind: "imitar", allyP: ev.allyP, allyI: ev.allyI,
                                    casterP: ev.casterIdx, casterFieldIdx: fieldIdx,
                                    mimicAbilityName: ev.abilityName || "Habilidade",
                                    mimicSourceName: ev.mimicName,
                                    fieldPatches: idPatch ? [idPatch] : undefined,
                                });
                                if (idPatch) {
                                    const { targetP, targetI, ...flags } = idPatch;
                                    try {
                                        await dfOnlineCommitMutations([{
                                            op: "setStatus",
                                            targetP,
                                            targetI,
                                            flags,
                                        }], { reconcile: true });
                                    } catch (e) {
                                        console.warn("[DF online] imitar FIELD_COMMIT", e);
                                    }
                                }
                            }
                            await animateImitar(ev.allyP, ev.allyI, ev.casterIdx, fieldIdx);
                            log(`🎭 ${state.players[ev.casterIdx].field[fieldIdx]?.name || "Campeão"} imitou a habilidade de ${ev.mimicName}: ${ev.abilityName}.`);
                            break;
                        case "URSIFICACAO":
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const banjo = state.players[ev.casterIdx]?.field?.[ev.targetI];
                                dfOnlineBroadcastVisual({
                                    kind: "ursificacao",
                                    allyP: ev.casterIdx,
                                    allyI: ev.targetI,
                                    fieldPatches: banjo ? [{
                                        targetP: ev.casterIdx,
                                        targetI: ev.targetI,
                                        name: banjo.name,
                                        power: banjo.power,
                                        basePower: banjo.basePower,
                                        currentPower: banjo.currentPower ?? ev.newPower ?? banjo.power ?? 0,
                                        abilityType: banjo.abilityType ?? null,
                                        abilityName: banjo.abilityName ?? null,
                                        abilityDesc: banjo.abilityDesc ?? null,
                                        onEnter: banjo.onEnter ?? null,
                                        onDestroy: banjo.onDestroy ?? null,
                                        talentEffect: banjo.talentEffect ?? null,
                                        summonRitual: banjo.summonRitual ?? null,
                                        constantEffect: banjo.constantEffect ?? null,
                                        isToken: !!banjo.isToken,
                                        hidden: !!banjo.hidden,
                                    }] : undefined,
                                });
                            }
                            await playUrsificacaoVisual(ev.casterIdx, ev.targetI);
                            log(`🐻 ${ev.origName} foi Ursificado — virou BANJO (Poder ${ev.newPower})!`);
                            break;
                        case "TRANSFORM_VULN_DESTROY":
                        case "TRANSFORMAR_BICHINHO": {
                            const success = ev.type === "TRANSFORMAR_BICHINHO" && ev.success;
                            const puff = await playTransformarBichinhoVisual(ev.targetP, ev.targetI, success);
                            await dismissTransformPuff(puff);
                            if (ev.type !== "TRANSFORM_VULN_DESTROY") {
                                const champEl = getChampionDom(ev.targetP, ev.targetI);
                                if (champEl) {
                                    try { window.applyCardArtTree?.(champEl); } catch (e) {}
                                }
                                updateUI();
                            }
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                if (ev.type === "TRANSFORM_VULN_DESTROY") {
                                    dfOnlineBroadcastVisual({
                                        kind: "transformar_bichinho",
                                        casterP: ev.casterIdx, casterField: fieldIdx,
                                        targetP: ev.targetP, targetI: ev.targetI,
                                        success: true,
                                        fieldPatches: [{ targetP: ev.targetP, targetI: ev.targetI, removed: true }],
                                    });
                                    try {
                                        await dfOnlineCommitMutations([{
                                            op: "destroy",
                                            targetP: ev.targetP,
                                            targetI: ev.targetI,
                                            awardVpTo: ev.casterIdx,
                                            forceAward: true,
                                            reason: "transformarBichinho",
                                        }], { reconcile: true });
                                    } catch (e) { /* */ }
                                } else {
                                    const live = state.players[ev.targetP]?.field?.[ev.targetI];
                                    const idPatch = live
                                        ? dfOnlineIdentityFieldPatch(ev.targetP, ev.targetI, live)
                                        : null;
                                    dfOnlineBroadcastVisual({
                                        kind: "transformar_bichinho",
                                        casterP: ev.casterIdx, casterField: fieldIdx,
                                        targetP: ev.targetP, targetI: ev.targetI,
                                        success: !!ev.success,
                                        fieldPatches: idPatch ? [idPatch] : undefined,
                                    });
                                    if (live) await dfOnlineCommitTransformToken(ev.targetP, ev.targetI, live);
                                }
                            }
                            if (ev.type === "TRANSFORM_VULN_DESTROY") {
                                log(`☠️ ${ev.origName} (Vulnerável) foi destruído ao tentar virar Bichinho Fofinho!`);
                                floatText(`☠️ ${ev.origName} destruído (Vulnerável)!`, "warn center", 1800);
                            } else if (success) {
                                const newName = state.players[ev.targetP]?.field[ev.targetI]?.name;
                                if (newName) {
                                    window.dfPrefetchCardArt?.(newName);
                                    await window.dfEnsureArtsLoaded?.([newName]).catch(() => {});
                                }
                                log(`✨ ${ev.origName} (Poder ${ev.origPower}) virou BICHINHO FOFINHO (Poder ${ev.newPower})!`);
                            } else {
                                const newName = state.players[ev.targetP]?.field[ev.targetI]?.name;
                                if (newName) {
                                    window.dfPrefetchCardArt?.(newName);
                                    await window.dfEnsureArtsLoaded?.([newName]).catch(() => {});
                                }
                                log(`💀 ${ev.origName} (Poder ${ev.origPower}) virou O CHEFÃO (Poder ${ev.newPower})! O feitiço deu errado!`);
                            }
                            break;
                        }
                        case "FURIA": {
                            const fIdx = ev.fieldIdx ?? fieldIdx;
                            const champ = state.players[ev.casterIdx]?.field?.[fIdx];
                            log(`🔥 ${champ?.name || "Campeão"} entrou em FÚRIA (+1 Poder por 1 rodada)!`);
                            try { window.sfx && window.sfx("buff_power"); } catch (e) {}
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote && champ) {
                                dfOnlineBroadcastVisual({
                                    kind: "fury",
                                    ownerP: ev.casterIdx,
                                    fieldIdx: fIdx,
                                    fieldPatches: [{
                                        targetP: ev.casterIdx,
                                        targetI: fIdx,
                                        fury: true,
                                        furyTurns: champ.furyTurns ?? 1,
                                        furyStacks: champ.furyStacks ?? ev.furyStacks ?? 1,
                                        furyBonusActive: !!champ.furyBonusActive,
                                        currentPower: champ.currentPower ?? champ.power ?? 0,
                                    }],
                                });
                            }
                            const fEl = getChampionDom(ev.casterIdx, fIdx);
                            if (fEl) {
                                fEl.classList.add("fury-flash");
                                setTimeout(() => fEl.classList.remove("fury-flash"), 900);
                            }
                            if (window.DfSpriteVfx?.playFuryBurst) {
                                await window.DfSpriteVfx.playFuryBurst(ev.casterIdx, fIdx);
                            }
                            updateUI();
                            break;
                        }
                        case "GRITO_DE_GUERRA":
                            log(`🔥 Grito de Guerra concedeu Fúria a ${(ev.applied || []).map((t) => t.name).join(" e ")}.`);
                            await playFuryGrantTargets(ev.casterIdx, ev.applied || []);
                            break;
                        case "GUARDIAO":
                            try { window.sfx && window.sfx("shield"); } catch (e) {}
                            log(`🛡️ Guardião protegeu ${(ev.names || []).join(" e ")} por 1 rodada!`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const fieldPatches = (ev.picks || []).map((pk) => ({
                                    targetP: pk.p,
                                    targetI: pk.i,
                                    shielded: true,
                                    shieldedTurns: 1,
                                }));
                                dfOnlineBroadcastVisual({
                                    kind: "guardian", casterP: ev.casterIdx, picks: ev.picks, fieldPatches,
                                });
                            }
                            await animateGuardiao(ev.casterIdx, ev.picks || []);
                            break;
                        case "AURA_ANTI_MAGIA":
                            log(`⬡ ${state.players[ev.casterIdx]?.field?.[fieldIdx]?.name || "Campeão"} ganhou Barreira permanente (Aura Anti-Magia)!`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "barrier_grant",
                                    ownerP: ev.casterIdx,
                                    indices: [fieldIdx],
                                    fieldPatches: [{
                                        targetP: ev.casterIdx,
                                        targetI: fieldIdx,
                                        barrier: true,
                                        barrierPermanent: true,
                                        barrierTurns: 0,
                                    }],
                                });
                            }
                            await animateBarrierGrant(ev.casterIdx, [fieldIdx]);
                            break;
                        case "AURA_DE_FOGO":
                            log(`🔥 Aura de Fogo em ${(ev.names || []).join(" e ")} (3 rodadas)!`);
                            floatText("🔥 AURA DE FOGO — 3 rodadas", "warn center", 1800);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const fieldPatches = (ev.indices || []).map((i) => ({
                                    targetP: ev.casterIdx,
                                    targetI: i,
                                    fireAura: true,
                                    fireAuraTurns: 3,
                                }));
                                dfOnlineBroadcastVisual({
                                    kind: "fire_aura", ownerP: ev.casterIdx, indices: ev.indices, fieldPatches,
                                });
                            }
                            if (ev.indices?.length) await animateAuraDeFogoGrant(ev.casterIdx, ev.indices);
                            break;
                        case "FUMACA_TOXICA":
                            try { window.sfx && window.sfx("poison"); } catch (e) {}
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const immuneKeys = new Set(
                                    (ev.immune || []).map((im) => `${im.p}:${im.i}`),
                                );
                                const fieldPatches = (ev.picks || [])
                                    .filter((pk) => !immuneKeys.has(`${pk.p}:${pk.i}`))
                                    .map((pk) => ({
                                        targetP: pk.p,
                                        targetI: pk.i,
                                        vulnerable: true,
                                    }));
                                dfOnlineBroadcastVisual({
                                    kind: "fumaca_toxica",
                                    casterP: ev.casterIdx,
                                    casterFieldIdx: fieldIdx,
                                    picks: ev.picks,
                                    immune: ev.immune || [],
                                    fieldPatches,
                                });
                            }
                            await playFumacaToxicaVisual(ev.casterIdx, fieldIdx, ev.picks || []);
                            if ((ev.names || []).length) {
                                log(`☣️ ${state.players[ev.casterIdx]?.name || "Jogador"}: Fumaça Tóxica — ${(ev.names || []).join(" e ")} ficaram Vulneráveis!`);
                            }
                            await dfAnnounceBarrierVulnerableImmunity(ev.immune);
                            break;
                        case "RAIO_DUPLO":
                            // MP: envelope/auth do SUMMON já sincroniza poder — não PRESENT
                            // cosmético (evita removed:true falso e double patch).
                            try { window.sfx && window.sfx("lightning"); } catch (e) {}
                            for (const h of ev.hits || []) {
                                await animateRaioDuploStrike(ev.casterIdx, h.p, h.i);
                            }
                            log(`⚡ Raio Duplo atingiu ${(ev.names || []).join(" e ")} (-1 Poder cada, sem PV por destruição).`);
                            break;
                        case "DEFENSOR":
                            log(`🛡️ ${state.players[ev.casterIdx]?.field?.[ev.fieldIdx ?? fieldIdx]?.name || "Campeão"} recebeu Proteção permanente.`);
                            updateUI();
                            break;
                        case "RAJADA_CONGELANTE_FREEZE":
                            log(`❄️ ${ev.targetName || "Campeão"} foi Congelado por 2 rodadas.`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const iced = state.players[ev.targetP]?.field?.[ev.targetI];
                                const fieldPatches = iced
                                    ? [{
                                        targetP: ev.targetP,
                                        targetI: ev.targetI,
                                        frozen: true,
                                        frozenTurns: iced.frozenTurns ?? 2,
                                    }]
                                    : [];
                                // Broadcast ANTES do await — peer vê gelo em paralelo.
                                dfOnlineBroadcastVisual({
                                    kind: "rajada_congelante",
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    casterP: ev.casterIdx,
                                    fieldPatches,
                                });
                                try {
                                    await dfOnlineCommitStatus(ev.targetP, ev.targetI, { broadcast: false });
                                } catch (e) { /* */ }
                            }
                            await animateIce(ev.targetP, ev.targetI);
                            updateUI();
                            break;
                        case "RAJADA_CONGELANTE_DESTROY":
                            log(`💥 ${ev.targetName || "Campeão"} já estava Congelado e foi destruído pela Rajada Congelante${ev.vpGain ? " (+1 PV)" : " (Sem Honra — 0 PV)"}.`);
                            floatText("❄️💥 Estilhaçado pelo gelo!", "warn center", 1800);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "rajada_congelante_destroy",
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    fieldPatches: [{ targetP: ev.targetP, targetI: ev.targetI, removed: true }],
                                });
                            }
                            await playFreezeShatterDestroyVisual(ev.targetP, ev.targetI, vfxCtx);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                try {
                                    await dfOnlineCommitMutations([{
                                        op: "destroy",
                                        targetP: ev.targetP,
                                        targetI: ev.targetI,
                                        awardVpTo: ev.vpGain ? ev.casterIdx : undefined,
                                        noVpOnKill: !ev.vpGain,
                                        reason: "rajadaCongelante",
                                    }], { reconcile: true });
                                } catch (e) { /* */ }
                            }
                            break;
                        case "CORROMPER":
                            log(ev.alreadyNoHonor
                                ? `💀 ${ev.targetName || "Campeão"} já estava corrompido; Corromper não acumulou.`
                                : `💀 ${ev.targetName || "Campeão"} ficou corrompido — o adversário que o destruir não recebe Ponto de vitória.`);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote && !ev.alreadyNoHonor) {
                                dfOnlineBroadcastVisual({
                                    kind: "corrupt",
                                    casterP: ev.casterIdx ?? casterIdx,
                                    casterFieldIdx: fieldIdx,
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    fieldPatches: [{
                                        targetP: ev.targetP,
                                        targetI: ev.targetI,
                                        corruptedNoHonor: true,
                                    }],
                                });
                                try {
                                    await dfOnlineCommitStatus(ev.targetP, ev.targetI, { broadcast: false });
                                } catch (e) { /* */ }
                            }
                            {
                                const el = getChampionDom(ev.targetP, ev.targetI);
                                if (el && window.DfVfxEngine?.wantsGpuPresentation?.()
                                    && typeof window.DfPixiVfx?.playCorruptScene === "function") {
                                    const r = el.getBoundingClientRect();
                                    await window.DfPixiVfx.playCorruptScene(
                                        r.left + r.width / 2,
                                        r.top + r.height / 2,
                                        { cinematic: true },
                                    );
                                }
                            }
                            updateUI();
                            break;
                        case "MORDIDA_VENENOSA":
                            if (!ev.applied) {
                                log(`☠️ ${ev.targetName || "Campeão"} já estava Envenenado; Mordida Venenosa não alterou o veneno.`);
                            } else {
                                log(`🐍 ${ev.targetName || "Campeão"} recebeu Envenenado por 2 rodadas.`);
                                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                    const bitten = state.players[ev.targetP]?.field?.[ev.targetI];
                                    const fieldPatches = bitten
                                        ? [{
                                            targetP: ev.targetP,
                                            targetI: ev.targetI,
                                            poisoned: true,
                                            poisonTurns: bitten.poisonTurns ?? 2,
                                            poisonedByP: bitten.poisonedByP ?? ev.casterIdx,
                                        }]
                                        : [];
                                    dfOnlineBroadcastVisual({
                                        kind: "mordida_venenosa",
                                        targetP: ev.targetP,
                                        targetI: ev.targetI,
                                        casterP: ev.casterIdx ?? casterIdx,
                                        casterFieldIdx: fieldIdx,
                                        fieldPatches,
                                    });
                                    try {
                                        await dfOnlineCommitStatus(ev.targetP, ev.targetI, { broadcast: false });
                                    } catch (e) { /* */ }
                                }
                                await animateMordidaVenenosa(ev.targetP, ev.targetI);
                                updateUI();
                            }
                            break;
                        case "INCENDIAR":
                            log(`🔥 ${ev.targetName || "Campeão"} ficou Em Chamas por 4 rodadas (−1 Poder após cada manutenção).`);
                            floatText("🔥 EM CHAMAS — 4 rodadas", "warn center", 1800);
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                const burned = state.players[ev.targetP]?.field?.[ev.targetI];
                                const fieldPatches = burned
                                    ? [{
                                        targetP: ev.targetP,
                                        targetI: ev.targetI,
                                        burning: true,
                                        burningTurns: burned.burningTurns ?? 4,
                                        burningByP: burned.burningByP ?? ev.casterIdx,
                                    }]
                                    : [];
                                dfOnlineBroadcastVisual({
                                    kind: "incendiar",
                                    targetP: ev.targetP,
                                    targetI: ev.targetI,
                                    casterP: ev.casterIdx,
                                    casterFieldIdx: fieldIdx,
                                    fieldPatches,
                                });
                                try {
                                    await dfOnlineCommitStatus(ev.targetP, ev.targetI, { broadcast: false });
                                } catch (e) { /* */ }
                            }
                            await animateIncendiarGrant(ev.targetP, ev.targetI, {
                                casterP: ev.casterIdx, casterField: fieldIdx,
                            });
                            updateUI();
                            break;
                        case "ON_DESTROY_BURST":
                            updateUI();
                            if (ev.ability === "explosaoGelo") {
                                log(`❄️ Explosão de Gelo de ${ev.source || "Campeão"} congelou ${(ev.applied || []).length} alvo(s) por 2 rodadas.`);
                                for (const target of ev.applied || []) await animateIce(target.p, target.i);
                            } else if (ev.ability === "explosaoVenenosa") {
                                log(`☠️ Explosão Venenosa de ${ev.source || "Campeão"} envenenou ${(ev.applied || []).length} alvo(s).`);
                                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                    dfOnlineBroadcastVisual({
                                        kind: "explosao_venenosa_burst",
                                        applied: ev.applied || [],
                                        source: ev.source || null,
                                        ownerIdx: ev.ownerIdx,
                                    });
                                }
                                await animateExplosaoVenenosaTargets(ev.applied || []);
                            } else if (ev.ability === "furiaLegado") {
                                log(`🔥 Retaliação de ${ev.source || "Campeão"} concedeu Fúria a ${(ev.applied || []).map((t) => t.name).join(" e ")}.`);
                                await playFuryGrantTargets(ev.ownerIdx, ev.applied || []);
                            }
                            break;
                        default:
                            break;
                    }
                }
                checkWin();
            }

            async function dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, resolution = {}) {
                await ensureVfxReady();
                const hinted = state.players[casterIdx]?.field?.[fieldIdx];
                const liveIdx = dfResolveOnEnterCasterIdx(
                    casterIdx,
                    hinted?.onEnter,
                    fieldIdx,
                    resolution.casterUid ?? hinted?.uid,
                );
                if (liveIdx < 0) return false;
                fieldIdx = liveIdx;
                const FX = window.DfEffects;
                const ER = window.DfEffectsResolve;
                if (!FX?.applyOnEnter && !ER?.applyOnEnter) return false;
                const preField = captureFieldForPostDestroy();
                const preDomSnaps = dfCaptureAllFieldDomSnaps();
                let res = FX?.applyOnEnter
                    ? FX.applyOnEnter(state, casterIdx, fieldIdx, resolution)
                    : ER.applyOnEnter(state, casterIdx, fieldIdx, resolution);
                if (!res.ok) return false;
                if ((res.events || []).some((e) => e.type === "ON_ENTER_DELEGATE") && ER?.applyOnEnter) {
                    res = ER.applyOnEnter(state, casterIdx, fieldIdx, resolution);
                }
                if (!res.ok) return false;
                if ((res.events || []).some((e) => e.type === "ON_ENTER_DELEGATE")) return false;
                if (!(res.events || []).length) return false;
                await playOnEnterEvents(res.events, casterIdx, fieldIdx, { preField, preDomSnaps });
                replayPostDestroyAfterAuthority(preField, { visualOnly: false });
                for (const ev of res.events) {
                    if (ev.type !== "IMITAR") continue;
                    const liveIdx = state.players[casterIdx].field.findIndex((c) => c && c.uid === ev.casterUid);
                    if (liveIdx < 0) continue;
                    const mimicked = state.players[casterIdx].field[liveIdx];
                    if (ev.copiedConstantEffect || (mimicked.abilityType === "constant" && mimicked.abilityName)) {
                        applyConstantFieldEffects(casterIdx, liveIdx);
                        recalcInspiracao();
                    }
                    if (!ev.copiedOnEnter || ev.copiedOnEnter === "imitar") continue;
                    gamePhase = "normal";
                    targetData = {};
                    await resolveOnEnter(casterIdx, liveIdx);
                }
                // Peer já recebeu fieldPatches nos PLAY_VISUAL — sem SYNC_STATE cosmético.
                updateUI();
                return true;
            }

            function refreshHandChampionForSummon(placed, playerIdx) {
                if (!placed || placed.category !== "champion") return;
                const pl = state.players[playerIdx];
                const freshDef = window.DfData?.cardDefs?.find((d) => d.name === placed.name);
                if (!freshDef || !pl) return;
                if (!pl.maldicaoForgetNext && placed.silencedInHand) {
                    placed.silencedInHand = false;
                }
                if (pl.maldicaoForgetNext) return;
                if (placed.silenced) return;
                placed.silenced = false;
                if (placed.onDestroy == null && freshDef.onDestroy != null) placed.onDestroy = freshDef.onDestroy;
                if (placed.onEnter == null && freshDef.onEnter != null) placed.onEnter = freshDef.onEnter;
                if (placed.constantEffect == null && freshDef.constantEffect != null) {
                    placed.constantEffect = freshDef.constantEffect;
                }
                placed.abilityType = freshDef.abilityType ?? placed.abilityType;
                placed.abilityName = freshDef.abilityName ?? placed.abilityName;
                placed.abilityDesc = freshDef.abilityDesc ?? placed.abilityDesc;
                const needsOnEnterReset = placed._necromanciaFresh ||
                    (!placed.onEnter && freshDef.onEnter);
                if (needsOnEnterReset && placed.onEnter && pl.onEnterUsedThisTurn) {
                    const idx = pl.onEnterUsedThisTurn.indexOf(placed.onEnter);
                    if (idx >= 0) pl.onEnterUsedThisTurn.splice(idx, 1);
                }
            }

            async function resolveOnEnter(casterIdx, fieldIdx, casterUid = null) {
                const hinted = state.players[casterIdx]?.field?.[fieldIdx];
                const liveIdx = dfResolveOnEnterCasterIdx(
                    casterIdx,
                    hinted?.onEnter,
                    fieldIdx,
                    casterUid ?? hinted?.uid,
                );
                if (liveIdx < 0) return;
                fieldIdx = liveIdx;
                const caster = state.players[casterIdx]?.field?.[fieldIdx];
                if (!caster?.onEnter || caster.silenced) return;
                const mimickedExec = !!(caster.mimico
                    && caster.onEnter
                    && caster.mimicOnEnter
                    && caster.onEnter === caster.mimicOnEnter);
                if (caster.onEnterConsumed && !mimickedExec) return;
                const usedOnEnter = state.players[casterIdx]?.onEnterUsedThisTurn || [];
                // Evita dupla aplicação de on-enter AUTO já resolvido no servidor MP.
                // target / necromancia_pick precisam da UI do cliente mesmo se a chave
                // estiver na lista (ex.: 2º campeão com a mesma habilidade no turno).
                // Imitar: pode repetir instantânea já usada neste turno (manual).
                let plan = window.DfEffects?.planOnEnter?.(state, casterIdx, fieldIdx)
                    ?? { ok: true, mode: "auto", ability: caster.onEnter };
                if (!mimickedExec
                    && usedOnEnter.includes(caster.onEnter)
                    && (plan.mode === "auto" || plan.mode === "visual_only" || plan.mode === "none")) {
                    return;
                }
                if (!plan.ok) {
                    if (plan.code === "NO_IMITAR_TARGET") {
                        log(`${caster.name} entrou em campo, mas não há aliados com habilidade para imitar.`);
                        floatText("Sem habilidades para imitar", "info center", 1500);
                    } else if (plan.code) {
                        log(`OnEnter bloqueado (${plan.code}).`);
                        if (plan.code === "FIELD_FULL_DRAGON") {
                            floatText("Campo cheio — sem espaço pro Dragão", "warn center", 2000);
                        }
                    }
                    return;
                }
                const onEnterEnemyPick = new Set([
                    "bolaDeFogo", "assassinar", "transformarBichinho",
                    "rajadaCongelante", "mordidaVenenosa", "incendiar",
                ]);
                if (plan.mode === "auto" && onEnterEnemyPick.has(plan.ability)) {
                    plan = { ok: true, mode: "target", targetKind: "enemy", ability: plan.ability };
                }
                if (plan.mode === "visual_only") {
                    const tokenDef = caster.onEnter === "invokeCubicDragon" ? cubicDragonDef : babyDragonDef;
                    const ok = await summonDragonToken(casterIdx, tokenDef);
                    if (ok) markOnEnterUsed(casterIdx, caster.onEnter);
                    return;
                }
                if (plan.mode === "auto") {
                    if (plan.ability === "trocaInjusta") {
                        const enemies = [];
                        for (let ep = 0; ep < state.playersCount; ep++) {
                            if (ep === casterIdx) continue;
                            state.players[ep].field.forEach((c, i) => {
                                if (c && c.currentPower === 2) enemies.push({ p: ep, i });
                            });
                        }
                        if (!enemies.length) {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário de Poder 2 para trocar.`);
                            floatText("Sem alvos de Poder 2", "info center", 1500);
                            return;
                        }
                        const pick = enemies[Math.floor(Math.random() * enemies.length)];
                        if (await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { enemyP: pick.p, enemyI: pick.i })) return;
                    } else if (plan.ability === "fumacaToxica") {
                        const applied = await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, {
                            avoidPower1: true,
                        });
                        if (!applied) {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário para a Fumaça Tóxica.`);
                            floatText("Sem alvos adversários", "info center", 1500);
                        }
                        return;
                    } else if (plan.ability === "raioDuplo") {
                        const applied = await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, {});
                        if (!applied) {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário para o Raio Duplo.`);
                            floatText("Sem alvos adversários", "info center", 1500);
                        }
                        return;
                    } else if (plan.ability === "pesadelo" || plan.ability === "roubar" || plan.ability === "desacelerar") {
                        const targetIdx = pickInstantPlayerTarget(casterIdx, plan.ability);
                        if (targetIdx == null) return;
                        await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { targetPlayerIdx: targetIdx });
                        return;
                    } else if (plan.ability === "guardiao" || plan.ability === "auraDeFogo"
                        || plan.ability === "gritoDeGuerra") {
                        const applied = await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, {});
                        if (!applied && plan.ability === "guardiao") {
                            log("Guardião: nenhum aliado disponível para proteger.");
                        }
                        return;
                    } else if (plan.ability === "furia" || plan.ability === "auraAntiMagia" || plan.ability === "defensor") {
                        if (await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { casterUid: caster.uid })) return;
                        if (plan.ability === "furia") await applyFuryOnEnter(casterIdx, fieldIdx);
                        else if (plan.ability === "auraAntiMagia" && !caster.silenced) {
                            grantBarrierPermanent(caster);
                            markOnEnterUsed(casterIdx, "auraAntiMagia");
                            if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                                dfOnlineBroadcastVisual({
                                    kind: "barrier_grant",
                                    ownerP: casterIdx,
                                    indices: [fieldIdx],
                                    fieldPatches: [{
                                        targetP: casterIdx,
                                        targetI: fieldIdx,
                                        barrier: true,
                                        barrierPermanent: true,
                                        barrierTurns: 0,
                                    }],
                                });
                                dfOnlineCommitChampStatus(casterIdx, fieldIdx, { broadcast: false });
                            }
                            await animateBarrierGrant(casterIdx, [fieldIdx]);
                            log(`⬡ ${caster.name} ganhou Barreira permanente (Aura Anti-Magia)!`);
                            updateUI();
                        }
                        return;
                    } else if (await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, {})) {
                        return;
                    }
                }
                if (plan.mode === "necromancia_pick") {
                    await resolveOnEnterNecromancia(casterIdx, fieldIdx);
                    return;
                }
                if (plan.mode === "target") {
                    await resolveOnEnterWithTarget(casterIdx, fieldIdx, plan);
                    return;
                }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote
                    && !DF_ONLINE_PICK_PHASES.has(gamePhase)) {
                    dfOnlineBroadcastState();
                }
            }

            function pickInstantPlayerTarget(casterIdx, ability) {
                const candidates = [];
                for (let i = 0; i < state.playersCount; i++) {
                    if (i === casterIdx) continue;
                    const pl = state.players[i];
                    if (!pl) continue;
                    if (ability === "roubar" && !(pl.hand?.length)) continue;
                    if (ability === "pesadelo" && pl.skipDraw) continue;
                    if (ability === "desacelerar" && pl.skipNextAction) continue;
                    candidates.push(i);
                }
                if (!candidates.length) return null;
                if (ability === "roubar") {
                    const pick = aiChooseRoubar(casterIdx);
                    return pick != null && candidates.includes(pick) ? pick : candidates[0];
                }
                if (ability === "pesadelo" && state.players[casterIdx]?.isAI) {
                    const pick = aiChoosePesadelo(casterIdx);
                    return pick != null && candidates.includes(pick) ? pick : candidates[0];
                }
                if (ability === "desacelerar" && state.players[casterIdx]?.isAI) {
                    const pick = aiChooseDesacelerar(casterIdx);
                    return pick != null && candidates.includes(pick) ? pick : candidates[0];
                }
                return candidates[0];
            }

            function onEnterEnemyFilter(ability) {
                if (ability === "assassinar") return (c) => c.currentPower === 1;
                if (ability === "transformarBichinho") return (c) => c.currentPower >= 2 && !c.barrier;
                return () => true;
            }

            /** Fase target-champion após invocação — preview fechado + re-render + bordas no DOM. */
            function dfEnterTargetChampionPhase(ability, casterIdx, fieldIdx, targets, logMsg) {
                gamePhase = "target-champion";
                const casterSnap = state.players[casterIdx]?.field?.[fieldIdx];
                targetData = {
                    ability,
                    caster: casterIdx,
                    casterFieldIdx: fieldIdx,
                    casterUid: casterSnap?.uid,
                    targets,
                    targetIndex: 0,
                };
                log(logMsg);
                dfClosePreviewForTargeting();
                dfInvalidateAllQuadrantFp();
                targets.forEach(({ p }) => dfInvalidateQuadrantFp(p));
                document.body.setAttribute("data-targeting", "target-champion");
                updateUI({ immediate: true });
            }

            function onEnterAllyGather(casterIdx, fieldIdx, ability) {
                if (ability === "fortalecer") return gatherAllyTargets(casterIdx, fieldIdx, allyTargetCanGainPower);
                if (ability === "devorar") return gatherAllyTargets(casterIdx, fieldIdx, (c) => !c.inspiracao);
                if (ability === "imitar") return gatherImitableAllies(casterIdx, fieldIdx);
                if (ability === "corromper") return gatherAllyTargets(casterIdx, fieldIdx, () => true);
                return gatherAllyTargets(casterIdx, fieldIdx, () => true);
            }



            async function resolveOnEnterNecromancia(casterIdx, fieldIdx) {
                const caster = state.players[casterIdx]?.field?.[fieldIdx];
                const casterDiscard = state.players[casterIdx]?.discard;
                if (!casterDiscard?.length) {
                    log(`${caster?.name || "Campeão"} entrou em campo, mas o Descarte está vazio — Necromancia falhou.`);
                    floatText("Descarte vazio", "info center", 1500);
                    return;
                }
                // Até 4 últimas do descarte (push = mais recentes no fim).
                const picks = casterDiscard.slice(-Math.min(4, casterDiscard.length));
                try { window.sfx && window.sfx("necromancia"); } catch (e) {}
                if (state.players[casterIdx].isAI) {
                    const choice = aiResolveNecromancia(picks);
                    await resolveNecromanciaChoice(casterIdx, choice);
                    markOnEnterUsed(casterIdx, "necromancia");
                    return;
                }
                await openNecromanciaPicker(casterIdx, picks);
                markOnEnterUsed(casterIdx, "necromancia");
            }

            async function resolveOnEnterWithTarget(casterIdx, fieldIdx, plan) {
                const caster = state.players[casterIdx]?.field?.[fieldIdx];
                const ability = plan.ability;
                const isAI = !!state.players[casterIdx]?.isAI;

                if (plan.targetKind === "player") {
                    if (isAI) {
                        const res = await aiPickOnEnterResolution(ability, casterIdx, fieldIdx);
                        if (res) await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, res);
                        return;
                    }
                    if (ability === "roubar" && !aiHasRoubarTarget(casterIdx)) {
                        log("Nenhum adversário tem carta na mão pra roubar.");
                        floatText("Sem alvos pra roubar", "info center", 1500);
                        return;
                    }
                    if (ability === "desacelerar" && !aiHasDesacelerarTarget(casterIdx)) {
                        log("Todos os adversários já estão desacelerados.");
                        return;
                    }
                    const opp = (casterIdx === 0) ? 1 : 0;
                    if (ability === "pesadelo") {
                        if (!state.players[opp].skipDraw) await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { targetPlayerIdx: opp });
                        else log("Adversário já está com Pesadelo.");
                        return;
                    }
                    if (ability === "roubar") {
                        await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { targetPlayerIdx: opp });
                        return;
                    }
                    if (ability === "desacelerar") {
                        if (!state.players[opp].skipNextAction) await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, { targetPlayerIdx: opp });
                        else log("Adversário já está desacelerado.");
                    }
                    return;
                }

                if (plan.targetKind === "enemy") {
                    if (isAI) {
                        let res = await aiPickOnEnterResolution(ability, casterIdx, fieldIdx);
                        // Sem fallback genérico: a IA pode retornar null de propósito
                        // (ex.: só restam alvos que ela matará neste turno — não gastar status).
                        if (res) await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, res);
                        return;
                    }
                    const targets = gatherEnemyTargets(casterIdx, onEnterEnemyFilter(ability));
                    if (!targets.length) {
                        if (ability === "transformarBichinho") {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário com Poder 2 ou mais.`);
                            floatText("Sem alvos para transformar", "info center", 1500);
                        } else if (ability === "bolaDeFogo") {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário para a Bola de Fogo.`);
                            floatText("Sem alvos adversários", "info center", 1500);
                        } else if (ability === "assassinar") {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário de Poder 1 para Assassinar.`);
                            floatText("Sem alvos de Poder 1", "info center", 1500);
                        } else if (ability === "rajadaCongelante") {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário para a Rajada Congelante.`);
                            floatText("Sem alvos adversários", "info center", 1500);
                        } else if (ability === "incendiar" || ability === "mordidaVenenosa") {
                            log(`${caster.name} entrou em campo, mas não há Campeão adversário.`);
                            floatText("Sem alvos adversários", "info center", 1500);
                        }
                        return;
                    }
                    const logs = {
                        bolaDeFogo: "Clique no campeão adversário destacado em VERMELHO — Bola de Fogo tira 1 de Poder dele.",
                        assassinar: "Clique no campeão adversário de Poder 1 destacado em VERMELHO — Assassinar destrói o alvo.",
                        transformarBichinho: "Clique no campeão adversário destacado em ROXO — ele pode virar um Bichinho Fofinho ou um Terrível Monstro!",
                        rajadaCongelante: "Clique no campeão adversário destacado em AZUL — congele por 2 rodadas ou destrua se já estiver Congelado.",
                        mordidaVenenosa: "Clique no campeão adversário destacado — ele recebe Envenenado por 2 rodadas.",
                        incendiar: "Clique no campeão adversário destacado — ele fica Em Chamas por 4 rodadas (−1 Poder por rodada).",
                    };
                    dfEnterTargetChampionPhase(ability, casterIdx, fieldIdx, targets, logs[ability] || "Escolha um alvo adversário.");
                    return;
                }

                if (plan.targetKind === "ally") {
                    if (isAI) {
                        let res = await aiPickOnEnterResolution(ability, casterIdx, fieldIdx);
                        if (!res) {
                            const allies = onEnterAllyGather(casterIdx, fieldIdx, ability);
                            if (allies.length) res = { targetI: allies[0].i };
                        }
                        if (res) await dfApplyOnEnterWithVisuals(casterIdx, fieldIdx, res);
                        return;
                    }
                    const allyTargets = onEnterAllyGather(casterIdx, fieldIdx, ability);
                    if (!allyTargets.length) {
                        if (ability === "devorar") {
                            const anyAlly = gatherAllyTargets(casterIdx, fieldIdx, () => true).length > 0;
                            if (anyAlly) {
                                log(`${caster.name} entrou em campo, mas todos os aliados estão Inspirados.`);
                                floatText("Campeões com Inspiração não podem ser Devorados", "warn center", 2200);
                            } else {
                                log(`${caster.name} entrou em campo, mas não há aliado para devorar.`);
                            }
                        } else if (ability === "imitar") {
                            log(`${caster.name} entrou em campo, mas não há aliados com habilidade para imitar.`);
                            floatText("Sem habilidades para imitar", "info center", 1500);
                        } else if (ability === "fortalecer") {
                            log("Nenhum aliado pode receber +Poder.");
                        } else if (ability === "ursificacao") {
                            log(`${caster.name} entrou em campo, mas não há aliado para Ursificar.`);
                            floatText("Sem aliados para Ursificar", "info center", 1500);
                        }
                        return;
                    }
                    gamePhase = "target-ally";
                    const casterSnap = state.players[casterIdx]?.field?.[fieldIdx];
                    targetData = {
                        ability,
                        caster: casterIdx,
                        casterFieldIdx: fieldIdx,
                        casterUid: casterSnap?.uid,
                        allyTargets,
                        targetIndex: 0,
                    };
                    // MP: ao mirar (Ursificação etc.) destrava overlays da invocação
                    // para o jogador conseguir clicar / ampliar de novo.
                    if (window.__DF_ONLINE) {
                        try {
                            document.querySelectorAll(".phase-blocker").forEach((el) => el.remove());
                            // Não matar summon-fly / forceReset aqui — causa freeze + face quebrada.
                        } catch (eUnlock) { /* */ }
                    }
                    const logs = {
                        fortalecer: "Clique no campeão aliado destacado em VERDE — +1 de Poder.",
                        devorar: "Clique no campeão aliado destacado em vermelho — ele será devorado.",
                        imitar: "Escolha um Campeão aliado destacado em ROXO — Imitar copia e executa a habilidade dele, mesmo que já tenha sido usada neste turno.",
                        ursificacao: "Escolha um Campeão aliado destacado em ROXO para transformar em Urso.",
                        corromper: "Escolha um Campeão aliado destacado — ele ficará corrompido; o adversário que o destruir não recebe Ponto de vitória.",
                    };
                    log(logs[ability] || "Escolha um aliado.");
                    updateUI();
                }
            }

            async function dfConfirmOnEnterTarget(ability, casterIdx, fieldIdx, target) {
                // Capturar uid ANTES de dismiss (que zera targetData).
                const savedCasterUid = targetData?.casterUid;
                // Destrava mira ANTES do VFX sem forceReset/MO storm (freeze) —
                // nos dois modos: vs-IA travava vários segundos aqui.
                try {
                    dfDismissTargetingPhase();
                    window.__dfMpTargetResolve = true;
                    window.__dfPauseFieldLockMO?.(true);
                    window.DfTargetLevitate?.pause?.(true);
                    document.querySelectorAll(".phase-blocker").forEach((el) => {
                        try { el.remove(); } catch (eRm) { /* */ }
                    });
                    enterProcessed = false;
                    clearTimeout(window.__dfTargetResolveFailsafe);
                    window.__dfTargetResolveFailsafe = setTimeout(() => {
                        window.__dfMpTargetResolve = false;
                        window.__dfPauseFieldLockMO?.(false);
                        window.DfTargetLevitate?.pause?.(false);
                    }, 20000);
                } catch (ePre) { /* */ }
                try {
                const liveCasterIdx = dfResolveOnEnterCasterIdx(
                    casterIdx, ability, fieldIdx, savedCasterUid);
                if (liveCasterIdx < 0) {
                    log("Não foi possível resolver o campeão da habilidade.");
                    gamePhase = "normal";
                    targetData = {};
                    updateUI();
                    return;
                }
                // Nunca aplicar gelo/dano inimigo em aliado (mira SYNC errada no MP).
                const enemyOnly = new Set([
                    "rajadaCongelante", "bolaDeFogo", "assassinar", "mordidaVenenosa",
                    "incendiar", "transformarBichinho",
                ]);
                if (enemyOnly.has(ability) && target?.p === casterIdx) {
                    log("Alvo inválido.");
                    gamePhase = "normal";
                    targetData = {};
                    updateUI();
                    return;
                }
                const resolution = { targetP: target.p, targetI: target.i };
                if (ability === "fortalecer" || ability === "devorar" || ability === "imitar"
                    || ability === "ursificacao" || ability === "corromper") {
                    resolution.targetI = target.i;
                    delete resolution.targetP;
                }
                // Bola de Fogo local: mesmo pipeline do talento (Proteção Divina → Barreira → -1).
                // Assim Fúria só some se Poder de fato caiu.
                if (ability === "bolaDeFogo") {
                    markOnEnterUsed(casterIdx, "bolaDeFogo");
                    await castBolaDeFogo(casterIdx, liveCasterIdx, target.p, target.i, false);
                    gamePhase = "normal";
                    targetData = {};
                    updateUI();
                    checkWin();
                    dfRestoreFieldPresentation();
                    return;
                }
                // Assassinar: FIELD_COMMIT destroy (mesmo path do talento) — evita revive no peer.
                if (ability === "assassinar") {
                    markOnEnterUsed(casterIdx, "assassinar");
                    await castAssassinar(casterIdx, liveCasterIdx, target.p, target.i);
                    gamePhase = "normal";
                    targetData = {};
                    updateUI();
                    checkWin();
                    dfRestoreFieldPresentation();
                    return;
                }
                if (ability === "transformarBichinho") resolution.success = Math.random() < 0.90;
                if (ability === "imitar") {
                    gamePhase = "normal";
                    targetData = {};
                }
                // MP: Imitar (e alvos) autoritativos — servidor aplica + chain Roubar etc.
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote
                    && ["imitar", "fortalecer", "devorar", "ursificacao", "corromper",
                        "pesadelo", "roubar", "desacelerar", "mordidaVenenosa",
                        "incendiar", "rajadaCongelante", "bolaDeFogo"].includes(ability)) {
                    try {
                        // skipActorPresentFire: um único await do envelope (sem void+await = freeze).
                        const ack = await dfOnlineSendActionAwait({
                            type: "ABILITY_TARGET",
                            playerId: casterIdx,
                            casterIdx,
                            fieldIdx: liveCasterIdx,
                            abilityKey: ability,
                            targetI: resolution.targetI,
                            targetP: resolution.targetP,
                            targetPlayerIdx: resolution.targetPlayerIdx,
                            resolution,
                        }, { noSnap: true, actorPresent: true, skipActorPresentFire: true });
                        if (ack?.ok && ack.authoritativeState?.players?.length) {
                            dfOnlineReconcileSnapshot(
                                { state: ack.authoritativeState, full: true },
                                { skipPhase: true },
                            );
                            gamePhase = "normal";
                            targetData = {};
                            updateUI();
                            checkWin();
                            // VFX em background com budget curto — UI já liberada (anti-freeze).
                            if (typeof dfOnlineReplayPresentationEnvelope === "function") {
                                void Promise.race([
                                    dfOnlineReplayPresentationEnvelope(ack, {
                                        authApplied: true,
                                        budgetMs: 2200,
                                    }),
                                    wait(2400),
                                ]).catch(() => {});
                            }
                            if (ability === "imitar") {
                                const mim = state.players[casterIdx]?.field?.[liveCasterIdx];
                                if (mim?.onEnter && mim.onEnter !== "imitar" && !mim.onEnterConsumed) {
                                    // Habilidade copiada que pede alvo (Bola de Fogo,
                                    // Assassinar…) precisa abrir a mira de verdade:
                                    // com void + timeout a fase morria antes da escolha.
                                    try {
                                        await resolveOnEnter(casterIdx, liveCasterIdx, mim.uid);
                                    } catch (eChain) {
                                        console.warn("[DF online] imitar chain", eChain);
                                    }
                                }
                            }
                            return;
                        }
                    } catch (e) {
                        console.warn("[DF online] ABILITY_TARGET", e);
                    }
                }
                const applied = await dfApplyOnEnterWithVisuals(casterIdx, liveCasterIdx, resolution);
                if (!applied && ability === "fortalecer") {
                    const ally = state.players[target.p]?.field?.[target.i];
                    if (ally) {
                        dfBumpChampionPower(ally, 1);
                        log(`${state.players[casterIdx].name} fortaleceu ${ally.name} (+1 Poder).`);
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            dfOnlineBroadcastVisual({
                                kind: "strong_arm",
                                targetP: target.p,
                                targetI: target.i,
                                powerAfter: ally.currentPower,
                                casterP: casterIdx,
                                casterField: liveCasterIdx,
                                fieldPatches: [{ targetP: target.p, targetI: target.i, currentPower: ally.currentPower }],
                            });
                            try {
                                await dfOnlineCommitStatus(target.p, target.i, { broadcast: false });
                            } catch (e) { /* */ }
                        }
                        await animateStrongArm(target.p, target.i, {
                            casterP: casterIdx,
                            casterField: liveCasterIdx,
                            forceDomFallback: true,
                        });
                    }
                }
                if (ability !== "imitar") {
                    gamePhase = "normal";
                    targetData = {};
                }
                updateUI();
                checkWin();
                if (!window.__DF_ONLINE) dfRestoreFieldPresentation();
                } finally {
                    // Libera input imediatamente nos dois modos; sem forceReset agressivo.
                    try {
                        clearTimeout(window.__dfTargetResolveFailsafe);
                        window.__dfTargetResolveFailsafe = null;
                        if (["target-champion", "target-ally"].includes(gamePhase)) {
                            gamePhase = "normal";
                            targetData = {};
                        }
                        document.querySelectorAll(".phase-blocker").forEach((el) => el.remove());
                        enterProcessed = false;
                        window.__dfMpTargetResolve = false;
                        window.__dfPauseFieldLockMO?.(false);
                        window.DfTargetLevitate?.pause?.(false);
                        window.DfTargetLevitate?.stopAll?.();
                        if (!window.__dfSummonInFlight && !window._summonLock) {
                            dfRestoreFieldPresentation();
                        }
                    } catch (eFin) { /* */ }
                }
            }

            // IA: pontua cartas do descarte pra Necromancia. Prioriza:
            // Campeões de maior Poder (1-2 são as únicas opções práticas) >
            // talentos úteis (Bola de Fogo, Proteção Divina, Bloquear) >
            // resto. Empate: aleatório implícito via ordem do sorteio.


            // Remove a carta escolhida do descarte e adiciona à mão do
            // invocador. NÃO respeita MAX_HAND (efeito poderoso intencional).
            //
            // REGRA (pedido do usuário):
            //   (a) A carta volta SEM nenhum status (limpa tudo que tinha em
            //       campo antes de morrer: frozen, shielded, silenced,
            //       poisoned, etc.). Como onEnter NÃO é tocado, ao ser
            //       invocada novamente, a habilidade dispara como se fosse
            //       compra fresca.
            //   (b) Animação FLUIDA: a carta sai do #discard-pile e voa em
            //       arco até a mão do invocador, então a mensagem
            //       "Necromancia feita — {Herói} comprou 1 carta do descarte"
            //       aparece centralizada.
            async function resolveNecromanciaChoice(casterP, chosenCard) {
                if (!chosenCard) return;
                const discard = state.players[casterP].discard;
                const idx = discard.indexOf(chosenCard);
                if (idx < 0) return;
                discard.splice(idx, 1);
                // Limpa TODOS os status persistentes/temporários — a carta
                // renasce limpa, pronta pra disparar onEnter ao ser invocada.
                const STATUS_KEYS = [
                    "tapped", "frozen", "frozenTurns", "shielded", "shieldedTurns", "shieldedPermanent",
                    "silenced", "freeAttack", "poisoned", "poisonTurns", "poisonedByP", "vulnerable",
                    "corruptedNoHonor",
                    "barrier", "barrierTurns", "barrierPermanent", "fireAura", "fireAuraTurns",
                    "burning", "burningTurns", "burningByP",
                    "pulled", "pulledFromOwner", "pulledTurns",
                    "foreverGrowth", "wallBuff", "wallBuffApplied", "wallBuffSnapshot",
                    "guerraBuff", "guerraBuffTurns",
                    "fury", "furyTurns", "furyStacks", "furyBonusActive",
                    "mimico", "mimicAbilityName", "mimicAbilityDesc", "mimicOnEnter", "mimicOnDestroy",
                    "inspiracao", "inspiracaoDissipada", "silencedInHand", "summoned", "hasUsedOnEnter"
                ];
                STATUS_KEYS.forEach(k => {
                    if (!(k in chosenCard)) return;
                    chosenCard[k] = (k === "pulledFromOwner" || k === "poisonedByP")
                        ? -1
                        : (k.endsWith("Turns") || k === "furyStacks" ? 0 : false);
                });
                chosenCard.hasUsedOnEnter = false;
                chosenCard._necromanciaFresh = true;
                chosenCard.onEnterConsumed = false;
                const freshDef = window.DfData?.cardDefs?.find((c) => c.name === chosenCard.name);
                if (freshDef) {
                    chosenCard.onEnter = freshDef.onEnter ?? null;
                    chosenCard.onDestroy = freshDef.onDestroy ?? null;
                    chosenCard.talentEffect = freshDef.talentEffect ?? null;
                    chosenCard.constantEffect = freshDef.constantEffect ?? null;
                    chosenCard.abilityType = freshDef.abilityType ?? chosenCard.abilityType;
                    chosenCard.abilityName = freshDef.abilityName ?? chosenCard.abilityName;
                    chosenCard.abilityDesc = freshDef.abilityDesc ?? chosenCard.abilityDesc;
                    chosenCard.silenced = false;
                    chosenCard.silencedInHand = false;
                    // `onEnterConsumed` marca "já entrou em campo alguma vez" e
                    // é o que bloqueia a Instantânea em planOnEnter/applyOnEnter.
                    // Sem limpar, o campeão ressuscitado voltava à mão mas
                    // entrava MUDO — a Necromancia o devolve como compra fresca.
                    chosenCard.onEnterConsumed = false;
                    if (freshDef.onEnter && state.players[casterP]?.onEnterUsedThisTurn) {
                        const usedIdx = state.players[casterP].onEnterUsedThisTurn.indexOf(freshDef.onEnter);
                        if (usedIdx >= 0) state.players[casterP].onEnterUsedThisTurn.splice(usedIdx, 1);
                    }
                }
                chosenCard.inspiracaoSnapshot = null;
                if ("pulledFromOwner" in chosenCard) chosenCard.pulledFromOwner = null;
                // Restaura Poder base — currentPower volta a refletir o card original.
                if (typeof chosenCard.basePower === "number") {
                    chosenCard.currentPower = chosenCard.basePower;
                } else if (typeof chosenCard.power === "number") {
                    chosenCard.currentPower = chosenCard.power;
                    chosenCard.basePower = chosenCard.power;
                }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "necromancia", casterP, cardName: chosenCard.name,
                    });
                }
                // Animação carta-do-descarte → mão do invocador.
                await animateNecromanciaFlyToHand(casterP, chosenCard);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    try {
                        await dfOnlineCommitMutations([{
                            op: "discardToHand",
                            targetP: casterP,
                            card: { ...chosenCard },
                            cardName: chosenCard.name,
                            uid: chosenCard.uid,
                        }], { reconcile: true });
                    } catch (e) {
                        console.warn("[DF online] necromancia FIELD_COMMIT", e);
                        state.players[casterP].hand.push(chosenCard);
                    }
                } else {
                    state.players[casterP].hand.push(chosenCard);
                }
                updateUI();
                const heroName = state.players[casterP].name || "Jogador";
                log(`💀 NECROMANCIA: ${heroName} comprou ${chosenCard.name} do descarte.`);
            }

            // Voo da carta saindo do #discard-pile até a mão do invocador.
            // Usa a arte real da carta (cards/<nome>.png) com fallback pro
            // banner de talento — a carta gira, brilha e cresce no caminho.
            // Padrão: dfVfxMount + tamanho de hand-card (como Roubar / drawAnim).
            async function animateNecromanciaFlyToHand(casterP, card) {
                const fromEl = getDiscardPileEl(casterP);
                const handEl = document.querySelector(`#quadrant-${dfQuadrantForPlayer(casterP)} .quadrant-hand`);
                if (!fromEl || !handEl || !card) return;
                const fr = fromEl.getBoundingClientRect();
                const fromX = fr.left + fr.width / 2;
                const fromY = fr.top + fr.height / 2;
                const landing = dfHandLandingCenter(casterP, undefined);
                const toX = landing?.x ?? (handEl.getBoundingClientRect().left + handEl.getBoundingClientRect().width / 2);
                const toY = landing?.y ?? (handEl.getBoundingClientRect().top + handEl.getBoundingClientRect().height / 2);
                const sizeSlot = handEl.querySelector(
                    ".hand-wrap .hcard, .ai-hand-wrap .ai-back, .ai-hand-wrap .hcard, .hcard",
                ) || handEl.querySelector(".hand-wrap, .ai-hand-wrap");
                const srcSize = sizeSlot ? dfHandSlotCardSize(sizeSlot) : null;
                let cw;
                let ch;
                if (srcSize && srcSize.w > 16 && srcSize.h > 20) {
                    cw = srcSize.w;
                    ch = srcSize.h;
                } else {
                    const cs = getComputedStyle(document.documentElement);
                    cw = parseFloat(cs.getPropertyValue("--df-hand-card-w")) || (FX.mobile ? 68 : 74);
                    ch = parseFloat(cs.getPropertyValue("--df-hand-card-h")) || Math.round(cw / DF_CARD_ASPECT);
                }
                const start = dfVfxMap(fromX, fromY);
                const end = dfVfxMap(toX, toY);
                const dx = end.x - start.x;
                const dy = end.y - start.y;
                if (dfVfxCanvasActive()) {
                    const sz = dfVfxMapSize(cw, ch);
                    cw = sz.width;
                    ch = sz.height;
                }
                const flyArt = window.dfPrimaryCardArtSrc?.(card.name || "")
                    || (window.dfCardSrc ? window.dfCardSrc(card.name || "") : `cards/v2/${(card.name || "").replace(/\s+/g, "_")}.png`);
                const fly = document.createElement("div");
                fly.className = "necro-fly-card";
                fly.style.cssText =
                    `position:${dfVfxPos()};left:${start.x}px;top:${start.y}px;` +
                    `width:${cw}px;height:${ch}px;min-width:${cw}px;min-height:${ch}px;` +
                    `transform:translate(-50%,-50%) scale(0.55) rotate(-18deg);z-index:9520;pointer-events:none;` +
                    `border-radius:10px;border:3px solid #c89aff;` +
                    `box-shadow:0 0 24px rgba(200,140,255,0.95),0 0 48px rgba(120,40,200,0.7);` +
                    `background:#1a1228 center/cover no-repeat;background-image:url('${flyArt}'),linear-gradient(160deg,#3a1a5a,#1a0830);` +
                    `opacity:0;will-change:transform,opacity;filter:drop-shadow(0 0 20px #c896ff) brightness(1.15);`;
                fly.dataset.dfVfxMapped = "1";
                dfVfxMount(fly);
                void fly.offsetWidth;
                fly.style.transition =
                    "transform 950ms cubic-bezier(.45,.05,.3,1), opacity 280ms ease, filter 950ms ease, box-shadow 950ms ease";
                fly.style.opacity = "1";
                for (let i = 0; i < 7; i++) {
                    const t = (i + 1) / 8;
                    const trail = document.createElement("div");
                    const tw = cw * (1 - t * 0.55);
                    const th = ch * (1 - t * 0.55);
                    trail.style.cssText =
                        `position:${dfVfxPos()};left:${start.x + dx * t}px;top:${start.y + dy * t}px;` +
                        `width:${tw}px;height:${th}px;border-radius:10px;` +
                        `background:radial-gradient(ellipse, rgba(200,140,255,0.55), rgba(120,40,200,0) 70%);` +
                        `z-index:9519;pointer-events:none;opacity:0;transform:translate(-50%,-50%);` +
                        `transition:opacity 240ms ease;filter:blur(2px);`;
                    trail.dataset.dfVfxMapped = "1";
                    dfVfxMount(trail);
                    setTimeout(() => { trail.style.opacity = "1"; }, 100 + i * 80);
                    setTimeout(() => { trail.style.opacity = "0"; }, 460 + i * 80);
                    setTimeout(() => trail.remove(), 820 + i * 80);
                }
                const qEl = document.getElementById(`quadrant-${dfQuadrantForPlayer(casterP)}`);
                if (qEl) {
                    const orig = qEl.style.boxShadow;
                    qEl.style.transition = "box-shadow 280ms ease";
                    qEl.style.boxShadow = "0 0 0 4px #c89aff inset, 0 0 36px 6px rgba(200,140,255,0.55) inset";
                    setTimeout(() => { qEl.style.boxShadow = orig || ""; }, 1100);
                }
                fly.style.transform =
                    `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px)) scale(1) rotate(360deg)`;
                fly.style.filter = "drop-shadow(0 0 10px #c896ff) brightness(1.0)";
                await wait(960);
                fly.style.opacity = "0";
                await wait(220);
                fly.remove();
            }

            // Overlay DOM — até 4 cartas clicáveis. Pixi hub não é usado (tela
            // preta / hits invisíveis). ESC NÃO fecha (habilidade irrevogável).
            function openNecromanciaPicker(casterP, picks) {
                return new Promise((resolve) => {
                    try { window.DfPixiVfx?.forceClearStage?.(); } catch (err) { /* */ }

                    const panel = $("necromancia-panel");
                    const overlay = $("necromancia-overlay");
                    if (!panel || !overlay) {
                        resolve();
                        return;
                    }
                    // Acima do canvas Pixi (COMBAT_Z 100100) e fundo legível.
                    if (overlay.parentElement !== document.body) {
                        document.body.appendChild(overlay);
                    }
                    panel.innerHTML =
                        `<p style="color:#e8d8ff;font-family:Cinzel,Georgia,serif;font-weight:700;margin:0 0 14px;font-size:1.05rem;text-shadow:0 2px 8px rgba(0,0,0,0.85)">Traga uma carta de volta para sua mão</p>` +
                        `<div class="necro-pick-row" style="display:flex;flex-wrap:wrap;gap:12px;justify-content:center;align-items:flex-start"></div>`;
                    const row = panel.querySelector(".necro-pick-row");
                    picks.forEach((c, i) => {
                        const wrap = document.createElement("div");
                        wrap.className = "necro-pick";
                        wrap.dataset.idx = String(i);
                        wrap.style.cssText = "cursor:pointer;border:3px solid #8a5cff;border-radius:10px;padding:6px;background:#1a1228;transition:transform .15s, box-shadow .15s, border-color .15s;box-shadow:0 0 12px rgba(138,92,255,0.5);width:min(148px,32vw);aspect-ratio:5/7;display:flex;flex-direction:column;align-items:stretch;justify-content:center;position:relative;overflow:hidden;box-sizing:border-box";
                        const host = document.createElement("div");
                        host.className = "necro-pick-face hcard type-champion";
                        host.style.cssText = "position:relative;width:100%;height:100%;border-radius:6px;overflow:hidden;margin:0;min-height:0";
                        wrap.appendChild(host);
                        row.appendChild(wrap);
                        if (window.DfCardFace?.isComposed?.(c)) {
                            host.classList.add("has-composed-face");
                            window.DfCardFace.mount(host, c, { power: c.currentPower ?? c.power ?? c.basePower });
                        } else {
                            const img = document.createElement("img");
                            img.alt = c.name || "";
                            img.draggable = false;
                            img.style.cssText = "width:100%;height:100%;object-fit:cover;border-radius:6px;display:block";
                            img.src = window.dfPrimaryCardArtSrc?.(c.name)
                                || (window.dfCardSrc ? window.dfCardSrc(c.name) : `cards/v2/${String(c.name || "").replace(/\s+/g, "_")}.png`);
                            img.onerror = () => {
                                host.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#fff;font-weight:700;text-align:center;padding:8px;font-size:0.85rem">${c.name || "?"}</div>`;
                            };
                            host.appendChild(img);
                            try { window.dfAttachCardArt?.(host, c.name); } catch (e) { /* */ }
                        }
                    });
                    overlay.classList.add("active");
                    try { window.applyCardArtTree?.(overlay); } catch (e) { /* */ }
                    const prevPhase = gamePhase;
                    gamePhase = "necromancia";
                    const onClick = async (e) => {
                        const card = e.target.closest(".necro-pick");
                        if (!card) return;
                        const idx = parseInt(card.dataset.idx, 10);
                        if (isNaN(idx) || !picks[idx]) return;
                        panel.querySelectorAll(".necro-pick").forEach(el => { el.style.pointerEvents = "none"; el.style.opacity = "0.4"; });
                        card.style.opacity = "1";
                        card.style.borderColor = "#ffd76b";
                        card.style.boxShadow = "0 0 28px rgba(255,215,107,0.95)";
                        card.style.transform = "scale(1.08)";
                        panel.removeEventListener("click", onClick);
                        await wait(420);
                        overlay.classList.remove("active");
                        panel.innerHTML = "";
                        gamePhase = prevPhase === "necromancia" ? "normal" : prevPhase;
                        await resolveNecromanciaChoice(casterP, picks[idx]);
                        resolve();
                    };
                    panel.addEventListener("click", onClick);
                });
            }

            // IA: escolhe o melhor aliado pra Wu-Kong/Enigma imitar.
            // Prioriza onEnter ofensivos (assassinar, transformarBichinho,
            // bolaDeFogo, devorar) > buffs (fortalecer, rapidez) > geração
            // (invokeDragon) > controle (pesadelo, roubar, desacelerar) >
            // onDestroy (vinganca, legado, noHonor). Empate: maior poder.


            // IMITAR — copia os campos de habilidade do aliado escolhido pro
            // invocador e executa onEnter (se houver). NUNCA copia "imitar"
            // de outro Wu-Kong/Enigma (já filtrado no gather), evita loop.
            // Para habilidades de target (bolaDeFogo, assassinar, etc.) o
            // invocador é o caster — alvos válidos são calculados normalmente
            // a partir dele via resolveOnEnter.
            async function castImitar(casterP, casterFieldIdx, allyP, allyI) {
                const caster = state.players[casterP].field[casterFieldIdx];
                const ally = state.players[allyP].field[allyI];
                if (!caster || !ally) return;
                try { window.sfx && window.sfx("imitar"); } catch (e) {}
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "imitar", allyP, allyI, casterP, casterFieldIdx,
                        mimicAbilityName: ally.abilityName || "Habilidade",
                        mimicSourceName: ally.name,
                    });
                }
                await animateImitar(allyP, allyI, casterP, casterFieldIdx);
                // Copia identidade de habilidade (mantém nome do invocador).
                caster.abilityType = ally.abilityType;
                caster.abilityName = ally.abilityName;
                caster.abilityDesc = ally.abilityDesc;
                caster.onEnter = ally.onEnter;
                caster.onDestroy = dfResolveCopiedOnDestroy(ally) || ally.onDestroy;
                const copiedConstant = ally.constantEffect
                    || (ally.abilityType === "constant" && ally.abilityName === "Inspirar" ? "inspirar"
                        : ally.abilityType === "constant" && ally.abilityName === "Investida" ? "investida"
                        : ally.abilityType === "constant" && ally.abilityName === "Tiro Duplo" ? "tiroDuplo"
                        : null);
                caster.constantEffect = copiedConstant;
                caster.talentEffect = ally.talentEffect || null;
                caster.mimicOnDestroy = caster.onDestroy;
                caster.mimicOnEnter = ally.onEnter;
                caster.mimicConstantEffect = copiedConstant;
                // MIMICO — marca o invocador (Wu-Kong/Enigma) com flag visível.
                // Ícone roxo aparece na coroa de status; ampliar a carta
                // mostra o nome+descrição da habilidade copiada.
                caster.mimico = true;
                caster.mimicAbilityName = ally.abilityName || "Habilidade";
                caster.mimicAbilityDesc = ally.abilityDesc || "";
                caster.mimicSourceName = ally.name;
                log(`🎭 ${caster.name} imitou a habilidade de ${ally.name}: ${ally.abilityName}.`);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) dfOnlineBroadcastState();
                updateUI();
                // Guard duplo: NUNCA executa 'imitar' encadeado (loop infinito).
                // O filtro do gather já bloqueia, mas defesa-em-profundidade
                // protege contra mutação posterior (paladino ult, etc.).
                markOnEnterUsed(casterP, "imitar");
                if (copiedConstant || (caster.abilityType === "constant" && caster.abilityName)) {
                    const liveIdx0 = state.players[casterP].field.findIndex(c => c && c.uid === caster.uid);
                    if (liveIdx0 >= 0) {
                        applyConstantFieldEffects(casterP, liveIdx0);
                        recalcInspiracao();
                    }
                }
                if (caster.onEnter && caster.onEnter !== "imitar") {
                    gamePhase = "normal";
                    targetData = {};
                    const liveIdx = state.players[casterP].field.findIndex(c => c && c.uid === caster.uid);
                    if (liveIdx >= 0) await resolveOnEnter(casterP, liveIdx);
                }
            }

            // Animação curta: linha de luz roxa do aliado → invocador, com
            // partículas e pulse, indicando que a habilidade foi copiada.
            async function animateImitar(allyP, allyI, casterP, casterI) {
                await dfAwaitChampionDom(allyP, allyI, 1600);
                await dfAwaitChampionDom(casterP, casterI, 1600);
                const src = getChampionDom(allyP, allyI);
                const dst = getChampionDom(casterP, casterI);
                if (!src || !dst) {
                    console.warn("[DF] animateImitar: DOM ausente", { allyP, allyI, casterP, casterI });
                    return;
                }
                const sr = src.getBoundingClientRect();
                const dr = dst.getBoundingClientRect();
                const sx = sr.left + sr.width / 2;
                const sy = sr.top + sr.height / 2;
                const dx = dr.left + dr.width / 2;
                const dy = dr.top + dr.height / 2;
                const beam = document.createElement("div");
                beam.style.cssText = `position:${dfVfxPos()};left:${sx}px;top:${sy}px;width:${Math.hypot(dx-sx,dy-sy)}px;height:6px;
                    background:linear-gradient(90deg,rgba(180,80,255,0)0%,rgba(200,120,255,0.95)50%,rgba(180,80,255,0)100%);
                    box-shadow:0 0 22px 8px rgba(180,80,255,0.65);transform-origin:0 50%;
                    transform:rotate(${Math.atan2(dy-sy,dx-sx)}rad);z-index:9990;pointer-events:none;
                    border-radius:4px;opacity:0;transition:opacity .12s ease-out;`;
                dfVfxMount(beam);
                requestAnimationFrame(() => { beam.style.opacity = "1"; });
                spawnParticles(sx, sy, 8);
                await wait(220);
                spawnParticles(dx, dy, 10);
                dst.style.transition = "transform .18s ease-out, filter .18s ease-out";
                dst.style.transform = "scale(1.12)";
                dst.style.filter = "drop-shadow(0 0 18px rgba(200,120,255,0.95))";
                await wait(220);
                dst.style.transform = "";
                dst.style.filter = "";
                beam.style.opacity = "0";
                await wait(200);
                beam.remove();
            }

            // Maldição dos Sete Mares — onda cinematográfica (Pixi+GSAP), sem texto.
            async function animateMaldicaoSeteMares(casterIdx) {
                if (!dfMatchAlive()) return;
                const hits = [];
                for (let p = 0; p < state.playersCount; p++) {
                    if (p === casterIdx) continue;
                    const q = document.getElementById(`quadrant-${dfQuadrantForPlayer(p)}`);
                    if (!q) continue;
                    const field = q.querySelector(".quadrant-field") || q.querySelector(".field-wrap") || q;
                    const r = field.getBoundingClientRect();
                    if (r.width < 8 || r.height < 8) continue;
                    hits.push({ r, playerP: p });
                }
                await ensureVfxReady();
                const pixi = window.DfPixiVfx;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof pixi?.playMaldicaoSeteMaresScene === "function";
                if (gpu && hits.length) {
                    const points = hits.map((h) => ({
                        cx: h.r.left + h.r.width / 2,
                        cy: h.r.top + h.r.height * 0.52,
                        fieldW: h.r.width,
                        fieldH: h.r.height,
                    }));
                    const ok = await pixi.playMaldicaoSeteMaresScene({ hits: points, cinematic: true });
                    if (ok) return;
                }
                if (!window.DfSpriteVfx) return;
                await DfSpriteVfx.playCurseSea(hits);
            }

            // Box "VINGANÇA" + animação Pixi (espada) ou fallback DOM.
            async function animateVinganca(targetP, targetI, opts = {}) {
                await ensureVfxReady();
                const uid = opts.uid;
                await dfAwaitChampionDom(targetP, targetI, 1600);
                let el = (uid != null ? getChampionDomByUid(uid) : null) || getChampionDom(targetP, targetI);
                let r = el?.getBoundingClientRect();
                if (!r || r.width < 4) r = championVisualRect(targetP, targetI);
                const cx = r ? r.left + r.width / 2 : window.innerWidth / 2;
                const cy = r ? r.top + r.height / 2 : window.innerHeight / 2;
                const pixi = window.DfPixiVfx;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    || window.DfVfxEngine?.wantsCinematic?.();
                if (gpu && pixi?.playVingancaSwordScene) {
                    try {
                        await Promise.race([
                        pixi.playVingancaSwordScene({ toX: cx, toY: cy, cinematic: true }),
                        wait(FX.mobile ? 1200 : 2200),
                    ]);
                    } finally {
                        try { window.DfPixiVfx?.sweepOrphanScenes?.(); } catch (e) { /* */ }
                    }
                    return;
                }
                const ov = document.createElement("div");
                ov.className = "no-honor-burst";
                ov.innerHTML =
                    `<div class="no-honor-skull">⚔️</div>` +
                    `<div class="no-honor-banner" style="background:linear-gradient(180deg,#a00,#400);border-color:#ff5050">VINGANÇA</div>` +
                    `<div class="no-honor-sub">Um Campeão adversário perdeu 1 Poder!</div>`;
                dfVfxMount(ov);
                setTimeout(() => ov.remove(), 1900);
                el = (uid != null ? getChampionDomByUid(uid) : null) || el;
                if (el) {
                    el.style.transition = "filter .15s ease-out, transform .15s ease-out";
                    el.style.filter = "drop-shadow(0 0 18px rgba(255,40,40,1))";
                    el.style.transform = "translateY(-6px) scale(1.06)";
                    spawnParticles(cx, cy, 10);
                    await wait(280);
                    el.style.filter = "";
                    el.style.transform = "";
                }
            }

            // LEGADO — martelo Pixi+GSAP fortalecendo aliado (fallback DOM).
            async function animateLegado(targetP, targetI) {
                await ensureVfxReady();
                const el = getChampionDom(targetP, targetI);
                const r = el?.getBoundingClientRect();
                const cx = r ? r.left + r.width / 2 : window.innerWidth / 2;
                const cy = r ? r.top + r.height / 2 : window.innerHeight / 2;
                const pixi = window.DfPixiVfx;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    || window.DfVfxEngine?.wantsCinematic?.();
                if (gpu && pixi?.playLegadoHammerScene) {
                    try {
                        await Promise.race([
                        pixi.playLegadoHammerScene({ toX: cx, toY: cy, cinematic: true }),
                        wait(FX.mobile ? 900 : 1500),
                    ]);
                    } finally {
                        try { window.DfPixiVfx?.sweepOrphanScenes?.(); } catch (e) { /* */ }
                    }
                    return;
                }
                const banner = document.createElement("div");
                banner.style.cssText = dfVfxCanvasActive()
                    ? "position:absolute;top:101px;left:640px;transform:translateX(-50%) scale(0.6);z-index:9110;pointer-events:none;background:linear-gradient(180deg,#c89a2a,#6b4f10);border:2px solid #ffd770;border-radius:10px;padding:6px 18px;font-weight:900;letter-spacing:0.18rem;font-size:1.15rem;color:#fff4b0;text-shadow:0 0 12px rgba(255,210,80,1),0 0 22px rgba(255,170,30,0.9),0 3px 6px rgba(0,0,0,0.95);box-shadow:0 0 22px rgba(255,200,60,0.65),0 6px 18px rgba(0,0,0,0.6);opacity:0;transition:transform 320ms cubic-bezier(.2,.8,.3,1.4), opacity 220ms ease;"
                    : "position:fixed;top:14%;left:50%;transform:translateX(-50%) scale(0.6);z-index:9110;pointer-events:none;background:linear-gradient(180deg,#c89a2a,#6b4f10);border:2px solid #ffd770;border-radius:10px;padding:6px 18px;font-weight:900;letter-spacing:0.18rem;font-size:clamp(0.95rem,2.6vw,1.3rem);color:#fff4b0;text-shadow:0 0 12px rgba(255,210,80,1),0 0 22px rgba(255,170,30,0.9),0 3px 6px rgba(0,0,0,0.95);box-shadow:0 0 22px rgba(255,200,60,0.65),0 6px 18px rgba(0,0,0,0.6);opacity:0;transition:transform 320ms cubic-bezier(.2,.8,.3,1.4), opacity 220ms ease;";
                banner.textContent = "👑 LEGADO";
                dfVfxMount(banner);
                void banner.offsetWidth;
                banner.style.opacity = "1";
                banner.style.transform = "translateX(-50%) scale(1)";
                setTimeout(() => {
                    banner.style.opacity = "0";
                    banner.style.transform = "translateX(-50%) scale(0.85)";
                }, 1400);
                setTimeout(() => banner.remove(), 1750);

                if (!el || !r?.width) return;

                // 1) Raios solares girando atrás do aliado.
                const rays = document.createElement("div");
                rays.className = "legado-rays";
                rays.style.left = `${cx - 180}px`;
                rays.style.top  = `${cy - 180}px`;
                dfVfxMount(rays);
                setTimeout(() => rays.remove(), 1520);

                // 2) Aura dourada pulsante DIRETO no card (transform/box-shadow).
                const prevTransition = el.style.transition;
                const prevFilter = el.style.filter;
                const prevAnim = el.style.animation;
                const prevBoxShadow = el.style.boxShadow;
                const prevZ = el.style.zIndex;
                el.style.zIndex = "60";
                el.style.transition = "filter 260ms ease-out, transform 260ms cubic-bezier(.2,.7,.3,1.4)";
                el.style.filter = "drop-shadow(0 0 22px rgba(255,225,120,1)) drop-shadow(0 0 44px rgba(255,180,40,0.95)) brightness(1.25) saturate(1.25)";
                el.style.transform = "translateY(-12px) scale(1.18)";
                el.style.animation = "legadoAuraPulse 700ms ease-in-out 2";

                // 3) Partículas douradas brotando do aliado.
                for (let i = 0; i < 22; i++) {
                    const ang = Math.random() * Math.PI * 2;
                    const dist = 70 + Math.random() * 130;
                    const dur = 700 + Math.random() * 500;
                    const dot = document.createElement("div");
                    const size = 6 + Math.random() * 8;
                    dot.style.cssText = `position:${dfVfxPos()};left:${cx}px;top:${cy}px;width:${size}px;height:${size}px;border-radius:50%;background:radial-gradient(circle at 35% 30%, #fff8c0 0%, #ffd460 60%, #a36b00 100%);z-index:9100;pointer-events:none;transform:translate(-50%,-50%);transition:transform ${dur}ms cubic-bezier(.2,.7,.3,1), opacity ${dur}ms ease-out;box-shadow:0 0 10px rgba(255,210,80,0.95);`;
                    dfVfxMount(dot);
                    void dot.offsetWidth;
                    dot.style.transform = `translate(calc(-50% + ${Math.cos(ang)*dist}px), calc(-50% + ${Math.sin(ang)*dist - 30}px)) scale(0.3)`;
                    dot.style.opacity = "0";
                    setTimeout(() => dot.remove(), dur + 50);
                }

                spawnParticles(cx, cy, 18);
                await wait(950);
                // Restaura estado original do card.
                el.style.filter = prevFilter || "";
                el.style.transform = "";
                el.style.animation = prevAnim || "";
                el.style.boxShadow = prevBoxShadow || "";
                el.style.transition = prevTransition || "";
                el.style.zIndex = prevZ || "";
            }

            const DEVOUR_OK_CONSTANT_NAMES = new Set(["BICHINHO FOFINHO", "BANJO", "O CHEFÃO"]);



            // IA: escolhe o melhor aliado pra Tirânico/Carnivora devorar.
            // Prioriza Habilidades INSTANTÂNEAS; evita CONSTANTES exceto
            // Bichinho Fofinho, Banjo e Terrível Monstro.

            // IA: escolhe o aliado MENOS valioso pra sacrificar no Ritual.
            // Prefere tapped/frozen (já "queimados"), Poder menor, e evita
            // Sobrepujar/Resistente (corpos de batalha) quando há outro candidato.

            // Aliados que a IA pretende sacrificar neste turno (Ômega/Tiamat).


            function gatherAllyTargets(casterIdx, exclude, filter) {
                return DfRules.gatherAllyTargets(state, casterIdx, exclude, filter);
            }

            // Marca habilidades onEnter já usadas neste turno pelo jogador
            // (limites 1×/turno de algumas cartas; Imitar ainda pode copiá-las).
            function markOnEnterUsed(pIdx, onEnterKey) {
                if (!onEnterKey || !state.players[pIdx]) return;
                const pl = state.players[pIdx];
                if (!pl.onEnterUsedThisTurn) pl.onEnterUsedThisTurn = [];
                if (!pl.onEnterUsedThisTurn.includes(onEnterKey)) pl.onEnterUsedThisTurn.push(onEnterKey);
            }

            const IMITATOR_NAMES = new Set(["WU-KONG", "ENIGMA"]);
            const isImitatorChamp = (c) => c && IMITATOR_NAMES.has(c.name);

            // Aliados copiáveis por IMITAR — mesma regra humana + IA.
            function gatherImitableAllies(casterIdx, excludeFieldIdx) {
                return DfRules.gatherImitableAllies(state, casterIdx, excludeFieldIdx);
            }
            // Filtro pra habilidades/ultimates que dão +Poder (Fortalecer onEnter,
            // ult Linguarudo). A partir desta versão, COME PEDRA / GUARDIÃO
            // DA CHAVE (Resistente) PODEM ganhar Poder normalmente — a
            // restrição antiga foi removida a pedido do usuário.
            const allyTargetCanGainPower = (c) => !!c;

            function dfChampionPower(champ) {
                return champ?.currentPower ?? champ?.power ?? champ?.basePower ?? 0;
            }

            function dfBumpChampionPower(champ, delta) {
                if (!champ || !delta) return;
                champ.currentPower = dfChampionPower(champ) + delta;
            }

            function dfResolveOnEnterCasterIdx(casterIdx, ability, hintIdx, casterUid) {
                const field = state.players[casterIdx]?.field || [];
                if (casterUid != null) {
                    const byUid = field.findIndex((c) => c && c.uid === casterUid);
                    if (byUid >= 0) return byUid;
                }
                if (hintIdx != null && hintIdx >= 0 && hintIdx < field.length) {
                    const hinted = field[hintIdx];
                    if (hinted && !hinted.silenced && hinted.onEnter === ability) return hintIdx;
                }
                // Sem findIndex amplo por onEnter — evita Rei Gelado “roubar” o caster
                // quando outro campeão é invocado (MP uid stale).
                return -1;
            }

            // ============================================================
            // RESTRIÇÃO DE BUFF DA IA (pedido do usuário)
            // ------------------------------------------------------------
            // A IA NUNCA deve empilhar +Poder (Poção do Alquimista,
            // Fortalecer, Vampirismo, Força Infinita etc.) num Campeão que
            // JÁ tenha Poder >= 4 — A MENOS que o adversário também tenha
            // pelo menos um Campeão com Poder >= 4 em campo (aí a corrida
            // de poder se justifica). Afeta SÓ a tomada de decisão da IA;
            // o jogador humano continua livre pra buffar quem quiser.
            // ============================================================
            const AI_BUFF_POWER_CAP = 4;



            // INSPIRAR (PRINCESA AURORA) — constante.
            // Por jogador, varre o field e marca quem está adjacente (índices
            // ±1, linear) a um Campeão com `constantEffect === "inspirar"`
            // não-silenciado. Adjacentes ganham status `inspiracao` + 1 Poder
            // (snapshot guarda o currentPower pós-buff). Mecânicas:
            //  - Ganhar status: +1 Poder, snapshot = currentPower atual.
            //  - currentPower < snapshot → status DISSIPADO sem devolver o +1
            //    (regra do usuário: perder Poder dissipa a inspiração; o
            //    Campeão fica -2 efetivos em relação ao pré-inspiração).
            //  - currentPower > snapshot → atualiza snapshot (não dissipa).
            //  - Inspirador sai/morre/silenciado → não-adjacente: -1 Poder
            //    devolvido, status limpo.
            //  - Inspiradores não buffam outros inspiradores (evita loops).
            //  - Idempotente: chamado no início de updateUI, então toda
            //    mudança de field re-converge.
            function recalcInspiracao() {
                for (let p = 0; p < state.playersCount; p++) {
                    const field = state.players[p].field;
                    if (!field) continue;
                    const inspirators = new Set();
                    field.forEach((c, i) => {
                        if (c && !c.silenced && (c.constantEffect === "inspirar"
                            || (c.abilityType === "constant" && c.abilityName === "Inspirar"))) inspirators.add(i);
                    });
                    field.forEach((c, i) => {
                        if (!c) return;
                        // Inspiradores não buffam a si mesmos nem a outros inspiradores.
                        const isInsp = inspirators.has(i);
                        const isAdj = !isInsp && (inspirators.has(i - 1) || inspirators.has(i + 1));
                        if (isAdj) {
                            if (c.inspiracaoDissipada) {
                                // LOCK: já dissipou nesta vizinhança. Só
                                // re-buffa se o inspirador sair (clear no
                                // ramo `else` abaixo).
                                return;
                            }
                            if (!c.inspiracao) {
                                c.currentPower += 1;
                                c.inspiracao = true;
                                c.inspiracaoSnapshot = c.currentPower;
                            } else if (c.currentPower < (c.inspiracaoSnapshot || 0)) {
                                // Tomou dano → dissipa SEM devolver o +1.
                                // Flag persistente impede recalc re-aplicar
                                // a cada updateUI enquanto inspirador vivo.
                                c.inspiracao = false;
                                c.inspiracaoSnapshot = null;
                                c.inspiracaoDissipada = true;
                            } else if (c.currentPower > (c.inspiracaoSnapshot || 0)) {
                                // Ganhou Poder de outra fonte → snapshot acompanha.
                                c.inspiracaoSnapshot = c.currentPower;
                            }
                        } else {
                            // Sem inspirador adjacente: limpa lock (se o
                            // inspirador voltar depois, re-buffa do zero).
                            if (c.inspiracao) {
                                c.inspiracao = false;
                                reduceChampionPower(c, 1, p, i);
                                c.inspiracaoSnapshot = null;
                            }
                            c.inspiracaoDissipada = false;
                        }
                    });
                }
            }

            /* Fortalecer: +1 poder pra um aliado. A IA escolhe entre:
               (a) o aliado que está EMPATADO com a maior ameaça inimiga (vira
                   vitorioso na próxima troca), (b) o aliado em poder 1 que
                   está vulnerável a Assassinar/Bola de Fogo, (c) snowballing
                   o mais forte (incluindo Sobrepujar/Filhote). */


            function gatherEnemyTargets(caster, filterFn) {
                return DfRules.gatherEnemyTargets(state, caster, filterFn);
            }

            function pickRandomEnemyChampions(caster, count, opts = {}) {
                let pool = gatherEnemyTargets(caster, () => true);
                if (opts.avoidPower1) {
                    const noP1 = pool.filter((t) => championPrintedPower(state.players[t.p]?.field[t.i]) > 1);
                    if (noP1.length) pool = noP1;
                }
                for (let i = pool.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [pool[i], pool[j]] = [pool[j], pool[i]];
                }
                return pool.slice(0, Math.min(count, pool.length));
            }

            function applyPoisonStatus(casterP, targetP, targetI) {
                const t = state.players[targetP]?.field[targetI];
                if (!t) return false;
                t.poisoned = true;
                t.poisonTurns = 2;
                t.poisonedByP = casterP;
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    void dfOnlineCommitStatus(targetP, targetI, { broadcast: false });
                }
                return true;
            }

            function showPesadeloPicker(casterIdx) {
                gamePhase = "menu";
                targetData = { ability: "pesadelo", caster: casterIdx, pesadeloResolved: false };
                const targets = [];
                for (let i = 0; i < state.playersCount; i++) {
                    if (i !== casterIdx) targets.push(i);
                }
                let init = 0;
                for (let i = 0; i < targets.length; i++) {
                    if (targets[i] !== casterIdx) { init = i; break; }
                }
                menuData = {
                    type: "target-player",
                    selected: init,
                    targets,
                    options: targets.map(t => {
                        const pl = state.players[t];
                        const heroDef = pl.heroDef || getHeroDef(pl.heroId);
                        const heroName = heroDef ? heroDef.name : pl.name;
                        return { label: `🎯 ${heroName}` };
                    })
                };
                // Cabeçalho com o texto pedido pelo usuário, incluindo a
                // explicação do que é Saque Livre.
                const header =
                    `<h3>💀 PESADELO</h3>` +
                    `<div style="color:#ffe6b0; font-size:0.96rem; line-height:1.45; margin:8px 0 4px; text-align:center; max-width:360px;">` +
                    `Escolha um dos Heróis abaixo, ele Não poderá fazer saque livre no turno dele.` +
                    `<div style="color:#c9b0e8; font-size:0.8rem; font-style:italic; margin-top:6px; line-height:1.35;">` +
                    `(Saque livre - Ato de comprar uma carta grátis no inicio de cada turno).` +
                    `</div>` +
                    `</div>`;
                openOverlay(header, menuData.options);
            }



            // True quando existe pelo menos um adversário SEM o efeito
            // Pesadelo ativo. Usado pela IA pra decidir se vale a pena
            // invocar um campeão "pesadelo" (Void / Succubus) — se todo
            // mundo já tá afetado, ela espera invocar pra não desperdiçar.


            function dfBuildPesadeloDeckSmokeHtml() {
                return `<div class="pesadelo-deck-smoke" aria-hidden="true">` +
                    `<div class="pesadelo-deck-smoke-layer pesadelo-deck-smoke-a"></div>` +
                    `<div class="pesadelo-deck-smoke-layer pesadelo-deck-smoke-b"></div>` +
                    `<div class="pesadelo-deck-smoke-layer pesadelo-deck-smoke-c"></div>` +
                    `</div>`;
            }

            function dfRemovePesadeloShroud(pIdx) {
                const deckEl = getDeckPileEl(pIdx);
                deckEl?.querySelector(".pesadelo-deck-smoke-wrap")?.remove();
                deckEl?.querySelector(":scope > .pesadelo-deck-skull")?.remove();
                deckEl?.classList.remove("pesadelo-deck-afflicted");
                const qEl = document.getElementById(`quadrant-${dfQuadrantForPlayer(pIdx)}`);
                qEl?.querySelector(".pesadelo-quadrant-veil")?.remove();
                qEl?.classList.remove("pesadelo-shrouded");
            }

            function dfEnsurePesadeloDeckSmoke(pIdx, animateSettle) {
                if (!state.players[pIdx]?.skipDraw) {
                    dfRemovePesadeloShroud(pIdx);
                    return;
                }
                const deckEl = getDeckPileEl(pIdx);
                if (!deckEl) return;
                deckEl.classList.add("pesadelo-deck-afflicted");
                // Só fumaça no baralho — sem ícone 💀 residual na tela (autor: só a animação).
                deckEl.querySelector(":scope > .pesadelo-deck-skull")?.remove();
                let wrap = deckEl.querySelector(".pesadelo-deck-smoke-wrap");
                if (!wrap) {
                    wrap = document.createElement("div");
                    wrap.className = "pesadelo-deck-smoke-wrap" +
                        (animateSettle ? " pesadelo-deck-smoke-settle" : "");
                    wrap.innerHTML = dfBuildPesadeloDeckSmokeHtml();
                    deckEl.appendChild(wrap);
                }
            }

            function dfEnsurePesadeloShroud(pIdx, animateSettle) {
                dfEnsurePesadeloDeckSmoke(pIdx, animateSettle);
            }

            function dfSyncPesadeloShrouds() {
                if (!state.started) return;
                for (let p = 0; p < state.playersCount; p++) {
                    if (state.players[p]?.skipDraw) dfEnsurePesadeloShroud(p, false);
                    else dfRemovePesadeloShroud(p);
                }
            }

            /** Pesadelo afeta sempre o adversário — nunca o campo de quem invocou. */
            function dfPesadeloVictimPlayer(targetIdx, casterIdx) {
                const caster = casterIdx != null ? (casterIdx | 0) : null;
                if (caster == null) {
                    return (targetIdx != null && targetIdx >= 0) ? (targetIdx | 0) : null;
                }
                const t = (targetIdx != null && targetIdx >= 0) ? (targetIdx | 0) : null;
                if (t != null && t !== caster) return t;
                return dfRivalPlayerIdx(caster);
            }

            /** Retângulo do campo do adversário afetado — centro da fumaça Pesadelo. */
            function dfPesadeloFieldRect(victimP) {
                const qIdx = dfQuadrantForPlayer(victimP);
                const qEl = document.getElementById(`quadrant-${qIdx}`);
                const fieldEl = qEl?.querySelector(".quadrant-field");
                const fr = fieldEl?.getBoundingClientRect();
                if (fr && fr.width > 24 && fr.height > 24) return fr;
                return qEl?.getBoundingClientRect() || fr || null;
            }

            async function playPesadeloSmokeVisual(targetIdx, casterIdx) {
                const victim = casterIdx != null
                    ? dfRivalPlayerIdx(casterIdx)
                    : dfPesadeloVictimPlayer(targetIdx, casterIdx);
                if (victim == null) return;
                updateUI(true);
                await wait(48);
                const fr = dfPesadeloFieldRect(victim);
                if (fr && fr.width > 0 && fr.height > 0) {
                    const cx = fr.left + fr.width / 2;
                    const cy = fr.top + fr.height / 2;
                    const gpuNight = window.DfVfxEngine?.wantsGpuPresentation?.()
                        && typeof window.DfPixiVfx?.playNightmareScene === "function";
                    if (gpuNight) {
                        // PESADELO cinematográfico (Pixi+GSAP): invocação sombria com
                        // partículas, vórtice de fumaça roxa e caveira fantasma.
                        await window.DfPixiVfx.playNightmareScene({ cx, cy, cinematic: true });
                    } else {
                        const host = document.createElement("div");
                        host.className = "pesadelo-field-smoke-host";
                    const spread = Math.min(fr.width, fr.height) * 0.42;
                    host.style.cssText =
                        `position:${dfVfxPos()};left:${cx}px;top:${cy}px;` +
                        `transform:translate(-50%,-50%);` +
                        `width:1px;height:1px;` +
                        `z-index:9195;pointer-events:none;overflow:visible;`;
                    dfVfxMount(host);
                    try {
                        const puffCount = (window.__dfFX?.mobile) ? 14 : 22;
                        for (let i = 0; i < puffCount; i++) {
                            const puff = document.createElement("div");
                            puff.className = "pesadelo-smoke-puff-local";
                            const ang = (i / puffCount) * Math.PI * 2 + Math.random() * 0.6;
                            const dist = spread * (0.35 + Math.random() * 0.65);
                            const size = 70 + Math.random() * 110;
                            puff.style.left = "0px";
                            puff.style.top = "0px";
                            puff.style.width = size + "px";
                            puff.style.height = size + "px";
                            puff.style.setProperty("--dx", (Math.cos(ang) * dist) + "px");
                            puff.style.setProperty("--dy", (-60 - Math.random() * spread * 0.9) + "px");
                            puff.style.setProperty("--sc", (1.6 + Math.random() * 1.4).toFixed(2));
                            puff.style.setProperty("--dur", (1.0 + Math.random() * 0.6) + "s");
                            puff.style.animationDelay = (i * 24) + "ms";
                            host.appendChild(puff);
                        }
                        await wait((window.__dfFX?.mobile) ? 1300 : 1500);
                    } finally {
                        host.remove();
                        }
                    }
                }
                dfEnsurePesadeloDeckSmoke(victim, true);
                await wait(500);
            }

            async function applyPesadelo(casterIdx, targetIdx) {
                markOnEnterUsed(casterIdx, "pesadelo");
                const victim = dfPesadeloVictimPlayer(targetIdx, casterIdx);
                if (victim == null) return;
                state.players[victim].skipDraw = true;
                log(`💀 Pesadelo em ${state.players[victim].name}.`);
                try { window.sfx && window.sfx("nightmare"); } catch (e) {}
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({ kind: "pesadelo", casterIdx, targetIdx: victim });
                }
                await playPesadeloSmokeVisual(victim, casterIdx);
                dfSyncPesadeloShrouds();
                updateUI();
            }

            async function confirmPesadeloTarget(targetIdx) { if (!targetData || targetData.ability !== "pesadelo" || targetData
                    .pesadeloResolved) return;
                targetData.pesadeloResolved = true;
                await applyPesadelo(targetData.caster, targetIdx);
                gamePhase = "normal";
                $("menu-overlay").classList.remove("active");
                targetData = {};
                menuData = null;
                enterProcessed = false;
                updateUI(); }

            // =============================================================
            // ROUBAR (Tagarela / Raziel) — onEnter instantâneo
            // =============================================================
            // Reusa o picker "target-player" da Pesadelo, mas com a pergunta
            // "Qual jogador você deseja roubar?". O alvo perde 1 carta
            // aleatória da mão, e essa carta vai pra mão de quem invocou.
            // Se o alvo está com a mão vazia, o roubo falha silenciosamente
            // (a IA já evita escolher alvos sem cartas via aiChooseRoubar).




            function showRoubarPicker(casterIdx) {
                gamePhase = "menu";
                targetData = { ability: "roubar", caster: casterIdx, roubarResolved: false };
                const targets = [];
                for (let i = 0; i < state.playersCount; i++) {
                    if (i !== casterIdx && state.players[i].hand && state.players[i].hand.length > 0) targets.push(i);
                }
                menuData = {
                    type: "target-player",
                    selected: 0,
                    targets,
                    options: targets.map(t => {
                        const pl = state.players[t];
                        const heroDef = pl.heroDef || getHeroDef(pl.heroId);
                        const heroName = heroDef ? heroDef.name : pl.name;
                        const handLen = pl.hand?.length || 0;
                        return { label: `🎯 ${heroName} (${handLen} ${handLen === 1 ? "carta" : "cartas"})` };
                    })
                };
                const header =
                    `<h3>🃏 ROUBAR</h3>` +
                    `<div style="color:#ffe6b0; font-size:0.96rem; line-height:1.45; margin:8px 0 4px; text-align:center; max-width:360px;">` +
                    `Qual jogador você deseja roubar?` +
                    `<div style="color:#c9b0e8; font-size:0.8rem; font-style:italic; margin-top:6px; line-height:1.35;">` +
                    `O alvo perde 1 carta aleatória da mão dele — ela vai direto pra sua mão.` +
                    `</div>` +
                    `</div>`;
                openOverlay(header, menuData.options);
            }

            // ROUBAR — animação DIVERTIDA (sem moeda, focada em CARTA):
            //   1) Mão "ladrona" 🫳 pisca em cima da mão do alvo (dramatiza
            //      o "peguei!").
            //   2) Uma carta sai da mão do alvo, viaja em ARCO até a mão do
            //      ladrão, balançando e deixando rastro de estrelinhas ✨.
            //   3) Sem banner de texto — só a carta chegando na mão do ladrão.
            // Sem 🪙 em nenhum momento — Roubar = +1 CARTA, não dinheiro.
            async function animateRoubar(casterIdx, targetIdx, stolenCard, opts = {}) {
                try {
                    const qCaster = $(`quadrant-${dfQuadrantForPlayer(casterIdx)}`);
                    const qTarget = $(`quadrant-${dfQuadrantForPlayer(targetIdx)}`);
                    if (!qCaster || !qTarget) { await wait(80); return; }
                    const handCaster = qCaster.querySelector(".quadrant-hand") || qCaster;
                    const handTarget = qTarget.querySelector(".quadrant-hand") || qTarget;
                    // MP: layout estável (mãos .ai-back / pós-updateUI).
                    if (window.__DF_ONLINE || document.body.classList.contains("df-pvp-mode")) {
                        await dfFlushHandLayout();
                    }
                    let sr = handTarget.getBoundingClientRect();
                    let dr = handCaster.getBoundingClientRect();
                    if (!sr.width || !sr.height || !dr.width || !dr.height) {
                        await dfFlushHandLayout(2);
                        sr = handTarget.getBoundingClientRect();
                        dr = handCaster.getBoundingClientRect();
                        if (!sr.width || !sr.height || !dr.width || !dr.height) {
                            await wait(80); return;
                        }
                    }

                    const cardName = typeof stolenCard === "string"
                        ? stolenCard
                        : (stolenCard?.cardName || stolenCard?.name || null);
                    const cardPow = stolenCard?.currentPower ?? stolenCard?.power ?? "?";

                    /* Tamanho = carta de mão (--df-hand-card-*), NUNCA .ai-back pequenino. */
                    const cssSz = dfHandCardCssSize();
                    let cw = cssSz.w;
                    let ch = cssSz.h;
                    const faceSlot = handCaster.querySelector(".hand-wrap .hcard")
                        || document.querySelector("#quadrant-0 .hand-wrap .hcard, .quadrant-hand .hcard");
                    if (faceSlot) {
                        const faceSz = dfHandSlotCardSize(faceSlot);
                        if (faceSz && faceSz.w > 40 && faceSz.h > 50) {
                            cw = faceSz.w;
                            ch = faceSz.h;
                        }
                    }

                    // Pré-aquece face (composta) — evita voo preto enquanto decode.
                    if (cardName && window.__DF_ONLINE) {
                        try {
                            await Promise.race([
                                Promise.resolve(window.DfCardFace?.warmFace?.({
                                    name: cardName,
                                    currentPower: cardPow,
                                    power: stolenCard?.power ?? cardPow,
                                }, { power: cardPow })).catch(() => null),
                                wait(900),
                            ]);
                        } catch (eWarm) { /* */ }
                    }

                    let refRect = (opts.originRect && opts.originRect.width)
                        ? opts.originRect
                        : null;
                    if (!refRect) {
                        const originSlot = handTarget.querySelector(
                            ".hand-wrap .hcard, .ai-hand-wrap .ai-back, .ai-hand-wrap .hcard, .hcard, .ai-back",
                        );
                        refRect = originSlot?.getBoundingClientRect?.();
                        if ((!refRect || !refRect.width) && window.__DF_ONLINE) {
                            await dfFlushHandLayout(2);
                            const retry = handTarget.querySelector(
                                ".hand-wrap .hcard, .ai-hand-wrap .ai-back, .ai-hand-wrap .hcard, .hcard, .ai-back",
                            );
                            refRect = retry?.getBoundingClientRect?.();
                        }
                    }
                    const startVpX = refRect
                        ? refRect.left + refRect.width / 2
                        : sr.left + sr.width / 2;
                    const startVpY = refRect
                        ? refRect.top + refRect.height / 2
                        : sr.top + sr.height / 2;
                    /* Destino = slot real onde a carta roubada vai encostar na mão do
                       ladrão (a carta é empilhada no fim), não o centro da mão. */
                    const landing = dfHandLandingCenter(casterIdx, undefined);
                    const endVpX = landing?.x ?? (dr.left + dr.width / 2);
                    const endVpY = landing?.y ?? (dr.top + dr.height / 2);
                    const start = dfVfxMap(startVpX, startVpY);
                    const end = dfVfxMap(endVpX, endVpY);
                    const dx = end.x - start.x;
                    const dy = end.y - start.y;
                    if (dfVfxCanvasActive()) {
                        const sz = dfVfxMapSize(cw, ch);
                        cw = sz.width;
                        ch = sz.height;
                    }

                    const card = document.createElement("div");
                    card.className = "roubar-card-fly roubar-card-face hcard has-art art-ready";
                    card.style.position = dfVfxPos();
                    card.style.left = start.x + "px";
                    card.style.top = start.y + "px";
                    card.style.transform = "translate(-50%, -50%) rotate(-8deg)";
                    card.style.width = cw + "px";
                    card.style.height = ch + "px";
                    card.style.maxWidth = "none";
                    card.style.maxHeight = "none";
                    card.style.minWidth = cw + "px";
                    card.style.minHeight = ch + "px";
                    card.style.overflow = "visible";
                    card.style.borderRadius = "10px";
                    card.style.boxSizing = "border-box";
                    card.style.background = "transparent";
                    card.innerHTML = `<div class="pow">${cardPow}</div><div class="nm">${cardName || ""}</div>`;
                    const artSnap = {
                        cardName,
                        name: cardName,
                        currentPower: cardPow,
                        basePower: stolenCard?.power ?? cardPow,
                    };
                    // 1) Bitmap assado (nunca preto) → 2) face composta → 3) art PNG.
                    let baked = "";
                    try {
                        if (cardName && window.DfCardFace?.getFaceDataUrl) {
                            baked = window.DfCardFace.getFaceDataUrl(cardName, cardPow, {}) || "";
                        }
                    } catch (eBake) { baked = ""; }
                    if (baked) {
                        const img = document.createElement("img");
                        img.className = "card-art-bg";
                        img.alt = "";
                        img.draggable = false;
                        img.src = baked;
                        img.style.cssText =
                            "position:absolute;inset:0;width:100%;height:100%;object-fit:cover;" +
                            "pointer-events:none;display:block;opacity:1;z-index:0;border-radius:8px;";
                        card.insertBefore(img, card.firstChild);
                        card.classList.add("has-art", "art-ready");
                    }
                    dfEnsureBattleFlyArt(card, artSnap);
                    if (!card.querySelector("img.card-art-bg, .df-card-face")) {
                        // Último recurso: arte estática — nunca retângulo preto.
                        try {
                            const src = window.dfPrimaryCardArtSrc?.(cardName);
                            if (src) {
                                const img = document.createElement("img");
                                img.className = "card-art-bg";
                                img.alt = "";
                                img.draggable = false;
                                img.src = src;
                                img.style.cssText =
                                    "position:absolute;inset:0;width:100%;height:100%;object-fit:cover;" +
                                    "pointer-events:none;display:block;opacity:1;border-radius:8px;";
                                card.insertBefore(img, card.firstChild);
                            }
                        } catch (eArt) { /* */ }
                    }
                    card.classList.remove("df-card-face--loading", "art-loading");
                    card.classList.add("art-ready", "has-art");
                    /* Marcar ANTES de montar: dfVfxMount remapearia left/top/tamanho
                       já convertidos, dobrando a escala (carta gigante). */
                    card.dataset.dfVfxMapped = "1";
                    dfVfxMount(card);

                    const arcLift = Math.min(
                        Math.max(dfVfxCanvasActive() ? 26 : 40, Math.abs(dx) * 0.16),
                        Math.max(48, Math.abs(dy) * 0.42),
                    );
                    /* Voo natural: arco suave e leve inclinação — sem pião de 720°. */
                    const anim = card.animate([
                        { transform: "translate(-50%, -50%) rotate(-8deg)", offset: 0 },
                        {
                            transform: `translate(calc(-50% + ${dx * 0.32}px), calc(-50% + ${dy * 0.32 - arcLift}px)) rotate(-3deg)`,
                            offset: 0.38,
                        },
                        {
                            transform: `translate(calc(-50% + ${dx * 0.72}px), calc(-50% + ${dy * 0.72 - arcLift * 0.62}px)) rotate(4deg)`,
                            offset: 0.72,
                        },
                        {
                            transform: `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px)) rotate(0deg)`,
                            offset: 1,
                        },
                    ], { duration: 880, easing: "cubic-bezier(.33,.02,.32,1)", fill: "forwards" });

                    const SPARKS = 9;
                    const sparkChars = ["✨", "💫", "⭐"];
                    for (let i = 0; i < SPARKS; i++) {
                        setTimeout(() => {
                            const t = (i + 1) / (SPARKS + 1);
                            const vx = startVpX + (endVpX - startVpX) * t;
                            const vy = startVpY + (endVpY - startVpY) * t - arcLift * Math.sin(Math.PI * t);
                            const sp = dfVfxMap(vx, vy);
                            const s = document.createElement("div");
                            s.className = "roubar-sparkle";
                            s.style.position = dfVfxPos();
                            s.style.left = sp.x + "px";
                            s.style.top = sp.y + "px";
                            s.textContent = sparkChars[i % sparkChars.length];
                            dfVfxMount(s);
                            s.dataset.dfVfxMapped = "1";
                            setTimeout(() => s.remove(), 720);
                        }, 80 + i * 75);
                    }

                    await anim.finished.catch(() => {});
                    card.remove();
                    await wait(120);
                } catch (e) { /* noop — animação cosmética */ }
            }

            // DESACELERAR — onda temporal do campeão até o quadrante adversário.
            async function animateDesacelerar(casterIdx, casterFieldIdx, targetIdx) {
                let fromEl = null;
                let qTarget = null;
                const cleanupEls = [];
                window.__dfDesacelerarAnimActive = true;
                window.__dfDesacelerarAnimStartedAt = Date.now();
                try {
                    try { window.sfx && window.sfx("nightmare"); } catch (e) {}
                    qTarget = document.getElementById(`quadrant-${dfQuadrantForPlayer(targetIdx)}`);
                    if (!qTarget) {
                        await wait(700);
                        window.__dfDesacelerarAnimActive = false;
                        return;
                    }

                    fromEl = (casterFieldIdx != null && casterFieldIdx >= 0)
                        ? getChampionDom(casterIdx, casterFieldIdx)
                        : null;

                    const tr = qTarget.getBoundingClientRect();
                    const endX = tr.left + tr.width / 2;
                    const endY = tr.top + tr.height * 0.2;

                    const pixi = window.DfPixiVfx;
                    const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                        && typeof pixi?.playDesacelerarScene === "function";
                    if (gpu && fromEl) {
                        await ensureVfxReady();
                        const fr = fromEl.getBoundingClientRect();
                        const ok = await pixi.playDesacelerarScene({
                            fromX: fr.left + fr.width / 2,
                            fromY: fr.top + fr.height / 2,
                            toX: endX,
                            toY: endY,
                            cinematic: true,
                            onAfflict: () => {
                                qTarget.classList.add("desacelerar-afflicted");
                                qTarget.querySelector(".action-dots")
                                    ?.classList.add("desacelerar-action-hit");
                            },
                        });
                        if (ok) {
                            await wait(FX.mobile ? 1650 : 2050);
                            return;
                        }
                    }

                    if (fromEl) {
                        fromEl.classList.add("desacelerar-cast-flash");
                        const fr = fromEl.getBoundingClientRect();
                        const startX = fr.left + fr.width / 2;
                        const startY = fr.top + fr.height / 2;
                        const dx = endX - startX;
                        const dy = endY - startY;
                        const dist = Math.hypot(dx, dy) || 1;
                        const rot = Math.atan2(dy, dx) * 180 / Math.PI;
                        const beam = document.createElement("div");
                        beam.className = "desacelerar-time-beam";
                        beam.style.left = startX + "px";
                        beam.style.top = startY + "px";
                        beam.style.width = dist + "px";
                        beam.style.setProperty("--rot", rot + "deg");
                        dfVfxMount(beam);
                        cleanupEls.push(beam);
                        await wait(FX.mobile ? 560 : 680);
                    } else {
                        await wait(FX.mobile ? 280 : 360);
                    }

                    const ripple = document.createElement("div");
                    ripple.className = "desacelerar-target-ripple";
                    ripple.style.left = endX + "px";
                    ripple.style.top = endY + "px";
                    dfVfxMount(ripple);
                    cleanupEls.push(ripple);

                    await wait(FX.mobile ? 380 : 480);

                    qTarget.classList.add("desacelerar-afflicted");
                    const veil = document.createElement("div");
                    veil.className = "desacelerar-quadrant-veil";
                    qTarget.appendChild(veil);

                    const clock = document.createElement("div");
                    clock.className = "desacelerar-clock-glyph";
                    clock.innerHTML =
                        '<div class="desac-clock-face">' +
                            '<div class="desac-clock-hand desac-clock-hour"></div>' +
                            '<div class="desac-clock-hand desac-clock-minute"></div>' +
                            '<div class="desac-clock-center"></div>' +
                        '</div>';
                    clock.style.left = endX + "px";
                    clock.style.top = endY + "px";
                    dfVfxMount(clock);
                    cleanupEls.push(clock);

                    const actionDots = qTarget.querySelector(".action-dots");
                    if (actionDots) actionDots.classList.add("desacelerar-action-hit");

                    const minus = document.createElement("div");
                    minus.className = "desacelerar-minus-label";
                    minus.textContent = "−1 AÇÃO";
                    minus.style.left = endX + "px";
                    minus.style.top = (endY + 36) + "px";
                    dfVfxMount(minus);
                    cleanupEls.push(minus);

                    if (!FX.liteVfx) {
                        DfAnim.spawnBurst(12, "desacelerar-spark", (p, j) => {
                            p.textContent = ["⏳", "🕐", "⌛", "💫"][j % 4];
                            p.style.left = endX + "px";
                            p.style.top = endY + "px";
                            p.style.setProperty("--px", ((Math.random() - 0.5) * 120) + "px");
                            p.style.setProperty("--py", ((Math.random() - 0.5) * 90 - 20) + "px");
                        }, 1100, () => {
                            const d = document.createElement("div");
                            d.className = "desacelerar-spark";
                            return d;
                        });
                    }

                    await wait(FX.mobile ? 1650 : 2050);
                } catch (e) {
                    console.warn("[DF desacelerar VFX]", e);
                } finally {
                    cleanupEls.forEach((el) => { try { el.remove(); } catch (err) {} });
                    dfPurgeDesacelerarVfx();
                    window.__dfDesacelerarAnimActive = false;
                }
            }

            async function applyRoubar(casterIdx, targetIdx) {
                const targetP = state.players[targetIdx];
                const casterP = state.players[casterIdx];
                if (!targetP || !casterP) return;
                const hand = targetP.hand || [];
                if (hand.length <= 0) {
                    log(`${casterP.name} tentou roubar ${targetP.name}, mas a mão estava vazia.`);
                    floatText("Mão vazia!", "info center", 1500);
                    return;
                }
                const casterIsAi = !!casterP.isAI;
                const idx = casterIsAi
                    ? aiPickStealFromHand(hand)
                    : Math.floor(Math.random() * hand.length);
                const qVic = $(`quadrant-${dfQuadrantForPlayer(targetIdx)}`);
                const originEl = qVic?.querySelector(
                    ".hand-wrap .hcard, .ai-hand-wrap .ai-back, .ai-hand-wrap .hcard, .hcard, .ai-back",
                );
                const originRect = originEl?.getBoundingClientRect?.();
                const stolen = hand.splice(idx, 1)[0];
                casterP.hand.push(stolen);
                log(`🃏 ${casterP.name} roubou 1 CARTA de ${targetP.name}.`);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "roubar",
                        casterIdx,
                        targetIdx,
                        card: stolen,
                        cardSnap: {
                            name: stolen.name,
                            power: stolen.power,
                            currentPower: stolen.currentPower ?? stolen.power,
                        },
                        originRect: originRect && originRect.width
                            ? {
                                left: originRect.left,
                                top: originRect.top,
                                width: originRect.width,
                                height: originRect.height,
                            }
                            : null,
                    });
                }
                updateUI({ immediate: true });
                await dfFlushHandLayout();
                await animateRoubar(casterIdx, targetIdx, stolen, { originRect });
                updateUI();
            }

            function confirmRoubarTarget(targetIdx) {
                if (!targetData || targetData.ability !== "roubar" || targetData.roubarResolved) return;
                targetData.roubarResolved = true;
                const caster = targetData.caster;
                gamePhase = "normal";
                $("menu-overlay").classList.remove("active");
                targetData = {};
                menuData = null;
                enterProcessed = false;
                applyRoubar(caster, targetIdx);
            }

            // =============================================================
            // DESACELERAR (Maga do Tempo / Soldado Futurista) — onEnter instantâneo
            // =============================================================
            // Marca um adversário com skipNextAction=true. Na manutenção do
            // próximo turno dele, p.actions = MAX_ACTIONS - 1 e o flag é
            // consumido. Não acumula (igual à Pesadelo): se já está marcado,
            // jogar de novo não muda nada — a IA evita esses alvos.




            function showDesacelerarPicker(casterIdx) {
                gamePhase = "menu";
                targetData = { ability: "desacelerar", caster: casterIdx, desacelerarResolved: false };
                const targets = [];
                for (let i = 0; i < state.playersCount; i++) {
                    if (i !== casterIdx && !state.players[i].skipNextAction) targets.push(i);
                }
                menuData = {
                    type: "target-player",
                    selected: 0,
                    targets,
                    options: targets.map(t => {
                        const pl = state.players[t];
                        const heroDef = pl.heroDef || getHeroDef(pl.heroId);
                        const heroName = heroDef ? heroDef.name : pl.name;
                        return { label: `🎯 ${heroName}` };
                    })
                };
                const header =
                    `<h3>⏳ DESACELERAR</h3>` +
                    `<div style="color:#ffe6b0; font-size:0.96rem; line-height:1.45; margin:8px 0 4px; text-align:center; max-width:360px;">` +
                    `Qual jogador você deseja desacelerar?` +
                    `<div style="color:#c9b0e8; font-size:0.8rem; font-style:italic; margin-top:6px; line-height:1.35;">` +
                    `O alvo fará 1 ação a menos no próximo turno dele.` +
                    `</div>` +
                    `</div>`;
                openOverlay(header, menuData.options);
            }

            async function applyDesacelerar(casterIdx, targetIdx, casterFieldIdx = -1) {
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "desacelerar",
                        casterIdx,
                        targetIdx,
                        casterFieldIdx,
                    });
                }
                markOnEnterUsed(casterIdx, "desacelerar");
                const targetP = state.players[targetIdx];
                const casterP = state.players[casterIdx];
                if (!targetP || !casterP) return;
                targetP.skipNextAction = true;
                log(`⏳ ${casterP.name} desacelerou ${targetP.name} — ele fará 1 ação a menos!`);
                await animateDesacelerar(casterIdx, casterFieldIdx, targetIdx);
                updateUI();
            }

            async function confirmDesacelerarTarget(targetIdx) {
                if (!targetData || targetData.ability !== "desacelerar" || targetData.desacelerarResolved) return;
                targetData.desacelerarResolved = true;
                const caster = targetData.caster;
                const casterFieldIdx = targetData.casterFieldIdx ?? -1;
                gamePhase = "normal";
                $("menu-overlay").classList.remove("active");
                targetData = {};
                menuData = null;
                enterProcessed = false;
                await applyDesacelerar(caster, targetIdx, casterFieldIdx);
            }

            /* Bola de Fogo: -1 poder. Prefere alvos que MORREM (poder 1),
               depois ameaças crescentes (Filhote), Sobrepujares e altos poderes.
               Não atira em alvos com escudo. */
            // IA: alvo do ZERO ABSOLUTO. Prioriza inimigo JÁ congelado
            // (destrói), depois maior currentPower, depois ameaças do humano.
            // IA: alvo de CONGELAR (Frosty ult, etc.). Prioriza Poder ≥ 2;
            // só congela Poder 1 se não houver outro alvo (ex.: só restam P1).






            /* Assassinar: destrói qualquer alvo de poder 1, ignora "sem honra"
               (sempre concede PV via forceAward). Prefere ameaças crescentes
               primeiro (Filhote), depois Sobrepujares, depois alvos do humano. */


            // IA: TRANSFORMAR EM BICHINHO. Resultado é probabilístico
            // (80% reduz pela metade, 20% +1). A IA mira estritamente no
            // adversário com MAIOR currentPower — no caso comum (80%) causa
            // o maior estrago e, no pior caso (20%), o buff é só +1.
            // Escudo NÃO bloqueia transformação (não é redução de Poder),
            // então alvos com escudo são válidos — coerente com o human flow.


            function dfOnlineIdentityFieldPatch(targetP, targetI, card) {
                if (!card) return null;
                return {
                    targetP,
                    targetI,
                    name: card.name,
                    power: card.power,
                    basePower: card.basePower,
                    currentPower: card.currentPower ?? card.power ?? 0,
                    abilityType: card.abilityType ?? null,
                    abilityName: card.abilityName ?? null,
                    abilityDesc: card.abilityDesc ?? null,
                    onEnter: card.onEnter ?? null,
                    onDestroy: card.onDestroy ?? null,
                    talentEffect: card.talentEffect ?? null,
                    summonRitual: card.summonRitual ?? null,
                    constantEffect: card.constantEffect ?? null,
                    isToken: !!card.isToken,
                    hidden: !!card.hidden,
                    freeAttack: false,
                    frozen: false,
                    shielded: false,
                    barrier: false,
                    vulnerable: false,
                };
            }

            async function dfOnlineCommitTransformToken(targetP, targetI, card) {
                if (!window.__DF_ONLINE || dfOnlineApplyingRemote || !card) return;
                const patch = dfOnlineIdentityFieldPatch(targetP, targetI, card);
                if (!patch) return;
                const { targetP: _tp, targetI: _ti, ...cardFlags } = patch;
                try {
                    await dfOnlineCommitMutations([{
                        op: "transformToken",
                        targetP,
                        targetI,
                        card: cardFlags,
                    }], { reconcile: true });
                } catch (e) {
                    console.warn("[DF online] transformToken FIELD_COMMIT", e);
                }
            }

            // TRANSFORMAR EM BICHINHO — animação cinematográfica + roll 90/10.
            // Mantém a posição do alvo no campo, preservando uid pra evitar
            // glitches de DOM. Status temporários (frozen/shielded/wallBuff/
            // poisoned/pulled/silenced) são limpos — o Campeão "renasce" como
            // token. NÃO chama destroyChampion: não há concessão de PV ao
            // adversário, é uma transformação, não destruição.
            async function playTransformarBichinhoVisual(targetP, targetI, success) {
                const tr = dfChampionAnchorRect(targetP, targetI);
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                const puff = document.createElement("div");
                puff.textContent = success ? "✨" : "💀";
                puff.style.cssText =
                    `transform:translate(-50%,-50%) scale(0.4);font-size:96px;z-index:9999;` +
                    `pointer-events:none;text-shadow:0 0 24px ${success ? "#c87aff" : "#ff5a5a"};` +
                    `transition:transform 420ms ease-out, opacity 420ms ease-out;opacity:0;`;
                dfVfxPlaceCenter(puff, cx, cy);
                requestAnimationFrame(() => {
                    puff.style.transform = "translate(-50%,-50%) scale(1.4)";
                    puff.style.opacity = "1";
                });
                try { window.sfx && window.sfx(success ? "transform_pet" : "transform_monster"); } catch (e) {}
                await wait(380);
                spawnParticles(cx, cy, 14);
                return puff;
            }

            async function dismissTransformPuff(puff) {
                if (!puff?.isConnected) return;
                await wait(180);
                puff.style.opacity = "0";
                puff.style.transform = "translate(-50%,-50%) scale(2.2)";
                await wait(280);
                puff.remove();
            }

            async function castTransformarBichinho(casterP, casterField, targetP, targetI) {
                const target = state.players[targetP].field[targetI];
                if (!target) return;
                // Transformar em Bichinho NÃO é redução de Poder — é
                // substituição completa do Campeão. Por isso NÃO dispara
                // Proteção Divina (que cancela reduções) nem dissolução
                // de Muralha do Alexander. Escudo também não bloqueia.
                const success = Math.random() < 0.90;
                const puff = await playTransformarBichinhoVisual(targetP, targetI, success);
                const origPower = target.currentPower;
                const origName = target.name;
                // VULNERÁVEL + sucesso (Bichinho Fofinho): destruição
                // instantânea em vez de transformar (regra Fumaça Tóxica).
                if (success && target.vulnerable) {
                    await dismissTransformPuff(puff);
                    log(`☠️ ${origName} (Vulnerável) foi destruído ao tentar virar Bichinho Fofinho!`);
                    floatText(`☠️ ${origName} destruído (Vulnerável)!`, "warn center", 1800);
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        dfOnlineBroadcastVisual({
                            kind: "transformar_bichinho",
                            casterP, casterField, targetP, targetI, success: true,
                            fieldPatches: [{ targetP, targetI, removed: true }],
                        });
                        destroyChampion(targetP, targetI, casterP, "transformarBichinho", {
                            forceAward: true,
                            skipOnlineSync: true,
                        });
                        try {
                            await dfOnlineCommitMutations([{
                                op: "destroy",
                                targetP,
                                targetI,
                                awardVpTo: casterP,
                                forceAward: true,
                                reason: "transformarBichinho",
                            }], { reconcile: true });
                        } catch (e) { /* */ }
                    } else {
                        destroyChampion(targetP, targetI, casterP, "transformarBichinho", { forceAward: true });
                    }
                    updateUI();
                    checkWin();
                    return;
                }
                // Aplica a transformação in-place.
                const tokenDef = success
                    ? cardDefs.find(d => d.name === "BICHINHO FOFINHO")
                    : cardDefs.find(d => d.name === "O CHEFÃO");
                const newPower = success ? Math.floor(origPower / 2) : (origPower + 1);
                // Copia campos descritivos do token; preserva uid/posição.
                target.name = tokenDef.name;
                // FIX (usuário): a joia de Poder no canto superior esquerdo
                // precisa MOSTRAR o novo valor após a transformação. Como
                // tokens não têm arte (.has-art false) e o .pow em .ccard
                // está sempre escondido, dependemos de .gem-overlay — que
                // só renderiza quando `currentPower !== basePower`. Por isso
                // forçamos basePower=0 — assim o overlay PNG da joia aparece
                // sempre que currentPower >= 1, mostrando o Poder real do
                // bichinho/monstro.
                // IMPORTANTE: mantemos `power = newPower` (não 0). Isso
                // preserva o Poder transformado quando o bichinho/monstro é
                // devolvido à mão por Amedrontar (Sinistrela ult / Talento
                // AMEDRONTAR), porque `cloneCard(d)` inicializa o clone com
                // `currentPower: d.power` e `basePower: d.power`. Se power
                // virasse 0, o token voltaria à mão sem Poder.
                target.power = newPower;
                target.basePower = 0;
                target.currentPower = newPower;
                target.abilityType = tokenDef.abilityType;
                target.abilityName = tokenDef.abilityName;
                target.abilityDesc = tokenDef.abilityDesc;
                target.onEnter = null;
                target.onDestroy = null;
                target.talentEffect = null;
                target.summonRitual = undefined;
                target.isToken = true;
                target.hidden = true;
                // Limpa TODO status (temporário e buffs externos). A criatura
                // "renasceu": qualquer Sobrepujar/Investida/Crescimento Eterno/
                // Guerra herdado some junto com a identidade antiga.
                target.frozen = false; target.frozenTurns = 0;
                target.shielded = false; target.shieldedTurns = 0; target.shieldedPermanent = false;
                target.freeAttack = false;
                target.silenced = false;
                target.poisoned = false; target.poisonTurns = 0; target.poisonedByP = -1;
                target.pulled = false; target.pulledFromOwner = -1; target.pulledTurns = 0;
                target.wallBuff = false; target.wallBuffApplied = false; target.wallBuffSnapshot = 0;
                target.foreverGrowth = false;
                target.guerraBuff = false; target.guerraBuffTurns = 0;
                target.fury = false; target.furyTurns = 0; target.furyStacks = 0; target.furyBonusActive = false;
                target.burning = false; target.burningTurns = 0; target.burningByP = undefined;
                target.vulnerable = false;
                target.fireAura = false; target.fireAuraTurns = 0;
                target.burning = false; target.burningTurns = 0; target.burningByP = undefined;
                target.barrier = false; target.barrierTurns = 0; target.barrierPermanent = false;
                await dismissTransformPuff(puff);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    const idPatch = dfOnlineIdentityFieldPatch(targetP, targetI, target);
                    dfOnlineBroadcastVisual({
                        kind: "transformar_bichinho",
                        casterP, casterField, targetP, targetI, success,
                        fieldPatches: idPatch ? [idPatch] : undefined,
                    });
                    await dfOnlineCommitTransformToken(targetP, targetI, target);
                }
                if (success) {
                    log(`✨ ${origName} (Poder ${origPower}) virou BICHINHO FOFINHO (Poder ${newPower})!`);
                    floatText(`✨ Virou Bichinho! (${newPower})`, "info center", 1800);
                } else {
                    log(`💀 ${origName} (Poder ${origPower}) virou O CHEFÃO (Poder ${newPower})! O feitiço deu errado!`);
                    floatText(`💀 Virou Monstro! (${newPower})`, "info center", 1800);
                }
                updateUI();
                checkWin();
            }

            function clearChampionFieldStatuses(c) {
                if (!c) return;
                c.frozen = false; c.frozenTurns = 0;
                c.shielded = false; c.shieldedTurns = 0; c.shieldedPermanent = false;
                c.freeAttack = false;
                c.silenced = false;
                c.poisoned = false; c.poisonTurns = 0; c.poisonedByP = -1;
                c.pulled = false; c.pulledFromOwner = -1; c.pulledTurns = 0;
                c.wallBuff = false; c.wallBuffApplied = false; c.wallBuffSnapshot = 0;
                c.foreverGrowth = false;
                c.guerraBuff = false; c.guerraBuffTurns = 0;
                c.barrier = false; c.barrierTurns = 0; c.barrierPermanent = false;
                c.fireAura = false; c.fireAuraTurns = 0;
                c.burning = false; c.burningTurns = 0; c.burningByP = undefined;
                c.fury = false; c.furyTurns = 0; c.furyStacks = 0; c.furyBonusActive = false;
                c.vulnerable = false;
                c.corruptedNoHonor = false;
            }

            async function applyFuryOnEnter(casterP, fieldIdx) {
                const c = state.players[casterP]?.field[fieldIdx];
                if (!c || c.silenced) return;
                DfRules.grantFuryStacks(c, 1);
                log(`🔥 ${c.name} entrou em FÚRIA (+1 Poder por 1 rodada)!`);
                try { window.sfx && window.sfx("buff_power"); } catch (e) {}
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({ kind: "fury", ownerP: casterP, fieldIdx });
                    dfOnlineCommitChampStatus(casterP, fieldIdx, { broadcast: false });
                }
                const el = getChampionDom(casterP, fieldIdx);
                if (el) {
                    el.classList.add("fury-flash");
                    setTimeout(() => el.classList.remove("fury-flash"), 700);
                }
                updateUI();
            }

            async function playFuryGrantTargets(ownerIdx, targets) {
                if (!targets?.length) return;
                try { window.sfx && window.sfx("buff_power"); } catch (e) {}
                // MP: não mostrar ícone de fúria antes do burst — updateUI depois.
                if (!window.__DF_ONLINE) updateUI();
                for (const target of targets) {
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        dfOnlineBroadcastVisual({
                            kind: "fury",
                            ownerP: ownerIdx,
                            fieldIdx: target.i,
                            fieldPatches: [{
                                targetP: ownerIdx,
                                targetI: target.i,
                                fury: true,
                                furyStacks: target.furyStacks ?? 1,
                            }],
                        });
                        dfOnlineCommitChampStatus(ownerIdx, target.i, { broadcast: false });
                    }
                    const el = getChampionDom(ownerIdx, target.i);
                    if (el) {
                        el.classList.add("fury-flash");
                        setTimeout(() => el.classList.remove("fury-flash"), 900);
                    }
                    if (window.DfSpriteVfx?.playFuryBurst) {
                        await window.DfSpriteVfx.playFuryBurst(ownerIdx, target.i);
                    }
                }
                updateUI();
            }

            async function castAuraAntiMagia(casterP, casterFieldIdx) {
                const ch = state.players[casterP]?.field[casterFieldIdx];
                if (!ch) return;
                grantBarrierPermanent(ch);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "barrier_grant",
                        ownerP: casterP,
                        indices: [casterFieldIdx],
                        fieldPatches: [{
                            targetP: casterP,
                            targetI: casterFieldIdx,
                            barrier: true,
                            barrierPermanent: true,
                            barrierTurns: 0,
                        }],
                    });
                    dfOnlineCommitChampStatus(casterP, casterFieldIdx, { broadcast: false });
                }
                log(`⬡ ${ch.name} ganhou Barreira permanente (Aura Anti-Magia)!`);
                updateUI();
                await animateBarrierGrant(casterP, [casterFieldIdx]);
                updateUI();
                checkWin();
            }

            async function castAuraDeFogo(casterP, casterFieldIdx) {
                const indices = [];
                const names = [];
                state.players[casterP].field.forEach((ch, i) => {
                    if (!ch || (ch.fireAura && ch.fireAuraTurns > 0)) return;
                    grantFireAura(ch, 3);
                    indices.push(i);
                    names.push(ch.name);
                });
                if (!names.length) {
                    log(`${state.players[casterP]?.field[casterFieldIdx]?.name || "Campeão"}: Aura de Fogo — nenhum aliado disponível (sem aura duplicada).`);
                    return;
                }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({ kind: "fire_aura", ownerP: casterP, indices });
                }
                log(`🔥 Aura de Fogo em ${names.join(" e ")} (3 rodadas)!`);
                floatText("🔥 AURA DE FOGO — 3 rodadas", "warn center", 1800);
                updateUI();
                if (indices.length) await animateAuraDeFogoGrant(casterP, indices);
                updateUI();
                checkWin();
            }

            async function animateAuraDeFogoGrant(ownerP, indices) {
                for (const i of indices) {
                    const el = getChampionDom(ownerP, i);
                    if (!el) continue;
                    el.classList.add("shielded-aura");
                    const r = el.getBoundingClientRect();
                    const burst = document.createElement("div");
                    burst.style.cssText =
                        `position:${dfVfxPos()};left:${r.left + r.width / 2}px;top:${r.top + r.height / 2}px;` +
                        `transform:translate(-50%,-50%);font-size:2.2rem;z-index:9110;pointer-events:none;` +
                        `filter:drop-shadow(0 0 12px #ff6020);opacity:0;transition:opacity 180ms ease, transform 320ms ease;`;
                    burst.textContent = "🔥";
                    dfVfxMount(burst);
                    requestAnimationFrame(() => {
                        burst.style.opacity = "1";
                        burst.style.transform = "translate(-50%,-50%) scale(1.35)";
                    });
                    setTimeout(() => burst.remove(), 420);
                }
                try { window.sfx && window.sfx("fireball"); } catch (e) {}
                await wait(650);
            }

            /**
             * Incendiar: labareda acerta o Campeão em cheio e o deixa
             * pegando fogo — só depois o status Em Chamas aparece nele.
             */
            async function animateIncendiarGrant(targetP, targetI, opts = {}) {
                let el = getChampionDom(targetP, targetI);
                if (!el) {
                    for (let n = 0; n < 16 && !el; n++) {
                        await wait(50);
                        el = getChampionDom(targetP, targetI);
                    }
                }
                try { window.sfx && window.sfx("fireball"); } catch (e) {}
                let flamePlayed = false;
                if (el && window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playIncendiarFlameScene === "function") {
                    const r = el.getBoundingClientRect();
                    if (r.width > 4 && r.height > 4) {
                        const cx = r.left + r.width / 2;
                        const cy = r.top + r.height / 2;
                        const src = opts.casterP != null && opts.casterField >= 0
                            ? getChampionDom(opts.casterP, opts.casterField)?.getBoundingClientRect?.()
                            : null;
                        try {
                            const sceneDone = window.DfPixiVfx.playIncendiarFlameScene({
                                cx, cy, w: r.width, h: r.height,
                                fromX: src && src.width > 4 ? src.left + src.width / 2 : undefined,
                                fromY: src && src.width > 4 ? src.top + src.height / 2 : undefined,
                                cinematic: true,
                            });
                            const raced = await Promise.race([
                                sceneDone.then((ok) => (ok ? "ok" : "fail")),
                                wait(3600).then(() => "timeout"),
                            ]);
                            if (raced === "ok") {
                                flamePlayed = true;
                            } else if (raced === "timeout") {
                                // Cena travada: aborta Pixi pra não acumular partículas.
                                try { window.DfPixiVfx?.forceClearStage?.(); } catch (eClr) { /* */ }
                            }
                        } catch (e) { /* fallback DOM */ }
                    }
                }
                if (el && flamePlayed) {
                    el.classList.add("em-chamas-flash");
                    setTimeout(() => el.classList.remove("em-chamas-flash"), 700);
                }
                if (el && !flamePlayed) {
                    el.classList.add("em-chamas-flash");
                    const r = el.getBoundingClientRect();
                    const burst = document.createElement("div");
                    burst.className = "df-em-chamas-burst";
                    burst.style.cssText =
                        `position:${dfVfxPos()};left:${r.left + r.width / 2}px;top:${r.top + r.height / 2}px;` +
                        `transform:translate(-50%,-50%);font-size:2rem;z-index:9110;pointer-events:none;` +
                        `filter:drop-shadow(0 0 14px #ff4010);opacity:0;`;
                    burst.textContent = "🔥";
                    dfVfxMount(burst);
                    requestAnimationFrame(() => {
                        burst.style.transition = "opacity 160ms ease, transform 380ms ease";
                        burst.style.opacity = "1";
                        burst.style.transform = "translate(-50%,-55%) scale(1.4)";
                    });
                    setTimeout(() => burst.remove(), 480);
                    setTimeout(() => el.classList.remove("em-chamas-flash"), 700);
                }
                // Só o fallback DOM precisa do respiro extra: a cena Pixi já
                // segura o tempo da labareda antes de o status aparecer.
                await wait(flamePlayed ? 120 : (FX.mobile ? 520 : 700));
            }

            /** Tick pós-manutenção: Em Chamas (−1 Poder) com animação breve. */
            async function applyEmChamasAfterMaintenance(pIdx, opts = {}) {
                const animate = opts.animate !== false && !window.__DF_SIM_MODE;
                // Snap antes do tick — quem pode morrer (Poder ≤1) precisa de VFX de destruição.
                const preDeathSnaps = new Map();
                if (animate) {
                    (state.players[pIdx]?.field || []).forEach((c, i) => {
                        if (!c?.burning || (c.burningTurns ?? 0) <= 0) return;
                        if ((c.currentPower ?? 0) > 1) return;
                        const snap = dfCaptureFieldCardSnap(pIdx, i);
                        if (snap) preDeathSnaps.set(c.uid ?? `${c.name}#${i}`, snap);
                    });
                }
                const result = DfRules.applyEmChamasTicks(state, pIdx);
                if (!result?.ticks?.length) return result;
                for (const t of result.ticks) {
                    log(`🔥 ${t.name} Em Chamas: −1 Poder (${t.before} → ${t.after}).`);
                    if (animate) {
                        const el = getChampionDom(pIdx, t.i);
                        if (el && t.after > 0) {
                            el.classList.add("em-chamas-tick");
                            const r = el.getBoundingClientRect();
                            // Fogo curto sobre o Campeão a cada −1 Poder.
                            let gpuFlame = null;
                            if (window.DfVfxEngine?.wantsGpuPresentation?.()
                                && typeof window.DfPixiVfx?.playIncendiarFlameScene === "function") {
                                gpuFlame = window.DfPixiVfx.playIncendiarFlameScene({
                                    cx: r.left + r.width / 2,
                                    cy: r.top + r.height / 2,
                                    w: r.width, h: r.height,
                                    short: true, cinematic: true,
                                }).catch(() => false);
                            }
                            let flame = null;
                            if (!gpuFlame) {
                                flame = document.createElement("div");
                                flame.className = "df-em-chamas-tick-fx";
                                flame.style.cssText =
                                    `position:${dfVfxPos()};left:${r.left + r.width / 2}px;top:${r.top + r.height * 0.35}px;` +
                                    `transform:translate(-50%,-50%);z-index:9120;pointer-events:none;font-size:1.6rem;` +
                                    `filter:drop-shadow(0 0 10px #ff6020);`;
                                flame.textContent = "🔥";
                                dfVfxMount(flame);
                            }
                            const dmg = document.createElement("div");
                            dmg.className = "df-em-chamas-dmg";
                            dmg.textContent = "−1";
                            dmg.style.cssText =
                                `position:${dfVfxPos()};left:${r.left + r.width / 2}px;top:${r.top + r.height * 0.2}px;` +
                                `transform:translate(-50%,0);z-index:9121;pointer-events:none;` +
                                `font-weight:800;font-size:1.35rem;color:#ffcc66;text-shadow:0 0 8px #ff4010;`;
                            dfVfxMount(dmg);
                            try { window.sfx && window.sfx("fireball"); } catch (e) {}
                            requestAnimationFrame(() => {
                                dmg.style.transition = "opacity 450ms ease, transform 450ms ease";
                                dmg.style.opacity = "0";
                                dmg.style.transform = "translate(-50%,-28px)";
                                if (!flame) return;
                                flame.style.transition = "opacity 400ms ease, transform 400ms ease";
                                flame.style.opacity = "0";
                                flame.style.transform = "translate(-50%,-80%) scale(1.3)";
                            });
                            if (gpuFlame) {
                                await Promise.race([gpuFlame, wait(1400)]);
                            } else {
                                await wait(FX.mobile ? 480 : 620);
                            }
                            flame?.remove();
                            dmg.remove();
                            el.classList.remove("em-chamas-tick");
                        } else if (t.after <= 0) {
                            await wait(180);
                        } else {
                            await wait(200);
                        }
                    }
                }
                for (const d of result.destroyed || []) {
                    log(`🔥 ${d.name} foi destruído pelas chamas${d.vpGain ? " (+1 PV)" : ""}.`);
                    if (animate) {
                        let snap = null;
                        for (const [, s] of preDeathSnaps) {
                            if (s.cardName === d.name || s.name === d.name) { snap = s; break; }
                        }
                        if (!snap && preDeathSnaps.size === 1) {
                            snap = preDeathSnaps.values().next().value;
                        }
                        if (snap) {
                            try {
                                await playChampionDestroyVisual(snap, null);
                            } catch (eDes) { /* */ }
                        }
                    }
                }
                if (result.ticks.length) updateUI();
                checkWin();
                return result;
            }

            async function castRaioDuplo(casterP, casterFieldIdx) {
                const picks = pickRandomEnemyChampions(casterP, 2);
                if (!picks.length) return;
                // Índice alto → baixo: remoções não deslocam os próximos alvos.
                const sorted = picks.slice().sort((a, b) => (a.p !== b.p ? b.p - a.p : b.i - a.i));
                // Snaps/centros ANTES do loop — 2º raio e estilhaço não dependem
                // do DOM após a 1ª destruição.
                const planned = sorted.map(({ p, i }) => {
                    const ch = state.players[p]?.field[i];
                    if (!ch) return null;
                    const el = getChampionDom(p, i);
                    const tr = el?.getBoundingClientRect?.();
                    return {
                        p,
                        i,
                        uid: ch.uid,
                        name: ch.name,
                        cx: tr ? tr.left + tr.width / 2 : null,
                        cy: tr ? tr.top + tr.height / 2 : null,
                        snap: typeof dfCaptureFieldCardSnap === "function"
                            ? dfCaptureFieldCardSnap(p, i)
                            : null,
                    };
                }).filter(Boolean);
                try { window.sfx && window.sfx("lightning"); } catch (e) {}
                const names = [];
                const hits = [];
                for (let hi = 0; hi < planned.length; hi++) {
                    const plan = planned[hi];
                    const field = state.players[plan.p]?.field || [];
                    let liveI = plan.uid != null
                        ? field.findIndex((c) => c && c.uid === plan.uid)
                        : plan.i;
                    if (liveI < 0) liveI = plan.i;
                    const ch = state.players[plan.p]?.field[liveI];
                    if (!ch) continue;
                    // Cada alvo recebe sua própria cena de raio (nunca pular o 2º).
                    try {
                        await Promise.race([
                            animateRaioDuploStrike(casterP, plan.p, liveI, {
                                cx: plan.cx,
                                cy: plan.cy,
                            }),
                            wait(2800),
                        ]);
                    } catch (eStrike) {
                        console.warn("[DF raioDuplo] strike", eStrike);
                    }
                    if (await offerReactiveProtection(casterP, plan.p, ch, "Raio Duplo")) continue;
                    if (await consumeBarrierIfAny(plan.p, liveI, "Raio Duplo")) continue;
                    const before = ch.currentPower;
                    reduceChampionPower(ch, 1, plan.p, liveI);
                    names.push(ch.name);
                    hits.push({ p: plan.p, i: liveI, before, after: ch.currentPower });
                    if (ch.currentPower <= 0 && before > 0) {
                        const deathSnap = plan.snap || (typeof dfCaptureFieldCardSnap === "function"
                            ? dfCaptureFieldCardSnap(plan.p, liveI)
                            : null);
                        const deathEl = getChampionDom(plan.p, liveI);
                        // Shatter ANTES de splice — evita “sumir seco”.
                        if (deathSnap) {
                            try {
                                const shatterP = playChampionDestroyVisual(
                                    deathSnap,
                                    deathEl?.isConnected ? deathEl : null,
                                );
                                destroyChampion(plan.p, liveI, casterP, "raioDuplo", {
                                    noVpOnKill: true,
                                    skipOnlineSync: true,
                                    deferShatter: true,
                                    skipDomHide: true,
                                    forceDestroy: true,
                                });
                                await Promise.race([shatterP, wait(2200)]);
                            } catch (eKill) {
                                destroyChampion(plan.p, liveI, casterP, "raioDuplo", {
                                    noVpOnKill: true,
                                    skipOnlineSync: true,
                                    forceDestroy: true,
                                });
                            }
                        } else {
                            destroyChampion(plan.p, liveI, casterP, "raioDuplo", {
                                noVpOnKill: true,
                                skipOnlineSync: true,
                                forceDestroy: true,
                            });
                            if (window.__dfPendingDestroyVisual) {
                                await window.__dfPendingDestroyVisual;
                                window.__dfPendingDestroyVisual = null;
                            }
                        }
                        if (window.__dfPendingDestroyVisual) {
                            try { await window.__dfPendingDestroyVisual; } catch (eP) { /* */ }
                            window.__dfPendingDestroyVisual = null;
                        }
                    }
                    updateUI();
                    // Respiro entre 1º e 2º raio (legibilidade).
                    if (hi < planned.length - 1) await wait(180);
                }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote && hits.length) {
                    const fieldPatches = hits.map((h) => {
                        if (h.after != null && (h.after | 0) <= 0) {
                            return { targetP: h.p, targetI: h.i, removed: true };
                        }
                        return { targetP: h.p, targetI: h.i, currentPower: h.after | 0 };
                    });
                    dfOnlineBroadcastVisual({
                        kind: "raio_duplo",
                        casterP,
                        casterFieldIdx,
                        picks: hits.map((h) => ({ p: h.p, i: h.i })),
                        fieldPatches,
                    });
                }
                log(`⚡ Raio Duplo atingiu ${names.join(" e ")} (-1 Poder cada, sem PV por destruição).`);
                floatText("⚡ RAIO DUPLO!", "warn center", 1600);
                updateUI();
                checkWin();
                // Sem SYNC_STATE imediato — peer sincroniza via fieldPatches.
            }

            async function animateRaioDuploStrike(casterP, targetP, targetI, opts = {}) {
                await ensureVfxReady();
                const el = getChampionDom(targetP, targetI);
                let tcx = opts.cx;
                let tcy = opts.cy;
                if (tcx == null || tcy == null) {
                    if (!el) { await wait(280); return; }
                    const tr = el.getBoundingClientRect();
                    tcx = tr.left + tr.width / 2;
                    tcy = tr.top + tr.height / 2;
                }

                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playRaioDuploStrikeScene === "function";
                if (gpu) {
                    try { window.sfx && window.sfx("lightning"); } catch (e) { /* */ }
                    try {
                        await window.DfPixiVfx.playRaioDuploStrikeScene({
                            cx: tcx, cy: tcy, cinematic: true,
                        });
                    } catch (ePix) {
                        console.warn("[DF raioDuplo] Pixi strike", ePix);
                    }
                    if (el?.isConnected) {
                        el.classList.add("raio-duplo-hit");
                        el.style.filter = "brightness(1.75) drop-shadow(0 0 18px rgba(120,220,255,0.95))";
                        await wait(220);
                        el.style.filter = "";
                        el.classList.remove("raio-duplo-hit");
                    } else {
                        await wait(220);
                    }
                    return;
                }

                const anim = { alive: () => true };
                const strikeFn = window.DfSpriteVfx?.spawnLightningStrike;
                if (strikeFn) {
                    await strikeFn(tcx, tcy, anim, {
                        fromY: Math.max(6, tcy - window.innerHeight * 0.38),
                        bold: false,
                        compact: true,
                        jitter: Math.random(),
                        flashColor: "rgba(200,235,255,0.65)",
                    });
                } else {
                    await wait(320);
                }
                if (el?.isConnected) {
                    el.classList.add("raio-duplo-hit");
                    el.style.filter = "brightness(1.9) drop-shadow(0 0 20px rgba(120,220,255,1))";
                }
                const ring = document.createElement("div");
                ring.className = "combat-impact-ring";
                dfVfxSetPoint(ring, tcx, tcy);
                spawnParticles(tcx, tcy, 10);
                await wait(380);
                if (el?.isConnected) {
                    el.style.filter = "";
                    el.classList.remove("raio-duplo-hit");
                }
                ring.remove();
            }

            async function playFumacaToxicaVisual(casterP, casterFieldIdx, picks) {
                await ensureVfxReady();
                // GPU cartoon (Pixi+GSAP): nuvens tóxicas verdes + caveiras nos alvos.
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playToxicSmokeScene === "function";
                if (gpu) {
                    const targets = (picks || []).map(({ p, i }) => {
                        const el = getChampionDom(p, i);
                        if (!el) return null;
                        const r = el.getBoundingClientRect();
                        return { cx: r.left + r.width / 2, cy: r.top + r.height / 2 };
                    }).filter(Boolean);
                    if (targets.length) {
                        try { window.sfx && window.sfx("poison"); } catch (e) { /* */ }
                        const ran = await window.DfPixiVfx.playToxicSmokeScene({ targets, cinematic: true });
                        if (ran) { try { window.DfPixiVfx?.sweepOrphanScenes?.(); } catch (e) { /* */ } return; }
                    }
                }
                if (!window.DfSpriteVfx) return;
                await DfSpriteVfx.playToxicSmoke({ casterP, casterFieldIdx, picks });
            }

            async function castFumacaToxica(casterP, casterFieldIdx) {
                const picks = pickRandomEnemyChampions(casterP, 2, { avoidPower1: true });
                if (!picks.length) {
                    log(`Fumaça Tóxica: nenhum Campeão adversário em campo.`);
                    return;
                }
                const casterName = state.players[casterP]?.name || "Jogador";
                try { window.sfx && window.sfx("poison"); } catch (e) {}
                const names = [];
                // Manual §6: Barreira = imunidade a Vulnerável.
                const immune = [];
                for (const { p, i } of picks) {
                    const ch = state.players[p]?.field[i];
                    if (!ch) continue;
                    if (ch.barrier || ch.barrierPermanent) {
                        immune.push({ p, i, name: ch.name });
                        continue;
                    }
                    ch.vulnerable = true;
                    names.push(ch.name);
                }
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    const immuneKeys = new Set(immune.map((im) => `${im.p}:${im.i}`));
                    const fieldPatches = picks
                        .filter((pk) => !immuneKeys.has(`${pk.p}:${pk.i}`))
                        .map((pk) => ({
                            targetP: pk.p,
                            targetI: pk.i,
                            vulnerable: true,
                        }));
                    dfOnlineBroadcastVisual({
                        kind: "fumaca_toxica", casterP, casterFieldIdx, picks, immune, fieldPatches,
                    });
                }
                await playFumacaToxicaVisual(casterP, casterFieldIdx, picks);
                for (const { p, i } of picks) {
                    const el = getChampionDom(p, i);
                    if (el) {
                        el.classList.add("poison-flash");
                        setTimeout(() => el.classList.remove("poison-flash"), 1300);
                    }
                }
                if (names.length) {
                    log(`☣️ ${casterName}: Fumaça Tóxica — ${names.join(" e ")} ficaram Vulneráveis!`);
                }
                await dfAnnounceBarrierVulnerableImmunity(immune);
                updateUI();
                checkWin();
                // Sem SYNC_STATE — fieldPatches sincronizam Vulnerável.
            }

            async function animateGuardiao(casterP, picks) {
                if (!picks?.length) return;
                const cleanup = [];
                const banner = document.createElement("div");
                banner.className = "guardian-banner";
                banner.textContent = "🛡️ GUARDIÃO";
                dfVfxMount(banner);
                cleanup.push(banner);
                requestAnimationFrame(() => banner.classList.add("visible"));

                for (const idx of picks) {
                    const el = getChampionDom(casterP, idx);
                    if (!el) continue;
                    const rect = el.getBoundingClientRect();
                    const cx = rect.left + rect.width / 2;
                    const cy = rect.top + rect.height / 2;
                    el.classList.add("guardian-protected");
                    const ring = document.createElement("div");
                    ring.className = "guardian-shield-ring";
                    dfVfxPlaceBox(ring, cx - 52, cy - 52, 104, 104);
                    cleanup.push(ring);
                    const dome = document.createElement("div");
                    dome.className = "guardian-shield-dome";
                    dfVfxPlaceBox(dome, cx - 46, cy - 46, 92, 92);
                    cleanup.push(dome);
                    if (!FX.liteVfx) {
                        DfAnim.spawnBurst(4, "guardian-spark", (p, i) => {
                            p.textContent = ["🛡️", "✨", "💠"][i % 3];
                            p.style.left = cx + "px";
                            p.style.top = cy + "px";
                            p.style.setProperty("--px", ((Math.random() - 0.5) * 90) + "px");
                            p.style.setProperty("--py", ((Math.random() - 0.5) * 70 - 20) + "px");
                        }, 900, () => {
                            const d = document.createElement("div");
                            d.className = "guardian-spark";
                            return d;
                        });
                    }
                }

                await wait(FX.liteVfx ? 750 : 1200);
                banner.classList.remove("visible");
                await wait(120);
                cleanup.forEach((el) => el.remove());
                picks.forEach((idx) => getChampionDom(casterP, idx)?.classList.remove("guardian-protected"));
            }

            async function castGuardiao(casterP, casterFieldIdx) {
                const picks = [];
                const names = [];
                state.players[casterP].field.forEach((c, i) => {
                    if (i === casterFieldIdx || !c || c.shielded) return;
                    c.shielded = true;
                    c.shieldedTurns = 1;
                    picks.push(i);
                    names.push(c.name);
                });
                if (!picks.length) {
                    log(`Guardião: nenhum aliado disponível para proteger.`);
                    return;
                }
                try { window.sfx && window.sfx("shield"); } catch (e) {}
                log(`🛡️ Guardião protegeu ${names.join(" e ")} por 1 rodada!`);
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    const fieldPatches = picks.map((i) => ({
                        targetP: casterP,
                        targetI: i,
                        shielded: true,
                        shieldedTurns: 1,
                    }));
                    dfOnlineBroadcastVisual({
                        kind: "guardian",
                        casterP,
                        picks: picks.map((i) => ({ p: casterP, i })),
                        fieldPatches,
                    });
                }
                await animateGuardiao(casterP, picks);
                updateUI();
                // Sem SYNC_STATE — fieldPatches sincronizam Escudo.
            }



            async function playUrsificacaoVisual(allyP, allyI) {
                let tr = dfChampionAnchorRect(allyP, allyI);
                if (!tr || tr.width < 4) {
                    const el = getChampionDom(allyP, allyI);
                    const r = el?.getBoundingClientRect?.();
                    if (r && r.width > 4) {
                        tr = { left: r.left, top: r.top, width: r.width, height: r.height };
                    } else {
                        tr = {
                            left: (window.innerWidth || 800) * 0.5 - 40,
                            top: (window.innerHeight || 600) * 0.45 - 40,
                            width: 80,
                            height: 80,
                        };
                    }
                }
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                const puff = document.createElement("div");
                puff.className = "df-ursificacao-puff";
                puff.textContent = "🐻";
                puff.style.cssText =
                    `transform:translate(-50%,-50%) scale(0.4);font-size:96px;z-index:9999;` +
                    `pointer-events:none;text-shadow:0 0 24px #c87a2f;` +
                    `transition:transform 420ms ease-out, opacity 420ms ease-out;opacity:0;`;
                dfVfxPlaceCenter(puff, cx, cy);
                requestAnimationFrame(() => {
                    puff.style.transform = "translate(-50%,-50%) scale(1.4)";
                    puff.style.opacity = "1";
                });
                try { window.sfx && window.sfx("transform_pet"); } catch (e) {}
                await wait(380);
                spawnParticles(cx, cy, 14);
                puff.style.opacity = "0";
                puff.style.transform = "translate(-50%,-50%) scale(2.2)";
                await wait(280);
                puff.remove();
            }

            async function castUrsificacao(casterP, casterFieldIdx, allyP, allyI) {
                const target = state.players[allyP]?.field[allyI];
                if (!target || allyP !== casterP) return;
                const banjoDef = cardDefs.find(d => d.name === "BANJO");
                if (!banjoDef) return;
                const origName = target.name;
                const replacedPower = (typeof target.currentPower === "number")
                    ? target.currentPower
                    : (target.basePower || target.power || 0);
                const newPower = replacedPower + 2;
                const pvp = window.__DF_ONLINE && !dfOnlineApplyingRemote;
                // MP: broadcast ANTES do await local — peer vê o 🐻 em paralelo.
                if (pvp) {
                    dfOnlineBroadcastVisual({
                        kind: "ursificacao",
                        allyP,
                        allyI,
                        fieldPatches: [{
                            targetP: allyP,
                            targetI: allyI,
                            name: "BANJO",
                            power: newPower,
                            basePower: 0,
                            currentPower: newPower,
                            abilityType: banjoDef.abilityType ?? null,
                            abilityName: banjoDef.abilityName ?? null,
                            abilityDesc: banjoDef.abilityDesc ?? null,
                            onEnter: null,
                            onDestroy: null,
                            talentEffect: null,
                            summonRitual: null,
                            constantEffect: null,
                            isToken: true,
                            hidden: true,
                        }],
                    });
                }
                try {
                    await Promise.race([
                        playUrsificacaoVisual(allyP, allyI),
                        wait(1600),
                    ]);
                } catch (eVis) { /* */ }
                target.name = banjoDef.name;
                // power = newPower (não 0) preserva o Poder caso o Banjo
                // volte à mão (Amedrontar); basePower=0 força o overlay da
                // joia a exibir o Poder real.
                target.power = newPower;
                target.basePower = 0;
                target.currentPower = newPower;
                target.abilityType = banjoDef.abilityType;
                target.abilityName = banjoDef.abilityName;
                target.abilityDesc = banjoDef.abilityDesc;
                target.onEnter = null;
                target.onDestroy = null;
                target.talentEffect = null;
                target.summonRitual = undefined;
                target.constantEffect = null;
                target.isToken = true;
                target.hidden = true;
                clearChampionFieldStatuses(target);
                if (pvp) {
                    try {
                        await Promise.race([
                            dfOnlineCommitTransformToken(allyP, allyI, target),
                            wait(4500),
                        ]);
                    } catch (eCommit) {
                        console.warn("[DF online] ursificacao commit", eCommit);
                    }
                }
                log(`🐻 ${origName} foi Ursificado — virou BANJO (Poder ${newPower})!`);
                gamePhase = "normal";
                targetData = {};
                try {
                    document.querySelectorAll(".phase-blocker").forEach((el) => el.remove());
                    window.DfPresentationBus?.forceReset?.();
                } catch (eClr) { /* */ }
                updateUI();
                checkWin();
            }

            let _spriteVfxHooksReady = false;
            function ensureSpriteVfxHooks() {
                if (!window.DfSpriteVfx) return;
                const pageDir = location.href.replace(/[#?].*$/, "").replace(/[^/]*$/, "");
                const vfxBase = pageDir + "vfx/";
                if (!_spriteVfxHooksReady) {
                    DfSpriteVfx.configure({
                        getChampionDom,
                        championVisualRect,
                        quadrantForPlayer: dfQuadrantForPlayer,
                        humanSeat: dfHumanSeat,
                        matchAlive: dfMatchAlive,
                        vfxBase,
                    });
                    _spriteVfxHooksReady = true;
                }
                void DfSpriteVfx.preloadAll?.();
                void DfSpriteVfx.preloadPoisonSlimePngs?.();
                DfSpriteVfx.wireUltimateDirector?.();
                window.__dfTriggerChampionShatter = triggerChampionShatter;
                window.__dfFlyFieldCardToDiscard = async (ownerP, fieldIdx, snap) => {
                    const el = getChampionDom(ownerP, fieldIdx);
                    await playChampionDestroyVisual(snap, el);
                };
            }

            async function playBolaDeFogoVisual(casterP, casterField, targetP, targetI, fromTalent = false, originOverride = null) {
                await ensureVfxReady();
                try {
                    await window.DfVfxEngine?.ensureCinematicReady?.({ waitFull: true, maxMs: 2500 });
                } catch (e) { /* */ }
                const uid = state.players[targetP]?.field[targetI]?.uid;
                let { el } = resolveChampionDom(targetP, targetI, uid);
                if (!el) {
                    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                    ({ el } = resolveChampionDom(targetP, targetI, uid));
                }
                if (!el) {
                    try { updateUI({ immediate: true }); } catch (e) { /* */ }
                    ({ el } = resolveChampionDom(targetP, targetI, uid));
                }
                if (!el) {
                    console.warn("[DF] playBolaDeFogoVisual: DOM do alvo ausente", targetP, targetI);
                    return;
                }
                const tr = el.getBoundingClientRect();
                if (!(tr.width > 2 && tr.height > 2)) {
                    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
                    ({ el } = resolveChampionDom(targetP, targetI, uid));
                    if (!el) {
                        console.warn("[DF] playBolaDeFogoVisual: DOM do alvo sem rect", targetP, targetI);
                        return;
                    }
                }
                const tr2 = el.getBoundingClientRect();
                const toX = tr2.left + tr2.width / 2;
                const toY = tr2.top + tr2.height / 2;
                let fromX = toX - 120;
                let fromY = toY - 80;
                if (originOverride && typeof originOverride.x === "number") {
                    fromX = originOverride.x;
                    fromY = originOverride.y;
                } else if (casterField != null && casterField >= 0) {
                    const cr = championVisualRect(casterP, casterField);
                    if (cr?.width > 4) {
                        fromX = cr.left + cr.width / 2;
                        fromY = cr.top + cr.height * 0.35;
                    }
                } else if (fromTalent) {
                    const handOrigin = dfCaptureTalentCardOrigin(casterP);
                    if (handOrigin) {
                        fromX = handOrigin.x;
                        fromY = handOrigin.y;
                    }
                }
                let played = false;
                if (window.DfSpriteVfx?.playFireball) {
                    try {
                        const spriteOk = await window.DfSpriteVfx.playFireball({
                            casterP,
                            casterField,
                            targetP,
                            targetI,
                            fromTalent,
                            originOverride: originOverride || { x: fromX, y: fromY },
                            fromX,
                            fromY,
                            toX,
                            toY,
                        });
                        played = spriteOk === true;
                    } catch (e) {
                        console.warn("[DF] playFireball sprite falhou", e);
                        played = false;
                    }
                }
                if (played) return;
                const pixi = window.DfPixiVfx;
                const sceneBusy = !!(pixi?.isAnySceneActive?.() || pixi?.isCombatSceneActive?.());
                if (!sceneBusy && pixi?.playFireballScene) {
                    try {
                        const ok = await pixi.playFireballScene({
                            fromX,
                            fromY,
                            toX,
                            toY,
                            fromTalent,
                            handOrigin: fromTalent || !!originOverride,
                            cinematic: true,
                            onImpact: () => {
                                try { window.DfSpriteVfx?.tremorQuadrant?.(targetP); } catch (e) { /* */ }
                            },
                        });
                        if (ok) return;
                    } catch (ePixi) {
                        console.warn("[DF] playFireballScene falhou", ePixi);
                    }
                }
                // DOM obrigatório se Pixi ocupado/abortou.
                if (window.DfSpriteVfx?.flyProjectile) {
                    const charge = document.createElement("div");
                    charge.className = "df-fireball-charge";
                    try {
                        window.DfSpriteVfx.vfxPlace?.(charge, fromX, fromY);
                        await wait(FX.mobile ? 160 : 220);
                    } finally {
                        charge.remove();
                    }
                    await window.DfSpriteVfx.flyProjectile(
                        "fire_proj", fromX, fromY, toX, toY,
                        { travelMs: FX.mobile ? 440 : 520 },
                    );
                    try {
                        window.DfSpriteVfx.domBigBoom?.(toX, toY, 980);
                        window.DfSpriteVfx.screenFlash?.(toX, toY, "rgba(255,160,60,0.78)", 0.68, 380);
                        window.DfSpriteVfx.tremorQuadrant?.(targetP);
                    } catch (eDom) { /* */ }
                }
            }

            function dfCaptureTalentCardOrigin(ownerP) {
                const spotlight = window.__dfTalentSpotlightEl?.();
                if (spotlight) {
                    const r = spotlight.getBoundingClientRect();
                    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
                }
                const q = document.getElementById(`quadrant-${dfQuadrantForPlayer(ownerP)}`);
                const handCards = q?.querySelectorAll(".quadrant-hand .ccard, .quadrant-hand .hcard, .quadrant-hand .hand-card");
                if (handCards?.length) {
                    const mid = handCards[Math.floor(handCards.length / 2)];
                    const r = mid.getBoundingClientRect();
                    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
                }
                const handEl = q?.querySelector(".quadrant-hand .hcard, .quadrant-hand .ccard");
                if (handEl) {
                    const r = handEl.getBoundingClientRect();
                    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
                }
                return null;
            }

            async function castBolaDeFogo(casterP, casterField, targetP, targetI, fromTalent = false, originOverride = null) {
                let target = state.players[targetP]?.field[targetI];
                if (!target) {
                    floatText("Alvo inválido.", "warn center", 1600);
                    console.warn("[DF] castBolaDeFogo: alvo ausente", targetP, targetI);
                    return;
                }
                let { el: targetEl, fieldIdx: liveI } = resolveChampionDom(targetP, targetI, target.uid);
                if (!targetEl) {
                    updateUI({ immediate: true });
                    ({ el: targetEl, fieldIdx: liveI } = resolveChampionDom(targetP, targetI, target.uid));
                }
                if (!targetEl) {
                    floatText("Não foi possível mirar o campeão — tente de novo.", "warn center", 2000);
                    console.warn("[DF] castBolaDeFogo: DOM ausente", targetP, targetI);
                    return;
                }
                targetI = liveI;
                target = state.players[targetP]?.field[targetI] || target;
                if (!dfMatchAlive()) return;
                if (await offerReactiveProtection(casterP, targetP, target, "Bola de Fogo")) {
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) dfOnlineSendNow({ type: "SYNC_STATE" });
                    updateUI();
                    return;
                }
                if (await consumeBarrierIfAny(targetP, targetI, "Bola de Fogo")) {
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) dfOnlineSendNow({ type: "SYNC_STATE" });
                    updateUI();
                    return;
                }
                const targetUid = target.uid;
                const semHonra = dfHasNoHonor(target);
                dfDismissTargetingPhase();

                const prePow = target.currentPower ?? target.power ?? 0;
                const nextPowApprox = target.vulnerable ? 0 : Math.max(0, prePow - 1);
                const bolaAnim = {
                    kind: "bola_de_fogo",
                    casterP,
                    casterField,
                    targetP,
                    targetI,
                    fromTalent: !!fromTalent,
                    originOverride,
                    // Talento: mesma fila board que talent_discard (evita origem sumir no peer).
                    parallelGroup: fromTalent ? "board" : undefined,
                    powerAfter: nextPowApprox,
                    fieldPatches: nextPowApprox <= 0
                        ? [{ targetP, targetI, removed: true }]
                        : [{ targetP, targetI, currentPower: nextPowApprox }],
                };
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual(bolaAnim);
                }
                await playBolaDeFogoVisual(casterP, casterField, targetP, targetI, fromTalent, originOverride);

                // MP: commit autoritativo — SYNC_STATE cosmético NÃO grava kill no servidor.
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    if (!dfOnlineNetReady()) {
                        dfOnlineActionFailToast?.("ability", "NOT_CONNECTED");
                        try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                        dfRestoreFieldPresentation();
                        return;
                    }
                    const ack = await dfOnlineSendActionAwait({
                        type: "FIELD_COMMIT",
                        mutations: [{
                            op: "reducePower",
                            targetP,
                            targetI,
                            amount: 1,
                            destroyIfZero: true,
                            awardVpTo: casterP,
                            noVpOnKill: !!semHonra,
                            reason: "bolaDeFogo",
                        }],
                    }, { noSnap: true });
                    if (!ack || ack.ok === false) {
                        dfOnlineActionFailToast?.("ability", ack?.error);
                        try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                        dfRestoreFieldPresentation();
                        return;
                    }
                    const destroyed = (ack.events || []).some((e) => e?.type === "DESTROY");
                    // Captura snap ANTES do reconcile (campo ainda tem a carta).
                    let deathSnap = null;
                    let deathEl = null;
                    if (destroyed) {
                        try {
                            deathSnap = dfCaptureFieldCardSnap(targetP, targetI);
                            deathEl = getChampionDom(targetP, targetI);
                        } catch (eSnap) { /* */ }
                    }
                    if (ack.authoritativeState?.players?.length) {
                        dfOnlineReconcileSnapshot(
                            { state: ack.authoritativeState, full: true },
                            { skipPhase: true },
                        );
                    }
                    if (destroyed && deathSnap) {
                        window.__dfPendingDestroyVisual = dfInstallPhase3().runDestruction(async () => {
                            await playChampionDestroyVisual(deathSnap, deathEl?.isConnected ? deathEl : null);
                        });
                    }
                    updateUI();
                    if (destroyed) {
                        if (window.__dfPendingDestroyVisual) {
                            await window.__dfPendingDestroyVisual;
                            window.__dfPendingDestroyVisual = null;
                        } else {
                            await wait(680);
                        }
                        if (semHonra) triggerNoHonorBurst();
                    }
                    checkWin();
                    dfRestoreFieldPresentation();
                    return;
                }

                const liveIdx = state.players[targetP].field.findIndex((c) => c && c.uid === targetUid);
                if (liveIdx < 0) return;
                const liveTarget = state.players[targetP].field[liveIdx];
                reduceChampionPower(liveTarget, 1, targetP, liveIdx);
                if (liveTarget.currentPower <= 0) {
                    destroyChampion(targetP, liveIdx, casterP, "bolaDeFogo", {
                        skipOnlineSync: true,
                        noVpOnKill: true,
                        suppressFloat: true,
                    });
                    if (window.__dfPendingDestroyVisual) {
                        await window.__dfPendingDestroyVisual;
                        window.__dfPendingDestroyVisual = null;
                    } else {
                    await wait(680);
                    }
                    if (semHonra) {
                        triggerNoHonorBurst();
                    } else if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        state.players[casterP].vp += 1;
                    }
                }
                updateUI();
                checkWin();
                dfRestoreFieldPresentation();
            }

            function championVisualRect(pIdx, fIdx) {
                const el = getChampionDom(pIdx, fIdx);
                if (el) return el.getBoundingClientRect();
                const qIdx = dfQuadrantForPlayer(pIdx);
                const field = document.querySelector(`#quadrant-${qIdx} .quadrant-field`);
                const cw = 48;
                const ch = 68;
                if (field) {
                    const cards = field.querySelectorAll(".ccard");
                    if (cards.length && fIdx >= cards.length) {
                        const last = cards[cards.length - 1].getBoundingClientRect();
                        const gap = Math.max(6, last.width * 0.12);
                        return {
                            left: last.right + gap,
                            top: last.top,
                            width: cw,
                            height: ch,
                        };
                    }
                    if (cards.length && fIdx < cards.length) {
                        return cards[fIdx].getBoundingClientRect();
                    }
                    const fr = field.getBoundingClientRect();
                    return {
                        left: fr.left + fr.width * 0.5 - cw / 2,
                        top: fr.top + fr.height * 0.42,
                        width: cw,
                        height: ch,
                    };
                }
                const q = document.getElementById(`quadrant-${qIdx}`);
                if (q) {
                    const r = q.getBoundingClientRect();
                    return {
                        left: r.left + r.width * 0.42,
                        top: r.top + r.height * 0.38,
                        width: cw,
                        height: ch,
                    };
                }
                return { left: window.innerWidth / 2, top: window.innerHeight / 2, width: 20, height: 20 };
            }

            async function playAssassinarVisual(casterP, casterField, targetP, targetI, ctx = {}) {
                await ensureVfxReady();
                const uid = ctx.preField?.[targetP]?.[targetI]?.uid;
                const snap = (uid && ctx.preDomSnaps?.get(uid))
                    || dfCaptureFieldCardSnap(targetP, targetI);
                const tr = snap
                    ? { left: snap.left, top: snap.top, width: snap.width, height: snap.height }
                    : championVisualRect(targetP, targetI);
                if (!tr || tr.width < 4) {
                    await playStandardDestroyVisual(targetP, targetI, ctx);
                    return;
                }
                const tcx = snap?.cx ?? (tr.left + tr.width / 2);
                const tcy = snap?.cy ?? (tr.top + tr.height / 2);
                let fromX = tcx - 100;
                let fromY = tcy - 70;
                if (casterField != null && casterField >= 0) {
                    const cr = championVisualRect(casterP, casterField);
                    if (cr?.width > 4) {
                        fromX = cr.left + cr.width / 2;
                        fromY = cr.top + cr.height * 0.35;
                    }
                } else {
                    const q = document.getElementById(`quadrant-${dfQuadrantForPlayer(casterP)}`);
                    const qr = q?.getBoundingClientRect?.();
                    if (qr) {
                        fromX = qr.left + qr.width / 2;
                        fromY = qr.top + qr.height * 0.28;
                    }
                }
                let destroyPromise = null;
                let impactCalled = false;
                const runDestroy = () => {
                    if (impactCalled) return destroyPromise;
                    impactCalled = true;
                    if (typeof ctx.onImpactState === "function") {
                        try { ctx.onImpactState(); } catch (e) { /* */ }
                    }
                    destroyPromise = playStandardDestroyVisual(targetP, targetI, ctx);
                    return destroyPromise;
                };
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playAssassinScene === "function";
                if (gpu) {
                    let ok = false;
                    try {
                        ok = await Promise.race([
                            window.DfPixiVfx.playAssassinScene({
                                cx: tcx, cy: tcy, fromX, fromY, cinematic: true,
                                onImpact: () => { runDestroy(); },
                            }),
                            wait(FX.mobile ? 2900 : 3500).then(() => false),
                        ]);
                    } catch (e) { ok = false; }
                    if (ok) {
                        if (!impactCalled) runDestroy();
                        if (destroyPromise) await destroyPromise;
                        return;
                    }
                }
                await runDestroy();
            }

            async function castAssassinar(casterP, casterField, targetP, targetI) {
                const preTarget = state.players[targetP]?.field[targetI];
                if (!preTarget || preTarget.currentPower !== 1) {
                    log("Assassinar só pode ser usado em Campeões de Poder 1.");
                    floatText("Assassinar: alvo precisa ter Poder 1", "info center", 1600);
                    return;
                }
                if (!getChampionDom(targetP, targetI) && !document.getElementById(`quadrant-${targetP}`)) return;
                dfDismissTargetingPhase();
                // Manual: Proteção só bloqueia ataques; Assassinar é destruição.
                // Proteção Divina / Barreira não cancelam Assassinar.
                const assTarget = state.players[targetP].field[targetI];
                if (!assTarget || assTarget.currentPower !== 1) {
                    log("Assassinar só funciona em Campeões de Poder 1.");
                    floatText("Assassinar: alvo precisa ter Poder 1", "info center", 1600);
                    updateUI();
                    return;
                }
                log("Assassinar!");
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    dfOnlineBroadcastVisual({
                        kind: "assassinar",
                        casterP,
                        casterField,
                        targetP,
                        targetI,
                        fieldPatches: [{ targetP, targetI, removed: true }],
                    });
                }
                const preField = captureFieldForPostDestroy();
                const preDomSnaps = dfCaptureAllFieldDomSnaps();
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    await playAssassinarVisual(casterP, casterField, targetP, targetI, { preField, preDomSnaps });
                    if (!dfOnlineNetReady()) {
                        dfOnlineActionFailToast?.("ability", "NOT_CONNECTED");
                        try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                        updateUI();
                        return;
                    }
                    const ack = await dfOnlineSendActionAwait({
                        type: "FIELD_COMMIT",
                        mutations: [{
                            op: "destroy",
                            targetP,
                            targetI,
                            reason: "assassinar",
                            awardVpTo: casterP,
                            forceAward: true,
                            requirePower: 1,
                        }],
                    }, { noSnap: true });
                    if (!ack || ack.ok === false) {
                        dfOnlineActionFailToast?.("ability", ack?.error);
                        try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                        updateUI();
                        return;
                    }
                    if (ack.authoritativeState?.players?.length) {
                        dfOnlineReconcileSnapshot(
                            { state: ack.authoritativeState, full: true },
                            { skipPhase: true },
                        );
                    }
                    updateUI();
                    checkWin();
                    return;
                }
                let stateDestroyed = false;
                const applyStateDestroy = () => {
                    if (stateDestroyed) return;
                    stateDestroyed = true;
                    destroyChampion(targetP, targetI, casterP, "assassinar", {
                        ignoreNoHonor: true,
                        forceAward: true,
                        skipOnlineSync: true,
                        deferShatter: true,
                        skipDomHide: true,
                    });
                };
                await playAssassinarVisual(casterP, casterField, targetP, targetI, {
                    preField,
                    preDomSnaps,
                    onImpactState: applyStateDestroy,
                });
                if (!stateDestroyed) applyStateDestroy();
                updateUI();
                checkWin(); }

            function destroyChampion(ownerIdx, fieldIdx, killerIdx, reason, opts = {}) {
                const owner = state.players[ownerIdx];
                const target = owner.field[fieldIdx];
                if (!target) return;
                dfNormalizeChampPower(target);
                const powerKillReasons = new Set([
                    "cometStarfall", "bolaDeFogo", "fireAura", "vinganca", "raioDuplo",
                    "explosao", "ultimate", "fireAndIce",
                ]);
                if (target.currentPower > 0 && !opts.forceDestroy && powerKillReasons.has(reason)) {
                    return;
                }
                const syncDestroyAnim = (window.__DF_ONLINE && !dfOnlineApplyingRemote && !opts.skipOnlineSync)
                    ? { kind: "destroy", ownerIdx, fieldIdx }
                    : null;
                // ÁUDIO: SFX universal de "shatter" (vozes foram removidas).
                try { window.sfx && window.sfx("champion_destroy"); } catch (e) {}
                // Captura posição/HTML ANTES de remover do estado — updateUI
                // destrói o DOM e o shatter/voo ao descarte ficava em (0,0).
                const deathSnap = dfCaptureFieldCardSnap(ownerIdx, fieldIdx);
                const dyingEl = getChampionDom(ownerIdx, fieldIdx);
                if (dyingEl && !opts.skipDomHide) {
                    dyingEl.classList.remove(
                        "ult-target-flash", "ult-frozen-cast", "ult-fortify-power",
                        "ult-shield-protect", "ult-war-impact", "ult-might-infinite",
                        "fear-card-shudder", "impact", "land-impact",
                        "drag-attack-target", "valid-target", "target", "hl",
                        "vt-red", "vt-green", "vt-blue", "vt-orange", "vt-purple",
                        "df-target-levitating",
                    );
                    dyingEl.classList.add("combat-animating");
                    dyingEl.style.setProperty("visibility", "hidden", "important");
                    dyingEl.style.setProperty("opacity", "0", "important");
                    dyingEl.style.setProperty("pointer-events", "none", "important");
                }
                window.dfPurgeTargetingVisuals?.();
                if (syncDestroyAnim) dfOnlineBroadcastVisual(syncDestroyAnim);
                owner.field.splice(fieldIdx, 1);
                pushDiscard(ownerIdx, target);
                dfInvalidateQuadrantFp(ownerIdx);
                // "Sem Honra": em vez de estilhaçar, o campeão FOGE por um
                // portal (Pixi+GSAP). Decisão tomada antes da animação.
                const effOnDestroy = dfResolveCopiedOnDestroy(target);
                const fleeNoHonor = dfHasNoHonor(target) && !opts.ignoreNoHonor;
                if (!opts.deferShatter && deathSnap) {
                    window.__dfPendingDestroyVisual = dfInstallPhase3().runDestruction(async () => {
                        try {
                            if (fleeNoHonor) {
                                await playNoHonorEscapeVisual(deathSnap, dyingEl);
                            } else {
                        await playChampionDestroyVisual(deathSnap, dyingEl);
                            }
                        } finally {
                            dyingEl?.remove?.();
                            try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
                        }
                    });
                } else if (!opts.skipDomHide) {
                    dyingEl?.remove?.();
                }
                // PALADINO — guarda referência ao último Campeão deste dono que
                // foi destruído. A ult "O Retorno do Herói" reanima essa carta
                // direto do descarte com Silêncio (sem habilidade).
                owner.lastDestroyedSummon = { name: target.name, discardRef: target };
                // Histórico ordenado pra nova ult do Paladino (escolha entre
                // os 2 últimos Campeões no descarte). Só Campeões entram.
                if (target.category === "champion") {
                    if (!owner.destroyedChampions) owner.destroyedChampions = [];
                    owner.destroyedChampions.push(target);
                }
                const semHonra = dfHasNoHonor(target) && !opts.ignoreNoHonor;
                const suppressFloat = !!opts.suppressFloat;
                let zeroShown = false;
                // MP: PV só via autoridade (FIELD_COMMIT / ATTACK_RESOLVE) — evita flash→wipe.
                const skipLocalVp = window.__DF_ONLINE && !dfOnlineApplyingRemote
                    && !opts.forceLocalVp && !opts.fromAuthority;
                if (killerIdx !== undefined && killerIdx !== null) {
                    if (opts.noVpOnKill || skipLocalVp) {
                        /* Raio Duplo / Bola de Fogo / MP: destruição sem PV local imediato */
                    } else if (opts.forceAward) {
                        state.players[killerIdx].vp += 1;
                    } else if (semHonra) {
                        if (!suppressFloat) {
                            triggerNoHonorBurst();
                        }
                        zeroShown = true;
                    } else {
                        state.players[killerIdx].vp += Math.max(1, opts.vpAmount || 1);
                    }
                }
                if (!suppressFloat && dfHasNoHonor(target) && !zeroShown) {
                    triggerNoHonorBurst();
                }
                // VINGANÇA (FÚRIA VERMELHA / FIONA) — onDestroy constante.
                // Um Campeão ALEATÓRIO do adversário (qualquer adversário do
                // dono do destruído) perde 1 ponto de Poder. Se chegar a 0,
                // é destruído (sem PV pra ninguém — é punição reativa).
                // Pulado sob Silêncio (Paladino). Disparado via setTimeout
                // pra não bloquear o destroy original — efeito assíncrono.
                if (effOnDestroy === "vinganca" && !target.silenced) {
                    // MP: autoridade (applyOnDestroyBurst / ATTACK_RESOLVE) aplica o −1;
                    // VFX vem dos events ON_DESTROY_BURST — evita double-apply + peer sem sync.
                    if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        queuePostDestroyEffect(() => triggerVinganca(ownerIdx));
                    }
                }
                // LEGADO — animação de +1 Poder só após a destruição terminar.
                // MP: quem sorteia e aplica o +1 é a autoridade (applyOnDestroyBurst);
                // aplicar aqui também dava buff fantasma, apagado no reconcile.
                if (effOnDestroy === "legado" && !target.silenced) {
                    if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        queuePostDestroyEffect(() => triggerLegado(ownerIdx));
                    }
                }
                if (effOnDestroy === "explosaoGelo" && !target.silenced) {
                    if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        queuePostDestroyEffect(() => triggerOnDestroyBurst(ownerIdx, target, reason));
                    }
                }
                if (effOnDestroy === "explosaoVenenosa" && !target.silenced
                    && DfRules.isCombatOrPowerReductionDestroy(reason)) {
                    if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        queuePostDestroyEffect(() => triggerOnDestroyBurst(ownerIdx, target, reason));
                    }
                }
                if (effOnDestroy === "furiaLegado" && !target.silenced) {
                    if (!(window.__DF_ONLINE && !dfOnlineApplyingRemote)) {
                        queuePostDestroyEffect(() => triggerOnDestroyBurst(ownerIdx, target, reason));
                    }
                }
                // AURA DE FOGO — efeito em sequência, não junto com Legado/outros.
                if (target.fireAura && target.fireAuraTurns > 0 && !target.silenced) {
                    const auraUid = target.uid;
                    if (!_dfFireAuraAppliedUids.has(auraUid)) {
                        _dfFireAuraAppliedUids.add(auraUid);
                        queuePostDestroyEffect(() => triggerFireAuraDeath(ownerIdx));
                    }
                }
            }

            async function triggerOnDestroyBurst(ownerIdx, source, reason) {
                const burst = DfRules.applyOnDestroyBurst(state, ownerIdx, source, reason, Math.random);
                if (!burst?.ability) return;
                if (burst.ability === "furiaLegado") {
                    if (!burst.applied.length) {
                        log(`🔥 Retaliação de ${source.name}: nenhum outro aliado em campo.`);
                    } else {
                        log(`🔥 Retaliação de ${source.name}: ${burst.applied.map((t) => t.name).join(" e ")} receberam Fúria.`);
                        await playFuryGrantTargets(ownerIdx, burst.applied);
                    }
                } else if (burst.ability === "explosaoGelo") {
                    if (!burst.applied.length) {
                        log(`❄️ Explosão de Gelo de ${source.name}: nenhum adversário em campo.`);
                    } else {
                        log(`❄️ Explosão de Gelo de ${source.name}: ${burst.applied.map((t) => t.name).join(" e ")} ficaram Congelados por 2 rodadas.`);
                        updateUI();
                        for (const target of burst.applied) await animateIce(target.p, target.i);
                    }
                } else {
                    if (!burst.targets.length) {
                        log(`☠️ Explosão Venenosa de ${source.name}: nenhum adversário em campo.`);
                    } else if (!burst.applied.length) {
                        log(`☠️ Explosão Venenosa de ${source.name}: os alvos sorteados já estavam Envenenados.`);
                    } else {
                        log(`☠️ Explosão Venenosa de ${source.name}: ${burst.applied.map((t) => t.name).join(" e ")} ficaram Envenenados.`);
                        updateUI();
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            dfOnlineBroadcastVisual({
                                kind: "explosao_venenosa_burst",
                                applied: burst.applied,
                                source: source.name,
                                ownerIdx,
                            });
                        }
                        await animateExplosaoVenenosaTargets(burst.applied);
                    }
                }
                updateUI();
                checkWin();
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) dfOnlineBroadcastState();
            }

            async function triggerFireAuraDeath(ownerIdx, opts = {}) {
                const visualOnly = !!opts.visualOnly;
                const enemies = [];
                for (let p = 0; p < state.playersCount; p++) {
                    if (p === ownerIdx) continue;
                    state.players[p].field.forEach((c, i) => { if (c) enemies.push({ p, i }); });
                }
                if (!enemies.length) {
                    log("🔥 Aura de Fogo: adversário sem Campeões em campo.");
                    return;
                }
                const pick = enemies[Math.floor(Math.random() * enemies.length)];
                const victim = state.players[pick.p]?.field[pick.i];
                if (!victim) return;
                const victimUid = victim.uid;
                try { window.sfx && window.sfx("fireball"); } catch (e) {}
                await animateFireAuraDeathStrike(pick.p, pick.i);
                if (visualOnly) {
                    updateUI();
                    return;
                }
                const liveIdx = state.players[pick.p].field.findIndex(c => c && c.uid === victimUid);
                if (liveIdx < 0) { updateUI(); return; }
                reduceChampionPower(state.players[pick.p].field[liveIdx], 1, pick.p, liveIdx);
                const liveVictim = state.players[pick.p].field[liveIdx];
                log(`🔥 Aura de Fogo: ${liveVictim.name} perdeu 1 Poder.`);
                if (liveVictim.currentPower <= 0) {
                    destroyChampion(pick.p, liveIdx, null, "fireAura", { noVpOnKill: true, ignoreNoHonor: true });
                }
                updateUI();
                checkWin();
            }

            async function animateFireAuraDeathStrike(targetP, targetI) {
                await ensureVfxReady();
                const el = getChampionDom(targetP, targetI);
                const r = el?.getBoundingClientRect();
                if (!r?.width) return;
                const toX = r.left + r.width / 2;
                const toY = r.top + r.height / 2;
                const fromY = Math.max(24, toY - Math.min(window.innerHeight * 0.45, 280));
                const fromX = toX + (Math.random() > 0.5 ? -1 : 1) * 90;
                const pixi = window.DfPixiVfx;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    || window.DfVfxEngine?.wantsCinematic?.();
                if (gpu && pixi?.playFireballScene) {
                    await Promise.race([
                        pixi.playFireballScene({
                            fromX, fromY, toX, toY,
                            cinematic: true,
                            onImpact: () => {
                                try { window.sfx?.("explosao"); } catch (e) { /* */ }
                            },
                        }),
                        wait(FX.mobile ? 1100 : 1800),
                    ]);
                    return;
                }
                if (window.DfSpriteVfx?.playFireball) {
                    await DfSpriteVfx.playFireball({
                        casterP: targetP,
                        casterField: -1,
                        targetP,
                        targetI,
                        originOverride: { x: fromX, y: fromY },
                    });
                }
            }

            // VINGANÇA — escolhe Campeão aleatório de qualquer adversário do
            // `ownerIdx` (o dono do destruído) e reduz currentPower em 1.
            // Se chegar a 0, destrói. Não aplica Proteção Divina (efeito
            // reativo de outra carta não dispara reação encadeada).
            async function triggerVinganca(ownerIdx, opts = {}) {
                const visualOnly = !!opts.visualOnly;
                const enemies = [];
                for (let p = 0; p < state.playersCount; p++) {
                    if (p === ownerIdx) continue;
                    state.players[p].field.forEach((c, i) => { enemies.push({ p, i }); });
                }
                if (!enemies.length) {
                    log("🩸 VINGANÇA: adversário sem Campeões em campo.");
                    return;
                }
                const pick = enemies[Math.floor(Math.random() * enemies.length)];
                const victim = state.players[pick.p].field[pick.i];
                if (!victim) return;
                const victimUid = victim.uid;
                // Re-resolve por uid antes do VFX — o slot pode ter mudado no delay pós-destroy.
                let liveIdx = state.players[pick.p].field.findIndex(c => c && c.uid === victimUid);
                if (liveIdx < 0) { updateUI(); return; }
                try { window.sfx && window.sfx("vinganca"); } catch (e) {}
                await animateVinganca(pick.p, liveIdx, { uid: victimUid });
                if (visualOnly) {
                    updateUI();
                    return;
                }
                liveIdx = state.players[pick.p].field.findIndex(c => c && c.uid === victimUid);
                if (liveIdx < 0) { updateUI(); return; }
                const liveVictim = state.players[pick.p].field[liveIdx];
                reduceChampionPower(liveVictim, 1, pick.p, liveIdx);
                log(`🩸 VINGANÇA: ${liveVictim.name} perdeu 1 Poder.`);
                if (liveVictim.currentPower <= 0) {
                    destroyChampion(pick.p, liveIdx, null, "vinganca", { ignoreNoHonor: true });
                }
                updateUI();
                checkWin();
            }

            // LEGADO — escolhe aliado aleatório do `ownerIdx` (mesmo dono
            // do destruído) e dá +1 Poder. Pula Resistentes (não ganham
            // Poder). Se não houver aliado válido, fizzle silencioso.
            async function triggerLegado(ownerIdx, opts = {}) {
                const visualOnly = !!opts.visualOnly;
                const ownerIsAI = !!(state.players[ownerIdx] && state.players[ownerIdx].isAI);
                const allyUids = [];
                state.players[ownerIdx].field.forEach((c) => {
                    if (!allyTargetCanGainPower(c)) return;
                    if (ownerIsAI && !aiAllyBuffAllowed(ownerIdx, c)) return;
                    allyUids.push(c.uid);
                });
                if (!allyUids.length) {
                    log("👑 LEGADO: nenhum aliado pode receber +Poder.");
                    return;
                }
                const pickUid = allyUids[Math.floor(Math.random() * allyUids.length)];
                let liveIdx = state.players[ownerIdx].field.findIndex(c => c && c.uid === pickUid);
                if (liveIdx < 0) return;
                const beneficiary = state.players[ownerIdx].field[liveIdx];
                if (!beneficiary) return;
                const beneficiaryUid = beneficiary.uid;
                const pick = { p: ownerIdx, i: liveIdx };
                try { window.sfx && window.sfx("legado"); } catch (e) {}
                await animateLegado(pick.p, pick.i);
                if (window.__DF_ONLINE && !window.__dfOnlineApplyingRemote && !visualOnly) {
                    try {
                        window.__dfOnline?.dfOnlineBroadcastVisual?.({
                            kind: "legado",
                            ownerP: ownerIdx,
                            targetP: pick.p,
                            targetI: pick.i,
                        });
                    } catch (e) { /* */ }
                }
                if (visualOnly) {
                    log(`👑 LEGADO: ${beneficiary.name} herdou o legado!`);
                    updateUI();
                    return;
                }
                liveIdx = state.players[pick.p].field.findIndex(c => c && c.uid === beneficiaryUid);
                if (liveIdx < 0) { updateUI(); return; }
                const liveBeneficiary = state.players[pick.p].field[liveIdx];
                if (!allyTargetCanGainPower(liveBeneficiary)) { updateUI(); return; }
                liveBeneficiary.currentPower += 1;
                log(`👑 LEGADO: ${liveBeneficiary.name} ganhou +1 Poder.`);
                updateUI();
            }

            // Quando um campeão com "Sem Honra" morre, mostra uma explosão
            // dramática de fumaça preta + caveira atravessando a tela com
            // o aviso "0 PV". O atacante "sente" que perdeu a recompensa.
            function triggerNoHonorBurst() {
                // Portal de fuga (Pixi+GSAP) já comunica Sem Honra — só tremor leve.
                const gameEl = document.getElementById("game") || document.body;
                gameEl.classList.add("screen-shake");
                setTimeout(() => gameEl.classList.remove("screen-shake"), 460);
            }

            function combatOutcome(a, d) { return DfRules.combatOutcome(a, d); }

            /** Encontro no centro — cartas se encostam ao longo do vetor de ataque (sem empilhar). */


            async function dfHideCombatFieldCard(el) {
                if (!el) return;
                el.classList.add("combat-src-hidden");
                el.style.visibility = "hidden";
                el.style.opacity = "0";
                el.style.pointerEvents = "none";
            }

            /** Estilhaço ou portal Sem Honra quando um clone de combate é destruído. */
            async function dfCombatKillBurst(flyEl, snap) {
                if (!flyEl?.isConnected && !snap) return;
                const rect = flyEl?.getBoundingClientRect?.();
                if ((!rect || rect.width < 4) && !(snap?.width > 4)) return;
                const cx = snap?.cx ?? (rect.left + rect.width / 2);
                const cy = snap?.cy ?? (rect.top + rect.height / 2);
                const snapData = snap || {
                    cx, cy,
                    width: rect?.width,
                    height: rect?.height,
                    left: rect?.left,
                    top: rect?.top,
                };
                const noHonor = dfHasNoHonor(snapData);
                if (noHonor) await playNoHonorEscapeVisual(snapData, flyEl);
                else await playChampionDestroyVisual(snapData, flyEl);
                flyEl?.remove?.();
            }

            /** Fallback: estilhaço ou Sem Honra se Pixi não exibiu durante o combate. */
            async function dfEnsureCombatKillVisuals(out, combatSnap, attOwner, attIdx, defOwner, defIdx) {
                const shown = window.__dfCombatKillVisual || {};
                const deathVisual = async (snap, el) => {
                    if (!snap) return;
                    const noHonor = dfHasNoHonor(snap);
                    if (noHonor) await playNoHonorEscapeVisual(snap, el);
                    else await playChampionDestroyVisual(snap, el);
                };
                if (out.killD && combatSnap?.def && !shown.def) {
                    await deathVisual(combatSnap.def, getChampionDom(defOwner, defIdx));
                }
                if (out.killA && combatSnap?.att && !shown.att) {
                    await deathVisual(combatSnap.att, getChampionDom(attOwner, attIdx));
                }
                window.__dfCombatKillVisual = null;
            }

            /** Recuo elástico pós-choque — cartas se separam antes da destruição. */
            async function dfCombatRecoil(attFly, defFly, attEndX, attEndY, defEndX, defEndY, ax, ay, dx, dy) {
                if (!attFly || !defFly) return;
                const recoilMs = FX.mobile ? 160 : 220;
                const attBackX = attEndX + (ax - attEndX) * 0.22;
                const attBackY = attEndY + (ay - attEndY) * 0.22;
                const defBackX = defEndX + (dx - defEndX) * 0.22;
                const defBackY = defEndY + (dy - defEndY) * 0.22;
                await Promise.all([
                    animateCombatFly(attFly, attEndX, attEndY, attBackX, attBackY, recoilMs, combatEaseOutExpo, { arc: 6, scalePeak: 1.02 }),
                    animateCombatFly(defFly, defEndX, defEndY, defBackX, defBackY, recoilMs, combatEaseOutExpo, { arc: 6, scalePeak: 1.02 }),
                ]);
            }

            /** Destruição no lugar (Pixi+GSAP) — sem voo ao descarte. */
            async function playChampionDestroyVisual(snap, sourceEl) {
                if (!snap && !sourceEl) return;
                let rect = sourceEl?.getBoundingClientRect?.();
                if ((!rect || rect.width < 4) && snap?.width > 4) {
                    rect = {
                        left: snap.left, top: snap.top,
                        width: snap.width, height: snap.height,
                    };
                }
                if (!rect || rect.width < 4) {
                    if (sourceEl) await dfHideCombatFieldCard(sourceEl);
                    try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
                    return;
                }
                const cx = snap?.cx ?? (rect.left + rect.width / 2);
                const cy = snap?.cy ?? (rect.top + rect.height / 2);
                const snapData = snap || {
                    cx, cy,
                    width: rect.width,
                    height: rect.height,
                    left: rect.left,
                    top: rect.top,
                };
                if (snap?.uid != null) {
                    const liveEl = document.querySelector(`.ccard[data-uid="${snap.uid}"]`);
                    if (liveEl && liveEl !== sourceEl) {
                        liveEl.classList.add("combat-animating");
                        liveEl.style.setProperty("visibility", "hidden", "important");
                        liveEl.style.setProperty("opacity", "0", "important");
                        liveEl.style.setProperty("pointer-events", "none", "important");
                    }
                }
                // Sem uid: NÃO esconder por fIdx — após splice o índice aponta outro campeão.
                if (sourceEl?.isConnected) {
                    sourceEl.classList.add("combat-animating");
                    await dfHideCombatFieldCard(sourceEl);
                }
                const srcEl = sourceEl?.isConnected ? sourceEl : null;
                let pixiSnap = snapData;
                try {
                    const canvasRect = window.DfLayout?.viewportRectToCanvas?.({
                        left: snapData.left, top: snapData.top,
                        width: snapData.width, height: snapData.height,
                    });
                    if (canvasRect && Math.abs(canvasRect.width) > 4 && Math.abs(canvasRect.height) > 4) {
                        pixiSnap = Object.assign({}, snapData, {
                            combatW: Math.abs(canvasRect.width),
                            combatH: Math.abs(canvasRect.height),
                        });
                    }
                } catch (e) { /* */ }
                const gpuDestroy = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playChampionCombatDestroy === "function";
                if (gpuDestroy) {
                    if (!window.DfPixiVfx?.isCombatSceneActive?.()
                        && !window.DfPixiVfx?.isMagicMissilesBarrageActive?.()) {
                        try { window.DfPixiVfx?.sweepOrphanScenes?.(); } catch (e) { /* */ }
                    }
                    const ok = await window.DfPixiVfx.playChampionCombatDestroy(pixiSnap, {
                        cx, cy, fx: FX,
                    });
                    if (ok) {
                        try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
                        return;
                    }
                }
                await triggerChampionShatter(srcEl, snapData);
                try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
            }

            /**
             * SEM HONRA — em vez de estilhaçar, abre um portal sombrio (Pixi+GSAP)
             * e o campeão FOGE por ele: um clone DOM da carta encolhe/gira e some
             * dentro do portal. Fallback DOM simples quando não há GPU.
             */
            async function playNoHonorEscapeVisual(snap, sourceEl) {
                try {
                    let rect = sourceEl?.getBoundingClientRect?.();
                    if ((!rect || rect.width < 4) && snap?.width > 4) {
                        rect = { left: snap.left, top: snap.top, width: snap.width, height: snap.height };
                    }
                    if (!rect || rect.width < 4) {
                        if (sourceEl) await dfHideCombatFieldCard(sourceEl);
                        return;
                    }
                    const cx = snap?.cx ?? (rect.left + rect.width / 2);
                    const cy = snap?.cy ?? (rect.top + rect.height / 2);
                    if (sourceEl?.isConnected) {
                        sourceEl.classList.add("combat-animating");
                        await dfHideCombatFieldCard(sourceEl);
                    }
                    // Clone "fujão" — wrapper fixo (coords de viewport) com a
                    // carta dentro a 100%, igual ao padrão do estilhaço.
                    let host = null;
                    if (snap?.outerHTML || sourceEl) {
                        host = document.createElement("div");
                        if (snap?.outerHTML) host.innerHTML = snap.outerHTML;
                        else host.appendChild(sourceEl.cloneNode(true));
                        const inner = host.firstElementChild;
                        if (inner) {
                            inner.classList.remove("combat-animating", "combat-src-hidden", "valid-target", "target", "hl", "df-target-levitating");
                            inner.style.width = "100%";
                            inner.style.height = "100%";
                            inner.style.margin = "0";
                            inner.style.visibility = "visible";
                            inner.style.opacity = "1";
                        }
                        host.dataset.dfNoHonorFlee = "1";
                        host.style.cssText =
                            "position:fixed;left:" + rect.left + "px;top:" + rect.top + "px;" +
                            "width:" + rect.width + "px;height:" + rect.height + "px;margin:0;" +
                            "z-index:99998;pointer-events:none;visibility:visible;opacity:1;" +
                            "overflow:visible;transform-origin:center center;transition:none;";
                        document.body.appendChild(host);
                        try { window.applyCardArtTree?.(host); } catch (e) { /* */ }
                    }
                    const fleeIntoPortal = () => new Promise((resolve) => {
                        if (!host) { resolve(); return; }
                        const startT = performance.now();
                        const dur = 640;
                        const sX = rect.left + rect.width / 2;
                        const sY = rect.top + rect.height / 2;
                        const tick = (now) => {
                            const raw = Math.min(1, (now - startT) / dur);
                            const e = raw < 0.5 ? 2 * raw * raw : 1 - Math.pow(-2 * raw + 2, 2) / 2;
                            const curX = sX + (cx - sX) * e;
                            const curY = sY + (cy - sY) * e;
                            const sc = Math.max(0.04, 1 - e * 0.94);
                            const rot = e * 540;
                            host.style.left = (curX - rect.width / 2) + "px";
                            host.style.top = (curY - rect.height / 2) + "px";
                            host.style.transform = "scale(" + sc + ") rotate(" + rot + "deg)";
                            host.style.opacity = raw < 0.66 ? "1" : String(Math.max(0, 1 - (raw - 0.66) / 0.34));
                            if (raw < 1) requestAnimationFrame(tick);
                            else resolve();
                        };
                        requestAnimationFrame(tick);
                    });
                    const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                        && typeof window.DfPixiVfx?.playPortalEscapeScene === "function";
                    if (gpu) {
                        const ran = await window.DfPixiVfx.playPortalEscapeScene({ cx, cy, cinematic: true, onOpen: fleeIntoPortal });
                        if (!ran) await fleeIntoPortal();
                    } else {
                        await fleeIntoPortal();
                    }
                    try { host?.remove?.(); } catch (e) { /* */ }
                } catch (e) {
                    if (sourceEl) { try { await dfHideCombatFieldCard(sourceEl); } catch (err) { /* */ } }
                }
            }

            /** @deprecated — campeão destruído não voa mais ao descarte; usa destruição no lugar. */
            async function flyCombatCardToDiscard(sourceEl, ownerP, snap, existingFly) {
                void ownerP;
                const probe = existingFly || sourceEl;
                let rect = probe?.getBoundingClientRect?.();
                if ((!rect || rect.width < 4) && snap?.width > 4) {
                    rect = {
                        left: snap.left, top: snap.top,
                        width: snap.width, height: snap.height,
                    };
                }
                if (!rect || rect.width < 4) {
                    if (sourceEl) await dfHideCombatFieldCard(sourceEl);
                    return;
                }
                await playChampionDestroyVisual(snap, probe || sourceEl);
                existingFly?.remove?.();
            }

            // COMBATE CINEMATOGRÁFICO v2 — rAF + arco + hit-stop + dual lunge





            /** Move elemento fixed via transform (GPU) ao longo de arco parabólico. */










            async function animateCombat(attOwner, attIdx, defOwner, defIdx, outcome, snap) {
                let attEl = getChampionDom(attOwner, attIdx);
                let defEl = getChampionDom(defOwner, defIdx);
                if (!attEl && !snap?.att) return;
                dfCombatPurgeGhosts();
                try {
                    return await _animateCombatBody(attEl, defEl, outcome, snap, attOwner, attIdx, defOwner, defIdx);
                } finally {
                    dfCombatPurgeFlyGhosts?.() ?? dfCombatPurgeGhosts();
                }
            }



            /** Combate por clones (todas as plataformas) — cartas reais ficam
               ocultas; só os .battle-fly se movem. Evita transform órfão que
               deixava campeões colados/duplicados após a luta no desktop. */
            async function _animateCombatCloneFly(attEl, defEl, outcome, snap, geo, attOwner, attIdx, defOwner, defIdx) {
                const { ax, ay, dx, dy, attEndX, attEndY, defEndX, defEndY, clashX, clashY, ux, uy, crush } = geo;
                const chargeMs = FX.mobile ? 320 : (FX.liteVfx ? 300 : 420);
                const holdMs = FX.mobile ? 180 : (FX.liteVfx ? 120 : 160);
                const returnMs = FX.mobile ? 240 : (FX.liteVfx ? 260 : 320);
                const chargeOpts = FX.mobile
                    ? { arc: 28, scalePeak: 1.12 }
                    : { arc: 40, scalePeak: 1.16 };
                const returnOpts = FX.mobile
                    ? { arc: 16, scalePeak: 1 }
                    : { arc: 22, scalePeak: 1.01 };

                const attSnap = dfCombatSnapFromEl(attEl, snap?.att);
                const defSnap = dfCombatSnapFromEl(defEl, snap?.def);
                if (!attSnap) return;

                const attElHide = getChampionDom(attOwner, attIdx) || attEl;
                const defElHide = getChampionDom(defOwner, defIdx) || defEl;

                const attClass = FX.mobile ? "attacker-fly" : "attacker-fly combat-trail";
                const attFly = dfCreateBattleFlyFromSnap(attSnap, attClass);
                const defFly = defSnap ? dfCreateBattleFlyFromSnap(defSnap, "defender-fly") : null;
                if (!attFly) return;

                attFly.style.transform = dfCombatFlyTransform(ax, ay);
                if (defFly) defFly.style.transform = dfCombatFlyTransform(dx, dy);
                dfHideCombatSources(attElHide, defElHide, { forceClone: true });
                if (!FX.mobile) await new Promise((r) => requestAnimationFrame(r));

                await Promise.all([
                    animateCombatFly(attFly, ax, ay, attEndX, attEndY, chargeMs, combatEaseInOutQuint, chargeOpts),
                    defFly
                        ? animateCombatFly(defFly, dx, dy, defEndX, defEndY, chargeMs, combatEaseInOutQuint, chargeOpts)
                        : Promise.resolve(),
                ]);

                let attHitX = attEndX;
                let attHitY = attEndY;
                let defHitX = defEndX;
                let defHitY = defEndY;

                if (defFly && ux != null && uy != null) {
                    const bumpMs = FX.mobile ? 70 : 90;
                    const bumpOpts = { arc: 0, scalePeak: 1.04 };
                    attHitX = attEndX;
                    attHitY = attEndY;
                    defHitX = defEndX;
                    defHitY = defEndY;
                    await Promise.all([
                        animateCombatFly(attFly, attEndX, attEndY, attHitX, attHitY, bumpMs, combatEaseOutExpo, bumpOpts),
                        animateCombatFly(defFly, defEndX, defEndY, defHitX, defHitY, bumpMs, combatEaseOutExpo, bumpOpts),
                    ]);
                }

                if (!FX.liteVfx) {
                    spawnCombatSpeedLines(ax, ay, clashX, clashY);
                    if (defFly) spawnCombatSpeedLines(dx, dy, clashX, clashY, "rgba(255,140,140,0.9)");
                }

                const vfx = spawnCombatImpact(clashX, clashY, outcome, FX.liteVfx);
                const gameEl = document.getElementById("game") || document.body;
                gameEl.classList.add("screen-shake");
                setTimeout(() => gameEl.classList.remove("screen-shake"), FX.mobile ? 320 : 420);
                await wait(holdMs);

                if (defFly) {
                    if (!outcome.killD && !outcome.killA) {
                        await dfCombatRecoil(attFly, defFly, attHitX, attHitY, defHitX, defHitY, ax, ay, dx, dy);
                    } else {
                        await wait(FX.mobile ? 70 : 110);
                    }
                }

                if (vfx.flash?.remove) vfx.flash.remove();
                if (vfx.hitstop?.remove) vfx.hitstop.remove();
                if (vfx.slash1) vfx.slash1.remove();
                if (vfx.slash2) vfx.slash2.remove();
                vfx.clashTxt?.remove();

                if (outcome.killD && defFly) {
                    await dfCombatKillBurst(defFly, defSnap);
                    (window.__dfCombatKillVisual ||= {}).def = true;
                } else if (defFly) {
                    await animateCombatFly(defFly, defHitX, defHitY, dx, dy, returnMs, combatEaseOutExpo, returnOpts);
                    defFly.remove();
                }

                if (outcome.killA) {
                    await dfCombatKillBurst(attFly, attSnap);
                    (window.__dfCombatKillVisual ||= {}).att = true;
                } else {
                    await animateCombatFly(attFly, attHitX, attHitY, ax, ay, returnMs, combatEaseOutExpo, returnOpts);
                    attFly.remove();
                }
                await wait(FX.mobile ? 8 : 20);
                dfCombatMobileDim(false);
            }

            /** Combate in-place — anima as cartas REAIS no campo (sem sumir). */
            async function _animateCombatInPlace(attEl, defEl, outcome, geo) {
                const { ax, ay, dx, dy, attEndX, attEndY, defEndX, defEndY, clashX, clashY, ux, uy } = geo;
                if (!attEl) return;
                const chargeMs = FX.mobile ? 320 : (FX.liteVfx ? 300 : 420);
                const holdMs = FX.mobile ? 180 : (FX.liteVfx ? 120 : 160);
                const returnMs = FX.mobile ? 240 : (FX.liteVfx ? 260 : 320);
                const chargeOpts = FX.mobile
                    ? { arc: 28, scalePeak: 1.12 }
                    : { arc: 40, scalePeak: 1.16 };
                const returnOpts = FX.mobile
                    ? { arc: 16, scalePeak: 1 }
                    : { arc: 22, scalePeak: 1.01 };

                const armField = (el, role) => {
                    if (!el) return null;
                    try { window.DfTargetLevitate?.stopOne?.(el); } catch (e) { /* */ }
                    el.classList.remove("drag-attack-target", "df-target-levitating", "field-drag-src", "field-dragging");
                    // .combat-src-hidden vence .combat-animating no CSS (3 classes
                    // contra 2) — sem removê-la o fallback anima carta invisível.
                    el.classList.remove("combat-src-hidden");
                    el.classList.add("combat-animating", role);
                    delete el.dataset.dfFieldLocked;
                    ["transform", "translate", "scale", "rotate", "will-change", "transform-origin", "transition",
                     "visibility", "opacity", "pointer-events"].forEach((p) => {
                        el.style.removeProperty(p);
                    });
                    el.style.zIndex = "9850";
                    const r = el.getBoundingClientRect();
                    return { ox: r.left + r.width / 2, oy: r.top + r.height / 2 };
                };
                const attO = armField(attEl, "attacker-combat");
                const defO = defEl ? armField(defEl, "defender-combat") : null;
                if (!attO) return;

                await Promise.all([
                    animateCombatFieldCard(
                        attEl, attO.ox, attO.oy, ax, ay, attEndX, attEndY,
                        chargeMs, combatEaseInOutQuint, chargeOpts,
                    ),
                    defEl && defO
                        ? animateCombatFieldCard(
                            defEl, defO.ox, defO.oy, dx, dy, defEndX, defEndY,
                            chargeMs, combatEaseInOutQuint, chargeOpts,
                        )
                        : Promise.resolve(),
                ]);

                let attHitX = attEndX;
                let attHitY = attEndY;
                let defHitX = defEndX;
                let defHitY = defEndY;

                if (defEl && defO && ux != null && uy != null) {
                    const bumpMs = FX.mobile ? 70 : 90;
                    const bumpOpts = { arc: 0, scalePeak: 1.04 };
                    await Promise.all([
                        animateCombatFieldCard(
                            attEl, attO.ox, attO.oy, attEndX, attEndY, attHitX, attHitY,
                            bumpMs, combatEaseOutExpo, bumpOpts,
                        ),
                        animateCombatFieldCard(
                            defEl, defO.ox, defO.oy, defEndX, defEndY, defHitX, defHitY,
                            bumpMs, combatEaseOutExpo, bumpOpts,
                        ),
                    ]);
                }

                if (!FX.liteVfx) {
                    spawnCombatSpeedLines(ax, ay, clashX, clashY);
                    if (defEl) spawnCombatSpeedLines(dx, dy, clashX, clashY, "rgba(255,140,140,0.9)");
                }
                const vfx = spawnCombatImpact(clashX, clashY, outcome, FX.liteVfx);
                const gameEl = document.getElementById("game") || document.body;
                gameEl.classList.add("screen-shake");
                setTimeout(() => gameEl.classList.remove("screen-shake"), FX.mobile ? 320 : 420);
                try { window.sfx?.("combat_clash"); } catch (e) { /* */ }
                await wait(holdMs);

                if (defEl && defO) {
                    if (!outcome.killD && !outcome.killA) {
                        const recoilMs = FX.mobile ? 160 : 220;
                        const recoilOpts = { arc: 6, scalePeak: 1.02 };
                        const attBackX = attHitX + (ax - attHitX) * 0.22;
                        const attBackY = attHitY + (ay - attHitY) * 0.22;
                        const defBackX = defHitX + (dx - defHitX) * 0.22;
                        const defBackY = defHitY + (dy - defHitY) * 0.22;
                        await Promise.all([
                            animateCombatFieldCard(
                                attEl, attO.ox, attO.oy, attHitX, attHitY, attBackX, attBackY,
                                recoilMs, combatEaseOutExpo, recoilOpts,
                            ),
                            animateCombatFieldCard(
                                defEl, defO.ox, defO.oy, defHitX, defHitY, defBackX, defBackY,
                                recoilMs, combatEaseOutExpo, recoilOpts,
                            ),
                        ]);
                    } else {
                        await wait(FX.mobile ? 70 : 110);
                    }
                }

                if (vfx.flash?.remove) vfx.flash.remove();
                if (vfx.hitstop?.remove) vfx.hitstop.remove();
                if (vfx.slash1) vfx.slash1.remove();
                if (vfx.slash2) vfx.slash2.remove();
                vfx.clashTxt?.remove();

                if (!outcome.killA) {
                    await animateCombatFieldCard(
                        attEl, attO.ox, attO.oy, attHitX, attHitY, ax, ay,
                        returnMs, combatEaseOutExpo, returnOpts,
                    );
                }
                if (defEl && defO && !outcome.killD) {
                    await animateCombatFieldCard(
                        defEl, defO.ox, defO.oy, defHitX, defHitY, dx, dy,
                        returnMs, combatEaseOutExpo, returnOpts,
                    );
                }
                await wait(FX.mobile ? 8 : 20);
                dfCombatMobileDim(false);
            }

            async function _animateCombatBody(attEl, defEl, outcome, snap, attOwner, attIdx, defOwner, defIdx) {
                if (!attEl && snap?.att) {
                    attEl = getChampionDom(snap.att.pIdx, snap.att.fIdx);
                }
                if (!defEl && snap?.def) {
                    defEl = getChampionDom(snap.def.pIdx, snap.def.fIdx);
                }
                const aRect = snap?.att
                    ? { left: snap.att.left, top: snap.att.top, width: snap.att.width, height: snap.att.height }
                    : (attEl ? attEl.getBoundingClientRect() : null);
                if (!aRect) return;
                const dRect = snap?.def
                    ? { left: snap.def.left, top: snap.def.top, width: snap.def.width, height: snap.def.height }
                    : (defEl ? defEl.getBoundingClientRect() : aRect);

                const ax = snap?.att?.cx ?? (aRect.left + aRect.width / 2);
                const ay = snap?.att?.cy ?? (aRect.top + aRect.height / 2);
                const dx = snap?.def?.cx ?? (dRect.left + dRect.width / 2);
                const dy = snap?.def?.cy ?? (dRect.top + dRect.height / 2);
                const attWvp = dfCombatViewportSize(attEl, aRect).w;
                const defWvp = dfCombatViewportSize(defEl, dRect).w;
                const geo = dfCombatMeetGeometry(ax, ay, dx, dy, attWvp, defWvp);

                const attElHide = getChampionDom(attOwner, attIdx) || attEl;
                const defElHide = getChampionDom(defOwner, defIdx) || defEl;
                let combatVisualDone = false;
                let hidePulse = null;
                try {

                const discardCenter = (p) => {
                    const el = getDiscardPileEl(p);
                    const r = el?.getBoundingClientRect?.();
                    return r ? { x: r.left + r.width / 2, y: r.top + r.height / 2 } : null;
                };
                const attSnap = snap?.att || dfCombatSnapFromEl(attEl, snap?.att);
                const defSnap = snap?.def || dfCombatSnapFromEl(defEl, snap?.def);

                // Pré-aquece faces compostas antes do Pixi esconder o DOM.
                try {
                    const warm = window.DfCardFace?.warmFace;
                    if (warm) {
                        const jobs = [];
                        if (attSnap?.cardName || attSnap?.name) {
                            jobs.push(warm({
                                name: attSnap.cardName || attSnap.name,
                                currentPower: attSnap.currentPower ?? attSnap.power,
                                power: attSnap.basePower ?? attSnap.power,
                            }, { power: attSnap.currentPower ?? attSnap.power }));
                        }
                        if (defSnap?.cardName || defSnap?.name) {
                            jobs.push(warm({
                                name: defSnap.cardName || defSnap.name,
                                currentPower: defSnap.currentPower ?? defSnap.power,
                                power: defSnap.basePower ?? defSnap.power,
                            }, { power: defSnap.currentPower ?? defSnap.power }));
                        }
                        if (jobs.length) {
                            await Promise.race([
                                Promise.all(jobs.map((j) => Promise.resolve(j).catch(() => null))),
                                wait(1400),
                            ]);
                        }
                    }
                } catch (e) { /* */ }

                // Pixi (quando GPU) → in-place nas cartas reais → clones DOM.
                // Nunca forçar só in-place: se travar, o timeout de 14s deixa
                // o combate sem animação (regressão 1.48.43).
                try { window.__dfPauseFieldLockMO?.(true); } catch (e) { /* */ }
                // Identidade dos combatentes: esconder por ÍNDICE fazia o pulso de
                // 80ms ocultar o campeão errado quando o campo reordenava no meio
                // da cena (campeões sumindo durante a animação de combate).
                const attUid = attSnap?.uid ?? state.players[attOwner]?.field?.[attIdx]?.uid ?? null;
                const defUid = defSnap?.uid ?? state.players[defOwner]?.field?.[defIdx]?.uid ?? null;
                const combatUids = new Set([attUid, defUid].filter((u) => u != null).map(String));
                const hideCombatSourcesNow = () => {
                    const hideSrc = (el) => {
                        if (!el?.isConnected) return;
                        // Só esconde quem é de fato um dos combatentes.
                        const uid = el.dataset?.uid;
                        if (combatUids.size && uid && !combatUids.has(String(uid))) return;
                        // NÃO usar combat-animating aqui — essa classe força
                        // visibility:visible e deixa o "clone" no slot (Pixi voa).
                        el.classList.remove("combat-animating", "attacker-combat", "defender-combat");
                        el.classList.add("combat-src-hidden");
                        el.style.setProperty("visibility", "hidden", "important");
                        el.style.setProperty("opacity", "0", "important");
                        el.style.setProperty("pointer-events", "none", "important");
                    };
                    hideSrc(attElHide);
                    hideSrc(defElHide);
                    // Re-aplica se updateUI recriou o DOM no meio da cena — por uid,
                    // nunca por slot (slot pode já pertencer a outro campeão).
                    combatUids.forEach((uid) => {
                        document.querySelectorAll(
                            `.quadrant-field .ccard[data-uid="${uid}"]`,
                        ).forEach(hideSrc);
                    });
                    if (!combatUids.size) {
                        hideSrc(getChampionDom(attOwner, attIdx));
                        hideSrc(getChampionDom(defOwner, defIdx));
                    }
                    window.__dfCombatSourcesHidden = true;
                };
                // Devolve os combatentes vivos ao campo. Chamado pelo Pixi ANTES de
                // destruir os sprites, para não existir 1 frame sem DOM e sem Pixi
                // (campeão "desaparecendo" no fim da animação). Idempotente: o
                // finally chama de novo sem efeito colateral.
                const restoreCombatSourcesNow = () => {
                    try { if (hidePulse) clearInterval(hidePulse); } catch (e) { /* */ }
                    hidePulse = null;
                    window.__dfCombatSourcesHidden = false;
                    const deadUids = new Set();
                    if (outcome.killA && attUid != null) deadUids.add(String(attUid));
                    if (outcome.killD && defUid != null) deadUids.add(String(defUid));
                    if (!outcome.killA) {
                        dfRestoreCombatFieldCard(getChampionDom(attOwner, attIdx) || attElHide);
                    }
                    if (!outcome.killD) {
                        dfRestoreCombatFieldCard(getChampionDom(defOwner, defIdx) || defElHide);
                    }
                    document.querySelectorAll(
                        ".quadrant-field .ccard.combat-src-hidden",
                    ).forEach((el) => {
                        const uid = el.dataset?.uid;
                        if (uid && deadUids.has(String(uid))) return;
                        dfRestoreCombatFieldCard(el);
                    });
                };
                // Reesconde só DEPOIS do 1º hide (Pixi já tem sprites) —
                // esconder cedo = campeões sumindo durante o warm.
                try {
                    hidePulse = setInterval(() => {
                        if (!window.__dfCombatSourcesHidden) return;
                        if (!window.__dfCombatActive && !window.DfPixiVfx?.isCombatSceneActive?.()) return;
                        try { hideCombatSourcesNow(); } catch (e) { /* */ }
                    }, 80);
                } catch (e) { /* */ }
                // Ocultar DOM via onHideSources após sprites Pixi (sem duplicata / sem blank).
                const pixiOk = await runCombatPixiScene({
                    attSnap,
                    defSnap,
                    geo,
                    outcome,
                    discardAtt: discardCenter(attOwner),
                    discardDef: discardCenter(defOwner),
                    onHideSources: hideCombatSourcesNow,
                    onShowSources: restoreCombatSourcesNow,
                    onImpact: () => {
                        try { window.sfx?.("combat_clash"); } catch (e) { /* */ }
                        const gameEl = document.getElementById("game") || document.body;
                        gameEl.classList.add("screen-shake");
                        setTimeout(
                            () => gameEl.classList.remove("screen-shake"),
                            FX.mobile ? 220 : 260,
                        );
                    },
                });
                try { if (hidePulse) clearInterval(hidePulse); } catch (e) { /* */ }
                hidePulse = null;
                if (pixiOk) {
                    combatVisualDone = true;
                    return;
                }
                // Pixi falhou (talvez após hide) — restaura DOM antes do fallback.
                // MP: só restaura se Pixi já limpou o stage (anti-duplicata).
                if (window.__DF_ONLINE || document.body.classList.contains("df-pvp-mode")) {
                    const tClear = Date.now();
                    while (window.DfPixiVfx?.isCombatSceneActive?.() && Date.now() - tClear < 450) {
                        await wait(40);
                    }
                    try { window.DfPixiVfx?.abortCombatScene?.(); } catch (eAb) { /* */ }
                }
                window.__dfCombatSourcesHidden = false;
                try {
                    dfRestoreCombatFieldCard?.(attElHide);
                    dfRestoreCombatFieldCard?.(defElHide);
                    dfRestoreCombatFieldCard?.(getChampionDom(attOwner, attIdx));
                    dfRestoreCombatFieldCard?.(getChampionDom(defOwner, defIdx));
                } catch (e) { /* */ }

                // updateUI pode ter recriado os .ccard durante a cena Pixi: animar
                // as refs antigas deixaria as cartas vivas escondidas no campo.
                const attElLive = getChampionDom(attOwner, attIdx) || attEl;
                const defElLive = getChampionDom(defOwner, defIdx) || defEl;
                if (attElLive) {
                    // In-place: esconde qualquer clone residual.
                    try {
                        document.querySelectorAll(".battle-fly").forEach((el) => el.remove());
                    } catch (eRm) { /* */ }
                    await _animateCombatInPlace(attElLive, defElLive, outcome, geo);
                    combatVisualDone = true;
                    return;
                }

                console.warn("[DF combat] Pixi/in-place falhou — fallback clones DOM .battle-fly");
                // Clones: fontes DEVEM ficar ocultas.
                try { hideCombatSourcesNow(); } catch (eH2) { /* */ }
                await _animateCombatCloneFly(attEl, defEl, outcome, snap, geo, attOwner, attIdx, defOwner, defIdx);
                combatVisualDone = true;
                } finally {
                    try { if (hidePulse) clearInterval(hidePulse); } catch (e) { /* */ }
                    hidePulse = null;
                    try { window.__dfPauseFieldLockMO?.(false); } catch (e) { /* */ }
                    window.__dfCombatSourcesHidden = false;
                    if (combatVisualDone) {
                        dfCombatVisualCleanup();
                        // Nenhum campeão vivo pode continuar invisível: quem sobrou
                        // com combat-src-hidden e não morreu volta a aparecer.
                        restoreCombatSourcesNow();
                    } else {
                        dfCombatForceCleanup({
                            attOwner, attIdx, defOwner, defIdx,
                            killA: outcome.killA, killD: outcome.killD,
                        });
                    }
                }
            }

            function applyCombatMechanics(attOwner, attIdx, defOwner, defIdx, attacker, out, opts = {}) {
                const tied = out.killA && out.killD;
                const attackerUid = attacker?.uid || null;
                if (out.killD) {
                    const defNow = state.players[defOwner].field[defIdx];
                    if (defNow) {
                        destroyChampion(defOwner, defIdx, attOwner, "combat", {
                            skipOnlineSync: true,
                            deferShatter: true,
                            vpAmount: DfRules.combatVictoryPointReward(attacker),
                        });
                    }
                }
                if (out.killA) {
                    let idx = state.players[attOwner].field.findIndex(c => c === attacker);
                    if (idx < 0 && attackerUid) {
                        idx = state.players[attOwner].field.findIndex(c => c?.uid === attackerUid);
                    }
                    if (idx < 0) {
                        const bySlot = state.players[attOwner].field[attIdx];
                        if (bySlot) idx = attIdx;
                    }
                    if (idx >= 0) {
                        const defender = state.players[defOwner]?.field?.[defIdx];
                        destroyChampion(attOwner, idx, tied ? null : defOwner, "combat", {
                            skipOnlineSync: true,
                            deferShatter: true,
                            vpAmount: DfRules.combatVictoryPointReward(defender),
                        });
                    }
                }
                if (out.killD && !out.killA && hasTiroDuplo(attacker) && !attacker.tiroDuploUsedThisTurn && !cannotReceiveInvestida(attacker)) {
                    attacker.tapped = false;
                    attacker.freeAttack = true;
                    attacker.tiroDuploUsedThisTurn = true;
                }
            }

            let _dfReactiveBlockWaiter = null;





            async function resolveCombat(attOwner, attIdx, defOwner, defIdx, opts = {}) {
                const attacker = state.players[attOwner].field[attIdx];
                const defender = state.players[defOwner].field[defIdx];
                if (!attacker || !defender) return { ok: false };
                dfEnsurePresentationUnblocked("combate");
                dfPurgeDesacelerarVfx();
                const onlineActor = window.__DF_ONLINE && !dfOnlineApplyingRemote && attOwner === dfLocalSeat();
                // MP: telegraph imediato (peer vê tell) enquanto a reação resolve — sem atraso de 5s na anim.
                if (onlineActor && !opts.skipReactive) {
                    dfOnlineBroadcastVisual({
                        kind: "combat_telegraph",
                        attOwner,
                        attIdx,
                        defOwner,
                        defIdx,
                    });
                }
                const blocked = opts.skipReactive
                    ? false
                    : await dfOnlineResolveReactiveBlock(attOwner, attIdx, defOwner, defIdx, attacker, defender);
                if (blocked) {
                    window.__dfCombatPending = null;
                    window.__dfCombatPreSnap = null;
                    dfCombatForceCleanup({ attOwner, attIdx, defOwner, defIdx });
                    attacker.tapped = true;
                    if (attacker.freeAttack) attacker.freeAttack = false;
                    updateUI();
                    if (onlineActor) {
                        // Feedback local (dedupe com ANSWER handler).
                        try {
                            await dfOnlinePlayReactivePeerFeedback("block", {
                                defenderPlayerId: defOwner,
                                defenderIdx: defIdx,
                                defOwner,
                                defIdx,
                            });
                        } catch (e) { /* */ }
                        try {
                            await dfOnlineSendActionAwait({
                                type: "ATTACK_RESOLVE",
                                attackerIdx: attIdx,
                                defenderPlayerId: defOwner,
                                defenderIdx: defIdx,
                                blocked: true,
                            }, { noSnap: true });
                        } catch (e2) { /* */ }
                    }
                    return { blocked: true };
                }
                const out = combatOutcome(attacker, defender);
                let combatSnap = window.__dfCombatPreSnap;
                window.__dfCombatPreSnap = null;
                if (!combatSnap?.att || !combatSnap?.def) {
                    combatSnap = {
                        att: dfCaptureFieldCardSnap(attOwner, attIdx),
                        def: dfCaptureFieldCardSnap(defOwner, defIdx),
                    };
                }
                dfRefreshCombatSnapPowers(combatSnap);

                dfArmCombatFieldPresentation(attOwner, attIdx, defOwner, defIdx);

                const combatVfxMs = window.__DF_SIM_MODE ? 6000
                    : (window.__DF_ONLINE ? 14000 : 9000);
                window.__dfCombatKillVisual = null;
                // MP: ATTACK_RESOLVE em paralelo com a cinemática (sem esperar ACK).
                let attackAckOk = !onlineActor;
                let pendingAttackAuth = null;
                let attackAckPromise = null;
                if (onlineActor) {
                    const fieldPatches = [];
                    if (out.killD) {
                        fieldPatches.push({ targetP: defOwner, targetI: defIdx, removed: true });
                    }
                    if (out.killA) {
                        fieldPatches.push({ targetP: attOwner, targetI: attIdx, removed: true });
                    } else {
                        fieldPatches.push({
                            targetP: attOwner,
                            targetI: attIdx,
                            tapped: true,
                            freeAttack: false,
                        });
                    }
                    attackAckPromise = dfOnlineSendActionAwait({
                        type: "ATTACK_RESOLVE",
                        attOwner,
                        attackerIdx: attIdx,
                        defenderPlayerId: defOwner,
                        defenderIdx: defIdx,
                        blocked: false,
                        killA: !!out.killA,
                        killD: !!out.killD,
                        anim: {
                            kind: "combat",
                            attOwner,
                            attIdx,
                            defOwner,
                            defIdx,
                            killA: !!out.killA,
                            killD: !!out.killD,
                            fieldPatches,
                        },
                    }, { noSnap: true });
                }
                try {
                    await dfInstallPhase3().runCombat(async () => {
                        window.__dfCombatActive = {
                            attOwner, attIdx, defOwner, defIdx,
                            // uids: re-render no meio da cena não pode esconder o
                            // campeão que passou a ocupar o slot (campeões sumindo).
                            uids: [
                                state.players[attOwner]?.field?.[attIdx]?.uid,
                                state.players[defOwner]?.field?.[defIdx]?.uid,
                            ].filter((u) => u != null).map(String),
                        };
                        window.__dfCombatPending = null;
                        try {
                            await Promise.race([
                                animateCombat(attOwner, attIdx, defOwner, defIdx, out, combatSnap),
                                wait(combatVfxMs).then(() => {
                                    console.warn("[DF combat] timeout — encerrando cinemática");
                                    dfCombatForceCleanup({
                                        attOwner, attIdx, defOwner, defIdx,
                                        killA: out.killA, killD: out.killD,
                                    });
                                }),
                            ]);
                        } finally {
                            window.__dfCombatActive = null;
                            window.__dfCombatSourcesHidden = false;
                            document.body.classList.remove("df-combat-active");
                        }
                    });
                } catch (combatRunErr) {
                    console.warn("[DF resolveCombat]", combatRunErr);
                    dfCombatForceCleanup({
                        attOwner, attIdx, defOwner, defIdx,
                        killA: out.killA, killD: out.killD,
                    });
                }

                // Sempre (sucesso, fallback ou timeout): estilhaço dos mortos.
                await dfEnsureCombatKillVisuals(out, combatSnap, attOwner, attIdx, defOwner, defIdx);

                if (attackAckPromise) {
                    const ack = await attackAckPromise;
                    if (!ack || ack.ok === false) {
                        const err = String(ack?.error || "");
                        // ACK_TIMEOUT após cinemática local: não spammar toast de sync.
                        if (err !== "ACK_TIMEOUT" && err !== "TIMEOUT") {
                            dfOnlineActionFailToast?.("attack", ack?.error);
                        }
                        try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                        // Se auth veio no ack parcial, ainda aplica; senão cleanup.
                        if (ack?.authoritativeState?.players?.length) {
                            attackAckOk = true;
                            pendingAttackAuth = ack.authoritativeState;
                        } else {
                            dfCombatForceCleanup({ attOwner, attIdx, defOwner, defIdx });
                            updateUI();
                            return { ok: false, rejected: true };
                        }
                    } else {
                        attackAckOk = true;
                        pendingAttackAuth = ack.authoritativeState || null;
                        window.__dfLastAttackAck = ack;
                    }
                }

                // Só aplica kill local se o servidor aceitou (MP) — evita revive no END_TURN.
                if (!onlineActor || attackAckOk) {
                    const stillAtt = state.players[attOwner]?.field?.[attIdx];
                    if (stillAtt) {
                        stillAtt.tapped = true;
                        if (stillAtt.freeAttack) stillAtt.freeAttack = false;
                    }
                    applyCombatMechanics(attOwner, attIdx, defOwner, defIdx, stillAtt || attacker, out);
                }
                if (onlineActor && pendingAttackAuth?.players?.length) {
                    dfOnlineReconcileSnapshot(
                        { state: pendingAttackAuth, full: true },
                        { skipPhase: true },
                    );
                }
                // VP_GAIN dos eventos: cobre auth sem campo vp.
                try {
                    const evs = window.__dfLastAttackAck?.events;
                    if (Array.isArray(evs)) {
                        for (const ev of evs) {
                            if (ev?.type === "VP_GAIN" && state.players[ev.playerId] != null && (ev.amount | 0) > 0) {
                                const pl = state.players[ev.playerId];
                                const authVp = pendingAttackAuth?.players?.[ev.playerId]?.vp;
                                // Autoridade manda; sem o campo vp, aplica o
                                // incremento do evento (o ack só é lido uma vez).
                                if (authVp != null) pl.vp = authVp | 0;
                                else pl.vp = (pl.vp | 0) + (ev.amount | 0);
                            }
                            if (ev?.type === "ON_DESTROY_BURST" && ev.ability === "legado") {
                                for (const t of ev.applied || []) {
                                    if (t?.p == null || t?.i == null) continue;
                                    try { window.sfx && window.sfx("legado"); } catch (eSfx) { /* */ }
                                    try {
                                        await animateLegado(t.p, t.i);
                                    } catch (e) { /* */ }
                                    log(`👑 LEGADO: ${t.name || "Campeão"} ganhou +1 Poder.`);
                                }
                            }
                            if (ev?.type === "ON_DESTROY_BURST" && ev.ability === "vinganca") {
                                for (const t of ev.applied || []) {
                                    if (t?.p == null || t?.i == null) continue;
                                    try {
                                        await animateVinganca(t.p, t.i, { uid: null });
                                    } catch (e) { /* */ }
                                    log(`🩸 VINGANÇA: ${t.name || "Campeão"} perdeu 1 Poder.`);
                                }
                            }
                        }
                    }
                } catch (e) { /* */ }
                window.__dfLastAttackAck = null;

                const liveAtt = state.players[attOwner]?.field?.find?.((c) => c && c.uid === attacker.uid) || state.players[attOwner]?.field?.[attIdx];
                if (out.killD && !out.killA && liveAtt && hasTiroDuplo(liveAtt) && liveAtt.tiroDuploUsedThisTurn) {
                    const liveIdx = state.players[attOwner].field.indexOf(liveAtt);
                    if (liveIdx >= 0) await animateTiroDuploInvestida(attOwner, liveIdx);
                }

                updateUI(true);
                dfCombatForceCleanup({
                    attOwner, attIdx, defOwner, defIdx,
                    killA: out.killA, killD: out.killD,
                });
                dfCombatPurgeGhosts();
                const hardResetFieldSizes = () => {
                    document.querySelectorAll(".quadrant-field > .ccard").forEach((el) => {
                        try { dfRestoreCombatFieldCard(el); } catch (e) { /* */ }
                    });
                    window.dfStabilizeFieldCards?.();
                };
                hardResetFieldSizes();
                requestAnimationFrame(() => {
                    hardResetFieldSizes();
                });

                // ATTACK_RESOLVE já enviado/awaited no início (onlineActor).

                const wonOnCombat = checkWin({ suppressShow: true });
                if (wonOnCombat || state.winner !== null) {
                    await wait(DF_VICTORY_PAUSE_MS);
                    showWin();
                }
                return { blocked: false, ok: true };
            }

            async function dfOnlineResolveCombatThenBroadcast(attOwner, attIdx, defOwner, defIdx) {
                return await resolveCombat(attOwner, attIdx, defOwner, defIdx);
            }

            function startAttackSelect() {
                const pid = state.currentPlayer;
                const p = state.players[pid];
                if (p.actions < 1 && !p.field.some(c => c.freeAttack)) {
                    // Feedback FORTE: banner central + sacode pontos de ação,
                    // pra ensinar o jogador que ele NÃO tem ações pra atacar.
                    flashInsufficientActions(1, p.actions, null);
                    log("Sem ações para atacar.");
                    gamePhase = "normal";
                    return;
                }
                const enemies = gatherEnemyTargets(pid, () => true);
                if (!enemies.length) { log("Sem alvos."); gamePhase = "normal"; return; }
                const atkChoices = p.field.map((c, i) => ({ c, i })).filter(x => !x.c.tapped && !x.c.frozen);
                if (!atkChoices.length) { log("Nenhum campeão disponível."); gamePhase = "normal"; return; }
                selectedFieldIdx = atkChoices[0].i;
                gamePhase = "select-attacker";
                targetData = { attackerOwner: pid };
                log("Clique no seu campeão destacado em verde que vai atacar.");
                updateUI(); }

            function defenderChoicesFor(attackerOwner) {
                const arr = [];
                for (let p = 0; p < state.playersCount; p++) {
                    if (p === attackerOwner) continue;
                    state.players[p].field.forEach((c, i) => {
                        if (!c.shielded && !c.pulled) arr.push({ p, i });
                    });
                }
                return arr;
            }

            /** Motor multiplayer: resolve ataque em um passo (sem UI de seleção). */
            async function engineResolveAttack(playerId, attackerIdx, defenderPlayerId, defenderIdx) {
                if (state.winner !== null) return { ok: false, error: "GAME_OVER" };
                if (playerId !== state.currentPlayer) return { ok: false, error: "NOT_YOUR_TURN" };
                if (gamePhase !== "normal") return { ok: false, error: "BAD_PHASE", phase: gamePhase };
                const pl = state.players[playerId];
                const attacker = pl?.field[attackerIdx];
                const defender = state.players[defenderPlayerId]?.field[defenderIdx];
                if (!attacker || attacker.tapped || attacker.frozen || attacker.pulled) {
                    return { ok: false, error: "BAD_ATTACKER" };
                }
                if (!defender || defender.shielded || defender.pulled) {
                    return { ok: false, error: "BAD_DEFENDER" };
                }
                if (!canAttackerTargetDefender(attacker, defender)) {
                    return { ok: false, error: "INVALID_TARGET" };
                }
                const cost = getAttackActionCost(attacker, defender);
                if (!attackIsFree(attacker) && pl.actions < cost) {
                    return { ok: false, error: "NO_ACTIONS" };
                }
                // Snap + pending ANTES de qualquer rebuild (igual drag-attack).
                window.__dfCombatPreSnap = {
                    att: dfCaptureFieldCardSnap(playerId, attackerIdx),
                    def: dfCaptureFieldCardSnap(defenderPlayerId, defenderIdx),
                };
                window.__dfCombatPending = {
                    attOwner: playerId,
                    attIdx: attackerIdx,
                    defOwner: defenderPlayerId,
                    defIdx: defenderIdx,
                };
                const free = attackIsFree(attacker);
                if (!free) pl.actions -= cost;
                gamePhase = "normal";
                targetData = {};
                let res;
                try {
                    res = await resolveCombat(playerId, attackerIdx, defenderPlayerId, defenderIdx);
                } catch (e) {
                    console.warn("[DF engineResolveAttack]", e);
                    if (!free) pl.actions += cost;
                    window.__dfCombatPending = null;
                    window.__dfCombatPreSnap = null;
                    dfCombatForceCleanup?.({
                        attOwner: playerId, attIdx: attackerIdx,
                        defOwner: defenderPlayerId, defIdx: defenderIdx,
                    });
                    updateUI();
                    return { ok: false, error: "COMBAT_FAILED" };
                }
                if (res?.ok === false || res?.rejected) {
                    if (!free) pl.actions += cost;
                    window.__dfCombatPending = null;
                    window.__dfCombatPreSnap = null;
                    updateUI();
                    return res;
                }
                updateUI();
                return { ok: true, ...(res && typeof res === "object" ? res : {}) };
            }

            async function onChampionClick(pIdx, fIdx) {
                const targetingPick = ["target-champion", "target-ally", "ultimate-target"].includes(gamePhase);
                const localTalentPick = targetingPick
                    && (state.activeTalent?.ownerP === dfLocalSeat()
                        || (gamePhase === "ultimate-target" && dfIsLocalPlayer(state.currentPlayer)));
                if (!dfIsMyTurn() && !localTalentPick) return;
                if (gamePhase === "detail") {
                    closeDetail();
                    return;
                }
                if (gamePhase === "summon-placement") return;
                if (gamePhase === "normal") {
                    // No DESKTOP o ataque já funciona arrastando a carta
                    // com o mouse (pointerdown do mouse aciona o mesmo
                    // fluxo de drag-attack do toque). O clique simples
                    // continua abrindo o ZOOM da carta — clicar no
                    // backdrop ou apertar Esc fecha. Antes a gente tentava
                    // entrar em select-defender automaticamente no clique,
                    // mas isso deixava a carta "presa" num preview meio
                    // transparente sem o jogador conseguir prosseguir.
                    const card = state.players[pIdx].field[fIdx];
                    if (card) openCardZoom(card);
                    return;
                }
                if (gamePhase === "select-attacker" && dfIsLocalPlayer(pIdx)) {
                    const c = state.players[dfHumanSeat()].field[fIdx];
                    if (!c || c.tapped || c.frozen || c.pulled) { updateUI(); return; }
                    // 1 clique no próprio campeão = confirma como atacante e
                    // avança automaticamente para a fase de escolher defensor.
                    // (Antes precisava clicar e depois apertar Enter, o que
                    // não existe no celular.)
                    selectedFieldIdx = fIdx;
                    updateUI();
                    confirmEnter();
                    return;
                }
                if (gamePhase === "select-defender") {
                    // 1 clique no campeão inimigo = confirma como defensor e
                    // resolve o combate imediatamente.
                    if (dfIsLocalPlayer(pIdx)) { updateUI(); return; }
                    const enemy = state.players[pIdx]?.field[fIdx];
                    if (!enemy || enemy.shielded || enemy.pulled) { updateUI(); return; }
                    targetData.currentEnemyPlayer = pIdx;
                    selectedEnemyIdx = fIdx;
                    updateUI();
                    confirmEnter();
                    return;
                }
                // Mira de talentos/ultimates: 1 toque/clique no alvo válido =
                // já confirma. Antes precisava de duplo toque (≤450ms), o que
                // era confuso no celular.
                if (gamePhase === "target-champion") {
                    const idx = targetData.targets.findIndex(t => t.p === pIdx && t.i === fIdx);
                    if (idx >= 0) {
                        targetData.targetIndex = idx;
                        lastTargetTap = { p: -1, i: -1, t: 0 };
                        await confirmEnter();
                    }
                    return;
                }
                if (gamePhase === "target-ally") {
                    const idx = targetData.allyTargets.findIndex(t => t.p === pIdx && t.i === fIdx);
                    if (idx >= 0) {
                        targetData.targetIndex = idx;
                        lastTargetTap = { p: -1, i: -1, t: 0 };
                        await confirmEnter();
                        return;
                    }
                    if (targetData.ability === "ritualSacrifice") {
                        cancelRitualSacrifice();
                    }
                    return;
                }
                if (gamePhase === "ultimate-target") {
                    const idx = targetData.targets.findIndex(t => t.p === pIdx && t.i === fIdx);
                    if (idx >= 0) {
                        targetData.targetIndex = idx;
                        lastTargetTap = { p: -1, i: -1, t: 0 };
                        await confirmEnter();
                    }
                    return;
                }
            }

            function attackerChoices() {
                const pid = dfLocalSeat();
                return state.players[pid].field.map((c, i) => i).filter(i => !state.players[pid].field[
                    i].tapped && !state.players[pid].field[i].frozen && !state.players[pid].field[i].pulled);
            }

            function defenderChoices() {
                return defenderChoicesFor(state.currentPlayer);
            }

            async function confirmEnter() {
                const openingPhase = gamePhase;
                const isTargetPick = ["target-champion", "target-ally", "ultimate-target"].includes(openingPhase);
                if (!isTargetPick && enterProcessed) return;
                enterProcessed = true;
                // Trava MutationObservers ANTES de qualquer updateUI na mira, nos DOIS
                // modos (borda destacada + levitate + field-lock = freeze de vários
                // segundos / "Página sem resposta"). vs-IA sofria o mesmo storm.
                const mpTargetUnlock = () => {
                    try {
                        clearTimeout(window.__dfTargetResolveFailsafe);
                        window.__dfTargetResolveFailsafe = null;
                        window.__dfMpTargetResolve = false;
                        window.__dfPauseFieldLockMO?.(false);
                        window.DfTargetLevitate?.pause?.(false);
                    } catch (eU) { /* */ }
                };
                if (isTargetPick) {
                    try {
                        window.__dfMpTargetResolve = true;
                        window.__dfPauseFieldLockMO?.(true);
                        window.DfTargetLevitate?.pause?.(true);
                        document.querySelectorAll(".phase-blocker").forEach((el) => el.remove());
                        window.dfPurgeTargetingVisuals?.();
                        // Failsafe: exceção no meio da resolução não pode deixar
                        // observers pausados pro resto da partida.
                        clearTimeout(window.__dfTargetResolveFailsafe);
                        window.__dfTargetResolveFailsafe = setTimeout(mpTargetUnlock, 20000);
                    } catch (ePre) { /* */ }
                }
                try {
                    if (gamePhase === "menu" && menuData) chooseMenuOption();
                    else if (gamePhase === "select-attacker") {
                    const attOwner = targetData.attackerOwner ?? state.currentPlayer;
                    const champ = state.players[attOwner].field[selectedFieldIdx];
                    if (champ && champ.frozen) { gamePhase = "menu";
                        menuData = { type: "unfreeze", fieldIdx: selectedFieldIdx, attackerOwner: attOwner, confirmed: false };
                        openOverlay("<h3>❄️ Congelado!</h3><p>Sacrificar 1 ação para descongelar?</p>",
                            [{ label: "Sim" }, { label: "Não" }]);
                        menuData.confirmed = true;
                        updateUI(); return; }
                    gamePhase = "select-defender";
                    targetData = { attackerOwner: attOwner, attackerIdx: selectedFieldIdx, currentEnemyPlayer: null };
                    const defs = defenderChoicesFor(attOwner);
                    if (!defs.length) { gamePhase = "normal";
                        targetData = {}; return; }
                    selectedEnemyIdx = defs[0].i;
                    targetData.currentEnemyPlayer = defs[0].p;
                    log("Clique no campeão adversário destacado em verde que será atacado.");
                    updateUI(); } else if (gamePhase === "select-defender") {
                    const attOwner = targetData.attackerOwner ?? state.currentPlayer;
                    const valid = state.players[targetData
                        .currentEnemyPlayer]?.field[selectedEnemyIdx]; if (!valid || valid.shielded || valid.pulled) { gamePhase =
                            "normal"; return; } const attChamp = state.players[attOwner].field[targetData.attackerIdx];
                    if (!canAttackerTargetDefender(attChamp, valid)) {
                        if (isPesadoDemais(attChamp) && isResistente(valid)) {
                            flashRuleBanner("Banjo não pode atacar Campeões Resistentes.", "");
                        } else if (isResistente(valid) && cannotHitResistente(attChamp)) {
                            flashRuleBanner("Campeões com investida não podem atacar campeões Resistentes.", "");
                        }
                        gamePhase = "normal"; return;
                    }
                    const cost = getAttackActionCost(attChamp, valid);
                    if (!attackIsFree(attChamp)) { if (state.players[attOwner].actions < cost) {
                        if (cost >= 2 && isPesadoDemais(attChamp)) {
                            flashRuleBanner("Você não tem ações suficientes para atacar com Banjo.",
                                `Banjo precisa de <b>2 Ações</b> para Atacar • Você tem <b>${state.players[attOwner].actions}</b>`);
                        } else if (cost === 2) {
                            flashRuleBanner("Você não tem ações suficientes para atacá-lo.",
                                `Atacar um Campeão <b>Resistente</b> custa <b>2 Ações</b> • Você tem <b>${state.players[attOwner].actions}</b>`);
                        } else {
                            flashInsufficientActions(cost, state.players[attOwner].actions, null);
                            log("Sem ações!");
                        }
                        gamePhase = "normal"; return; }
                    state.players[attOwner].actions -= cost; }
                await dfOnlineResolveCombatThenBroadcast(
                    attOwner,
                    targetData.attackerIdx,
                    targetData.currentEnemyPlayer,
                    selectedEnemyIdx,
                );
                gamePhase = "normal";
                targetData = {};
                updateUI();                 } else if (gamePhase === "target-champion") { const t = targetData.targets[targetData
                    .targetIndex]; if (!t) return;
                const td = {
                    ...targetData,
                    targets: targetData.targets?.slice?.() ?? targetData.targets,
                    casterUid: targetData.casterUid,
                };
                // Não limpar targetData antes do resolve — dfConfirmOnEnterTarget precisa do casterUid.
                const onEnterAbilities = new Set([
                    "bolaDeFogo", "assassinar", "transformarBichinho",
                    "rajadaCongelante", "mordidaVenenosa", "incendiar",
                ]);
                if (onEnterAbilities.has(td.ability) && td.casterFieldIdx != null) {
                    await dfConfirmOnEnterTarget(td.ability, td.caster, td.casterFieldIdx, t);
                    return;
                }
                dfDismissTargetingPhase();
                if (td.ability === "bolaDeFogo") await castBolaDeFogo(
                    td.caster, td.casterFieldIdx, t.p, t.i, false); if (td.ability ===
                    "assassinar") await castAssassinar(td.caster, td.casterFieldIdx, t.p, t.i); if (
                    td.ability === "bolaDeFogoTalento") await resolveTalentBolaDeFogo(td.handIdx, t
                    .p, t.i); if (td.ability === "explosao") await resolveTalentExplosao(td.handIdx,
                    t.p, t.i); if (td.ability === "zeroAbsoluto") await resolveTalentZeroAbsoluto(td.handIdx,
                    t.p, t.i); if (td.ability === "medoTalento") await resolveTalentMedo(td.handIdx,
                    t.p, t.i); if (                    td.ability === "transformarBichinho") await castTransformarBichinho(
                    td.caster, td.casterFieldIdx, t.p, t.i);
                if (td.ability === "baforadaVenenosa") {
                    const casterP = td.caster ?? dfLocalSeat();
                    dfDismissTargetingPhase();
                    await resolveTalentBaforadaVenenosa(casterP, t.p, t.i);
                    updateUI();
                    checkWin();
                    return;
                }
                gamePhase = "normal";
                targetData = {};
                updateUI();
                dfRestoreFieldPresentation();
                } else if (gamePhase === "target-ally") { const t = targetData.allyTargets[targetData
                    .targetIndex]; if (!t) return;
                const onEnterAllyEngine = new Set([
                    "fortalecer", "devorar", "ursificacao", "imitar", "corromper",
                ]);
                if (onEnterAllyEngine.has(targetData.ability) && targetData.casterFieldIdx != null) {
                    await dfConfirmOnEnterTarget(
                        targetData.ability,
                        targetData.caster,
                        targetData.casterFieldIdx,
                        t,
                    );
                    return;
                }
                if (targetData.ability === "fortalecer") {
                    const ally = state.players[t.p]?.field?.[t.i];
                    const casterP = targetData.caster;
                    const casterField = targetData.casterFieldIdx;
                    dfDismissTargetingPhase();
                    if (ally) {
                        dfBumpChampionPower(ally, 1);
                        log(`${state.players[casterP].name} fortaleceu ${ally.name} (+1 Poder).`);
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            dfOnlineBroadcastVisual({
                                kind: "strong_arm",
                                targetP: t.p,
                                targetI: t.i,
                                powerAfter: ally.currentPower,
                                casterP,
                                casterField,
                                fieldPatches: [{ targetP: t.p, targetI: t.i, currentPower: ally.currentPower }],
                            });
                            void dfOnlineCommitStatus(t.p, t.i, { broadcast: false });
                        }
                        // MP: não await VFX — libera input na hora (anti-freeze).
                        if (window.__DF_ONLINE) {
                            void animateStrongArm(t.p, t.i, {
                                casterP,
                                casterField,
                            }).catch(() => {});
                            updateUI();
                            checkWin();
                            return;
                        }
                        await animateStrongArm(t.p, t.i, {
                            casterP,
                            casterField,
                        });
                    }
                }
                else if (targetData.ability === "fortalecerTalento") {
                    const allyP = t.p;
                    const allyI = t.i;
                    dfDismissTargetingPhase();
                    if (window.__DF_ONLINE) {
                        void resolveTalentFortalecer(allyP, allyI).catch(() => {});
                        updateUI();
                        checkWin();
                        return;
                    }
                    await resolveTalentFortalecer(allyP, allyI);
                    updateUI();
                    checkWin();
                    return;
                }
                else if (targetData.ability === "devorar") {
                    const casterP = targetData.caster;
                    const casterFieldIdx = targetData.casterFieldIdx;
                    const ally = state.players[t.p].field[t.i];
                    const allyPow = ally.currentPower;
                    const allyName = ally.name;
                    const preyI = t.i;
                    const preyUid = ally?.uid || null;
                    const casterUid = state.players[casterP]?.field?.[casterFieldIdx]?.uid || null;
                    const powerAfterApprox = (state.players[casterP]?.field?.[casterFieldIdx]?.currentPower ?? 0) + allyPow;
                    const newIdx = (preyI < casterFieldIdx) ? casterFieldIdx - 1 : casterFieldIdx;
                    const pvpDevour = window.__DF_ONLINE && !dfOnlineApplyingRemote;
                    if (pvpDevour) {
                        // MP: VFX com presa no campo; mutação só via FIELD_COMMIT (evita
                        // splice local mid-anim esconder o Devorar no índice da presa).
                        dfOnlineBroadcastVisual({
                            kind: "devour",
                            targetP: t.p,
                            targetI: preyI,
                            casterP,
                            casterFieldIdx,
                            fieldPatches: [
                                {
                                    targetP: casterP,
                                    targetI: casterFieldIdx,
                                    currentPower: powerAfterApprox,
                                },
                                { targetP: t.p, targetI: preyI, removed: true },
                            ],
                        });
                        const preField = captureFieldForPostDestroy();
                        const preDomSnaps = dfCaptureAllFieldDomSnaps();
                        await animateDevour(t.p, t.i, {
                            preField,
                            preDomSnaps,
                            destroyOnImpact: false,
                        });
                        try {
                            await dfOnlineCommitMutations([
                                {
                                    op: "destroy",
                                    targetP: t.p,
                                    targetI: preyI,
                                    reason: "devorar",
                                    noVpOnKill: true,
                                },
                                {
                                    op: "setStatus",
                                    targetP: casterP,
                                    targetI: newIdx,
                                    flags: { currentPower: powerAfterApprox },
                                },
                            ], { reconcile: true });
                        } catch (e) {
                            console.warn("[DF online] devour target FIELD_COMMIT", e);
                            // Fallback local se o commit falhar.
                            destroyChampion(t.p, t.i, null, "devorar", {
                                ignoreNoHonor: true,
                                deferShatter: true,
                                skipDomHide: true,
                                skipOnlineSync: true,
                            });
                            const cFail = state.players[casterP]?.field?.[
                                (t.i < casterFieldIdx) ? casterFieldIdx - 1 : casterFieldIdx
                            ];
                            if (cFail) cFail.currentPower = (cFail.currentPower ?? 0) + allyPow;
                        }
                        // Nunca deixar o Devorar invisível após reconcile.
                        try {
                            const liveCaster = (casterUid && typeof getChampionDomByUid === "function")
                                ? getChampionDomByUid(casterUid)
                                : getChampionDom(casterP, newIdx);
                            if (liveCaster) {
                                liveCaster.classList.remove("combat-animating", "combat-src-hidden");
                                liveCaster.style.removeProperty("visibility");
                                liveCaster.style.removeProperty("opacity");
                                liveCaster.style.removeProperty("pointer-events");
                            }
                        } catch (eRest) { /* */ }
                        log(`${state.players[casterP]?.field?.[newIdx]?.name || "Invocador"} devorou ${allyName} (+${allyPow} Poder).`);
                        void preyUid;
                    } else {
                        const preField = captureFieldForPostDestroy();
                        const preDomSnaps = dfCaptureAllFieldDomSnaps();
                        let stateKilled = false;
                        const killDevoured = () => {
                            if (stateKilled) return;
                            stateKilled = true;
                            destroyChampion(t.p, t.i, null, "devorar", {
                                ignoreNoHonor: true,
                                deferShatter: true,
                                skipDomHide: true,
                            });
                        };
                        await animateDevour(t.p, t.i, {
                            preField,
                            preDomSnaps,
                            destroyOnImpact: true,
                            onImpactState: killDevoured,
                        });
                        if (!stateKilled) killDevoured();
                        const c2 = state.players[casterP].field[newIdx];
                        if (c2) c2.currentPower += allyPow;
                        log(`${c2 ? c2.name : "Invocador"} devorou ${allyName} (+${allyPow} Poder).`);
                    }
                    // SEM floatText: aviso amarelo proibido durante Habilidades.
                }
                else if (targetData.ability === "ursificacao") {
                    await castUrsificacao(targetData.caster, targetData.casterFieldIdx, t.p, t.i);
                }
                else if (targetData.ability === "ritualSacrifice") {
                    const ritualHandIdx = targetData.ritualHandIdx;
                    const ritualCardName = targetData.ritualCardName;
                    const casterP = targetData.caster;
                    const sacIdx = t.i;
                    const sacCard = state.players[t.p].field[t.i];
                    const sacName = sacCard?.name;
                    const sacUid = sacCard?.uid || undefined;
                    destroyChampion(t.p, t.i, null, "ritualSacrifice", { ignoreNoHonor: true });
                    if (window.__dfPendingDestroyVisual) {
                        await window.__dfPendingDestroyVisual;
                        window.__dfPendingDestroyVisual = null;
                    }
                    log(`Sacrifício consumado: ${sacName} foi oferecido para invocar ${ritualCardName}.`);
                    gamePhase = "normal";
                    targetData = {};
                    state.activeTalent = null; // tira o holofote do RITUAL antes da invocação
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        try {
                            dfOnlineBroadcastVisual({ kind: "ritual_spotlight_clear", ownerP: casterP });
                        } catch (e) { /* */ }
                    }
                    updateUI();
                    await summonFromHand(casterP, ritualHandIdx, true, true, null, {
                        sacrificeIdx: sacIdx,
                        sacrificeUid: sacUid,
                    });
                    updateUI();
                    checkWin();
                    return;
                }
                gamePhase = "normal";
                targetData = {};
                try { window.dfPurgeTargetingVisuals?.(); } catch (e) { /* */ }
                updateUI();
                checkWin();
                } else if (gamePhase === "ultimate-target") { const t = targetData.targets[targetData
                    .targetIndex]; if (!t) return;
                const ultCaster = targetData.caster;
                dfDismissTargetingPhase();
                try {
                    await executeUltimate(ultCaster, t.p, t.i);
                } catch (ultErr) {
                    console.warn("[DF ultimate-target]", ultErr);
                }
                gamePhase = "normal";
                targetData = {};
                updateUI();
                } else if (gamePhase === "detail") closeDetail();
                    // Em fase normal, Enter não invoca mais — pra invocar/usar
                    // talento, o jogador precisa arrastar a carta da mão até o
                    // seu próprio campo.
                } finally {
                    if (window.__DF_ONLINE && !dfOnlineApplyingRemote
                        && gamePhase === "normal" && !state.activeTalent) {
                        dfOnlineBroadcastState();
                    }
                    const targetPick = ["target-champion", "target-ally", "ultimate-target"].includes(openingPhase);
                    if (targetPick) enterProcessed = false;
                    else setTimeout(() => { enterProcessed = false; }, 40);
                    // Libera observers após a mira (delay curto p/ o DOM estabilizar).
                    if (isTargetPick) {
                        setTimeout(mpTargetUnlock, 120);
                    }
                }
            }



            // EXPLOSÃO (Talento) — PvP: estado + sync antes da animação no oponente.


            // ZERO ABSOLUTO (Talento) — PvP: sync + replay de animação no oponente.


            function duplicateFieldChampion(source) {
                const dup = { ...source, uid: newCardUid() };
                dup.tapped = false;
                return dup;
            }









            // Pedido do usuário: a IA NUNCA deve envenenar (Baforada Venenosa)
            // um Campeão que pretende destruir NESTE mesmo turno — o veneno
            // (mata em 2 rodadas) seria desperdiçado num alvo que já morre no
            // combate de agora. Aqui montamos o conjunto de adversários que a
            // IA consegue destruir com um ataque LIMPO ainda neste turno
            // (atacante disponível, orçamento de Ações OK, aiShouldAttack OK e
            // combatOutcome.killD). Chave: "p:i".









            // =============================================================
            // CANCELAR ULTIMATE (reativa) — quando adversário usa Ultimate,
            // o defensor com a carta em mão pode cancelar o EFEITO (4s).
            // O uso da Ultimate adversária JÁ foi consumido antes desta
            // oferta — conforme regra do usuário.
            // =============================================================
            async function offerCancelUltimate(casterP, hero) {
                for (let defOwner = 0; defOwner < state.playersCount; defOwner++) {
                    if (defOwner === casterP) continue;
                    const defP = state.players[defOwner];
                    if (!defP) continue;

                    // MP: caster NUNCA abre overlay local — só QUERY ao holder (fog-of-war).
                    if (window.__DF_ONLINE) {
                        if (!dfIsLocalPlayer(casterP) || dfOnlineApplyingRemote) continue;
                        const cancelled = await dfOnlineResolveReactiveCancel(casterP, hero, defOwner);
                        if (cancelled) {
                            // ANSWER já pode ter tocado VFX — dedupe no helper.
                            try {
                                await dfOnlinePlayReactivePeerFeedback("cancel", {
                                    defenderPlayerId: defOwner,
                                    casterP,
                                    ultimateName: hero?.ultimateName || null,
                                });
                            } catch (e) { /* */ }
                            updateUI();
                            return true;
                        }
                        continue;
                    }

                    const handIdx = defP.hand.findIndex(c => c && c.talentEffect === "cancelarUltimate");
                    if (handIdx < 0) continue;

                    if (defOwner !== 0) {
                        if (!aiShouldCancelUltimate(casterP, hero)) continue;
                        const card = defP.hand.splice(handIdx, 1)[0];
                        state.activeTalent = { ownerP: defOwner, card };
                        log(`${defP.name} cancelou a Ultimate de ${state.players[casterP].name}!`);
                        updateUI();
                        await animateCancelUltimate(casterP, hero);
                        await commitActiveTalent(defOwner);
                        return true;
                    }
                    const cancelled = await showHumanCancelUltimatePrompt(0, handIdx, casterP, hero);
                    if (cancelled) return true;
                }
                return false;
            }



            function showHumanCancelUltimatePrompt(defOwner, handIdx, casterP, hero) {
                return new Promise((resolve) => {
                    // MP: só o holder da carta pode ver o prompt.
                    if (window.__DF_ONLINE && !dfIsLocalPlayer(defOwner)) {
                        resolve(false);
                        return;
                    }
                    const overlay = $("block-overlay");
                    if (!overlay) { resolve(false); return; }
                    const prevPhase = gamePhase;
                    gamePhase = "reactive-block";
                    const casterName = state.players[casterP]?.name || "Adversário";
                    const ultName = hero?.ultimateName || "Ultimate";
                    const cancelArt = dfReactivePromptArtUrl("CANCELAR ULTIMATE");
                    overlay.innerHTML =
                        '<div class="panel" style="width:min(440px,92vw);max-width:92vw;max-height:92vh;overflow-x:hidden;overflow-y:auto;text-align:center;padding:14px;box-sizing:border-box">' +
                            '<div style="font-size:0.95rem;color:#8fffae;margin-bottom:6px">⚡ Reação: CANCELAR ULTIMATE</div>' +
                            '<img src="' + cancelArt + '" alt="Cancelar Ultimate" class="reactive-card-img" draggable="false">' +
                            '<div style="font-size:0.88rem;color:#e9d8ff;margin-bottom:6px;line-height:1.35">' +
                                '<b style="color:#ff8585">' + casterName + '</b> está usando <b>' + ultName + '</b>.' +
                            '</div>' +
                            '<div style="font-size:1rem;color:#fff;margin:8px 0 6px"><b>Deseja Cancelar essa Ultimate?</b></div>' +
                            '<div style="font-size:0.82rem;color:#aaa;margin-bottom:8px">O uso da Ultimate dele será consumido mesmo se cancelar.</div>' +
                            '<div style="height:6px;background:#241830;border-radius:3px;overflow:hidden;margin:6px 0 10px">' +
                                '<div id="block-progress-bar" style="height:100%;width:100%;background:linear-gradient(90deg,#8fffae,#44cc66);transition:width 100ms linear"></div>' +
                            '</div>' +
                            '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;box-sizing:border-box">' +
                                '<button id="block-yes" class="menu-btn" style="background:#2a6a3a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">SIM</button>' +
                                '<button id="block-no" class="menu-btn" style="background:#6a2a2a;min-width:0;width:100%;padding:12px 8px;font-size:1rem;letter-spacing:1px;margin:0">NÃO</button>' +
                            '</div>' +
                        '</div>';
                    overlay.classList.add("active");
                    window.applyCardArtTree?.(overlay);
                    window.dfRewriteDomAssets?.(overlay);

                    const DURATION = 5000;
                    const startT = performance.now();
                    let done = false;
                    const bar = overlay.querySelector("#block-progress-bar");
                    const tick = () => {
                        if (done) return;
                        const elapsed = performance.now() - startT;
                        const pct = Math.max(0, 1 - elapsed / DURATION);
                        if (bar) bar.style.width = (pct * 100).toFixed(1) + "%";
                        if (elapsed >= DURATION) { finish(false); return; }
                        requestAnimationFrame(tick);
                    };
                    const finish = async (cancelled) => {
                        if (done) return;
                        done = true;
                        overlay.classList.remove("active");
                        overlay.innerHTML = "";
                        gamePhase = prevPhase;
                        if (cancelled) {
                            const defP = state.players[defOwner];
                            const stillThere = defP?.hand?.[handIdx]?.talentEffect === "cancelarUltimate"
                                ? handIdx
                                : (defP?.hand?.findIndex(c => c && c.talentEffect === "cancelarUltimate") ?? -1);
                            if (stillThere >= 0) {
                                const card = defP.hand.splice(stillThere, 1)[0];
                                state.activeTalent = { ownerP: defOwner, card };
                            }
                            log("✋ Você cancelou a Ultimate adversária!");
                            updateUI();
                            if (window.__DF_ONLINE) {
                                resolve(true);
                                void (async () => {
                                    try {
                                        await animateCancelUltimate(casterP, hero);
                                        await commitActiveTalent(defOwner);
                                    } catch (e) { /* */ }
                                    updateUI();
                                })();
                                return;
                            }
                            await animateCancelUltimate(casterP, hero);
                            await commitActiveTalent(defOwner);
                            updateUI();
                        } else {
                            log("Você não cancelou a Ultimate.");
                            updateUI();
                        }
                        resolve(cancelled);
                    };
                    overlay.querySelector("#block-yes")?.addEventListener("click", () => finish(true));
                    overlay.querySelector("#block-no")?.addEventListener("click", () => finish(false));
                    requestAnimationFrame(tick);
                });
            }

            function explosaoTargetRect(targetP, targetI) {
                const targetEl = getChampionDom(targetP, targetI);
                if (targetEl) return targetEl.getBoundingClientRect();
                const vr = championVisualRect(targetP, targetI);
                return {
                    left: vr.left,
                    top: vr.top,
                    width: vr.width || 48,
                    height: vr.height || 68,
                };
            }

            async function playExplosaoVisual(_casterP, targetP, targetI, opts = {}) {
                await ensureVfxReady();
                await dfAwaitChampionDom(targetP, targetI, 1600);
                const tr = explosaoTargetRect(targetP, targetI);
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                let impactDone = null;
                let impactCalled = false;
                const onImpact = () => {
                    if (impactCalled) return;
                    impactCalled = true;
                    if (typeof opts.onImpact === "function") {
                        try {
                            const r = opts.onImpact();
                            if (r && typeof r.then === "function") impactDone = r;
                        } catch (e) { /* */ }
                    }
                };
                const BOOM_SEC = 1.55;
                const SAFETY_MS = Math.round((BOOM_SEC + 1.1) * 1000);
                const qTarget = document.getElementById(`quadrant-${dfQuadrantForPlayer(targetP)}`);
                const tremor = () => {
                    if (!qTarget) return;
                    qTarget.classList.add("ground-tremor");
                    setTimeout(() => qTarget.classList.remove("ground-tremor"), 1100);
                };
                const gpuBoom = window.DfVfxEngine?.wantsGpuPresentation?.();
                if (gpuBoom) {
                    tremor();
                    const sceneOpts = { cx, cy, cinematic: true, onImpact, durationSec: BOOM_SEC };
                    let ok = false;
                    try {
                        if (typeof window.DfPixiVfx?.playExplosionScene === "function") {
                            ok = !!(await Promise.race([
                                window.DfPixiVfx.playExplosionScene(sceneOpts).catch(() => false),
                                wait(SAFETY_MS).then(() => false),
                            ]));
                        }
                        // Fallback Pixi cartoon se a cena principal falhar (sem early-return cego).
                        if (!ok && typeof window.DfPixiVfx?.playToonExplosionScene === "function") {
                            ok = !!(await Promise.race([
                                window.DfPixiVfx.playToonExplosionScene(sceneOpts).catch(() => false),
                                wait(SAFETY_MS).then(() => false),
                            ]));
                        }
                    } catch (e) {
                        ok = false;
                    }
                    if (ok) {
                        if (!impactCalled) onImpact();
                        if (impactDone) await impactDone;
                        return;
                    }
                    /* Pixi falhou — cai no DOM impactante abaixo (antes sumia a animação). */
                }
                try { window.sfx && window.sfx("explosao"); } catch (e) { /* */ }
                const cp = dfVfxMap(cx, cy);
                const pos = dfVfxPos();
                const flash = document.createElement("div");
                flash.style.cssText = "position:" + pos + ";inset:0;background:radial-gradient(circle at " + cp.x + "px " + cp.y + "px, rgba(255,200,80,0.7), rgba(255,80,0,0.28) 28%, transparent 58%);pointer-events:none;z-index:9998;opacity:0;transition:opacity .1s";
                flash.dataset.dfVfxMapped = "1";
                dfVfxMount(flash);
                requestAnimationFrame(() => { flash.style.opacity = "1"; });
                const boom = document.createElement("div");
                boom.style.cssText = "transform:translate(-50%,-50%) scale(0.15);background:radial-gradient(circle, #fff 0%, #ffe066 16%, #ff8a1c 40%, #ff2d00 70%, rgba(120,0,0,0) 100%);box-shadow:0 0 90px 36px rgba(255,140,0,0.9),0 0 180px 70px rgba(255,60,0,0.6);pointer-events:none;z-index:9999;transition:transform .7s cubic-bezier(.2,.9,.3,1), opacity .45s ease-in .45s;opacity:1";
                dfVfxPlaceBox(boom, cx - 22, cy - 22, 44, 44);
                const ring = document.createElement("div");
                ring.style.cssText = "transform:translate(-50%,-50%) scale(0.15);border:7px solid rgba(255,210,90,0.98);box-shadow:0 0 34px rgba(255,160,40,0.85) inset, 0 0 34px rgba(255,160,40,0.85);pointer-events:none;z-index:9997;transition:transform .9s ease-out, opacity .9s ease-out;opacity:1;border-radius:50%";
                dfVfxPlaceBox(ring, cx - 34, cy - 34, 68, 68);
                const bang = document.createElement("div");
                bang.textContent = "BOOM!";
                bang.style.cssText = "transform:translate(-50%,-50%) rotate(-8deg) scale(0.25);font-family:'Cinzel',serif;font-weight:900;font-size:3.6rem;color:#fff;text-shadow:0 0 16px #ff2d00,0 4px 0 #7a1500,-2px -2px 0 #ffd76b,3px 3px 0 #7a1500;pointer-events:none;z-index:10000;opacity:0;transition:transform .42s cubic-bezier(.2,1.5,.4,1.2), opacity .35s";
                dfVfxSetPoint(bang, cx, cy);
                for (let i = 0; i < 18; i++) {
                    const ember = document.createElement("div");
                    ember.textContent = i % 3 === 0 ? "✦" : (i % 3 === 1 ? "💥" : "•");
                    ember.style.cssText = "font-size:" + (0.7 + Math.random() * 1.1) + "rem;color:#ffb040;text-shadow:0 0 10px #ff4000;pointer-events:none;z-index:9999;opacity:1;transition:transform .9s ease-out, opacity .9s ease-out";
                    dfVfxSetPoint(ember, cx, cy);
                    const ang = (Math.PI * 2 * i) / 18;
                    const dist = 70 + Math.random() * 120;
                    requestAnimationFrame(() => {
                        ember.style.transform = "translate(" + (Math.cos(ang) * dist) + "px," + (Math.sin(ang) * dist * 0.75 - 30) + "px) scale(0.4)";
                        ember.style.opacity = "0";
                    });
                    setTimeout(() => ember.remove(), 1000);
                }
                await wait(20);
                boom.style.transform = "translate(-50%,-50%) scale(7.5)";
                ring.style.transform = "translate(-50%,-50%) scale(15)";
                ring.style.opacity = "0";
                bang.style.opacity = "1";
                bang.style.transform = "translate(-50%,-50%) rotate(-8deg) scale(1.25)";
                onImpact();
                DfAnim.spawnParticles(cx, cy, FX.n(16));
                tremor();
                await wait(Math.round(BOOM_SEC * 1000));
                boom.style.opacity = "0";
                bang.style.opacity = "0";
                flash.style.opacity = "0";
                await wait(140);
                boom.remove(); ring.remove(); bang.remove(); flash.remove();
                if (impactDone) await impactDone;
            }

            async function applyExplosaoMechanics(casterP, targetP, targetI, opts = {}) {
                const target = state.players[targetP]?.field[targetI];
                if (!target) return { destroyed: false };
                if (await offerReactiveProtection(casterP, targetP, target, "Explosão")) {
                    updateUI();
                    return { destroyed: false };
                }
                if (await consumeBarrierIfAny(targetP, targetI, "Explosão")) {
                    updateUI();
                    return { destroyed: false };
                }
                // MP: commit autoritativo (fieldPatches sozinhos não persistem no END_TURN).
                if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                    if (!dfOnlineNetReady()) {
                        dfOnlineActionFailToast?.("ability", "NOT_CONNECTED");
                        try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                        return { destroyed: false };
                    }
                    const ack = await dfOnlineSendActionAwait({
                        type: "FIELD_COMMIT",
                        mutations: [{
                            op: "reducePower",
                            targetP,
                            targetI,
                            amount: 2,
                            destroyIfZero: true,
                            awardVpTo: casterP,
                            reason: "explosao",
                        }],
                    }, { noSnap: true });
                    if (!ack || ack.ok === false) {
                        dfOnlineActionFailToast?.("ability", ack?.error);
                        try { await dfOnlineHealFromAckOrRollback?.(ack); } catch (e) { /* */ }
                        return { destroyed: false };
                    }
                    const destroyed = (ack.events || []).some((e) => e?.type === "DESTROY");
                    if (ack.authoritativeState?.players?.length) {
                        dfOnlineReconcileSnapshot(
                            { state: ack.authoritativeState, full: true },
                            { skipPhase: true, clearLocalPick: true },
                        );
                    }
                    gamePhase = "normal";
                    targetData = {};
                    window.dfPurgeTargetingVisuals?.();
                    updateUI();
                    checkWin();
                    return { destroyed, targetP, targetI };
                }
                reduceChampionPower(target, 2, targetP, targetI);
                let destroyed = false;
                if (target.currentPower <= 0) {
                    destroyChampion(targetP, targetI, casterP, "explosao", {
                        skipOnlineSync: true,
                        deferShatter: opts.deferDestroyVisual !== false,
                    });
                    destroyed = true;
                }
                updateUI();
                checkWin();
                return { destroyed, targetP, targetI };
            }

            async function castExplosao(casterP, targetP, targetI) {
                const preField = captureFieldForPostDestroy();
                const preDomSnaps = dfCaptureAllFieldDomSnaps();
                // Boom → mecânica → destroy visual na sequência imediata (sem gap).
                await playExplosaoVisual(casterP, targetP, targetI);
                const result = await applyExplosaoMechanics(casterP, targetP, targetI, {
                    deferDestroyVisual: true,
                });
                if (result?.destroyed) {
                    await playStandardDestroyVisual(
                        result.targetP,
                        result.targetI,
                        { preField, preDomSnaps },
                    );
                }
            }

            function zeroTargetRect(targetP, targetI) {
                const targetEl = getChampionDom(targetP, targetI);
                if (targetEl) return targetEl.getBoundingClientRect();
                const vr = championVisualRect(targetP, targetI);
                return {
                    left: vr.left,
                    top: vr.top,
                    width: vr.width || 48,
                    height: vr.height || 68,
                };
            }

            async function playZeroAbsolutoVisual(_casterP, targetP, targetI, opts = {}) {
                const tr = zeroTargetRect(targetP, targetI);
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                const gpu = window.DfVfxEngine?.wantsGpuPresentation?.()
                    && typeof window.DfPixiVfx?.playZeroAbsolutoScene === "function";
                if (gpu) {
                    try {
                        await window.DfVfxEngine?.ensureCinematicReady?.({
                            waitFull: false,
                            maxMs: 2500,
                        });
                    } catch (eReady) { /* */ }
                    try {
                        const ok = await window.DfPixiVfx.playZeroAbsolutoScene({
                            cx, cy, cinematic: true,
                            wasFrozen: !!opts.wasFrozen,
                            w: tr.width, h: tr.height,
                        });
                        if (ok !== false) return;
                    } catch (ePix) {
                        console.warn("[DF] playZeroAbsolutoScene", ePix);
                    }
                }
                const cp = dfVfxMap(cx, cy);
                const pos = dfVfxPos();
                const sky = document.createElement("div");
                sky.style.cssText = "position:" + pos + ";inset:0;background:radial-gradient(circle at " + cp.x + "px " + cp.y + "px, rgba(170,230,255,0.45), rgba(50,130,210,0.25) 30%, transparent 60%);pointer-events:none;z-index:9998;opacity:0;transition:opacity .2s";
                sky.dataset.dfVfxMapped = "1";
                dfVfxMount(sky);
                requestAnimationFrame(() => { sky.style.opacity = "1"; });
                const ice = document.createElement("div");
                ice.style.cssText = "transform:translate(-50%,-50%) scale(0.2) rotate(-8deg);background:linear-gradient(135deg, rgba(220,245,255,0.95) 0%, rgba(140,200,240,0.85) 50%, rgba(60,130,200,0.9) 100%);clip-path:polygon(15% 0,85% 5%,100% 30%,95% 75%,75% 100%,25% 100%,5% 75%,0 30%);border:3px solid rgba(220,245,255,0.95);box-shadow:0 0 40px 10px rgba(160,220,255,0.85), inset 0 0 30px rgba(255,255,255,0.6);pointer-events:none;z-index:9999;opacity:0.9;transition:transform .45s cubic-bezier(.2,.9,.3,1)";
                dfVfxPlaceBox(ice, cx - tr.width * 0.7, cy - tr.height * 0.7, tr.width * 1.4, tr.height * 1.4);
                for (let i = 0; i < 24; i++) {
                    const s = document.createElement("div");
                    s.textContent = ["❄️","❅","❆"][i % 3];
                    const sx = cx + (Math.random() - 0.5) * 240;
                    const sy = cy - 200 - Math.random() * 80;
                    s.style.cssText = "font-size:" + (0.9 + Math.random() * 1.1) + "rem;color:#cef1ff;text-shadow:0 0 8px #fff;pointer-events:none;z-index:9999;opacity:0.95;transition:transform 1.1s ease-in, opacity 1.1s ease-in";
                    dfVfxSetPoint(s, sx, sy);
                    requestAnimationFrame(() => {
                        s.style.transform = "translateY(" + (180 + Math.random() * 120) + "px) rotate(" + ((Math.random() - 0.5) * 360) + "deg)";
                        s.style.opacity = "0";
                    });
                    setTimeout(() => s.remove(), 1200);
                }
                await wait(30);
                ice.style.transform = "translate(-50%,-50%) scale(1) rotate(0deg)";
                await wait(550);
                if (opts.wasFrozen) {
                    ice.style.transition = "transform .3s ease-in, opacity .3s ease-in";
                    ice.style.transform = "translate(-50%,-50%) scale(1.4) rotate(15deg)";
                    ice.style.opacity = "0";
                    for (let i = 0; i < 14; i++) {
                        spawnParticles(cx + (Math.random() - 0.5) * 60, cy + (Math.random() - 0.5) * 60, 1);
                    }
                    await wait(320);
                } else {
                    ice.style.transition = "opacity .55s ease-out";
                    ice.style.opacity = "0";
                    await wait(560);
                }
                ice.remove();
                sky.style.opacity = "0";
                setTimeout(() => sky.remove(), 240);
            }

            async function applyZeroAbsolutoMechanics(casterP, targetP, targetI) {
                const target = state.players[targetP]?.field[targetI];
                const wasFrozen = !!(target && target.frozen);
                if (target) {
                    if (wasFrozen) {
                        log(`❄️💥 ZERO ABSOLUTO destruiu ${target.name} (já estava Congelado).`);
                        floatText("❄️💥 Estilhaçado!", "warn center", 1600);
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            const ack = await dfOnlineSendActionAwait({
                                type: "FIELD_COMMIT",
                                mutations: [{
                                    op: "destroy",
                                    targetP,
                                    targetI,
                                    awardVpTo: casterP,
                                    reason: "zeroAbsoluto",
                                }],
                            }, { noSnap: true });
                            if (ack?.authoritativeState?.players?.length) {
                                dfOnlineReconcileSnapshot(
                                    { state: ack.authoritativeState, full: true },
                                    { skipPhase: true, clearLocalPick: true },
                                );
                            }
                        } else {
                            destroyChampion(targetP, targetI, casterP, "zeroAbsoluto", { skipOnlineSync: true });
                        }
                    } else {
                        target.frozen = true;
                        target.frozenTurns = 3;
                        log(`❄️ ${target.name} foi Congelado por 3 rodadas (Zero Absoluto).`);
                        if (window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                            await dfOnlineCommitStatus(targetP, targetI, {
                                kind: "zero_absoluto",
                                broadcast: false,
                            });
                        }
                    }
                }
                updateUI();
                checkWin();
            }

            async function castZeroAbsoluto(casterP, targetP, targetI) {
                const pre = state.players[targetP]?.field[targetI];
                const wasFrozen = !!(pre && pre.frozen);
                await playZeroAbsolutoVisual(casterP, targetP, targetI, { wasFrozen });
                await applyZeroAbsolutoMechanics(casterP, targetP, targetI);
            }

            // Shows a centered zoom of the talent card to every player for
            // 1.5s before the effect resolves, so opponents can see what was
            // played (Bola de Fogo / Medo). Purely visual; no logic changes.
            function showTalentReveal(card) {
                return new Promise(resolve => {
                    const ov = document.createElement("div");
                    ov.className = "talent-reveal-overlay";
                    const tc = getCardTypeClass(card);
                    ov.innerHTML = `<div class="talent-reveal-card hcard ${tc}"><div class="pow">${card.currentPower ?? card.power ?? 0}</div><div class="nm">${card.name}</div></div>`;
                    dfVfxMount(ov);
                    if (window.applyCardArtTree) window.applyCardArtTree(ov);
                    // Force reflow to start animation
                    void ov.offsetWidth;
                    ov.classList.add("active");
                    setTimeout(() => {
                        ov.classList.remove("active");
                        setTimeout(() => { ov.remove(); resolve(); }, 220);
                    }, 1500);
                });
            }



            // GANCHO — devolve campeões puxados ao dono original quando o
            // contador zera. É chamado uma vez na manutenção do caster (depois
            // do ganho de PV), pra que o caster receba 1 PV pelo Campeão puxado
            // antes de devolvê-lo.
            function returnPulledChampions(pIdx) {
                const p = state.players[pIdx];
                if (!p) return;
                const stillHere = [];
                for (const c of p.field) {
                    if (c.pulled) {
                        c.pulledTurns -= 1;
                        if (c.pulledTurns <= 0) {
                            const ownerIdx = c.pulledFromOwner;
                            c.pulled = false;
                            c.tapped = true; // volta tappeado (já agiu nesta rodada)
                            c.pulledFromOwner = -1;
                            c.pulledTurns = 0;
                            if (ownerIdx >= 0 && state.players[ownerIdx]) {
                                state.players[ownerIdx].field.push(c);
                                log(`🪝 ${c.name} voltou para ${state.players[ownerIdx].name}.`);
                            } else {
                                stillHere.push(c);
                            }
                            continue;
                        }
                    }
                    stillHere.push(c);
                }
                p.field = stillHere;
            }

            // ===== JEKIRO — Fogo e Gelo (CONGELA) =====
            // ===== JEKIRO — Fogo e Gelo (CONGELA por 2 rodadas) =====
            // REESCRITO: o anterior era 1 floquinho de neve emoji — fraco.
            // Agora é uma NEVASCA cinematográfica: vinheta azul cobre a
            // tela, uma onda de choque cyan explode no alvo, 14 estilhaços
            // de gelo voam pra fora em estrela, e o alvo é ENCAPSULADO num
            // bloco de cristal que congela em camadas.


            // ===== JEKIRO — Fogo e Gelo (QUEIMA -1 Poder) =====


            // ===== SANGUE DE DRAGÃO — invocação =====




            // GANCHO — sorteador do alvo da Ult.
            // Filtra adversários com Poder 1 ou 2 e sorteia 65% P1 / 35% P2.
            function pickHookTarget(casterIdx) {
                const pow1 = [];
                const pow2 = [];
                for (let p = 0; p < state.playersCount; p++) {
                    if (p === casterIdx) continue;
                    state.players[p].field.forEach((c, i) => {
                        if (c.currentPower === 1) pow1.push({ p, i });
                        else if (c.currentPower === 2) pow2.push({ p, i });
                    });
                }
                if (!pow1.length && !pow2.length) return null;
                const usePow1 = pow1.length > 0 && (pow2.length === 0 || Math.random() < 0.65);
                const pool = usePow1 ? pow1 : pow2;
                return pool[Math.floor(Math.random() * pool.length)];
            }

            // ===== PALADINO — "O Retorno do Herói" =====
            // Campeão aleatório de Poder 2 no descarte volta ao campo —
            // Constantes aptas; Instantâneas sem disparo nesta invocação.
            function pickPaladinoRandomPower2Discard(pIdx) {
                const pl = state.players[pIdx];
                const pool = [];
                (pl.discard || []).forEach((ref) => {
                    if (!ref) return;
                    if (ref.category && ref.category !== "champion" && ref.category !== "hidden") return;
                    let baseDef = cardDefs.find(d => d.name === ref.name);
                    if (!baseDef) baseDef = dragonTokenDef(ref.name);
                    if (!baseDef || baseDef.category === "talent" || baseDef.category === "reaction") return;
                    if (baseDef.power !== 2) return;
                    pool.push({ ref, baseDef });
                });
                if (!pool.length) return null;
                return pool[Math.floor(Math.random() * pool.length)];
            }
            function getPaladinoReturnCandidates(pIdx) {
                const pick = pickPaladinoRandomPower2Discard(pIdx);
                return pick ? [pick] : [];
            }

            // Move o Campeão escolhido do DESCARTE pro CAMPO (Ação Livre),
            // com Poder base e Silêncio. Anima a reanimação. Compartilhado
            // entre o fluxo do jogador (modal) e o da IA.
            async function paladinoRevive(pIdx, cand, hero) {
                const pl = state.players[pIdx];
                if (!cand || pl.field.length >= MAX_FIELD) return false;
                const baseDef = cand.baseDef;
                const dIdx = pl.discard.indexOf(cand.ref);
                if (dIdx >= 0) pl.discard.splice(dIdx, 1);
                // Remove do histórico pra não ser re-oferecido.
                if (pl.destroyedChampions) {
                    const hIdx = pl.destroyedChampions.indexOf(cand.ref);
                    if (hIdx >= 0) pl.destroyedChampions.splice(hIdx, 1);
                }
                const isConstant = baseDef.abilityType === "constant" || !!baseDef.constantEffect;
                // cloneCard zera TODOS os status (barrier, vulnerable, poisoned…).
                // O objeto montado à mão herdava flags residuais do cardDef, e um
                // `barrier: true` fantasma fazia a Ultimate do Rei Bomba ser
                // consumida pela Barreira sem tirar Poder — parecia "não funcionar".
                const revived = { ...cloneCard(baseDef),
                    silenced: !isConstant,
                    onEnter: isConstant ? (baseDef.onEnter ?? null) : null,
                    constantEffect: baseDef.constantEffect ?? null,
                    onDestroy: baseDef.onDestroy ?? null };
                pl.field.push(revived);
                const ri = pl.field.length - 1;
                pl.lastDestroyedSummon = null;
                if (isConstant) {
                    log(`${pl.name} trouxe ${revived.name} de volta — Habilidade Constante ativa!`);
                } else {
                    log(`${pl.name} trouxe ${revived.name} de volta — Habilidade Instantânea indisponível nesta invocação.`);
                }
                updateUI();
                await animateResurrectImpact(pIdx, ri, hero);
                checkWin();
                return true;
            }

            // Modal de escolha do jogador humano: mostra as cartas lado a
            // lado com "Qual Campeão deve retornar?". Clicar resolve a ult.
            function openPaladinoChoice(pIdx, cands, hero) {
                // Remove qualquer modal anterior pendente.
                document.querySelectorAll(".paladino-choice-overlay").forEach(o => o.remove());
                gamePhase = "ultimate-choice";
                const overlay = document.createElement("div");
                overlay.className = "overlay active paladino-choice-overlay";
                const title = document.createElement("div");
                title.className = "paladino-choice-title";
                title.textContent = "Qual Campeão deve retornar?";
                const row = document.createElement("div");
                row.className = "paladino-choice-row";
                // Mesma convenção de URL de arte usada pelo applyCardArt.
                const artBase = (document.querySelector('base')?.getAttribute('href')) || './';
                const palArtUrl = (name) => {
                    const key = name.replace(/ /g, "_");
                    const h = window.__DF_CARD_HASHES?.[key] || "";
                    const v = window.__DF_CARD_ART_V || "";
                    const qs = [h, v && v !== "dev" ? v : ""].filter(Boolean).join("-");
                    return `url('${artBase.replace(/\/$/, "")}/cards/v2/${key}.png${qs ? "?v=" + qs : ""}')`;
                };
                cands.forEach(cand => {
                    const def = cand.baseDef;
                    const card = document.createElement("button");
                    card.type = "button";
                    card.className = "hcard has-art paladino-choice-card " + getCardTypeClass(def);
                    // Seta a arte direto (não usamos applyCardArtTree aqui pra
                    // não correr o risco de ela remover `has-art` por não achar
                    // o `.nm` interno que ela espera).
                    card.innerHTML =
                        `<div class="paladino-choice-pow">${def.power}</div>` +
                        `<div class="paladino-choice-name">${def.name}</div>`;
                    window.dfAttachCardArt?.(card, def.name);
                    card.addEventListener("click", async () => {
                        if (overlay._chosen) return;
                        overlay._chosen = true;
                        overlay.remove();
                        gamePhase = "normal";
                        const begun = await beginUltimate(pIdx);
                        if (!begun.proceed) { updateUI(); return; }
                        await paladinoRevive(pIdx, cand, hero);
                        updateUI();
                    });
                    row.appendChild(card);
                });
                overlay.appendChild(title);
                overlay.appendChild(row);
                // Clicar FORA das cartas cancela (não gasta uso da ult) —
                // evita prender o jogador caso mude de ideia.
                overlay.addEventListener("click", (e) => {
                    if (e.target === overlay && !overlay._chosen) {
                        overlay._chosen = true;
                        overlay.remove();
                        gamePhase = "normal";
                        log("O Retorno do Herói cancelado.");
                        updateUI();
                    }
                });
                dfVfxMount(overlay);
            }

            // ===== PALADINO — animação de impacto na reanimação =====
            async function animateResurrectImpact(casterP, targetI, hero) {
                await ensureVfxReady();
                try {
                    await window.DfVfxEngine?.ensureCinematicReady?.({ waitFull: true, maxMs: 12000 });
                } catch (e) { /* */ }
                if (!window.DfUltimateDirector?.isReady?.()) {
                    window.DfUltimateDirector?.ensureInstalled?.();
                    window.DfSpriteVfx?.wireUltimateDirector?.();
                }
                if (window.DfUltimateDirector?.play) {
                    await window.DfUltimateDirector.play("resurrect", {
                        casterP, targetP: casterP, targetI,
                    });
                    return;
                }
                if (window.DfSpriteVfx) {
                    await DfSpriteVfx.playUltimate("resurrect", { casterP, targetP: casterP, targetI });
                }
            }

            // ===== ALQUIMISTA — Poção (emoji + impacto — independente do director) =====
            async function playAlchemistPotionVisual(targetP, targetI, success) {
                const el = getChampionDom(targetP, targetI);
                const r = el?.getBoundingClientRect();
                const cx = r ? r.left + r.width / 2 : window.innerWidth / 2;
                const cy = r ? r.top + r.height / 2 : window.innerHeight * 0.44;
                const cleanup = [];

                try { window.sfx && window.sfx("potion"); } catch (e) {}

                const herald = document.createElement("div");
                herald.className = "df-alch-potion-herald";
                herald.innerHTML = `<span class="df-alch-herald-main">⚗️</span><span class="df-alch-herald-sub">🧪</span>`;
                herald.style.left = cx + "px";
                herald.style.top = (cy - 80) + "px";
                dfVfxMount(herald);
                cleanup.push(herald);

                const trail = document.createElement("div");
                trail.className = "df-alch-potion-trail";
                trail.style.left = cx + "px";
                trail.style.top = cy + "px";
                dfVfxMount(trail);
                cleanup.push(trail);

                const potion = document.createElement("div");
                potion.className = "df-alch-potion-fly";
                potion.innerHTML =
                    `<span class="df-alch-potion-emoji">🧪</span>` +
                    `<span class="df-alch-potion-bubble">⚗️</span>` +
                    `<span class="df-alch-potion-spark">✨</span>`;
                potion.style.left = cx + "px";
                potion.style.top = cy + "px";
                dfVfxMount(potion);
                cleanup.push(potion);

                if (el) el.classList.add("ult-potion-pending");
                await wait(FX.mobile ? 280 : 360);

                const fallFrom = Math.min(window.innerHeight * 0.58, FX.mobile ? 340 : 480);
                const FLY_MS = FX.mobile ? 680 : 860;
                const t0 = performance.now();
                await new Promise((resolve) => {
                    function tick(now) {
                        const t = Math.min(1, (now - t0) / FLY_MS);
                        const ease = 1 - Math.pow(1 - t, 3);
                        const y = -fallFrom * (1 - ease) + 8 * Math.sin(Math.PI * ease);
                        const spin = (1 - ease) * 22;
                        const sc = 0.75 + ease * 0.45;
                        potion.style.transform =
                            `translate(-50%, calc(-50% + ${y}px)) rotate(${spin}deg) scale(${sc})`;
                        trail.style.height = Math.max(24, fallFrom * (1 - ease) * 0.92) + "px";
                        trail.style.opacity = String(0.35 + ease * 0.55);
                        if (t < 1) requestAnimationFrame(tick);
                        else resolve();
                    }
                    requestAnimationFrame(tick);
                });

                herald.classList.add("fade-out");
                const splash = document.createElement("div");
                splash.className = "df-alch-potion-splash" + (success ? " good" : " bad");
                splash.style.left = cx + "px";
                splash.style.top = cy + "px";
                splash.innerHTML = success
                    ? `<span>💧</span><span>✨</span><span>➕</span>`
                    : `<span>💧</span><span>☠️</span><span>💜</span>`;
                dfVfxMount(splash);
                cleanup.push(splash);

                const burstN = FX.mobile ? 10 : 16;
                const burstIcons = success
                    ? ["✨", "⭐", "💚", "🧪", "⚗️"]
                    : ["💜", "☠️", "💀", "🧪", "💨"];
                for (let i = 0; i < burstN; i++) {
                    const b = document.createElement("div");
                    b.className = "df-alch-potion-burst-emoji";
                    b.textContent = burstIcons[i % burstIcons.length];
                    b.style.left = cx + "px";
                    b.style.top = cy + "px";
                    const ang = (i / burstN) * Math.PI * 2;
                    b.style.setProperty("--dx", Math.round(Math.cos(ang) * (50 + Math.random() * 70)) + "px");
                    b.style.setProperty("--dy", Math.round(-40 - Math.random() * 80) + "px");
                    b.style.animationDelay = (i * 28) + "ms";
                    dfVfxMount(b);
                    cleanup.push(b);
                }

                const ring = document.createElement("div");
                ring.className = "df-alch-potion-ring" + (success ? " good" : " bad");
                ring.style.left = cx + "px";
                ring.style.top = cy + "px";
                dfVfxMount(ring);
                cleanup.push(ring);

                const flash = document.createElement("div");
                flash.className = "df-alch-potion-flash" + (success ? " good" : " bad");
                flash.style.setProperty("--hx", ((cx / window.innerWidth) * 100) + "%");
                flash.style.setProperty("--hy", ((cy / window.innerHeight) * 100) + "%");
                dfVfxMount(flash);
                cleanup.push(flash);

                if (el) {
                    el.classList.remove("ult-potion-pending");
                    el.classList.add(success ? "potion-buff-pop" : "potion-debuff-shake");
                    el.classList.add(success ? "ult-potion-good" : "ult-potion-bad");
                }
                try { window.sfx && window.sfx(success ? "buff_power" : "debuff"); } catch (e) {}

                await wait(FX.mobile ? 720 : 920);
                potion.remove();
                trail.remove();
                cleanup.forEach((n) => { try { n.remove(); } catch (e) { /* */ } });
                if (el) {
                    el.classList.remove(
                        "potion-buff-pop", "potion-debuff-shake", "ult-potion-good", "ult-potion-bad",
                    );
                }
            }



            // VALMONT — caixa de prompt central explicando o passo da ult.
            // Aparece no topo do tabuleiro com título grande + subtítulo.
            function showVampirismPrompt() {
                const old = document.querySelector(".ult-prompt-box");
                if (old) old.remove();
                const box = document.createElement("div");
                box.className = "ult-prompt-box";
                box.innerHTML =
                    `<div class="ult-prompt-title">Qual Campeão você quer usar o Vampirismo?</div>` +
                    `<div class="ult-prompt-sub">Campeões com poder 2 ou mais</div>`;
                dfVfxMount(box);
                setTimeout(() => { box.classList.add("fade-out"); setTimeout(() => box.remove(), 400); }, 3200);
            }

            // ===== VALMONT — Vampirismo: sangue fluindo do inimigo pro aliado =====


            // ===== TECNOMAGO — Outra Dimensão: buraco negro suga o Campeão =====


            function processFrozenCounters(pIdx) {
                const p = state.players[pIdx];
                let unfroze = false;
                p.field.forEach(c => {
                    if (c.frozen && c.frozenTurns > 0) {
                        c.frozenTurns -= 1;
                        if (c.frozenTurns <= 0) {
                            c.frozen = false;
                            c.frozenTurns = 0;
                            unfroze = true;
                        }
                    }
                });
                if (unfroze) {
                    log(`${p.name} teve campeões descongelados automaticamente.`);
                    updateUI();
                }
            }

            function processShieldCounters(pIdx) {
                const p = state.players[pIdx];
                let changed = false;
                p.field.forEach(c => {
                    if (c.barrier && !c.barrierPermanent && c.barrierTurns > 0) {
                        c.barrierTurns -= 1;
                        if (c.barrierTurns <= 0) {
                            c.barrier = false;
                            c.barrierTurns = 0;
                            changed = true;
                            log(`${c.name}: Barreira expirou.`);
                        }
                    }
                    if (c.fireAura && c.fireAuraTurns > 0) {
                        c.fireAuraTurns -= 1;
                        if (c.fireAuraTurns <= 0) {
                            c.fireAura = false;
                            c.fireAuraTurns = 0;
                            changed = true;
                            log(`${c.name}: Aura de Fogo expirou.`);
                        }
                    }
                    c.tiroDuploUsedThisTurn = false;
                    if (c.shielded && c.shieldedTurns > 0) {
                        c.shieldedTurns -= 1;
                        if (c.shieldedTurns <= 0) {
                            c.shielded = false;
                            c.shieldedTurns = 0;
                            changed = true;
                        }
                    }
                });
                if (changed) updateUI();
            }

            function processFuryCounters(pIdx) {
                const p = state.players[pIdx];
                let changed = false;
                p.field.forEach(c => {
                    if (!c.fury || c.furyTurns <= 0) return;
                    c.furyTurns -= 1;
                    if (c.furyTurns <= 0) {
                        const expired = DfRules.expireFuryStacks(c);
                        if (expired > 0) log(`${c.name}: Fúria expirou (-${expired} Poder).`);
                        changed = true;
                    }
                });
                if (changed) updateUI();
            }

            // Manutenção SEQUENCIADA e NARRADA por uma única CAIXA
            // contextual (.maint-box) que aparece SEMPRE em cima da mão
            // do jogador da vez. Substitui os splashes antigos. Ordem
            // (total ≤ 5s, pedido do usuário):
            //   1) Imagem do herói + "Vez de <Hero>"   (turn / dourado, 1100ms)
            //   2) box some → CONTAGEM com bounce dos campeões (≈1000ms)
            //   3) "N campeão{es} em campo = X PV{s} ganho{s}"  (vp / ciano, 1400ms)
            //   4) "🃏 Saque livre — +1 carta" (draw / verde, 1100ms)
            //      OU "💀 Pesadelo — Sem saque livre neste turno" (nightmare)
            //   4.5) "⏳ Desacelerado..." se aplicável (substitui o saque livre)
            //   5) box some — o desaparecimento JÁ marca o fim da manutenção
            // Phase-blocker fullscreen impede qualquer ação/preview de carta
            // durante toda a sequência.
            const MAINT_COUNT_MS = 1000;
            const MAINT_FADE_MS = 180;
            /** Banner de PV passivo (1,5s) — antes do saque livre (vs-IA e MP). */
            async function showPassiveVpMaintMessage(pIdx, opts = {}) {
                if (window.__DF_SIM_MODE) return;
                const p = state.players[pIdx];
                if (!p) return;
                const n = (p.field || []).length | 0;
                const vpMsg = n <= 0
                    ? "0 Campeões em campo - Não Ganhou PVs"
                    : (n === 1
                        ? "1 Campeão em campo - Ganhou 1 PV"
                        : "2 Campeões em campo - Ganhou 2 PVs");
                const box = opts.box || createMaintBox();
                const ownBox = !opts.box;
                const fade = opts.fadeMs != null
                    ? opts.fadeMs
                    : (window.__DF_ONLINE ? 140 : MAINT_FADE_MS);
                try {
                    await showMaintBox(box, pIdx, vpMsg, "vp", opts.ms ?? 1500);
                    await hideMaintBox(box, fade);
                } finally {
                    if (ownBox && box?.isConnected) box.remove();
                }
            }
            /** Manutenção sem UI — usada pelo motor de simulação IA vs IA no PC. */
            async function simMaintenanceFast(pIdx) {
                const p = state.players[pIdx];
                const plan = DfRules.computeMaintenancePlan(state, pIdx);
                const poisonVictims = (plan.poisonKills || []).map((k) => {
                    const ch = state.players[k.p]?.field[k.i];
                    return ch ? { p: k.p, i: k.i, uid: ch.uid, name: ch.name } : null;
                }).filter(Boolean);
                const preDomSnaps = poisonVictims.length ? dfCaptureAllFieldDomSnaps() : null;
                const maint = DfRules.runTurnMaintenance(state, pIdx);
                maint.statusLogs.forEach((msg) => log(msg));
                maint.returned.forEach((r) => {
                    log(`🪝 ${r.name} voltou para ${state.players[r.ownerIdx].name}.`);
                });
                if (maint.poisonDestroyed.length) {
                    await playPoisonMaintenanceDeaths(poisonVictims, preDomSnaps);
                    maint.poisonDestroyed.forEach((k) => {
                        log(`☠️ ${k.name} morreu envenenado.`);
                    });
                    updateUI();
                }
                checkWin();
                if (state.winner !== null) return;
                if (maint.skipDraw) {
                    /* Pesadelo — sem saque */
                } else if (p.hand.length < MAX_HAND) {
                    drawCard(pIdx, false);
                }
                await applyEmChamasAfterMaintenance(pIdx, { animate: false });
            }

            /** 1º turno de cada jogador (2P): turnNumber permanece 1 até o wrap. */
            function isFirstTurnForPlayer(_pIdx) {
                return (state.turnNumber | 0) <= 1;
            }

            /**
             * Abertura / 1ºs turnos: regras + saque livre, SEM banner de PV.
             * 1º jogador da partida: espera 1s com a mão de 4 cartas antes do saque.
             */
            async function maintenanceFirstTurns(pIdx) {
                const p = state.players[pIdx];
                if (!p) return;
                const openingBoot = !!(window.__dfMatchBoot || window.__dfOnlineMatchBoot);
                if (openingBoot) {
                    if (window.__dfMatchOpeningSeat == null) window.__dfMatchOpeningSeat = pIdx;
                    updateUI();
                    if (pIdx === (window.__dfMatchOpeningSeat | 0)) {
                        await wait(1000);
                    }
                }
                const plan = DfRules.computeMaintenancePlan(state, pIdx);
                const poisonVictims = (plan.poisonKills || []).map((k) => {
                    const ch = state.players[k.p]?.field[k.i];
                    return ch ? { p: k.p, i: k.i, uid: ch.uid, name: ch.name } : null;
                }).filter(Boolean);
                const preDomSnaps = poisonVictims.length ? dfCaptureAllFieldDomSnaps() : null;
                const maint = DfRules.runTurnMaintenance(state, pIdx);
                (maint.statusLogs || []).forEach((msg) => log(msg));
                (maint.returned || []).forEach((r) => {
                    log(`🪝 ${r.name} voltou para ${state.players[r.ownerIdx].name}.`);
                });
                if (maint.poisonDestroyed?.length) {
                    await playPoisonMaintenanceDeaths(poisonVictims, preDomSnaps);
                    maint.poisonDestroyed.forEach((k) => {
                        log(`☠️ ${k.name} morreu pelo VENENO!`);
                    });
                    updateUI();
                }
                checkWin();
                if (state.winner !== null) return;
                // Sem banner de PV no 1º turno — só saque livre.
                if (maint.skipDraw) {
                    dfRemovePesadeloShroud?.(pIdx);
                    log(`💀 ${p.name} perdeu o saque livre (Pesadelo).`);
                } else if (p.hand.length >= MAX_HAND) {
                    log(`✋ ${p.name} atingiu o limite de cartas na mão — sem saque livre.`);
                } else {
                    const animate = openingBoot || dfIsLocalPlayer(pIdx);
                    drawCard(pIdx, animate);
                    log(`🃏 ${p.name} comprou 1 carta no saque livre.`);
                    if (animate) {
                        try { await waitDrawAnim(); } catch (e) { /* */ }
                    }
                }
                await applyEmChamasAfterMaintenance(pIdx, { animate: false });
            }

            async function maintenance(pIdx) {
                window.__dfMaintRunning = true;
                window.__dfPauseHandFanMO?.(true);
                window.dfStabilizeHandWraps?.();
                try {
                // PvP: estado autoritativo do END_TURN já aplicou manutenção/saque.
                if (window.__dfOnlineSkipMaintRules && window.__DF_ONLINE) {
                    updateUI();
                    checkWin();
                    return;
                }
                if (window.__DF_SIM_MODE) {
                    await simMaintenanceFast(pIdx);
                    return;
                }
                if (window.__DF_ONLINE && !dfIsLocalPlayer(pIdx)) {
                    await simMaintenanceFast(pIdx);
                    updateUI();
                    checkWin();
                    return;
                }
                // 1º turno de cada jogador (e boot): saque livre sem banner de PV.
                if (window.__dfMatchBoot || window.__dfOnlineMatchBoot
                    || isFirstTurnForPlayer(pIdx)) {
                    await maintenanceFirstTurns(pIdx);
                    updateUI();
                    checkWin();
                    return;
                }
                const p = state.players[pIdx];
                const isHuman = dfIsLocalPlayer(pIdx);
                // Campo vazio do humano: libera invocar logo após saque/ações
                // (vale na 1ª rodada mesmo quando a IA começou — __dfMatchBoot
                // já foi limpo antes do turno humano).
                const fastHumanEmpty = isHuman && p.field.length === 0;
                const fastEmptyBoot = !!window.__dfMatchBoot && p.field.length === 0;
                const maintBeatMs = fastHumanEmpty ? 0 : (fastEmptyBoot ? 420 : (window.__DF_ONLINE ? 520 : 1000));
                const maintFadeMs = window.__DF_ONLINE ? 140 : MAINT_FADE_MS;
                const heroDef = p?.heroDef || (p ? getHeroDef(p.heroId) : null);
                const heroName = heroDef ? heroDef.name : (p?.name || "Jogador");
                const heroNameSafe = escapeHtmlMaint(heroName);

                const blocker = createPhaseBlocker();
                const box = createMaintBox();
                let keepTurnMaintBox = false;
                window.dfStabilizeFieldCards?.();
                try {
                    log(`🎮 Vez de ${heroName} começou.`);

                    // ===== 1) IMAGEM DO HERÓI + "Vez de <Hero>" =====
                    const heroImgPath = heroDef && heroDef.image
                        ? escapeHtmlMaint(heroDef.image)
                        : null;
                    const heroAvatar = heroImgPath
                        ? `<img class="maint-hero-img" src="${heroImgPath}" alt="${heroNameSafe}" draggable="false">`
                        : `<div style="font-size:2.2rem;line-height:1;margin-bottom:6px">${heroDef?.emoji || "🎮"}</div>`;
                    if (!fastHumanEmpty || !isHuman) {
                        await showMaintBox(
                            box, pIdx,
                            `${heroAvatar}Vez de <span class="hero-name">${heroNameSafe}</span>`,
                            "turn", maintBeatMs, "quadrant"
                        );
                        await hideMaintBox(box, maintFadeMs);
                    } else {
                        await showMaintBox(
                            box, pIdx,
                            `${heroAvatar}Vez de <span class="hero-name">${heroNameSafe}</span>`,
                            "turn", Math.max(700, maintBeatMs || 700), "quadrant"
                        );
                        await hideMaintBox(box, maintFadeMs);
                    }

                    // ===== 2) Motor puro (mesma lógica dos testes) + contagem visual =====
                    const plan = DfRules.computeMaintenancePlan(state, pIdx);
                    const poisonVictims = (plan.poisonKills || []).map((k) => {
                        const ch = state.players[k.p]?.field[k.i];
                        return ch ? { p: k.p, i: k.i, uid: ch.uid, name: ch.name } : null;
                    }).filter(Boolean);
                    const preDomSnaps = poisonVictims.length ? dfCaptureAllFieldDomSnaps() : null;
                    const maint = DfRules.runTurnMaintenance(state, pIdx);
                    (maint.statusLogs || []).forEach((msg) => log(msg));
                    if (maint.poisonDestroyed?.length) {
                        await playPoisonMaintenanceDeaths(poisonVictims, preDomSnaps);
                        maint.poisonDestroyed.forEach((k) => {
                            log(`☠️ ${k.name} morreu pelo VENENO!`);
                        });
                        updateUI();
                        floatText("🐍 Veneno fez efeito!", "warn center", 1600);
                        await wait(700);
                    }
                    (maint.returned || []).forEach((r) => {
                        log(`🪝 ${r.name} voltou para ${state.players[r.ownerIdx].name}.`);
                    });

                    const n = p.field.length;
                    const gain = maint.passiveVpGain || 0;
                    if (n > 0) {
                        const per = Math.max(280, MAINT_COUNT_MS / Math.max(1, n));
                        for (let i = 0; i < n; i++) {
                            const el = getChampionDom(pIdx, i);
                            const c = p.field[i];
                            if (el) {
                                el.classList.remove("counting-bounce", "counting-bounce-tapped");
                                void el.offsetWidth;
                                el.classList.add(c?.tapped ? "counting-bounce-tapped" : "counting-bounce");
                                setTimeout(() => {
                                    el.classList.remove("counting-bounce", "counting-bounce-tapped");
                                    ["transform", "scale", "translate", "rotate"].forEach((p) => {
                                        el.style.removeProperty(p);
                                    });
                                    el.style.setProperty("transform", "none", "important");
                                    el.style.setProperty("scale", "1", "important");
                                    dfStabilizeFieldCards(el, { force: true });
                                }, 560);
                            }
                            await wait(per);
                        }
                        window.dfStabilizeFieldCards?.();
                        requestAnimationFrame(() => window.dfStabilizeFieldCards?.());
                    } else {
                        await wait(fastHumanEmpty ? 0 : (fastEmptyBoot ? 120 : 600));
                    }

                    // ===== 3) PV passivo — mensagem 1,5s (não no 1º turno), depois saque livre =====
                    if (gain > 0) log(`+${gain} PV pra ${p.name} (${n === 1 ? "campeão" : "campeões"} em campo).`);
                    checkWin();
                    if (state.winner !== null) return;
                    if (!isFirstTurnForPlayer(pIdx)) {
                        await showPassiveVpMaintMessage(pIdx, { box, fadeMs: maintFadeMs });
                    }

                    // ===== 4) SAQUE LIVRE ou PESADELO =====
                    if (maint.skipDraw) {
                        dfRemovePesadeloShroud(pIdx);
                        log(`💀 ${p.name} perdeu o saque livre (Pesadelo).`);
                        const msg = isHuman
                            ? `💀 <b>Pesadelo</b><br>Sem saque livre neste turno.`
                            : `💀 <b>Pesadelo</b><br>${heroNameSafe} não faz saque livre.`;
                        await showMaintBox(box, pIdx, msg, "nightmare", 1000);
                    } else if (p.hand.length >= MAX_HAND) {
                        log(`✋ ${p.name} atingiu o limite de cartas na mão — sem saque livre.`);
                        const msg = isHuman
                            ? `Você atingiu o limite de cartas em mãos. Sem saque livre nesse turno.`
                            : `${heroNameSafe} atingiu o limite de cartas em mãos. Sem saque livre nesse turno.`;
                        await showMaintBox(box, pIdx, msg, "nightmare", 1600);
                    } else {
                        drawCard(pIdx, true);
                        log(`🃏 ${p.name} comprou 1 carta no saque livre.`);
                        await waitDrawAnim();
                        await wait(isHuman ? 120 : 80);
                    }

                    // Ações / untap / Investida já vieram de applyTurnRefresh no motor.
                    updateUI();
                    window.dfStabilizeFieldCards?.();
                    requestAnimationFrame(() => window.dfStabilizeFieldCards?.());
                    checkWin();
                    if (state.winner !== null) return;

                    if (isHuman && state.winner === null) {
                        if (blocker?.isConnected) blocker.remove();
                        gamePhase = "normal";
                    }

                    await hideMaintBox(box, MAINT_FADE_MS);
                    // ===== 5) Em Chamas (Incendiar) — após a manutenção =====
                    await applyEmChamasAfterMaintenance(pIdx, { animate: true });
                } finally {
                    if (blocker?.isConnected) blocker.remove();
                    if (box?.isConnected && !keepTurnMaintBox) box.remove();
                }
                if (state.winner === null && gamePhase === "menu") gamePhase = "normal";
                } finally {
                    window.__dfMaintRunning = false;
                    window.__dfPauseHandFanMO?.(false);
                    try { window.__dfSyncActionsPedestalForce?.(); } catch (e) { /* */ }
                    try { window.__dfSyncTurnClock?.(); } catch (e) { /* */ }
                    requestAnimationFrame(() => window.__dfFanAllHands?.());
                }
            }

            async function startTurn(pIdx) {
                if (!state.started) return;
                const gen = dfMatchGeneration;
                state.currentPlayer = pIdx;
                // Após o 1º startTurn, currentPlayer é a fonte de verdade —
                // limpa o seat de abertura (evita banner preso no opener
                // quando a IA passa a vez ainda dentro do boot).
                window.__dfMatchOpeningSeat = null;
                try { window.__dfSyncTurnBannerPedestal?.(); } catch (eBanSt) { /* */ }
                // Slow net: não aquecer catálogo no meio do turno local.
                try {
                    const local = (typeof dfLocalSeat === "function" ? dfLocalSeat() : 0) | 0;
                    if (pIdx === local && window.DfLazyLoad?.isSlowNetwork?.()) {
                        window.__dfMatchArtCoord?.deferCatalogForLocalTurn?.();
                    } else if (pIdx !== local) {
                        const idle = window.requestIdleCallback || ((fn) => setTimeout(fn, 500));
                        idle(() => {
                            try { window.__dfMatchArtCoord?.allowCatalogWarm?.(); } catch (e2) { /* */ }
                        });
                    }
                } catch (e) { /* */ }
                const bootTurn = !!(window.__dfMatchBoot || window.__dfOnlineMatchBoot || window.__dfOnlineSkipMaintRules);
                // MP: durante boot (saque livre) NÃO libera input — evita invocar
                // antes do saque e segundo startTurn com +1 PV fantasma.
                const lockBootInput = !!(window.__DF_ONLINE && (
                    window.__dfOnlineBootLockInput
                    || window.__dfOnlineMatchBoot
                    || window.__dfOnlineSkipMaintRules
                ));
                try { window.__dfRefreshDesktopHeroPanels?.(); } catch (e) { /* */ }
                if (state.players[pIdx]) state.players[pIdx].onEnterUsedThisTurn = [];
                // Relógio: sempre mostra tempo do jogador da vez (MP e vs-IA).
                if (state.winner === null) {
                    const d = $("timer-display");
                    if (d) d.textContent = TURN_TIME;
                    window.DfTurnClock?.start?.(TURN_TIME, true);
                    syncHeroPanelTimers(String(TURN_TIME), false);
                    try { window.__dfSyncTurnClock?.(); } catch (e) { /* */ }
                    // vs-IA: inicia o countdown já no começo do turno (hubs +
                    // timer-display). Antes ficava só após manutenção — e o
                    // warm de artes atrasava o startTurn em vários segundos.
                    if (!window.__DF_ONLINE) {
                        try { startTimer(); } catch (eT0) { /* */ }
                    }
                }
                // Boot offline: liberar invocação cedo. Boot MP: manter menu até manutenção.
                gamePhase = (bootTurn && !lockBootInput) ? "normal" : "menu";
                updateTurnPill();
                updateUI();
                // Relógio só inicia após manutenção — evita expirar durante
                // animações de início de turno e travar a passagem para a IA.
                try {
                    await maintenance(pIdx);
                } finally {
                    document.querySelectorAll(".phase-blocker").forEach((el) => el.remove());
                    dfPurgeDesacelerarVfx();
                    aiBusy = false;
                    if (state.winner === null && gamePhase === "menu") gamePhase = "normal";
                    window.dfStabilizeFieldCards?.();
                }
                if (!state.started || gen !== dfMatchGeneration) { stopTimer(); return; }
                if (state.winner !== null) { stopTimer(); return; }
                if (gamePhase === "menu") gamePhase = "normal";
                startTimer();
                try { window.__dfSyncActionsPedestalForce?.(); } catch (e) { /* */ }
                try { window.__dfSyncTurnClock?.(); } catch (e) { /* */ }
                try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                requestAnimationFrame(() => {
                    try { window.__dfSyncActionsPedestalForce?.(); } catch (e) { /* */ }
                    try { window.__dfSyncTurnClock?.(); } catch (e) { /* */ }
                    try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                });
                const plTurn = state.players[pIdx];
                if (plTurn && !plTurn.isAI && !window.__DF_SIM_MODE) {
                    gamePhase = "normal";
                    log(dfIsLocalPlayer(pIdx) ? "Seu turno começou." : `Turno de ${plTurn.name}.`);
                    // MP: sem floatText “Sua vez / Vez de herói” (pedido do autor).
                    updateUI();
                    try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                } else {
                    gamePhase = "normal";
                    aiBusy = false;
                    try {
                        await aiTakeTurn(pIdx);
                    } catch (aiStartErr) {
                        console.warn("[DF startTurn] aiTakeTurn falhou", aiStartErr);
                        aiBusy = false;
                        ensureTurnReady();
                        if (state.started && gen === dfMatchGeneration && state.currentPlayer === pIdx && state.winner === null) {
                            const T = DfProtocol?.ACTION_TYPES || {};
                            await dfDispatch({ type: T.END_TURN || "END_TURN", playerId: pIdx }, { fromHuman: false, broadcast: false });
                        }
                    }
                }
            }

            function checkWin(opts = {}) {
                // winner == null cobre null e undefined (legado !== null tratava undefined como vitória).
                if (state.winner != null) {
                    if (!opts.suppressShow && !$("win-overlay")?.classList.contains("active")) {
                        scheduleWinOverlay(opts.delayMs);
                    }
                    return true;
                }
                // MP: só autoridade define winner — nunca findWinnerIndex no cliente.
                if (window.__DF_ONLINE && !opts.fromAuthority) {
                    return false;
                }
                // Peer MP com fromAuthority mas sem winner: não promover.
                if (opts.fromAuthority) return false;
                const w = DfRules.findWinnerIndex(state);
                if (w != null) {
                    state.winner = w;
                    // Tempo do turno fica nos hubs — não manter #desktop-timer ao lado de Ações.
                    stopTimer();
                    if (!opts.suppressShow) scheduleWinOverlay(opts.delayMs ?? DF_VICTORY_PAUSE_MS);
                    return true;
                }
                return false;
            }

            function dfAwardMatchXp(playerWon) {
                if (window.__DF_SIM_MODE) return;
                if (!window.DfAuthClient?.getToken?.()) return;
                const gen = window.__dfMatchGeneration | 0;
                if (window.__dfMatchXpAwardedGen === gen) return;
                window.__dfMatchXpAwardedGen = gen;
                const matchType = window.__DF_ONLINE ? "pvp" : "ai";
                let diff;
                if (matchType === "ai") {
                    try { diff = getAiDifficulty(); } catch (e) { diff = aiDifficulty || "normal"; }
                    if (diff !== "hard") diff = "normal";
                }
                const outcome = playerWon ? "win" : "lose";
                window.DfAuthClient.awardMatchXp({ matchType, outcome, aiDifficulty: diff })
                    .then(() => { /* XP salvo no servidor */ })
                    .catch(() => { /* offline / sem sessão */ });
            }

            function showWin() {
                clearTimeout(_winOverlayTimer);
                _winOverlayTimer = null;
                if (state.winner == null) return;
                if ($("win-overlay")?.classList.contains("active")) return;
                try {
                    if (state.activeTalent) {
                        state.activeTalent = null;
                        updateUI(true);
                    }
                    document.getElementById("talent-spotlight-layer")?.replaceChildren?.();
                    document.getElementById("talent-spotlight-layer")
                        ?.classList?.remove("talent-spotlight-above-hud", "talent-spotlight-touch-hud");
                } catch (e) { /* */ }
                try { dfCombatForceCleanup(); } catch (e) { /* */ }
                try { window.DfPixiVfx?.clearStage?.(); } catch (e) { /* */ }
                const restoreArenaBehindWin = () => {
                    try {
                        window.DfLayout?.enforceMobileChrome?.();
                        const root = document.documentElement;
                        const stage = $("df-rotate-stage");
                        const game = $("game");
                        const mode = window.DfLayout?.combatArenaMode?.();
                        const url = window.DfLayout?.arenaBgUrl?.(mode);
                        if (!url) return;
                        const size = mode === "desktop-fullscreen" ? "cover" : "100% 100%";
                        const bg = `#0a0608 url("${url}") center center / ${size} no-repeat`;
                        root.style.setProperty("background", bg, "important");
                        stage?.style.setProperty("background", bg, "important");
                        game?.style.setProperty("background", "transparent", "important");
                    } catch (e) { /* mantém o modal utilizável mesmo sem layout */ }
                };
                restoreArenaBehindWin();
                try { window.__dfSyncArenaAlignment?.(); } catch (e) { /* */ }
                dfCombatPurgeGhosts();
                gamePhase = "game-over";
                // Esconde o relógio numérico ao lado de Ações (o tempo já está nos hubs).
                stopTimer();
                const w = state.winner;
                const playerWon = w === dfHumanSeat();
                const winner = state.players[w];
                const winnerHero = winner ? (winner.heroDef || getHeroDef(winner.heroId)) : null;
                const overlay = $("win-overlay");
                overlay.classList.toggle("victory", playerWon);
                overlay.classList.toggle("defeat", !playerWon);
                // Imagem do herói VENCEDOR em destaque no centro.
                const img = $("win-hero-img");
                if (img) {
                    if (winnerHero && winnerHero.image) {
                        img.src = winnerHero.image;
                        img.style.display = "";
                        img.onerror = () => { img.style.display = "none"; };
                    } else {
                        img.style.display = "none";
                    }
                }
                $("win-msg").textContent = playerWon ? "🏆 VITÓRIA!" : "💀 DERROTA";
                $("win-hero-name").textContent = winnerHero
                    ? `${winnerHero.emoji || ""} ${winnerHero.name}`.trim()
                    : (winner ? winner.name : "");
                $("win-sub").textContent = playerWon
                    ? `Você alcançou ${winner.vp} PV e venceu a batalha!`
                    : `${winner.name} alcançou ${winner.vp} PV. Tente de novo!`;
                // Multiplayer: sem "Jogar Novamente" (só Voltar ao Menu). vs-IA mantém Reiniciar.
                const winAgain = $("btn-win-again");
                if (winAgain) {
                    if (window.__DF_ONLINE) winAgain.setAttribute("hidden", "");
                    else winAgain.removeAttribute("hidden");
                }
                try { window.sfx && window.sfx(playerWon ? "victory" : "defeat"); } catch (e) {}
                overlay.classList.add("active");
                document.documentElement.classList.add("df-win-active");
                requestAnimationFrame(restoreArenaBehindWin);
                try { dfAwardMatchXp(playerWon); } catch (e) { /* */ }
                [
                    "df-pass-turn-pedestal", "df-combat-opcoes-pedestal", "df-buy-card-pedestal",
                    "df-deck-count-pedestal", "df-ultimate-pedestal", "df-ultimate-count-pedestal",
                    "df-actions-label-pedestal", "df-actions-count-pedestal", "df-turn-banner-pedestal",
                ].forEach((id) => {
                    const el = $(id);
                    if (!el) return;
                    el.hidden = false;
                    el.removeAttribute("hidden");
                    el.setAttribute("aria-hidden", "false");
                });
                const timerEl = $("desktop-timer");
                if (timerEl) {
                    timerEl.hidden = true;
                    timerEl.setAttribute("hidden", "");
                    timerEl.setAttribute("aria-hidden", "true");
                }
                try { window.__dfSyncPassTurnPedestal?.(); } catch (e) { /* */ }
                try { window.__dfSyncCombatOpcoesPedestal?.(); } catch (e) { /* */ }
                try { window.__dfSyncBuyCardPedestal?.(); } catch (e) { /* */ }
                try { window.__dfSyncUltimatePedestal?.(); } catch (e) { /* */ }
                try { window.__dfSyncActionsPedestal?.(); } catch (e) { /* */ }
                try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                requestAnimationFrame(() => {
                    try { window.__dfSyncPassTurnPedestal?.(); } catch (e) { /* */ }
                    try { window.__dfSyncCombatOpcoesPedestal?.(); } catch (e) { /* */ }
                    try { window.__dfSyncBuyCardPedestal?.(); } catch (e) { /* */ }
                    try { window.__dfSyncUltimatePedestal?.(); } catch (e) { /* */ }
                    try { window.__dfSyncActionsPedestal?.(); } catch (e) { /* */ }
                    try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                    const t2 = $("desktop-timer");
                    if (t2) {
                        t2.hidden = true;
                        t2.setAttribute("hidden", "");
                        t2.setAttribute("aria-hidden", "true");
                    }
                });
            }

            // Reinicia a partida atual: mantém o mesmo modo, herói do
            // jogador e objetivo de PV. Os adversários são re-sorteados
            // (heróis diferentes do jogador) pra dar variedade. Equivale
            // a clicar de novo no fluxo "modo → herói → objetivo" mas
            // sem voltar pra tela inicial.
            // Desistir: o jogador humano (p=0) abandona a partida e o
            // adversário com mais PV vence (empate → p=1). Vinculada ao
            // botão "🏳️ Desistir" no menu de ações (substituiu Passar a Vez).
            function surrenderGame() {
                try { dfEnsurePresentationUnblocked("surrender"); } catch (e) { /* */ }
                try { window.DfPixiVfx?.forceClearStage?.({ force: true }); } catch (e) { /* */ }
                try { window.DfPresentationBus?.forceReset?.(); } catch (e) { /* */ }
                try { window.DfMobileImmersive?.dismissTouchBlockers?.(); } catch (e) { /* */ }
                try {
                    document.querySelectorAll(".phase-blocker, #df-mobile-fs-entry").forEach((el) => el.remove());
                } catch (e) { /* */ }
                window._summonLock = false;
                window.__dfSummonInFlight = false;
                window.__dfCombatActive = null;
                window.__dfCombatPending = null;
                try { document.body.classList.remove("df-combat-active"); } catch (e) { /* */ }
                if (!state.started || state.winner !== null) return;
                const local = window.__DF_ONLINE ? dfLocalSeat() : 0;
                const opp = (local + 1) % state.playersCount;
                state.winner = opp;
                log(`🏳️ ${state.players[local]?.name || "Jogador"} desistiu! ${state.players[opp]?.name || "Adversário"} venceu por desistência.`);
                stopTimer();
                showWin();
            }

            /** Multiplayer: desistência autoritativa + overlay de derrota (sem ir ao HUB). */
            async function dfOnlineSurrenderAndShowDefeat() {
                if (!window.__DF_ONLINE || !state.started || state.winner !== null) {
                    surrenderGame();
                    return;
                }
                const seat = dfLocalSeat();
                try {
                    const ack = await dfOnlineSendActionAwait({
                        type: "SURRENDER",
                        playerId: seat,
                    });
                    if (ack?.authoritativeState?.players?.length) {
                        dfOnlineReconcileSnapshot(
                            { state: ack.authoritativeState, full: true },
                            { skipPhase: true },
                        );
                    }
                    if (state.winner == null) {
                        state.winner = (seat + 1) % state.playersCount;
                    }
                } catch (e) {
                    console.warn("[DF online] SURRENDER", e);
                    if (state.winner == null) {
                        state.winner = (seat + 1) % state.playersCount;
                    }
                }
                try { await dfNet?.leaveRoom?.({ forfeit: true }); } catch (e2) { /* */ }
                stopTimer();
                log(`🏳️ ${state.players[seat]?.name || "Jogador"} desistiu!`);
                showWin();
                checkWin({ suppressShow: true });
            }

            async function restartCurrentGame() {
                if (!state.started) return;
                if (window.__DF_ONLINE) return;
                // Abortar turno IA / VFX / locks ANTES do reset — senão reinícios
                // empilham turnos e a IA joga várias ações ao mesmo tempo.
                dfAbortActiveMatch();
                dfEnsureLocalPlayMode();
                stopTimer();
                closeOverlay();
                $("detail-overlay").classList.remove("active");
                $("discard-overlay").classList.remove("active");
                $("win-overlay").classList.remove("active");
                document.documentElement.classList.remove("df-win-active");
                $("hero-info-overlay").classList.remove("active");
                $("card-preview-container").classList.remove("active");
                closePreviewZoom?.();
                // Blackout: com #game oculto o CSS de menu volta a pintar o fundo
                // da seleção de herói (DESOLAÇÃO) por alguns frames. A cortina
                // preta cobre o intervalo até revealMatchBoard.
                document.documentElement.classList.add("df-restart-blackout");
                // Corte seco: esconde a arena antiga ANTES do warm — evita
                // flash fundo velho → fundo novo durante prepareMatchArts.
                const gHide = $("game");
                if (gHide) {
                    gHide.style.display = "none";
                    gHide.classList.remove("active", "arena-ready");
                }
                $("game-grid")?.classList.remove("arena-ready");
                document.body.classList.remove("df-arena-visible");
                // Re-sorteia os heróis dos oponentes mantendo o do jogador.
                const usedIds = [selectedHeroId];
                const allIds = heroDefs.map(h => h.id);
                for (let i = 1; i < selectedMode; i++) {
                    usedIds.push(pickRandomAiHeroId(usedIds, allIds));
                }
                resetState(selectedMode, usedIds);
                // Sorteia o 1º jogador ANTES de mostrar a arena / aquecer artes —
                // senão currentPlayer=0 mostra "SUA VEZ" falso por 1–2s.
                const firstPlayer = Math.random() < 0.5 ? 0 : 1;
                state.currentPlayer = firstPlayer;
                window.__dfMatchOpeningSeat = firstPlayer;
                window.__dfMatchBoot = true;
                try { window.__dfSyncTurnBannerPedestal?.(); } catch (eBan0) { /* */ }
                // Aplica CSS da arena nova já no DOM (ainda oculto).
                try {
                    window.DfLayout?.applyCombatArenaModeClasses?.(document.documentElement);
                    window.DfLayout?.applyCombatArenaModeClasses?.($("game"));
                    window.DfLayout?.syncLayoutViewport?.();
                } catch (eArena) { /* */ }
                dfSyncVersionGuardPolling(true);
                dfApplyDesktopFieldLock();
                dfRestartBlackoutFailsafe();
                await prepareMatchArtsForPlay();
                revealMatchBoard();
                try { window.__dfSyncTurnBannerPedestal?.(); } catch (eBan) { /* */ }
                log("Partida reiniciada!");
                // Mesmo sorteio 50/50 do início de partida.
                const firstName = state.players[firstPlayer]?.name || "?";
                log(`🎲 Sorteio: ${firstName} começa!`);
                try {
                    await startTurn(firstPlayer);
                } finally {
                    window.__dfMatchBoot = false;
                    window.__dfMatchOpeningSeat = null;
                    try { window.__dfSyncTurnBannerPedestal?.(); } catch (eBan2) { /* */ }
                }
            }

