            function dfOnlineActionFailToast(kind, err) {
                if (!window.__DF_ONLINE) return;
                const e = String(err || "");
                const now = Date.now();
                // Uma mensagem a cada ~6s — evita chuva de toasts no MP.
                if (dfOnlineActionFailToast._t && now - dfOnlineActionFailToast._t < 6000) return;
                dfOnlineActionFailToast._t = now;
                if (e === "ACK_TIMEOUT" || e === "TIMEOUT") {
                    // Silencioso no combate — evita banner falso de “sincronizando”.
                    return;
                }
                if (e === "NOT_ONLINE" || e === "NOT_CONNECTED") {
                    floatText("Sem conexão com o servidor — reconectando…", "warn center", 2400);
                    return;
                }
                if (e === "RATE_LIMIT") {
                    floatText("Aguarde um instante — servidor ocupado.", "warn center", 1800);
                    return;
                }
                if (e === "NOT_YOUR_TURN") {
                    floatText("Aguarde — o servidor ainda não liberou sua vez.", "warn center", 2200);
                    return;
                }
                if (e === "NOT_PLAYING" || e === "NOT_IN_ROOM" || e === "NO_SEAT") {
                    try { void window.__dfOnline?.dfOnlineRecoverMatchSeat?.(); } catch (eRec) { /* */ }
                    floatText("Partida não sincronizada — reconectando…", "warn center", 2400);
                    return;
                }
                if (kind === "draw") {
                    floatText("Não foi possível comprar — sincronizando…", "warn center", 1800);
                } else if (kind === "pass") {
                    floatText("Não foi possível passar a vez — sincronizando…", "warn center", 2200);
                } else {
                    floatText("Jogada rejeitada — sincronizando…", "warn center", 2000);
                }
            }

            async function dfOnlineHealFromAckOrRollback(ack) {
                if (ack?.authoritativeState?.players?.length) {
                    dfOnlineReconcileSnapshot(
                        { state: ack.authoritativeState, full: true },
                        { skipPhase: true },
                    );
                    updateUI();
                    return true;
                }
                try {
                    return !!(await dfOnlineRollbackToServer?.());
                } catch (e) {
                    console.warn("[DF online] heal", e);
                    return false;
                }
            }

            function dfOnlineNetReady() {
                // Sempre preferir o net da sessão online (fonte real do socket).
                const net = dfNet
                    || window.dfNet
                    || (typeof __dfOnline?.getNet === "function" ? __dfOnline.getNet() : null)
                    || window.__dfOnline?.getNet?.();
                if (!window.__DF_ONLINE || !net) return false;
                // net.connected já cruza flag local + socket.connected
                return !!net.connected;
            }

            async function endTurn() { if (state.winner !== null) return;
                if (state.activeTalent) {
                    try { abortActiveTalent(); } catch (e) { /* */ }
                }
                stopTimer();
                dfOnlineAbortCombatVisuals?.();
                try { window.DfUltimateDirector?.sweepOrphans?.(); } catch (e) { /* */ }
                try { window.DfUltimateDirector?.purgeUltimateVfx?.(); } catch (e) { /* */ }
                try { window.__dfPurgeDestroyArtifacts?.(); } catch (e) { /* */ }
                window.dfStabilizeFieldCards?.();
                state.players[state.currentPlayer].actions = Math.max(0, state.players[state.currentPlayer].actions);

                // Multiplayer: servidor aplica END_TURN (manutenção + saque do próximo).
                // Cliente local NÃO avança o turno sozinho — evita “dois jogos” e banners errados.
                // NUNCA cair no caminho offline enquanto __DF_ONLINE (causava freeze/desync).
                if (window.__DF_ONLINE) {
                    // Destrava applyingRemote órfão ANTES de decidir — senão o
                    // passar a vez “some” e a partida congela.
                    try { dfOnlineApplyingRemote = false; } catch (e) { /* */ }
                    try { window.__dfOnline?.dfOnlineResetPresentQueue?.(); } catch (e) { /* */ }
                    const endingSeat = state.currentPlayer;
                    if (window.__dfTurnEndingPending) return;
                    window.__dfTurnEndingPending = true;
                    const pendingSafety = setTimeout(() => {
                        if (window.__dfTurnEndingPending) {
                            window.__dfTurnEndingPending = false;
                            try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                        }
                    }, 12000);
                    try { window.__dfSyncTurnBannerPedestal?.(); } catch (e) { /* */ }
                    try { updateUI(); } catch (e) { /* */ }
                    if (!dfOnlineNetReady()) {
                        window.__dfTurnEndingPending = false;
                        clearTimeout(pendingSafety);
                        dfOnlineActionFailToast("pass", "NOT_CONNECTED");
                        try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                        if (state.winner === null && dfIsMyTurn()) startTimer();
                        return;
                    }
                    try {
                        let ack = await dfOnlineSendActionAwait({
                            type: "END_TURN",
                            playerId: endingSeat,
                        });
                        // ACK_TIMEOUT: servidor pode ter aplicado — reconciliar e, se ainda
                        // for nossa vez, tentar uma vez; senão seguir o estado do servidor.
                        if (ack && ack.ok === false && (ack.error === "ACK_TIMEOUT" || ack.error === "TIMEOUT")) {
                            try { await dfOnlineRollbackToServer?.(); } catch (e) { /* */ }
                            updateUI();
                            if (state.winner === null && state.currentPlayer === endingSeat) {
                                ack = await dfOnlineSendActionAwait({
                                    type: "END_TURN",
                                    playerId: endingSeat,
                                });
                            } else {
                                try {
                                    if ((state.turnNumber | 0) > 1) {
                                        await showPassiveVpMaintMessage(state.currentPlayer);
                                    }
                                } catch (e) { /* */ }
                                try {
                                    await dfOnlinePlayUpkeepDrawFromEvents?.(null);
                                } catch (e) { /* */ }
                                window.__dfOnlineSkipMaintRules = true;
                                try {
                                    await startTurn(state.currentPlayer);
                                } finally {
                                    window.__dfOnlineSkipMaintRules = false;
                                }
                                return;
                            }
                        }
                        if (!ack || ack.ok === false) {
                            window.__dfTurnEndingPending = false;
                            clearTimeout(pendingSafety);
                            dfOnlineActionFailToast("pass", ack?.error);
                            // Nunca avançar/restaurar turno localmente — só estado do servidor.
                            await dfOnlineRollbackToServer?.();
                            updateUI();
                            if (state.winner === null && dfIsMyTurn()) startTimer();
                            else if (state.winner === null && !dfIsMyTurn()) {
                                window.__dfOnlineSkipMaintRules = true;
                                try { await startTurn(state.currentPlayer); }
                                finally { window.__dfOnlineSkipMaintRules = false; }
                            }
                            return;
                        }
                        if (ack.authoritativeState?.players?.length) {
                            try { await window.dfOnlinePlayPoisonKillsFromEvents?.(ack.events); } catch (ePk) { /* */ }
                            try { window.dfOnlineArmUpkeepDrawIfNeeded?.(ack.events); } catch (eArm) { /* */ }
                            dfOnlineReconcileSnapshot(
                                { state: ack.authoritativeState, full: true },
                                { skipPhase: true },
                            );
                            // VP_GAIN de manutenção / veneno.
                            if (Array.isArray(ack.events)) {
                                for (const ev of ack.events) {
                                    if (ev?.type === "VP_GAIN" && state.players[ev.playerId] != null) {
                                        const authVp = ack.authoritativeState.players[ev.playerId]?.vp;
                                        if (authVp != null) state.players[ev.playerId].vp = authVp | 0;
                                        else if ((ev.amount | 0) > 0) {
                                            state.players[ev.playerId].vp =
                                                (state.players[ev.playerId].vp | 0) + (ev.amount | 0);
                                        }
                                    }
                                }
                            }
                            updateUI();
                            // Vitória por PV de manutenção (14 → 15 na virada):
                            // sem isso o winner ficava só no estado, sem overlay.
                            try { dfOnlineCheckWinFromAuthority?.(ack); } catch (eWin) { /* */ }
                            try {
                                if (window.__dfUpkeepDrawInFlight) {
                                    window.dfOnlineMarkUpkeepDrawPending?.(window.__dfUpkeepDrawSeat);
                                }
                            } catch (eMark) { /* */ }
                        } else {
                            // Sem estado no ACK: rollback ao servidor (nunca avançar turno localmente).
                            await dfOnlineRollbackToServer?.();
                            updateUI();
                        }
                        // PV passivo: mensagem 1,5s → só então anima o saque livre.
                        const authNextPre = ack.authoritativeState?.currentPlayer;
                        const nextForVp = (authNextPre === 0 || authNextPre === 1)
                            ? (authNextPre | 0)
                            : state.currentPlayer;
                        try {
                            if (!isFirstTurnForPlayer(nextForVp)) {
                                await showPassiveVpMaintMessage(nextForVp);
                            }
                        } catch (e) { /* */ }
                        try {
                            if (window.__dfUpkeepDrawInFlight) {
                                window.dfOnlineMarkUpkeepDrawPending?.(window.__dfUpkeepDrawSeat);
                            }
                        } catch (eMark2) { /* */ }
                        try {
                            await dfOnlinePlayUpkeepDrawFromEvents?.(ack.events);
                        } catch (e) { /* */ }
                        if (ack.turnDeadline) {
                            window.__dfTurnDeadline = ack.turnDeadline | 0;
                        } else {
                            window.__dfTurnDeadline = Date.now() + 70000;
                        }
                        // Preferir CP do ACK — evita banner invertido se state driftou.
                        const authNext = ack.authoritativeState?.currentPlayer;
                        const nextCp = (authNext === 0 || authNext === 1)
                            ? (authNext | 0)
                            : state.currentPlayer;
                        if (ack.seq != null) window.__dfLastEndTurnStartSeq = ack.seq | 0;
                        // Libera pending antes do startTurn (dfIsMyTurn / UI).
                        window.__dfTurnEndingPending = false;
                        window.__dfOnlineSkipMaintRules = true;
                        try {
                            await startTurn(nextCp);
                        } finally {
                            window.__dfOnlineSkipMaintRules = false;
                        }
                    } catch (e) {
                        console.warn("[DF online] END_TURN", e);
                        dfOnlineActionFailToast("pass", e?.message || "SEND_FAILED");
                        await dfOnlineHealFromAckOrRollback(null);
                        if (state.winner === null && dfIsMyTurn()) startTimer();
                        else if (state.winner === null && !dfIsMyTurn()) {
                            window.__dfOnlineSkipMaintRules = true;
                            try { await startTurn(state.currentPlayer); }
                            finally { window.__dfOnlineSkipMaintRules = false; }
                        }
                    } finally {
                        window.__dfTurnEndingPending = false;
                        clearTimeout(pendingSafety);
                        try { window.__dfSyncTurnBannerPedestal?.(); } catch (e2) { /* */ }
                    }
                    return;
                }

                // Offline / vs-IA
                DfRules.applyWallBonusOnTurnEnd(state, state.currentPlayer);
                let next = (state.currentPlayer + 1) % state.playersCount;
                if (next === 0) state.turnNumber = (state.turnNumber || 1) + 1;
                await startTurn(next);
            }

            function getPlayerVpAdvantageOverHuman(pIdx) { if (pIdx === 0) return 0; const humanVp = state.players[0].vp; const
                    aiVp = state.players[pIdx].vp; return humanVp - aiVp; }















