            /** Contexto da chamada dispatch ativa (applyVisual lê fromHuman/dropPoint). */
            let _dfDispatchOpts = null;

            /** SUMMON/ATTACK enriquecem o payload online dentro do applyVisual. */
            const DF_DISPATCH_VISUAL_BROADCAST = new Set(["SUMMON", "ATTACK_RESOLVE"]);
            /** Já enviados ao servidor dentro do applyVisual (não rebroadcast). */
            const DF_ONLINE_SERVER_FIRST = new Set(["END_TURN", "DRAW_CARD", "SUMMON", "SURRENDER", "FIELD_COMMIT"]);

            function dfDispatchHumanFeedback(action, result, opts) {
                if (!opts?.fromHuman || !dfIsLocalPlayer(action.playerId ?? state.currentPlayer)) return;
                const err = result?.error || result?.code;
                if (!err) return;
                const T = DfProtocol?.ACTION_TYPES || {};
                const pid = action.playerId ?? state.currentPlayer;
                const pl = state.players[pid];
                if (action.type === T.SUMMON || action.type === "SUMMON") {
                    const card = pl?.hand?.[action.handIdx];
                    if (err === "INSUFFICIENT_ACTIONS" && card) {
                        flashInsufficientActions(card.currentPower, pl.actions, action.handIdx);
                    } else if (err === "FIELD_FULL") {
                        notifyFieldFull(pid);
                    } else if (err === "NO_RITUAL_SACRIFICE" && card) {
                        flashRuleBanner(
                            `${card.name} requer sacrificar um Campeão aliado de Poder ${card.summonRitual}.`,
                            `Você não tem nenhum aliado de Poder <b>${card.summonRitual}</b> no campo.`);
                    } else if (err === "BAD_PHASE") {
                        floatText("Aguarde o fim da manutenção ou feche menus abertos.", "warn center", 1800);
                    } else if (err === "COMBAT_ACTIVE") {
                        floatText("Aguarde o combate terminar.", "warn center", 1400);
                    } else if (err === "NOT_YOUR_TURN") {
                        floatText("Aguarde sua vez.", "warn center", 1400);
                    } else if (err === "SUMMON_FAILED") {
                        floatText("Não foi possível invocar — tente de novo.", "warn center", 1600);
                    }
                }
                if ((action.type === T.DRAW_CARD || action.type === "DRAW_CARD") && err === "HAND_FULL") {
                    showHandLimitToast(`✋ <b>Limite de cartas</b><br>Você já tem ${MAX_HAND} cartas em mãos.<br>Jogue uma carta antes de comprar.`);
                }
            }

            /** Índice da mão por identidade (uid → nome), com o índice como último recurso. */
            function dfResolveHandIdxByIdentity(hand, handIdx, cardName, uid) {
                const idx = handIdx | 0;
                if (!Array.isArray(hand) || !hand.length) return idx;
                if (uid != null && uid !== "") {
                    const byUid = hand.findIndex((c) => c && String(c.uid ?? "") === String(uid));
                    if (byUid >= 0) return byUid;
                }
                const want = cardName != null ? String(cardName) : "";
                if (want) {
                    if (hand[idx] && String(hand[idx].name ?? "") === want) return idx;
                    const byName = hand.findIndex((c) => c && String(c.name ?? "") === want);
                    if (byName >= 0) return byName;
                }
                return idx;
            }

            /** Dispatch único: validação DfEngine + apply visual (game.html) ou rede. */
            async function dfDispatch(action, opts = {}) {
                const pid = action.playerId ?? state.currentPlayer;
                const shaped = { ...action, playerId: pid };
                _dfDispatchOpts = { ...opts, playerId: pid };
                try {
                    const isAi = !!state.players[pid]?.isAI;
                    const ctx = {
                        strictFumacaToxica: isAi,
                        avoidEnemyOnEnterWaste: isAi && !!opts.avoidEnemyOnEnterWaste,
                        allowWastedOnEnter: !isAi,
                    };
                    const result = await DfEngine.dispatch(shaped, {
                        getState: () => state,
                        applyVisual: async (a) => dfEngineApplyAction({ ...a, playerId: a.playerId ?? state.currentPlayer }),
                    }, ctx);
                    if (!result?.ok) dfDispatchHumanFeedback(shaped, result, opts);
                    if (result?.ok && opts.broadcast && window.__DF_ONLINE && !dfOnlineApplyingRemote) {
                        const T = DfProtocol?.ACTION_TYPES || {};
                        const t = shaped.type;
                        if (
                            !DF_DISPATCH_VISUAL_BROADCAST.has(t)
                            && !DF_ONLINE_SERVER_FIRST.has(t)
                            && t !== T.SUMMON
                            && t !== T.ATTACK_RESOLVE
                            && t !== T.END_TURN
                            && t !== T.DRAW_CARD
                        ) {
                            dfOnlineBroadcastAction(shaped, opts);
                        }
                    }
                    return result;
                } finally {
                    _dfDispatchOpts = null;
                }
            }

            /** Ação do assento local: marca fromHuman + broadcast online quando aplicável. */
            async function dfPlayerAction(action, opts = {}) {
                const pid = action.playerId ?? dfLocalSeat();
                const isLocalHuman = dfIsLocalPlayer(pid) && !state.players[pid]?.isAI;
                return dfDispatch(
                    { ...action, playerId: pid },
                    {
                        fromHuman: isLocalHuman,
                        broadcast: isLocalHuman && opts.broadcast !== false,
                        ...opts,
                    },
                );
            }

            window.dfDispatch = dfDispatch;
            window.dfPlayerAction = dfPlayerAction;
            window.dfPurgeDesacelerarVfx = dfPurgeDesacelerarVfx;




            function pickRandomAiHeroId(usedIds, allIds) {
                const available = allIds.filter((id) => !usedIds.includes(id));
                if (!available.length) return null;
                if (!aiUseHardWeights()) {
                    return available[Math.floor(Math.random() * available.length)];
                }
                let total = 0;
                const weights = available.map((id) => {
                    const w = aiHeroWeight(id);
                    total += w;
                    return w;
                });
                let r = Math.random() * total;
                for (let i = 0; i < available.length; i++) {
                    r -= weights[i];
                    if (r <= 0) return available[i];
                }
                return available[available.length - 1];
            }

            /* ============================================================
               aiShouldAttack — gatekeeper: a IA SÓ ataca quando faz sentido
               estratégico. Princípios:
                 1. NUNCA atacar pra morrer (atacante mais fraco que defensor).
                 2. Defensor com Sobrepujar e poder >= atacante: nunca.
                 3. Empate sem Sobrepujar de nenhum lado = troca mútua (ambos
                    morrem). Só aceitar se o defensor for ameaça real.
                 4. Ambos com Sobrepujar e empate = ninguém morre = nunca.
                 5. Saque livre (isFree) reduz custo da troca — um pouco
                    mais permissivo, mas "vai perder" continua proibido.
               ============================================================ */










