            function openGameMenu() {
                // MP: tela preta / resume falho — Escape/menu libera saída ao hub.
                if (window.__DF_ONLINE || document.body.classList.contains("df-pvp-mode")) {
                    const g = $("game");
                    const stuck = !state.started
                        || !g
                        || !g.classList.contains("active")
                        || g.style.display === "none";
                    if (stuck) {
                        void dfOnlineForceExitStuckMatch("OPEN_MENU_STUCK");
                        return;
                    }
                }
                if (!state.started || state.winner !== null) return;
                if (dfIsMyTurn() && gamePhase === "target-ally" && targetData?.ability === "ritualSacrifice") {
                    cancelRitualSacrifice();
                    return;
                }
                if (dfIsMyTurn() && ["select-attacker", "select-defender", "target-champion",
                     "target-ally", "ultimate-target", "unfreeze-choice"].includes(gamePhase)) {
                    if (state.activeTalent) abortActiveTalent();
                    gamePhase = "normal";
                    targetData = {};
                    updateUI();
                }
                if (gamePhase !== "normal" && gamePhase !== "menu") {
                    if (!dfIsMyTurn()) return;
                    gamePhase = "normal";
                    targetData = {};
                }
                openActionsMenu();
            }
            window.__dfOpenGameMenu = openGameMenu;
